def _load_local_env_file() -> None:
    explicit = os.environ.get("LL_WEB_ENV_FILE", "").strip()
    path = Path(explicit).expanduser() if explicit else Path(__file__).resolve().parent / ".env"
    if not path.exists():
        if explicit:
            raise RuntimeError("The configured LL_WEB_ENV_FILE does not exist.")
        return
    if path.is_symlink() or not path.is_file() or path.stat().st_size > 65536:
        raise RuntimeError("The environment file must be a small regular file, not a symlink.")
    if os.name != "nt" and path.stat().st_mode & 0o022:
        raise RuntimeError("The environment file must not be group/world writable.")
    for raw in path.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        if line.startswith("export "):
            line = line[7:]
        name, value = line.split("=", 1)
        name, value = name.strip(), value.strip()
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
            raise RuntimeError("Invalid environment variable name in configuration.")
        if name in {"PATH", "HOME", "CODEX_HOME", "SHELL", "COMSPEC"} or name.startswith(("LD_", "DYLD_", "PYTHON")):
            raise RuntimeError("Process execution variables cannot be loaded from the app environment file.")
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
            value = value[1:-1]
        os.environ.setdefault(name, value)

_load_local_env_file()

"""Shared security primitives for C-8 r102 (inserted into the full script)."""

class C8SecurityInputError(ValueError):
    """A request was rejected before any application operation was performed."""


def _c8_env_int(name, default, minimum, maximum):
    raw = os.environ.get(name, str(default))
    try:
        value = int(raw)
    except (TypeError, ValueError):
        raise RuntimeError(f"{name} must be an integer.") from None
    if not minimum <= value <= maximum:
        raise RuntimeError(f"{name} must be between {minimum} and {maximum}.")
    return value


def _c8_authority(value):
    """Parse an HTTP authority without discarding an invalid port or userinfo."""
    value = str(value or "")
    if not value or len(value) > 300 or re.search(r"[\s\x00-\x1f\x7f/@?#\\,%]", value):
        raise C8SecurityInputError("Invalid host.")
    parsed = urllib.parse.urlsplit("//" + value)
    if parsed.username is not None or parsed.password is not None or not parsed.hostname:
        raise C8SecurityInputError("Invalid host.")
    try:
        port = parsed.port
        host = parsed.hostname.encode("idna").decode("ascii").lower().rstrip(".")
    except (ValueError, UnicodeError):
        raise C8SecurityInputError("Invalid host or port.") from None
    if port is not None and not 1 <= port <= 65535:
        raise C8SecurityInputError("Invalid port.")
    if value.endswith(":"):
        raise C8SecurityInputError("Invalid port.")
    try:
        host = str(ipaddress.ip_address(host))
    except ValueError:
        if len(host) > 253 or any(not re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", x) for x in host.split(".")):
            raise C8SecurityInputError("Invalid DNS host.") from None
    return host, port


def _c8_origin(value):
    value = str(value or "")
    if re.search(r"[\s\x00-\x1f\x7f\\]", value):
        raise C8SecurityInputError("Invalid origin.")
    p = urllib.parse.urlsplit(value)
    if p.scheme not in {"http", "https"} or p.path or p.query or p.fragment:
        raise C8SecurityInputError("Invalid origin.")
    host, port = _c8_authority(p.netloc)
    return p.scheme, host, port or (443 if p.scheme == "https" else 80)


def _c8_same_origin(headers, tls):
    try:
        scheme = "https" if tls else "http"
        host, port = _c8_authority(headers.get("Host") or "")
        expected = (scheme, host, port or (443 if tls else 80))
        origin = headers.get("Origin")
        if origin:
            return _c8_origin(origin) == expected
        ref = headers.get("Referer")
        if not ref:
            return False
        p = urllib.parse.urlsplit(ref)
        if p.username is not None or p.password is not None:
            return False
        return _c8_origin(p.scheme + "://" + p.netloc) == expected
    except (ValueError, UnicodeError):
        return False


def _c8_parse_qs(value, *args, **kwargs):
    kwargs.setdefault("max_num_fields", 128)
    return urllib.parse.parse_qs(value, *args, **kwargs)


def _c8_json_object(raw):
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise C8SecurityInputError("Duplicate JSON keys are not accepted.")
            result[key] = value
        return result

    def constant(_):
        raise C8SecurityInputError("Non-finite JSON numbers are not accepted.")

    try:
        text = raw.decode("utf-8", "strict")
        # Reject excessive nesting before json.loads can hit Python's recursion limit.
        depth = 0
        quoted = False
        escaped = False
        for char in text:
            if quoted:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    quoted = False
            elif char == '"':
                quoted = True
            elif char in "[{":
                depth += 1
                if depth > 32:
                    raise C8SecurityInputError("JSON nesting is too deep.")
            elif char in "]}":
                depth -= 1
        obj = json.loads(text, object_pairs_hook=pairs, parse_constant=constant)
        if not isinstance(obj, dict):
            raise C8SecurityInputError("Expected a JSON object.")
        pending = [obj]
        count = 0
        while pending:
            value = pending.pop()
            count += 1
            if count > 100000:
                raise C8SecurityInputError("Too many JSON values.")
            if isinstance(value, dict):
                pending.extend(value.values())
                pending.extend(value.keys())
            elif isinstance(value, list):
                pending.extend(value)
            elif isinstance(value, float) and not math.isfinite(value):
                raise C8SecurityInputError("Non-finite JSON numbers are not accepted.")
            elif isinstance(value, str):
                value.encode("utf-8", "strict")
        return obj
    except C8SecurityInputError:
        raise
    except (ValueError, UnicodeError, RecursionError):
        raise C8SecurityInputError("Expected valid UTF-8 JSON.") from None


class _C8DeadlineReader:
    """Bound raw header bytes and elapsed read time, including trickle traffic."""

    def __init__(self, raw, connection):
        self.raw = raw
        self.connection = connection
        self.pending = bytearray()
        self.header_bytes = 0
        self.header_lines = 0
        self.headers_done = False
        self.deadline = time.monotonic() + 12.0
        self.body_deadline = None

    def __getattr__(self, name):
        return getattr(self.raw, name)

    def _chunk(self, maximum, deadline):
        left = deadline - time.monotonic()
        if left <= 0:
            raise TimeoutError("Request read deadline exceeded.")
        self.connection.settimeout(min(float(SECURITY_SOCKET_TIMEOUT_SECONDS), left))
        return self.raw.read1(maximum)

    def readline(self, size=-1):
        if self.headers_done:
            raise C8SecurityInputError("Unexpected line read after request headers.")
        limit = min(8192, size) if size > 0 else 8192
        while b"\n" not in self.pending:
            if len(self.pending) >= limit:
                raise C8SecurityInputError("Request line or header is too long.")
            chunk = self._chunk(min(4096, limit - len(self.pending)), self.deadline)
            if not chunk:
                if self.pending:
                    raise C8SecurityInputError("Incomplete request headers.")
                return b""
            self.pending.extend(chunk)
        end = self.pending.index(10) + 1
        line = bytes(self.pending[:end])
        del self.pending[:end]
        self.header_bytes += len(line)
        self.header_lines += 1
        if len(line) > limit or self.header_bytes > SECURITY_MAX_HEADER_CHARS or self.header_lines > 98:
            raise C8SecurityInputError("Request headers are too large.")
        if not line.endswith(b"\r\n") or b"\r" in line[:-2] or b"\x00" in line:
            raise C8SecurityInputError("Invalid request line ending.")
        if self.header_lines > 1 and line != b"\r\n":
            name, separator, value = line[:-2].partition(b":")
            if not separator or not re.fullmatch(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+", name):
                raise C8SecurityInputError("Invalid header name or folded header.")
            if any(c < 32 and c != 9 or c == 127 for c in value):
                raise C8SecurityInputError("Invalid header value.")
        if line == b"\r\n":
            self.headers_done = True
        return line

    def read(self, size=-1):
        if size < 0 or size > MAX_JSON_BYTES:
            raise C8SecurityInputError("Unbounded request body reads are not accepted.")
        if self.body_deadline is None:
            self.body_deadline = time.monotonic() + min(120.0, 15.0 + size / 65536.0)
        data = bytearray(self.pending[:size])
        del self.pending[:len(data)]
        while len(data) < size:
            chunk = self._chunk(min(65536, size - len(data)), self.body_deadline)
            if not chunk:
                raise C8SecurityInputError("Incomplete request body.")
            data.extend(chunk)
        return bytes(data)


def _c8_validate_request(handler):
    h = handler.headers
    if handler.request_version not in {"HTTP/1.0", "HTTP/1.1"}:
        raise C8SecurityInputError("Unsupported HTTP version.")
    path = str(handler.path)
    if not path.startswith("/") or path.startswith("//") or len(path) > SECURITY_MAX_PATH_CHARS or "#" in path:
        raise C8SecurityInputError("Invalid request target.")
    if re.search(r"[\x00-\x20\x7f\\]", path):
        raise C8SecurityInputError("Invalid request target.")
    route = urllib.parse.urlsplit(path).path
    for _ in range(3):
        if re.search(r"%(?![0-9a-fA-F]{2})", route) or re.search(r"%(?:2f|5c|00|0d|0a)", route, re.I):
            raise C8SecurityInputError("Ambiguous encoded request path.")
        route = urllib.parse.unquote(route)
    if "\\" in route or any(x in {".", ".."} for x in route.split("/")):
        raise C8SecurityInputError("Ambiguous request path.")
    for name in ("Host", "Content-Length", "Content-Type", "Origin", "Referer", "Cookie", "Authorization", "X-CSRF-Token", "Transfer-Encoding", "Expect", "Content-Encoding"):
        if len(h.get_all(name, [])) > 1:
            raise C8SecurityInputError("Duplicate security-sensitive header.")
    if len(h.get_all("Host", [])) != 1:
        raise C8SecurityInputError("Exactly one Host header is required.")
    _c8_authority(h["Host"])
    if h.get("Transfer-Encoding") is not None or h.get("Expect") is not None:
        raise C8SecurityInputError("Transfer-Encoding and Expect are not supported.")
    if (h.get("Content-Encoding") or "identity").lower() != "identity":
        raise C8SecurityInputError("Compressed request bodies are not supported.")
    length = h.get("Content-Length")
    if length is not None and (not re.fullmatch(r"[0-9]{1,10}", length) or int(length) > MAX_JSON_BYTES):
        raise C8SecurityInputError("Invalid or excessive Content-Length.")
    if handler.command in {"GET", "HEAD"} and int(length or 0):
        raise C8SecurityInputError("This method does not accept a request body.")
    if handler.command == "POST" and length is None:
        raise C8SecurityInputError("Content-Length is required.")


def _c8_bounded_inflate(data, limit, wbits=zlib.MAX_WBITS):
    limit = max(0, int(limit))
    decoder = zlib.decompressobj(wbits)
    raw = decoder.decompress(data, limit + 1)
    if len(raw) > limit or decoder.unconsumed_tail or not decoder.eof or decoder.unused_data:
        raise C8SecurityInputError("Compressed data is oversized, truncated, or has trailing streams.")
    return raw



def _c8_image_open(stream):
    image = Image.open(stream)
    if image.width <= 0 or image.height <= 0 or image.width * image.height > 8_000_000:
        image.close()
        raise C8SecurityInputError("Image pixel count exceeds the decoder memory budget.")
    if getattr(image, "n_frames", 1) > 200:
        image.close()
        raise C8SecurityInputError("Animated image has too many frames.")
    return image


def _c8_archive_name(name):
    name = str(name)
    parts = name.rstrip("/").split("/")
    if not name or len(name) > 512 or name.startswith("/") or "\\" in name or ":" in name or any(x in {"", ".", ".."} for x in parts) or any(ord(x) < 32 or ord(x) == 127 for x in name):
        raise C8SecurityInputError("Unsafe archive member path.")
    return name


def _c8_archive_budget():
    return _c8_env_int("LL_WEB_ARCHIVE_EXPANDED_BYTES", 32 * 1024 * 1024, 1048576, 256 * 1024 * 1024)


def _c8_check_zip(archive):
    infos = archive.infolist()
    if len(infos) > 2000:
        raise C8SecurityInputError("Too many archive entries.")
    total = 0
    seen = set()
    for item in infos:
        name = _c8_archive_name(item.filename)
        canonical = name.rstrip("/").casefold()
        if canonical in seen:
            raise C8SecurityInputError("Duplicate archive member path.")
        seen.add(canonical)
        mode = (item.external_attr >> 16) & 0o170000
        if mode not in {0, stat.S_IFREG, stat.S_IFDIR} or item.flag_bits & 1:
            raise C8SecurityInputError("Archive links, special files, and encrypted members are not supported.")
        total += item.file_size
        if item.file_size < 0 or total > _c8_archive_budget():
            raise C8SecurityInputError("Expanded archive exceeds the memory budget.")
    return infos


def _c8_zip_read(archive, member, limit=None):
    info = member if isinstance(member, zipfile.ZipInfo) else archive.getinfo(member)
    maximum = min(_c8_archive_budget(), _c8_archive_budget() if limit is None else int(limit))
    if info.file_size > maximum:
        raise C8SecurityInputError("Expanded archive member is too large.")
    with archive.open(info) as stream:
        raw = stream.read(maximum + 1)
    if len(raw) > maximum or len(raw) != info.file_size:
        raise C8SecurityInputError("Invalid expanded archive member size.")
    return raw


def _c8_egress_address_allowed(value):
    address = ipaddress.ip_address(value)
    if isinstance(address, ipaddress.IPv6Address):
        if address.ipv4_mapped:
            address = address.ipv4_mapped
        elif address.sixtofour or address.teredo or address in ipaddress.ip_network("64:ff9b::/96") or address in ipaddress.ip_network("64:ff9b:1::/48"):
            return False
    if address.is_loopback or address.is_link_local or address.is_multicast or address.is_unspecified or address.is_reserved:
        return False
    if str(address) in {"168.63.129.16", "100.100.100.200"}:
        return False
    if address.is_global:
        return True
    for cidr in re.split(r"[,;\s]+", os.environ.get("LL_WEB_EGRESS_ALLOW_CIDRS", "")):
        if cidr and address in ipaddress.ip_network(cidr, strict=False):
            return True
    return False


def _c8_open_egress_socket(host, port, timeout):
    if "%" in host:
        raise C8SecurityInputError("Scoped IP addresses are not allowed as web targets.")
    addresses = socket.getaddrinfo(host, port, type=socket.SOCK_STREAM)
    if not addresses or len(addresses) > 32:
        raise C8SecurityInputError("Target did not resolve safely.")
    if any(not _c8_egress_address_allowed(info[4][0]) for info in addresses):
        raise C8SecurityInputError("Web target resolves to a protected network address.")
    last_error = None
    end = time.monotonic() + min(60.0, max(0.1, float(timeout or 10.0)))
    for family, socktype, proto, _, sockaddr in addresses:
        sock = socket.socket(family, socktype, proto)
        try:
            left = end - time.monotonic()
            if left <= 0:
                raise TimeoutError("Outbound connection deadline exceeded.")
            sock.settimeout(left)
            # Connect to the already validated numeric address: no second DNS lookup.
            sock.connect(sockaddr)
            return sock
        except OSError as exc:
            last_error = exc
            sock.close()
    raise OSError("Unable to connect to web target.") from last_error


class _C8PublicHTTPConnection(http.client.HTTPConnection):
    def connect(self):
        if self._tunnel_host:
            raise C8SecurityInputError("Outbound proxy tunneling is disabled.")
        self.sock = _c8_open_egress_socket(self.host, self.port, self.timeout)


class _C8PublicHTTPSConnection(http.client.HTTPSConnection):
    def connect(self):
        if self._tunnel_host:
            raise C8SecurityInputError("Outbound proxy tunneling is disabled.")
        raw = _c8_open_egress_socket(self.host, self.port, self.timeout)
        try:
            self.sock = self._context.wrap_socket(raw, server_hostname=self.host)
        except BaseException:
            raw.close()
            raise


class _C8PublicHTTPHandler(urllib.request.HTTPHandler):
    def http_open(self, req):
        return self.do_open(_C8PublicHTTPConnection, req)


class _C8PublicHTTPSHandler(urllib.request.HTTPSHandler):
    def https_open(self, req):
        return self.do_open(_C8PublicHTTPSConnection, req, context=self._context)


class _C8EgressRequestGuard(urllib.request.BaseHandler):
    handler_order = 100

    def default_open(self, req):
        self._check(req)
        return None

    def _check(self, req):
        url = req.full_url
        if len(url) > 8192 or re.search(r"[\x00-\x20\x7f\\]", url):
            raise C8SecurityInputError("Invalid outbound URL.")
        p = urllib.parse.urlsplit(url)
        if p.scheme not in {"http", "https"} or p.fragment:
            raise C8SecurityInputError("Only HTTP and HTTPS web targets are supported.")
        _c8_authority(p.netloc)
        return req

    http_request = https_request = _check

    def _response(self, req, response):
        if response.code in {301, 302, 303, 307, 308}:
            location = response.headers.get("Location") or response.headers.get("URI")
            if location:
                new = urllib.parse.urljoin(req.full_url, location)
                oldp, newp = urllib.parse.urlsplit(req.full_url), urllib.parse.urlsplit(new)
                if oldp.scheme == "https" and newp.scheme != "https":
                    response.close()
                    raise C8SecurityInputError("HTTPS downgrade redirects are blocked.")
                old_origin = _c8_origin(oldp.scheme + "://" + oldp.netloc)
                new_origin = _c8_origin(newp.scheme + "://" + newp.netloc)
                if old_origin != new_origin:
                    # Preserve credential-bearing API requests by refusing to forward them.
                    credential_headers = {"authorization", "proxy-authorization", "cookie", "x-api-key", "api-key", "key", "x-c8-internal-token", "x-c8-internal-signature"}
                    for name, _ in req.header_items():
                        if name.lower() in credential_headers:
                            response.close()
                            raise C8SecurityInputError("Credential-bearing cross-origin redirect blocked.")
                    for name in list(req.headers):
                        if name.lower().startswith("x-c8-"):
                            req.remove_header(name)
        return _C8BoundedHTTPResponse(response)

    http_response = https_response = _response


def _c8_build_opener(*handlers, context=None):
    # Environment proxies and caller-supplied TLS bypasses must not bypass destination checks.
    context = context or ssl.create_default_context()
    if context.verify_mode != ssl.CERT_REQUIRED or not context.check_hostname:
        context = ssl.create_default_context()
    clean = [h for h in handlers if not isinstance(h, (urllib.request.ProxyHandler, urllib.request.HTTPHandler, urllib.request.HTTPSHandler))]
    return urllib.request.build_opener(urllib.request.ProxyHandler({}), _C8PublicHTTPHandler(), _C8PublicHTTPSHandler(context=context), _C8EgressRequestGuard(), *clean)


def _c8_urlopen(url, data=None, timeout=10.0, *, context=None):
    address = url.full_url if isinstance(url, urllib.request.Request) else str(url)
    if urllib.parse.urlsplit(address).scheme not in {"http", "https"}:
        raise C8SecurityInputError("Only HTTP and HTTPS web targets are supported.")
    return _c8_build_opener(context=context).open(url, data=data, timeout=min(60.0, max(0.1, float(timeout))))


class _C8BoundedHTTPResponse:
    def __init__(self, response):
        self.response = response
        self.remaining = 16 * 1024 * 1024
        self.deadline = time.monotonic() + 45.0

    def __getattr__(self, name):
        return getattr(self.response, name)

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.response.close()

    def read(self, size=-1):
        maximum = self.remaining if size is None or size < 0 else min(int(size), self.remaining)
        result = bytearray()
        while len(result) < maximum:
            left = self.deadline - time.monotonic()
            if left <= 0:
                self.response.close()
                raise TimeoutError("Outbound response read deadline exceeded.")
            fp = getattr(self.response, "fp", None)
            sock = getattr(getattr(fp, "raw", None), "_sock", None)
            if sock is not None:
                sock.settimeout(min(10.0, left))
            part = self.response.read1(min(65536, maximum - len(result)))
            if not part:
                break
            result.extend(part)
        self.remaining -= len(result)
        if self.remaining == 0:
            self.response.close()
            raise C8SecurityInputError("Outbound response exceeded the byte budget.")
        return bytes(result)


class _C8RequestsAdapter:
    """Small requests-compatible surface used by the embedded IP analysis providers."""

    def request(self, method, url, **kwargs):
        params = kwargs.get("params")
        if params:
            url += ("&" if "?" in url else "?") + urllib.parse.urlencode(params, doseq=True)
        headers = dict(kwargs.get("headers") or {})
        data = kwargs.get("data")
        if kwargs.get("json") is not None:
            data = json.dumps(kwargs["json"]).encode("utf-8")
            headers.setdefault("Content-Type", "application/json")
        elif isinstance(data, dict):
            data = urllib.parse.urlencode(data).encode("utf-8")
        elif isinstance(data, str):
            data = data.encode("utf-8")
        timeout = kwargs.get("timeout", 10.0)
        if isinstance(timeout, tuple):
            timeout = max(timeout)
        req = urllib.request.Request(url, data=data, headers=headers, method=method)
        try:
            response = _c8_urlopen(req, timeout=timeout)
        except urllib.error.HTTPError as exc:
            response = exc
        with response:
            raw = response.read(4 * 1024 * 1024 + 1)
            if len(raw) > 4 * 1024 * 1024:
                raise C8SecurityInputError("Provider response is too large.")
            class Result:
                def json(self):
                    return json.loads(self.text)
                def raise_for_status(self):
                    if self.status_code >= 400:
                        raise RuntimeError("Provider returned an HTTP error.")
            result = Result()
            result.status_code = int(response.code)
            result.ok = result.status_code < 400
            result.content = raw
            result.text = raw.decode("utf-8", "replace")
            result.headers = response.headers
            result.url = response.geturl()
            return result

    def get(self, url, **kwargs):
        return self.request("GET", url, **kwargs)

    def post(self, url, **kwargs):
        return self.request("POST", url, **kwargs)


_C8_LOCAL_KEY_LOCK = threading.RLock()


def _c8_read_secret(path):
    fd = os.open(str(path), os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0))
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_size > 8192:
            raise RuntimeError("Secret file must be a small regular file.")
        if os.name != "nt" and info.st_mode & 0o077:
            os.fchmod(fd, 0o600)
        return os.read(fd, 8193)
    finally:
        os.close(fd)


def _c8_load_existing_key(path):
    path = Path(path)
    if path.is_symlink() or path.parent.is_symlink():
        raise RuntimeError("Secret paths must not be symbolic links.")
    raw = _c8_read_secret(path)
    if raw.startswith(_LOCAL_STATE_DPAPI_MAGIC):
        key = _windows_dpapi_transform(base64.b64decode(raw[len(_LOCAL_STATE_DPAPI_MAGIC):].strip(), validate=True), protect=False)
    elif len(raw) == 32:
        key = raw  # A binary key may legitimately start/end with whitespace bytes.
    else:
        try:
            key = base64.b64decode(raw.strip(), validate=True)
        except (ValueError, binascii.Error):
            raise RuntimeError("Existing encryption key is invalid; restore it from backup.") from None
    if len(key) != 32:
        raise RuntimeError("Existing encryption key is invalid; it was not replaced.")
    return key


def _c8_load_or_create_key(path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    if path.is_symlink() or path.parent.is_symlink():
        raise RuntimeError("Secret paths must not be symbolic links.")
    if not path.exists():
        key = secrets.token_bytes(32)
        stage = path.with_name(path.name + ".new-" + secrets.token_hex(12))
        try:
            _atomic_write_secret(stage, _local_key_storage_bytes(key))
            try:
                # Publish complete key bytes once, without replacing another process's key.
                os.link(stage, path)
            except FileExistsError:
                pass
        finally:
            stage.unlink(missing_ok=True)
    return _c8_load_existing_key(path)


def _c8_security_log_text(value):
    return re.sub(r"[\x00-\x1f\x7f-\x9f]", "?", str(value))[:1500]


def _c8_safe_error(exc):
    # Driver, filesystem and upstream messages can contain paths, SQL or credentials.
    if isinstance(exc, C8SecurityInputError):
        return 400, str(exc)
    if isinstance(exc, PermissionError):
        return 403, "The operation is not permitted."
    if isinstance(exc, (ValueError, TypeError, KeyError, OverflowError)):
        return 400, "Invalid request data. Check the supplied values."
    if isinstance(exc, (TimeoutError, socket.timeout)):
        return 408, "The operation timed out."
    return 500, "The operation failed. Consult the server security log using the request ID."


