# ============================================================================
# MEMORY PROFILE / OOM PROTECTION
# ============================================================================
def _c8_detect_memory_limit_bytes() -> int:
    """Best-effort effective RAM limit, including Linux cgroup limits."""
    candidates: List[int] = []
    for raw_path in (
        "/sys/fs/cgroup/memory.max",                    # cgroup v2
        "/sys/fs/cgroup/memory/memory.limit_in_bytes", # cgroup v1
    ):
        try:
            raw = Path(raw_path).read_text(encoding="ascii", errors="ignore").strip()
            if raw and raw.lower() != "max":
                value = int(raw)
                # Ignore cgroup sentinel values that effectively mean unlimited.
                if 64 * 1024 * 1024 <= value <= 64 * 1024**4:
                    candidates.append(value)
        except Exception:
            pass
    try:
        with open("/proc/meminfo", "r", encoding="ascii", errors="ignore") as fh:
            for line in fh:
                if line.startswith("MemTotal:"):
                    candidates.append(int(line.split()[1]) * 1024)
                    break
    except Exception:
        pass
    try:
        pages = int(os.sysconf("SC_PHYS_PAGES"))
        page_size = int(os.sysconf("SC_PAGE_SIZE"))
        value = pages * page_size
        if value > 0:
            candidates.append(value)
    except Exception:
        pass
    return min(candidates) if candidates else 0


