_C8_HEAVY_ACTIVE_LOCK = threading.RLock()
_C8_HEAVY_ACTIVE: Dict[int, Dict[str, Any]] = {}
_C8_MEMORY_WATCHDOG_STARTED = False
_C8_MEMORY_WATCHDOG_LOCK = threading.Lock()


def _c8_current_rss_bytes() -> int:
    """Return current resident memory on Linux without importing psutil."""
    try:
        with open("/proc/self/status", "r", encoding="ascii", errors="ignore") as fh:
            for line in fh:
                if line.startswith("VmRSS:"):
                    return max(0, int(line.split()[1])) * 1024
    except Exception:
        pass
    return 0


def _c8_trim_memory() -> None:
    """Best-effort Python GC + glibc heap trim after large transient jobs."""
    try:
        gc.collect()
    except Exception:
        pass
    if sys.platform.startswith("linux"):
        try:
            import ctypes
            libc = ctypes.CDLL(None)
            trim = getattr(libc, "malloc_trim", None)
            if trim is not None:
                trim(0)
        except Exception:
            pass


def _c8_effective_memory_usage_bytes() -> Tuple[int, int]:
    """Return (used, limit) for the process cgroup when available, otherwise host RAM.

    Looking only at this Python process misses MySQL, the kernel page cache, and other
    services on a 1 GB VPS. Linux OOM decisions are based on the whole memory domain,
    so admission control needs the same broader view.
    """
    limit = int(C8_MEMORY_LIMIT_BYTES or 0)
    for raw_path in (
        "/sys/fs/cgroup/memory.current",
        "/sys/fs/cgroup/memory/memory.usage_in_bytes",
    ):
        try:
            raw = Path(raw_path).read_text(encoding="ascii", errors="ignore").strip()
            used = int(raw)
            if used >= 0 and limit > 0:
                return used, limit
        except Exception:
            pass
    try:
        mem_total = 0
        mem_available = 0
        with open("/proc/meminfo", "r", encoding="ascii", errors="ignore") as fh:
            for line in fh:
                if line.startswith("MemTotal:"):
                    mem_total = int(line.split()[1]) * 1024
                elif line.startswith("MemAvailable:"):
                    mem_available = int(line.split()[1]) * 1024
                if mem_total and mem_available:
                    break
        if mem_total:
            effective = min(mem_total, limit) if limit else mem_total
            # If the process is not cgroup constrained, host used memory is the best
            # predictor of an imminent OOM kill.
            used = max(0, mem_total - mem_available)
            if effective < mem_total:
                used = min(effective, max(_c8_current_rss_bytes(), used - (mem_total - effective)))
            return used, effective
    except Exception:
        pass
    rss = _c8_current_rss_bytes()
    return rss, limit


def _c8_memory_snapshot() -> Dict[str, Any]:
    used, limit = _c8_effective_memory_usage_bytes()
    rss = _c8_current_rss_bytes()
    ratio = (float(used) / float(limit)) if used > 0 and limit > 0 else 0.0
    return {"rss_bytes": rss, "domain_used_bytes": used, "limit_bytes": limit, "domain_ratio": round(ratio, 4)}


def _c8_memory_pressure(level: float = 0.72) -> bool:
    used, limit = _c8_effective_memory_usage_bytes()
    if not limit:
        return False
    threshold = int(limit * max(0.40, min(0.95, level)))
    return bool(used and used >= threshold)


def _c8_clear_soft_caches() -> None:
    """Drop recreatable caches before Linux has to choose a process to SIGKILL."""
    for name in ("_DOME_SNAPSHOT_CACHE", "_DOME_LOOKUP_CACHE", "_OSINT_PUBLIC_CACHE", "_IPF_RESULT_CACHE"):
        try:
            obj = globals().get(name)
            if isinstance(obj, dict):
                obj.clear()
        except Exception:
            pass
    # The embedded IP Forensics namespace is expensive. On small VPS hosts it is
    # safer to recompile on the next IPF run than to keep it resident indefinitely.
    if C8_LOW_MEMORY_MODE:
        try:
            lock = globals().get("_MAIN_MENU_IPF_LOCK")
            if not (lock is not None and getattr(lock, "locked", lambda: False)()):
                if "_MAIN_MENU_IPF_ENGINE_NS" in globals():
                    globals()["_MAIN_MENU_IPF_ENGINE_NS"] = None
        except Exception:
            pass


def _c8_memory_watchdog_worker() -> None:
    while True:
        time.sleep(5.0 if C8_LOW_MEMORY_MODE else 20.0)
        try:
            threshold = 0.60 if C8_ULTRA_LOW_MEMORY_MODE else (0.70 if C8_LOW_MEMORY_MODE else 0.82)
            if _c8_memory_pressure(threshold):
                _c8_clear_soft_caches()
                _c8_trim_memory()
        except Exception:
            pass


def _c8_start_memory_watchdog() -> None:
    global _C8_MEMORY_WATCHDOG_STARTED
    with _C8_MEMORY_WATCHDOG_LOCK:
        if _C8_MEMORY_WATCHDOG_STARTED:
            return
        _C8_MEMORY_WATCHDOG_STARTED = True
        threading.Thread(target=_c8_memory_watchdog_worker, daemon=True, name="c8-memory-watchdog").start()


@contextmanager
def _c8_heavy_operation(name: str, wait_seconds: Optional[float] = None):
    """Serialize high-RAM jobs with a bounded queue and memory-pressure guard.

    r49 gives IP Forensics a longer queue window while moving bounded crawler/archive
    work out of this high-RAM lane.  This avoids false "busy" failures without
    allowing multiple RAM-heavy analyzers to pile up on small VPS hosts.
    """
    pressure_level = 0.66 if C8_ULTRA_LOW_MEMORY_MODE else (0.74 if C8_LOW_MEMORY_MODE else 0.84)
    if _c8_memory_pressure(pressure_level):
        _c8_clear_soft_caches()
        _c8_trim_memory()
        # Give transient post-job allocations a moment to return to the allocator.
        for _ in range(4):
            if not _c8_memory_pressure(pressure_level):
                break
            time.sleep(0.25)
            _c8_trim_memory()
        if _c8_memory_pressure(pressure_level):
            raise RuntimeError(
                "The server is under memory pressure. Current work must finish before another high-memory analyzer can start."
            )

    if wait_seconds is None:
        wait_seconds = C8_HEAVY_OPERATION_WAIT_SECONDS
    try:
        wait_seconds = max(0.0, min(300.0, float(wait_seconds)))
    except Exception:
        wait_seconds = C8_HEAVY_OPERATION_WAIT_SECONDS

    deadline = time.monotonic() + wait_seconds
    acquired = False
    # Acquire in short slices instead of one opaque semaphore wait. This lets us
    # reclaim soft caches while queued and keeps the wait responsive to shutdown.
    while True:
        remaining = max(0.0, deadline - time.monotonic())
        if wait_seconds <= 0:
            acquired = _C8_HEAVY_OPERATION_SEMAPHORE.acquire(blocking=False)
            break
        acquired = _C8_HEAVY_OPERATION_SEMAPHORE.acquire(timeout=min(1.0, remaining))
        if acquired or remaining <= 0.0:
            break
        if C8_LOW_MEMORY_MODE:
            _c8_clear_soft_caches()
            _c8_trim_memory()

    if not acquired:
        with _C8_HEAVY_ACTIVE_LOCK:
            active = sorted(
                (dict(item) for item in _C8_HEAVY_ACTIVE.values()),
                key=lambda item: float(item.get("started_monotonic") or 0.0),
            )
        active_names = ", ".join(str(item.get("name") or "operation") for item in active[:3]) or "another high-memory operation"
        raise RuntimeError(
            f"{name} is queued behind {active_names} and could not obtain the high-memory slot within {wait_seconds:g} seconds. "
            "The request was not started; retry after the active analyzer finishes."
        )

    marker = id(threading.current_thread()) ^ int(time.monotonic_ns() & 0x7fffffff)
    with _C8_HEAVY_ACTIVE_LOCK:
        _C8_HEAVY_ACTIVE[marker] = {
            "name": str(name or "operation")[:120],
            "started_at": time.time(),
            "started_monotonic": time.monotonic(),
            "thread": threading.current_thread().name[:120],
        }
    try:
        yield
    finally:
        with _C8_HEAVY_ACTIVE_LOCK:
            _C8_HEAVY_ACTIVE.pop(marker, None)
        if C8_LOW_MEMORY_MODE:
            _c8_clear_soft_caches()
        _c8_trim_memory()
        _C8_HEAVY_OPERATION_SEMAPHORE.release()


@contextmanager
def _c8_bounded_network_operation(name: str):
    """Bound network-intensive scanners without occupying the global high-RAM slot.

    Site Forensics already caps pages and response bodies on small VPS
    hosts, so it can safely use this independent lane while IP Forensics or a file
    operation holds the high-RAM semaphore. RAM pressure is still checked first.
    """
    pressure_level = 0.64 if C8_ULTRA_LOW_MEMORY_MODE else (0.72 if C8_LOW_MEMORY_MODE else 0.86)
    if _c8_memory_pressure(pressure_level):
        _c8_clear_soft_caches()
        _c8_trim_memory()
        if _c8_memory_pressure(pressure_level):
            raise RuntimeError(
                f"The server is under memory pressure, so {name} was not started. Try again after current work finishes."
            )
    wait_seconds = C8_NETWORK_OPERATION_WAIT_SECONDS
    acquired = _C8_NETWORK_OPERATION_SEMAPHORE.acquire(
        blocking=bool(wait_seconds > 0),
        timeout=wait_seconds if wait_seconds > 0 else None,
    ) if wait_seconds > 0 else _C8_NETWORK_OPERATION_SEMAPHORE.acquire(blocking=False)
    if not acquired:
        raise RuntimeError(
            f"Another bounded website/network assessment is still running. {name} waited {wait_seconds:g} seconds for a slot; try again shortly."
        )
    try:
        yield
    finally:
        _c8_trim_memory()
        _C8_NETWORK_OPERATION_SEMAPHORE.release()

