ICMP_SERIES_GAP_SECONDS = max(0.03, min(0.5, float(os.environ.get("LL_WEB_ICMP_SERIES_GAP_SECONDS", "0.12") or "0.12")))
ICMP_CONTINUOUS_REPEAT_DEFAULT = max(10, min(ICMP_FAST_REPEAT_MAX, int(os.environ.get("LL_WEB_ICMP_CONTINUOUS_REPEAT", "60") or "60")))
