ICMP_MAX_WORKERS_DEFAULT = int(os.environ.get("LL_WEB_ICMP_MAX_WORKERS", "4" if C8_ULTRA_LOW_MEMORY_MODE else ("12" if C8_LOW_MEMORY_MODE else "64")))
ICMP_TCP_SCAN_WORKERS_DEFAULT = int(os.environ.get("LL_WEB_ICMP_TCP_SCAN_WORKERS", "16" if C8_ULTRA_LOW_MEMORY_MODE else ("32" if C8_LOW_MEMORY_MODE else "256")))
ICMP_UDP_SCAN_WORKERS_DEFAULT = int(os.environ.get("LL_WEB_ICMP_UDP_SCAN_WORKERS", "12" if C8_ULTRA_LOW_MEMORY_MODE else ("24" if C8_LOW_MEMORY_MODE else "256")))
ICMP_FULL_RANGE_MAX_HOSTS = max(1, min(16, int(os.environ.get("LL_WEB_ICMP_FULL_RANGE_MAX_HOSTS", "2" if C8_ULTRA_LOW_MEMORY_MODE else ("4" if C8_LOW_MEMORY_MODE else "8")))))
