IPF_FAST_MODE = os.environ.get("LL_WEB_IPF_FAST_MODE", "1").strip().lower() not in {"0", "false", "no", "off"}
IPF_API_TIMEOUT_SECONDS = max(1.5, min(12.0, float(os.environ.get("LL_WEB_IPF_API_TIMEOUT", "3.5" if IPF_FAST_MODE else "8.0") or ("3.5" if IPF_FAST_MODE else "8.0"))))
IPF_PROBE_TIMEOUT_SECONDS = max(0.25, min(2.0, float(os.environ.get("LL_WEB_IPF_PROBE_TIMEOUT", "0.70" if IPF_FAST_MODE else "1.2") or ("0.70" if IPF_FAST_MODE else "1.2"))))
# Full TCP verification stays exhaustive (1-65535), but r81 raises bounded
# concurrency and shortens per-port waits. Closed/filtered ports therefore finish
# much sooner without changing the target scope or adding exploit traffic.
_IPF_WORKERS_DEFAULT = "32" if C8_ULTRA_LOW_MEMORY_MODE else ("64" if C8_LOW_MEMORY_MODE else ("384" if IPF_FAST_MODE else "256"))
_IPF_INFLIGHT_DEFAULT = "512" if C8_ULTRA_LOW_MEMORY_MODE else ("1024" if C8_LOW_MEMORY_MODE else ("8192" if IPF_FAST_MODE else "4096"))
