def _apply_inline_api_keys() -> None:
    """Apply optional keys from the clearly marked setup block above.

    Existing process/.env values win, so operators can safely leave the inline
    strings blank and manage secrets outside the source file.
    """
    pairs = (
        ("VIRUSTOTAL_API_KEY", C8_VIRUSTOTAL_API_KEY),
        ("ABUSEIPDB_API_KEY", C8_ABUSEIPDB_API_KEY),
        ("GREYNOISE_API_KEY", C8_GREYNOISE_API_KEY),
        ("GREYNOISE_COMMUNITY_API_KEY", C8_GREYNOISE_COMMUNITY_API_KEY),
        ("IPHUB_API_KEY", C8_IPHUB_API_KEY),
        ("APILAYER_API_KEY", C8_APILAYER_API_KEY),
        ("GLOBALPING_API_KEY", C8_GLOBALPING_API_KEY),
    )
    for env_name, configured_value in pairs:
        value = str(configured_value or "").strip()
        if value and not str(os.environ.get(env_name) or "").strip():
            os.environ[env_name] = value


_apply_inline_api_keys()

