# Runtime storage is local to the current machine/user. No data is sent elsewhere except
# optional single-target public OSINT/RDAP lookups initiated by the user.
def _runtime_dir() -> Path:
    try:
        configured = os.environ.get("LL_WEB_RUNTIME_DIR", "").strip()
        base = Path(configured).expanduser() if configured else Path.home() / ".gov_style_console_powered"
    except Exception:
        base = Path(tempfile.gettempdir()) / "gov_style_console_powered"
    base.mkdir(parents=True, exist_ok=True)
    try:
        os.chmod(base, 0o700)
    except Exception:
        pass
    return base

