_PYMYSQL_BOOTSTRAP_SHA256 = (
    "62169ce6d5510f08e140c5e7990ee884a9764024e4a9a27b2cc11f1099322ae0"
)
_PYMYSQL_BOOTSTRAP_MAX_DOWNLOAD = 2 * 1024 * 1024
_PYMYSQL_BOOTSTRAP_MAX_EXTRACTED = 8 * 1024 * 1024


def _mysql_auto_install_enabled() -> bool:
    # The old per-driver switch may remain disabled in a copied .env file.
    # Required drivers are installed by default; only the new global switch
    # explicitly disables dependency installation.
    raw = str(os.environ.get("LL_WEB_AUTO_INSTALL_DEPS", "1") or "1").strip().lower()
    return raw not in {"0", "false", "no", "off", "disabled"}


def _activate_mysql_dependency_dir() -> None:
    """Make locally installed MySQL drivers importable without changing system Python."""
    try:
        MYSQL_DEPENDENCY_DIR.mkdir(parents=True, exist_ok=True)
        dep_path = str(MYSQL_DEPENDENCY_DIR.resolve())
        if dep_path not in sys.path:
            sys.path.insert(0, dep_path)
    except Exception:
        pass


_activate_mysql_dependency_dir()


_C8_PYTHON_PACKAGES = {
    "cryptography": ("cryptography", "cryptography==50.0.1"),
    "Pillow": ("PIL", "Pillow==12.3.0"),
    "pypdf": ("pypdf", "pypdf==6.18.0"),
    "bcrypt": ("bcrypt", "bcrypt==5.0.0"),
    "scapy": ("scapy.all", "scapy==2.7.0"),
    "reedsolo": ("reedsolo", "reedsolo==1.7.0"),
}
_C8_PY_DEP_LOCK = threading.Lock()
_C8_PY_DEP_FAILURES: Dict[str, str] = {}


def _c8_install_python_dependency(package: str, *, force: bool = False) -> Tuple[bool, str]:
    """Install a known missing package into the private runtime directory."""
    if package not in _C8_PYTHON_PACKAGES:
        raise ValueError("Unsupported automatic Python dependency.")
    module_name, requirement = _C8_PYTHON_PACKAGES[package]
    import importlib
    _activate_mysql_dependency_dir()
    if not force:
        try:
            importlib.import_module(module_name)
            return True, ""
        except Exception:
            pass
    if not _mysql_auto_install_enabled():
        return False, "Automatic Python dependency installation is disabled by LL_WEB_AUTO_INSTALL_DEPS=0."

    with _C8_PY_DEP_LOCK:
        if package in _C8_PY_DEP_FAILURES:
            return False, _C8_PY_DEP_FAILURES[package]
        if not force:
            try:
                importlib.import_module(module_name)
                return True, ""
            except Exception:
                pass
        print(f"Python dependency auto-setup: installing {requirement} locally...", flush=True)
        try:
            MYSQL_DEPENDENCY_DIR.mkdir(mode=0o700, parents=True, exist_ok=True)
        except OSError as exc:
            note = f"Cannot create the private Python dependency directory: {exc}"
            _C8_PY_DEP_FAILURES[package] = note
            return False, note

        args = [
            "install", "--disable-pip-version-check", "--no-input", "--no-compile",
            "--no-warn-script-location", "--only-binary=:all:", "--upgrade",
            "--timeout", "15", "--retries", "1", "--index-url", "https://pypi.org/simple",
            "--target", str(MYSQL_DEPENDENCY_DIR), requirement,
        ]
        commands = [([sys.executable, "-m", "pip", "--isolated", *args], None)]
        for pip_path in (shutil.which("pip3"), shutil.which("pip")):
            if pip_path:
                commands.append(([pip_path, "--isolated", "--python", sys.executable, *args], None))
        try:
            import ensurepip
            pip_wheels = sorted((Path(ensurepip.__file__).parent / "_bundled").glob("pip-*.whl"))
            if pip_wheels:
                commands.append((
                    [sys.executable, "-m", "pip", "--isolated", *args],
                    {**os.environ, "PYTHONPATH": str(pip_wheels[-1])},
                ))
        except (ImportError, AttributeError, OSError):
            pass

        failures = []
        if len(commands) == 1:
            try:
                pip_missing = importlib.util.find_spec("pip") is None
            except (ImportError, AttributeError, ValueError):
                pip_missing = False
            apt = shutil.which("apt-get")
            if pip_missing and apt and getattr(os, "geteuid", lambda: 1)() == 0:
                print("Python dependency auto-setup: installing pip with apt-get...", flush=True)
                apt_env = {**os.environ, "DEBIAN_FRONTEND": "noninteractive"}
                for apt_args in (["update"], ["install", "-y", "python3-pip"]):
                    try:
                        with tempfile.TemporaryFile() as log:
                            apt_result = subprocess.run(
                                [apt, *apt_args], stdin=subprocess.DEVNULL,
                                stdout=log, stderr=subprocess.STDOUT,
                                timeout=300, check=False, env=apt_env,
                            )
                            log.seek(max(0, log.tell() - 500))
                            apt_note = log.read().decode("utf-8", "replace").strip()
                        if apt_result.returncode:
                            failures.append(f"apt-get {apt_args[0]}: {apt_note[-350:]}")
                            break
                    except (OSError, subprocess.TimeoutExpired) as exc:
                        failures.append(f"apt-get {apt_args[0]}: {exc}")
                        break
                else:
                    importlib.invalidate_caches()
                    installed_pip = shutil.which("pip3") or shutil.which("pip")
                    if installed_pip:
                        commands.append((
                            [installed_pip, "--isolated", "--python", sys.executable, *args],
                            None,
                        ))
        for command, extra_env in commands:
            try:
                with tempfile.TemporaryFile() as log:
                    result = subprocess.run(
                        command, stdin=subprocess.DEVNULL, stdout=log,
                        stderr=subprocess.STDOUT, timeout=180, check=False, env=extra_env,
                    )
                    log.seek(max(0, log.tell() - 1500))
                    output = log.read().decode("utf-8", "replace").strip()
                if result.returncode:
                    failures.append((output.splitlines()[-1] if output else f"exit code {result.returncode}")[:400])
                    continue
                importlib.invalidate_caches()
                _activate_mysql_dependency_dir()
                # An older system package may already be imported. A clean
                # import of the new package happens on the next startup.
                if force and module_name == "cryptography":
                    for loaded in list(sys.modules):
                        if loaded == "cryptography" or loaded.startswith("cryptography."):
                            sys.modules.pop(loaded, None)
                importlib.import_module(module_name)
                print(f"Python dependency auto-setup: {package} ready.", flush=True)
                return True, ""
            except subprocess.TimeoutExpired:
                failures.append("installation timed out")
            except Exception as exc:
                failures.append(f"{type(exc).__name__}: {exc}"[:400])
        note = (
            f"{requirement} could not be installed with the running Python "
            f"({sys.executable}). " + " | ".join(failures[-3:])
        )[:1300]
        _C8_PY_DEP_FAILURES[package] = note
        return False, note


def _c8_ensure_crypto_runtime() -> str:
    """Restore encryption and Argon2id when the system Python lacks them."""
    global AESGCM, Argon2id
    if AESGCM is not None and Argon2id is not None:
        return ""
    ready, reason = _c8_install_python_dependency("cryptography", force=True)
    if not ready:
        return reason
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM as _AESGCM
        from cryptography.hazmat.primitives.kdf.argon2 import Argon2id as _Argon2id
        AESGCM, Argon2id = _AESGCM, _Argon2id
        # These imports occur before main(), so refresh the feature references
        # if cryptography was installed during this launch.
        from cryptography.hazmat.primitives import hashes as _hashes
        from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC as _PBKDF2HMAC
        from cryptography.hazmat.primitives.kdf.scrypt import Scrypt as _Scrypt
        globals().update({
            "_steg_hashes": _hashes,
            "_StegPBKDF2HMAC": _PBKDF2HMAC,
            "_StegScrypt": _Scrypt,
            "_STEG_CRYPTO_KDF_AVAILABLE": True,
        })
        return ""
    except Exception as exc:
        return f"cryptography installed but cannot load AESGCM and Argon2id: {exc}"


def _mysql_driver_available() -> bool:
    try:
        import importlib
        for module_name in ("mysql.connector", "pymysql", "MySQLdb"):
            try:
                importlib.import_module(module_name)
                return True
            except Exception:
                continue
    except Exception:
        pass
    return False


def _bootstrap_pymysql_without_pip() -> str:
    """Install pinned pure-Python PyMySQL with only the Python standard library."""
    if sys.version_info < (3, 9):
        raise RuntimeError(
            f"PyMySQL {_PYMYSQL_BOOTSTRAP_VERSION} requires Python 3.9 or newer."
        )
    request = urllib.request.Request(
        _PYMYSQL_BOOTSTRAP_URL,
        headers={
            "Accept": "application/octet-stream",
            "User-Agent": f"C-8-Console/{APP_VERSION} dependency-bootstrap",
        },
        method="GET",
    )
    tls_context = ssl.create_default_context()
    with _c8_urlopen(request, timeout=60, context=tls_context) as response:
        content_length = int(response.headers.get("Content-Length") or 0)
        if content_length > _PYMYSQL_BOOTSTRAP_MAX_DOWNLOAD:
            raise RuntimeError("The pinned PyMySQL wheel exceeds the download limit.")
        wheel_data = response.read(_PYMYSQL_BOOTSTRAP_MAX_DOWNLOAD + 1)
    if len(wheel_data) > _PYMYSQL_BOOTSTRAP_MAX_DOWNLOAD:
        raise RuntimeError("The pinned PyMySQL wheel exceeds the download limit.")
    actual_sha256 = hashlib.sha256(wheel_data).hexdigest()
    if not secrets.compare_digest(actual_sha256, _PYMYSQL_BOOTSTRAP_SHA256):
        raise RuntimeError(
            "The downloaded PyMySQL wheel failed SHA-256 verification."
        )

    MYSQL_DEPENDENCY_DIR.mkdir(parents=True, exist_ok=True)
    dependency_root = MYSQL_DEPENDENCY_DIR.resolve()
    with tempfile.TemporaryDirectory(
        prefix=".pymysql-bootstrap-",
        dir=str(dependency_root.parent),
    ) as temporary_dir:
        staging_root = Path(temporary_dir).resolve()
        extracted_size = 0
        extracted_files = 0
        with zipfile.ZipFile(BytesIO(wheel_data), "r") as archive:
            for member in archive.infolist():
                name = str(member.filename or "").replace("\\", "/")
                if member.is_dir() or not name.startswith("pymysql/"):
                    continue
                parts = tuple(part for part in name.split("/") if part)
                if (
                    not parts
                    or parts[0] != "pymysql"
                    or any(part in {".", ".."} for part in parts)
                ):
                    raise RuntimeError("The PyMySQL wheel contains an unsafe path.")
                extracted_size += max(0, int(member.file_size))
                if extracted_size > _PYMYSQL_BOOTSTRAP_MAX_EXTRACTED:
                    raise RuntimeError("The PyMySQL wheel exceeds the extraction limit.")
                target = staging_root.joinpath(*parts).resolve()
                if os.path.commonpath((str(staging_root), str(target))) != str(staging_root):
                    raise RuntimeError("The PyMySQL wheel contains an unsafe target.")
                target.parent.mkdir(parents=True, exist_ok=True)
                with archive.open(member, "r") as source, target.open("xb") as destination:
                    shutil.copyfileobj(source, destination, length=128 * 1024)
                extracted_files += 1
        staged_package = staging_root / "pymysql"
        if extracted_files < 5 or not (staged_package / "__init__.py").is_file():
            raise RuntimeError("The pinned PyMySQL wheel is incomplete.")
        destination_package = dependency_root / "pymysql"
        if destination_package.exists():
            shutil.rmtree(destination_package)
        os.replace(staged_package, destination_package)
    try:
        os.chmod(dependency_root / "pymysql", 0o700)
    except OSError:
        pass
    import importlib
    importlib.invalidate_caches()
    _activate_mysql_dependency_dir()
    module = importlib.import_module("pymysql")
    version = str(
        getattr(module, "VERSION_STRING", "") or _PYMYSQL_BOOTSTRAP_VERSION
    )
    return (
        f"Installed PyMySQL {version} from a pinned SHA-256 verified wheel "
        f"in {MYSQL_DEPENDENCY_DIR} without pip."
    )


def _ensure_mysql_driver() -> str:
    """Install PyMySQL into the console runtime folder when no driver is available.

    Use the pinned, checksum-verified wheel first. If that download fails, try
    pip --target so Ubuntu's system Python remains untouched.
    """
    global _MYSQL_DEP_INSTALL_ATTEMPTED, _MYSQL_DEP_INSTALL_RESULT
    _activate_mysql_dependency_dir()
    if _mysql_driver_available():
        return ""
    if not _mysql_auto_install_enabled():
        return "MySQL driver auto-install is disabled by LL_WEB_AUTO_INSTALL_DEPS=0."

    with _MYSQL_DEP_INSTALL_LOCK:
        if _mysql_driver_available():
            return ""
        if _MYSQL_DEP_INSTALL_ATTEMPTED:
            return _MYSQL_DEP_INSTALL_RESULT
        _MYSQL_DEP_INSTALL_ATTEMPTED = True

        print(
            f"MySQL driver auto-setup: installing verified PyMySQL "
            f"{_PYMYSQL_BOOTSTRAP_VERSION} locally...",
            flush=True,
        )
        errors = []
        try:
            _MYSQL_DEP_INSTALL_RESULT = _bootstrap_pymysql_without_pip()
            print(f"MySQL driver auto-setup: {_MYSQL_DEP_INSTALL_RESULT}", flush=True)
            return _MYSQL_DEP_INSTALL_RESULT
        except Exception as exc:
            errors.append(f"pinned PyMySQL download failed: {exc}")

        install_commands = [
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                "--disable-pip-version-check",
                "--no-input",
                "--upgrade",
                "--target",
                str(MYSQL_DEPENDENCY_DIR),
                "PyMySQL>=1.1,<2",
            ]
        ]
        for executable in (shutil.which("pip3"), shutil.which("pip")):
            if executable:
                command = [
                    executable,
                    "install",
                    "--disable-pip-version-check",
                    "--no-input",
                    "--upgrade",
                    "--target",
                    str(MYSQL_DEPENDENCY_DIR),
                    "PyMySQL>=1.1,<2",
                ]
                if command not in install_commands:
                    install_commands.append(command)

        for command in install_commands:
            try:
                proc = subprocess.run(
                    command,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    timeout=240,
                    check=False,
                )
                output = str(proc.stdout or "").strip()
                if proc.returncode == 0:
                    try:
                        import importlib
                        importlib.invalidate_caches()
                        _activate_mysql_dependency_dir()
                        importlib.import_module("pymysql")
                        _MYSQL_DEP_INSTALL_RESULT = (
                            f"Installed PyMySQL locally in {MYSQL_DEPENDENCY_DIR}."
                        )
                        print(f"MySQL driver auto-setup: {_MYSQL_DEP_INSTALL_RESULT}", flush=True)
                        return _MYSQL_DEP_INSTALL_RESULT
                    except Exception as import_error:
                        errors.append(f"PyMySQL installed but import failed: {import_error}")
                else:
                    last_line = output.splitlines()[-1] if output else f"exit code {proc.returncode}"
                    errors.append(f"{' '.join(command[:3])}: {last_line[:500]}")
            except FileNotFoundError as exc:
                errors.append(str(exc))
            except subprocess.TimeoutExpired:
                errors.append("PyMySQL installation timed out after 240 seconds.")
            except Exception as exc:
                errors.append(f"PyMySQL installation failed: {exc}")

        _MYSQL_DEP_INSTALL_RESULT = (
            "No MySQL Python driver is installed, and both private installation methods failed. "
            "Set LL_WEB_MYSQL_DEPS_DIR to a writable directory with PyMySQL installed, "
            "or install python3-pymysql for the system Python. "
            + " | ".join(errors[:1] + errors[-2:])
        )
        return _MYSQL_DEP_INSTALL_RESULT
