# Heavy media libraries are loaded lazily. This saves tens of MB at normal server startup.
Image = None
ExifTags = None
ImageOps = None
PIL_AVAILABLE = False

_PIL_INSTALL_LOCK = threading.Lock()
_PIL_INSTALL_ATTEMPTED = False
_PIL_INSTALL_ERROR = ""

def _ensure_pillow_available(force_install: bool = False) -> bool:
    """Load Pillow lazily and optionally prepare it for a required image-security path."""
    global PIL_AVAILABLE, Image, ExifTags, ImageOps, _PIL_INSTALL_ATTEMPTED, _PIL_INSTALL_ERROR
    if PIL_AVAILABLE and Image is not None:
        return True
    with _PIL_INSTALL_LOCK:
        if PIL_AVAILABLE and Image is not None:
            return True
        try:
            import importlib
            importlib.invalidate_caches()
            from PIL import Image as _Image, ExifTags as _ExifTags, ImageOps as _ImageOps
            Image, ExifTags, ImageOps = _Image, _ExifTags, _ImageOps
            PIL_AVAILABLE = True
            _PIL_INSTALL_ERROR = ""
            return True
        except Exception as import_exc:
            _PIL_INSTALL_ERROR = f"{type(import_exc).__name__}: {import_exc}"[:1200]
        if not _PIL_INSTALL_ATTEMPTED:
            _PIL_INSTALL_ATTEMPTED = True
            ready, reason = _c8_install_python_dependency("Pillow", force=True)
            if ready:
                try:
                    from PIL import Image as _Image, ExifTags as _ExifTags, ImageOps as _ImageOps
                    Image, ExifTags, ImageOps = _Image, _ExifTags, _ImageOps
                    PIL_AVAILABLE = True
                    _PIL_INSTALL_ERROR = ""
                    return True
                except Exception as exc:
                    reason = f"Pillow installed but the image decoder could not load: {exc}"
            _PIL_INSTALL_ERROR = reason[:1200]
        PIL_AVAILABLE = False
        return False


PdfReader = None
PdfWriter = None
NameObject = None
PYPDF_AVAILABLE = False
_PYPDF_IMPORT_LOCK = threading.Lock()

def _ensure_pypdf_available() -> bool:
    global PYPDF_AVAILABLE, PdfReader, PdfWriter, NameObject
    if PYPDF_AVAILABLE and PdfReader is not None:
        return True
    with _PYPDF_IMPORT_LOCK:
        if PYPDF_AVAILABLE and PdfReader is not None:
            return True
        try:
            from pypdf import PdfReader as _PdfReader, PdfWriter as _PdfWriter
            from pypdf.generic import NameObject as _NameObject
            PdfReader, PdfWriter, NameObject = _PdfReader, _PdfWriter, _NameObject
            PYPDF_AVAILABLE = True
            return True
        except Exception:
            pass
        ready, _reason = _c8_install_python_dependency("pypdf", force=True)
        if ready:
            try:
                from pypdf import PdfReader as _PdfReader, PdfWriter as _PdfWriter
                from pypdf.generic import NameObject as _NameObject
                PdfReader, PdfWriter, NameObject = _PdfReader, _PdfWriter, _NameObject
                PYPDF_AVAILABLE = True
                return True
            except Exception:
                pass
        PYPDF_AVAILABLE = False
        return False



def _dome_atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_bytes(data)
    tmp.replace(path)


def _dome_cached_remote_bytes(
    url: str,
    cache_path: Path,
    *,
    ttl_seconds: int,
    timeout_seconds: float,
    max_bytes: int,
    expected_prefix: str = "",
) -> Tuple[bytes, bool, str]:
    """Return (data, stale_cache_used, upstream_content_type)."""
    now = time.time()
    stale_data: Optional[bytes] = None
    try:
        if cache_path.exists() and cache_path.is_file():
            age = max(0.0, now - cache_path.stat().st_mtime)
            if age <= max(1, int(ttl_seconds)):
                return cache_path.read_bytes(), False, ""
            stale_data = cache_path.read_bytes()
    except Exception:
        stale_data = None

    try:
        req = urllib.request.Request(
            url,
            headers={
                "User-Agent": "C-8-Dome/1.0 map-cache (+server operator)",
                "Accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
                "Accept-Encoding": "identity",
                "Referer": "https://www.openstreetmap.org/",
            },
        )
        with _c8_urlopen(req, timeout=max(2.0, float(timeout_seconds))) as response:
            status = int(getattr(response, "status", 200) or 200)
            if status < 200 or status >= 300:
                raise RuntimeError(f"upstream HTTP {status}")
            content_type = str(response.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
            data = response.read(int(max_bytes) + 1)
            if len(data) > int(max_bytes):
                raise RuntimeError("upstream response exceeded cache size limit")
            if not data:
                raise RuntimeError("upstream returned an empty response")
            if expected_prefix and not content_type.startswith(expected_prefix):
                image_magic = data.startswith((b"\x89PNG\r\n\x1a\n", b"\xff\xd8\xff", b"RIFF"))
                if expected_prefix == "image/" and not image_magic:
                    raise RuntimeError(f"unexpected upstream content type: {content_type or 'missing'}")
            with _DOME_WEB_CACHE_LOCK:
                _dome_atomic_write(cache_path, data)
            return data, False, content_type
    except Exception:
        if stale_data:
            return stale_data, True, ""
        raise


def dome_web_asset(asset_name: str) -> Tuple[bytes, str, bool]:
    name = str(asset_name or "").strip().lstrip("/")
    spec = DOME_ASSET_SOURCES.get(name)
    if not spec:
        raise ValueError("Unknown Dome web asset.")
    url, mime, max_bytes = spec
    cache_path = DOME_ASSET_CACHE_DIR / name
    expected_digest = str(DOME_ASSET_SHA256.get(name) or "").lower()
    embedded = DOME_EMBEDDED_ASSETS_ZLIB_B64.get(name)
    if embedded:
        try:
            data = zlib.decompress(base64.b64decode(embedded.encode("ascii"), validate=True))
        except Exception as exc:
            raise RuntimeError(f"Built-in Dome asset could not be decoded: {name}.") from exc
        if not data or len(data) > int(max_bytes):
            raise RuntimeError(f"Built-in Dome asset has an invalid size: {name}.")
        actual_digest = hashlib.sha256(data).hexdigest()
        if not expected_digest or not secrets.compare_digest(actual_digest, expected_digest):
            raise RuntimeError(f"Built-in Dome asset integrity validation failed for {name}.")
        return data, mime, False
    for attempt in range(2):
        data, stale, _upstream_type = _dome_cached_remote_bytes(
            url,
            cache_path,
            ttl_seconds=DOME_ASSET_CACHE_TTL_SECONDS,
            timeout_seconds=12.0,
            max_bytes=max_bytes,
        )
        if not expected_digest:
            return data, mime, stale
        actual_digest = hashlib.sha256(data).hexdigest()
        if secrets.compare_digest(actual_digest, expected_digest):
            return data, mime, stale
        with _DOME_WEB_CACHE_LOCK:
            try:
                if cache_path.is_file():
                    cache_path.unlink()
            except Exception:
                pass
        if attempt == 0:
            continue
        raise RuntimeError(f"Dome asset integrity validation failed for {name}.")
    raise RuntimeError(f"Dome asset integrity validation failed for {name}.")


def _dome_prewarm_assets() -> None:
    for asset_name in ("leaflet.css", "leaflet.js", "leaflet.draw.css", "leaflet.draw.js", "images/layers.png", "images/spritesheet.png"):
        try:
            dome_web_asset(asset_name)
        except Exception as exc:
            print(f"Dome asset prewarm warning ({asset_name}): {exc}", file=sys.stderr, flush=True)


def _dome_tile_url(provider: str, z: int, x: int, y: int) -> str:
    provider = str(provider or "").strip().lower()
    sub = "abcd"[(x + y + z) % 4]
    if provider == "carto-dark":
        return f"https://{sub}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}.png"
    if provider == "carto-light":
        return f"https://{sub}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png"
    if provider == "osm":
        return f"https://tile.openstreetmap.org/{z}/{x}/{y}.png"
    if provider == "esri-street":
        return f"https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}"
    if provider == "esri-imagery":
        return f"https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}"
    raise ValueError("Unknown Dome tile provider.")


def dome_map_tile(provider: str, z: Any, x: Any, y: Any) -> Tuple[bytes, str, bool]:
    provider = str(provider or "").strip().lower()
    zi, xi, yi = int(z), int(x), int(y)
    if zi < 0 or zi > 20:
        raise ValueError("Tile zoom is outside the supported range.")
    limit = 1 << zi
    if xi < 0 or yi < 0 or xi >= limit or yi >= limit:
        raise ValueError("Tile coordinate is outside the supported range.")
    if provider not in {"carto-dark", "carto-light", "osm", "esri-street", "esri-imagery"}:
        raise ValueError("Unknown Dome tile provider.")
    cache_path = DOME_TILE_CACHE_DIR / provider / str(zi) / str(xi) / f"{yi}.tile"
    data, stale, upstream_type = _dome_cached_remote_bytes(
        _dome_tile_url(provider, zi, xi, yi),
        cache_path,
        ttl_seconds=DOME_TILE_CACHE_TTL_SECONDS,
        timeout_seconds=DOME_TILE_FETCH_TIMEOUT_SECONDS,
        max_bytes=DOME_TILE_MAX_BYTES,
        expected_prefix="image/",
    )
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        mime = "image/png"
    elif data.startswith(b"\xff\xd8\xff"):
        mime = "image/jpeg"
    elif data.startswith(b"RIFF"):
        mime = "image/webp"
    else:
        mime = upstream_type if upstream_type.startswith("image/") else "application/octet-stream"
    return data, mime, stale


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def json_safe(value: Any, max_str: int = 3000) -> Any:
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, bytes):
        return f"<bytes:{len(value)}>"
    if isinstance(value, (list, tuple, set)):
        vals = list(value)
        primitive = all((v is None or isinstance(v, (bool, int, float, str))) for v in vals[:1000])
        limit = 70000 if primitive else 2000
        safe_vals = [json_safe(v, max_str=max_str) for v in vals[:limit]]
        if len(vals) > limit:
            safe_vals.append(f"<truncated {len(vals) - limit} item(s)>")
        return safe_vals
    if isinstance(value, dict):
        out: Dict[str, Any] = {}
        limit = 1500
        for k, v in list(value.items())[:limit]:
            out[str(k)[:160]] = json_safe(v, max_str=max_str)
        if len(value) > limit:
            out["<truncated>"] = f"{len(value) - limit} additional key(s) omitted"
        return out
    s = str(value)
    if len(s) > max_str:
        s = s[: max_str - 1] + "…"
    return s


def _normalize_host_header(value: str) -> str:
    try:
        # Configuration also uses a bare IPv6 address; HTTP Host is validated separately.
        if str(value).count(":") > 1 and not str(value).startswith("["):
            return str(ipaddress.ip_address(value))
        return _c8_authority(value)[0]
    except (ValueError, UnicodeError):
        return ""


def _is_loopback_host(value: str) -> bool:
    host = _normalize_host_header(value)
    if host in {"localhost", "ip6-localhost"}:
        return True
    try:
        return ipaddress.ip_address(host).is_loopback
    except Exception:
        return False


def _client_is_loopback(client: str) -> bool:
    try:
        return ipaddress.ip_address(client).is_loopback
    except Exception:
        return client in {"localhost", "::1"}


def _env_truthy(name: str, default: bool = False) -> bool:
    raw = os.environ.get(name)
    if raw is None or str(raw).strip() == "":
        return default
    value = str(raw).strip().lower()
    if value in {"0", "false", "no", "off"}:
        return False
    return value in {"1", "true", "yes", "on"}


DEFAULT_TRUSTED_PROXY_CIDRS = (
    "127.0.0.1/32,::1/128"
)
DEFAULT_PRIVACY_SUPPRESSED_IPS = "47.146.74.134"
PRIVACY_SUPPRESSED_IP_LABEL = "[PRIVACY-SUPPRESSED-IP]"


def _privacy_suppressed_ip_set() -> set:
    raw = os.environ.get("LL_WEB_PRIVACY_SUPPRESS_IPS")
    if raw is None:
        raw = DEFAULT_PRIVACY_SUPPRESSED_IPS
    result = set()
    for item in re.split(r"[,;\s]+", str(raw or "")):
        item = item.strip()
        if not item:
            continue
        try:
            result.add(str(ipaddress.ip_address(item)))
        except Exception:
            continue
    return result


def _privacy_suppress_future_logs_enabled() -> bool:
    return _env_truthy("LL_WEB_PRIVACY_SUPPRESS_FUTURE_LOGS", default=True)


def _privacy_text_has_suppressed_ip(value: Any) -> bool:
    text = str(value or "")
    if not text:
        return False
    for ip in _privacy_suppressed_ip_set():
        if ip and ip in text:
            return True
    return False


def _privacy_value_has_suppressed_ip(value: Any) -> bool:
    if value in (None, ""):
        return False
    if isinstance(value, (dict, list, tuple, set)):
        try:
            return _privacy_text_has_suppressed_ip(json.dumps(json_safe(value, max_str=40000), ensure_ascii=False, default=str))
        except Exception:
            return _privacy_text_has_suppressed_ip(value)
    text = str(value or "")
    suppressed = _privacy_suppressed_ip_set()
    for item in re.split(r"[,;\s]+", text):
        item = item.strip()
        if not item:
            continue
        try:
            if str(ipaddress.ip_address(item)) in suppressed:
                return True
        except Exception:
            continue
    return _privacy_text_has_suppressed_ip(text)


def _privacy_request_is_suppressed(*values: Any) -> bool:
    if not _privacy_suppress_future_logs_enabled():
        return False
    return any(_privacy_value_has_suppressed_ip(value) for value in values)


def _privacy_redact_text(value: Any) -> str:
    text = str(value or "")
    for ip in _privacy_suppressed_ip_set():
        if ip:
            text = text.replace(ip, PRIVACY_SUPPRESSED_IP_LABEL)
    return text


def _public_access_enabled() -> bool:
    return _env_truthy("LL_WEB_ALLOW_PUBLIC_BIND", default=True)


def _wan_only_enabled() -> bool:
    return _env_truthy("LL_WEB_WAN_ONLY", default=False)


def _local_path_mode_enabled() -> bool:
    return (
        _env_truthy("LL_WEB_ENABLE_LOCAL_PATH_MODE", default=False)
        or _env_truthy("LL_WEB_ENABLE_DESTRUCTIVE_LOCAL_PATHS", default=False)
    )


def _active_probe_mode_enabled() -> bool:
    return _env_truthy("LL_WEB_ENABLE_ACTIVE_PROBES", default=True)


def _osint_execution_enabled() -> bool:
    return _env_truthy("LL_WEB_ENABLE_OSINT_RUN", default=False)


def _client_is_global_wan(client: str) -> bool:
    try:
        return ipaddress.ip_address(client).is_global
    except Exception:
        return False


def _allowed_public_hosts() -> set:
    hosts = set() if _wan_only_enabled() else {"localhost", "127.0.0.1", "::1"}
    for value in (WAN_PUBLIC_HOST, HOST):
        value = _normalize_host_header(str(value or ""))
        if value and value not in {"0.0.0.0", "::"}:
            hosts.add(value)
    raw = os.environ.get("LL_WEB_ALLOWED_HOSTS") or ""
    for item in re.split(r"[,;\s]+", raw):
        item = _normalize_host_header(item)
        if item:
            hosts.add(item)
    # The dedicated shop virtual host is part of this deployment. The function
    # is defined later in the file, so resolve it dynamically during requests.
    try:
        shop_hosts_fn = globals().get("_c8_shop_public_hosts")
        if callable(shop_hosts_fn):
            hosts.update(shop_hosts_fn())
    except Exception:
        pass
    # The dedicated opt-out virtual host is part of this deployment too.
    # Resolve dynamically because the portal helpers are defined later.
    try:
        optout_hosts_fn = globals().get("_c8_optout_public_hosts")
        if callable(optout_hosts_fn):
            hosts.update(optout_hosts_fn())
    except Exception:
        pass
    return hosts


def _host_header_allowed(value: str) -> bool:
    host = _normalize_host_header(value)
    if not host:
        return False
    allowed = _allowed_public_hosts()
    base = str(globals().get("C8_CONNECTIVITY_BASE_DOMAIN") or "").lower().rstrip(".")
    connectivity_host = bool(base and re.fullmatch(r"[0-9a-f]{24}\." + re.escape(base), host))
    return host in allowed or connectivity_host or (not _wan_only_enabled() and _is_loopback_host(host))


def _request_allowed(client: str, host_header: str) -> bool:
    if _wan_only_enabled():
        return _public_access_enabled() and _client_is_global_wan(client) and _host_header_allowed(host_header)
    if _client_is_loopback(client):
        return not host_header or _host_header_allowed(host_header)
    if not _public_access_enabled():
        return False
    return _host_header_allowed(host_header)


SECURITY_MAX_ACTIVE_REQUESTS = int(os.environ.get("LL_WEB_MAX_ACTIVE_REQUESTS", "6" if C8_ULTRA_LOW_MEMORY_MODE else ("10" if C8_LOW_MEMORY_MODE else "80")))
SECURITY_MAX_ACTIVE_PER_CLIENT = int(os.environ.get("LL_WEB_MAX_ACTIVE_PER_CLIENT", "3" if C8_ULTRA_LOW_MEMORY_MODE else ("4" if C8_LOW_MEMORY_MODE else "12")))
