def _client_security_key(client: str) -> str:
    try:
        return str(ipaddress.ip_address(client))
    except Exception:
        return str(client or "unknown")[:128]


def _client_network_security_key(client: str) -> str:
    try:
        ip = ipaddress.ip_address(str(client or ""))
        if not ip.is_global:
            return ""
        prefix = 24 if ip.version == 4 else 56
        return f"ipv{ip.version}:{ipaddress.ip_network(f'{ip}/{prefix}', strict=False)}"
    except Exception:
        return ""


def _allowed_client_networks() -> List[Any]:
    raw = os.environ.get("LL_WEB_ALLOWED_CLIENT_CIDRS") or os.environ.get("LL_WEB_ALLOW_CIDRS") or ""
    nets = []
    for item in re.split(r"[,;\s]+", raw):
        item = item.strip()
        if not item:
            continue
        try:
            nets.append(ipaddress.ip_network(item, strict=False))
        except Exception:
            continue
    return nets


def _parse_cidr_list(raw: Any) -> List[Any]:
    networks: List[Any] = []
    for item in re.split(r"[,;\s]+", str(raw or "")):
        item = item.strip()
        if not item:
            continue
        try:
            networks.append(ipaddress.ip_network(item, strict=False))
        except Exception:
            continue
    return networks


def _client_cidr_match(client: str, raw_cidrs: Any) -> str:
    try:
        address = ipaddress.ip_address(str(client or "").strip())
    except Exception:
        return ""
    for network in _parse_cidr_list(raw_cidrs):
        try:
            if address.version == network.version and address in network:
                return str(network)
        except Exception:
            continue
    return ""


def _client_deny_cidr_match(client: str) -> str:
    return _client_cidr_match(client, SECURITY_DENY_CLIENT_CIDRS_RAW)


def _user_agent_marker_match(user_agent: Any, markers: Any) -> str:
    ua = str(user_agent or "").strip().lower()
    if not ua:
        return ""
    for marker in markers or ():
        marker = str(marker or "").strip().lower()
        if marker and marker in ua:
            return marker
    return ""


def _blocked_user_agent_match(user_agent: Any) -> str:
    markers = SECURITY_BLOCKED_USER_AGENT_MARKERS
    if SECURITY_BLOCK_GREYNOISE:
        markers += SECURITY_GREYNOISE_USER_AGENT_MARKERS
    if SECURITY_BLOCK_THREAT_INTEL_SCANNERS:
        markers += SECURITY_THREAT_INTEL_USER_AGENT_MARKERS
    return _user_agent_marker_match(user_agent, markers)


def _greynoise_static_cidr_match(client: str) -> str:
    if not SECURITY_BLOCK_GREYNOISE:
        return ""
    return _client_cidr_match(client, SECURITY_GREYNOISE_DENY_CIDRS_RAW)


def _threat_intel_static_cidr_match(client: str) -> str:
    if not SECURITY_BLOCK_THREAT_INTEL_SCANNERS:
        return ""
    return _client_cidr_match(client, SECURITY_THREAT_INTEL_DENY_CIDRS_RAW)


def _rdap_network_marker_policy_match(
    client: str,
    enabled: bool,
    markers: Any,
    cache_lock: Any,
    cache: Dict[str, Dict[str, Any]],
    cache_ttl_seconds: int,
    reason: str,
) -> Dict[str, Any]:
    if not enabled:
        return {}
    try:
        address = ipaddress.ip_address(str(client or "").strip())
        if not address.is_global:
            return {}
        client_key = str(address)
    except Exception:
        return {}

    now = time.time()
    with cache_lock:
        cached = cache.get(client_key)
        if cached and float(cached.get("expires_at") or 0) > now:
            match = cached.get("match")
            return dict(match) if isinstance(match, dict) else {}

    match: Dict[str, Any] = {}
    rdap: Dict[str, Any] = {}
    try:
        lookup = globals().get("rdap_lookup_deep")
        if callable(lookup):
            rdap = lookup(client_key, include_rdap=True)  # type: ignore[misc]
        else:
            rdap = rdap_lookup(client_key)
    except Exception as exc:
        rdap = {"available": False, "error": str(exc)[:240]}

    try:
        fields = (
            "name", "net_name", "org_name", "org_handle", "handle", "parent",
            "parent_handle", "remarks", "notices", "entities", "entities_roles",
            "links", "source_url", "whois_server",
        )
        haystack = " ".join(str(rdap.get(field) or "") for field in fields).lower()
        marker = ""
        for item in markers or ():
            item = str(item or "").strip().lower()
            if item and item in haystack:
                marker = item
                break
        if marker:
            match = {
                "reason": reason,
                "marker": marker,
                "client": client_key,
                "rdap": {
                    "registry": str(rdap.get("registry") or rdap.get("source") or "")[:120],
                    "net_name": str(rdap.get("net_name") or rdap.get("name") or "")[:240],
                    "org_name": str(rdap.get("org_name") or "")[:240],
                    "cidr": str(rdap.get("cidr") or rdap.get("cidr_blocks") or "")[:500],
                    "source_url": str(rdap.get("source_url") or rdap.get("source") or "")[:500],
                },
            }
    except Exception:
        match = {}

    with cache_lock:
        cache[client_key] = {
            "expires_at": now + cache_ttl_seconds,
            "match": match,
        }
        if len(cache) > 5000:
            for old_key, old_row in list(cache.items())[:2500]:
                try:
                    if float((old_row or {}).get("expires_at") or 0) < now:
                        cache.pop(old_key, None)
                except Exception:
                    cache.pop(old_key, None)
    return match


def _greynoise_rdap_policy_match(client: str) -> Dict[str, Any]:
    return _rdap_network_marker_policy_match(
        client,
        SECURITY_BLOCK_GREYNOISE and SECURITY_GREYNOISE_RDAP_LOOKUP,
        SECURITY_GREYNOISE_NETWORK_MARKERS,
        _GREYNOISE_NETWORK_CACHE_LOCK,
        _GREYNOISE_NETWORK_CACHE,
        SECURITY_GREYNOISE_RDAP_CACHE_TTL_SECONDS,
        "greynoise_rdap_heuristic",
    )


def _greynoise_api_policy_match(client: str) -> Dict[str, Any]:
    if not SECURITY_BLOCK_GREYNOISE or not SECURITY_GREYNOISE_API_LOOKUP:
        return {}
    try:
        address = ipaddress.ip_address(str(client or "").strip())
        if address.version != 4 or not address.is_global:
            return {}
        client_key = str(address)
    except Exception:
        return {}

    now = time.time()
    with _GREYNOISE_API_CACHE_LOCK:
        cached = _GREYNOISE_API_CACHE.get(client_key)
        if cached and float(cached.get("expires_at") or 0) > now:
            match = cached.get("match")
            return dict(match) if isinstance(match, dict) else {}

    match: Dict[str, Any] = {}
    cache_ttl = SECURITY_GREYNOISE_API_CACHE_TTL_SECONDS
    try:
        url = f"{SECURITY_GREYNOISE_API_BASE_URL}/{urllib.parse.quote(client_key, safe='')}"
        headers = {
            "Accept": "application/json",
            "User-Agent": "C-8-Inbound-Security/1.0",
        }
        api_key = str(
            os.environ.get("GREYNOISE_COMMUNITY_API_KEY")
            or os.environ.get("GREYNOISE_COMMUNITY_KEY")
            or os.environ.get("GREYNOISE_API_KEY")
            or os.environ.get("GREYNOISE_KEY")
            or ""
        ).strip()
        if api_key:
            headers["key"] = api_key
        request = urllib.request.Request(url, headers=headers, method="GET")
        with _c8_urlopen(request, timeout=SECURITY_GREYNOISE_API_TIMEOUT_SECONDS) as response:
            raw = response.read(256_000)
        payload = json.loads(raw.decode("utf-8", errors="replace"))
        if isinstance(payload, dict) and payload.get("noise") is True:
            match = {
                "reason": "greynoise_noise_ip",
                "client": client_key,
                "classification": str(payload.get("classification") or "")[:80],
                "name": str(payload.get("name") or "")[:160],
                "last_seen": str(payload.get("last_seen") or "")[:80],
                "riot": bool(payload.get("riot")),
                "link": str(payload.get("link") or "")[:500],
            }
    except urllib.error.HTTPError as exc:
        if int(getattr(exc, "code", 0) or 0) not in {400, 404}:
            cache_ttl = SECURITY_GREYNOISE_API_ERROR_CACHE_TTL_SECONDS
    except Exception:
        cache_ttl = SECURITY_GREYNOISE_API_ERROR_CACHE_TTL_SECONDS

    with _GREYNOISE_API_CACHE_LOCK:
        _GREYNOISE_API_CACHE[client_key] = {
            "expires_at": now + cache_ttl,
            "match": match,
        }
        if len(_GREYNOISE_API_CACHE) > 10000:
            for old_key, old_row in list(_GREYNOISE_API_CACHE.items())[:5000]:
                try:
                    if float((old_row or {}).get("expires_at") or 0) < now:
                        _GREYNOISE_API_CACHE.pop(old_key, None)
                except Exception:
                    _GREYNOISE_API_CACHE.pop(old_key, None)
    return match


def _greynoise_network_policy_match(client: str) -> Dict[str, Any]:
    static_match = _greynoise_static_cidr_match(client)
    if static_match:
        return {"reason": "greynoise_cidr_deny", "cidr": static_match}
    rdap_match = _greynoise_rdap_policy_match(client)
    if rdap_match:
        return rdap_match
    return _greynoise_api_policy_match(client)


def _threat_intel_rdap_policy_match(client: str) -> Dict[str, Any]:
    return _rdap_network_marker_policy_match(
        client,
        SECURITY_BLOCK_THREAT_INTEL_SCANNERS and SECURITY_THREAT_INTEL_RDAP_LOOKUP,
        SECURITY_THREAT_INTEL_NETWORK_MARKERS,
        _THREAT_INTEL_NETWORK_CACHE_LOCK,
        _THREAT_INTEL_NETWORK_CACHE,
        SECURITY_THREAT_INTEL_RDAP_CACHE_TTL_SECONDS,
        "threat_intel_rdap_heuristic",
    )


def _threat_intel_network_policy_match(client: str) -> Dict[str, Any]:
    static_match = _threat_intel_static_cidr_match(client)
    if static_match:
        return {"reason": "threat_intel_cidr_deny", "cidr": static_match}
    return _threat_intel_rdap_policy_match(client)


def _government_static_cidr_match(client: str) -> str:
    if not SECURITY_BLOCK_GOV_NETWORKS:
        return ""
    return _client_cidr_match(client, SECURITY_GOV_DENY_CIDRS_RAW)


def _government_rdap_policy_match(client: str) -> Dict[str, Any]:
    return _rdap_network_marker_policy_match(
        client,
        SECURITY_BLOCK_GOV_NETWORKS and SECURITY_GOV_RDAP_LOOKUP,
        SECURITY_GOV_NETWORK_MARKERS,
        _GOV_NETWORK_CACHE_LOCK,
        _GOV_NETWORK_CACHE,
        SECURITY_GOV_RDAP_CACHE_TTL_SECONDS,
        "government_rdap_heuristic",
    )


def _government_network_policy_match(client: str) -> Dict[str, Any]:
    static_match = _government_static_cidr_match(client)
    if static_match:
        return {"reason": "government_cidr_deny", "cidr": static_match}
    return _government_rdap_policy_match(client)


def _client_cidr_allowed(client: str) -> bool:
    if _wan_only_enabled() and not _client_is_global_wan(client):
        return False
    if _client_is_loopback(client):
        return True
    nets = _allowed_client_networks()
    if not nets:
        return True
    try:
        ip = ipaddress.ip_address(client)
    except Exception:
        return False
    return any(ip in net for net in nets)


def _local_state_aes_available() -> bool:
    return bool(LOCAL_STATE_AES_ENABLED and AESGCM is not None)


def _write_all_fd(fd: int, data: bytes) -> None:
    view = memoryview(data)
    written = 0
    while written < len(view):
        count = os.write(fd, view[written:])
        if count <= 0:
            raise OSError("Atomic state write did not make progress.")
        written += count


def _windows_dpapi_transform(data: bytes, protect: bool) -> bytes:
    if os.name != "nt" or not data:
        raise OSError("Windows DPAPI is unavailable on this platform.")
    import ctypes
    from ctypes import wintypes

    class DATA_BLOB(ctypes.Structure):
        _fields_ = [("cbData", wintypes.DWORD), ("pbData", ctypes.POINTER(ctypes.c_byte))]

    source_buffer = ctypes.create_string_buffer(data)
    source_blob = DATA_BLOB(len(data), ctypes.cast(source_buffer, ctypes.POINTER(ctypes.c_byte)))
    entropy_value = b"C-8 local state AES-256 master key v1"
    entropy_buffer = ctypes.create_string_buffer(entropy_value)
    entropy_blob = DATA_BLOB(len(entropy_value), ctypes.cast(entropy_buffer, ctypes.POINTER(ctypes.c_byte)))
    output_blob = DATA_BLOB()
    crypt32 = ctypes.windll.crypt32
    kernel32 = ctypes.windll.kernel32
    flags = 0x1  # CRYPTPROTECT_UI_FORBIDDEN
    if protect:
        ok = crypt32.CryptProtectData(
            ctypes.byref(source_blob), None, ctypes.byref(entropy_blob), None, None,
            flags, ctypes.byref(output_blob),
        )
    else:
        ok = crypt32.CryptUnprotectData(
            ctypes.byref(source_blob), None, ctypes.byref(entropy_blob), None, None,
            flags, ctypes.byref(output_blob),
        )
    if not ok:
        raise OSError(f"Windows DPAPI operation failed with error {ctypes.get_last_error()}.")
    try:
        return ctypes.string_at(output_blob.pbData, output_blob.cbData)
    finally:
        if output_blob.pbData:
            kernel32.LocalFree(output_blob.pbData)


def _local_key_storage_bytes(key: bytes) -> bytes:
    mode = LOCAL_STATE_KEY_PROTECTION
    use_dpapi = os.name == "nt" and mode in {"", "auto", "dpapi", "windows-dpapi"}
    if use_dpapi:
        protected = _windows_dpapi_transform(key, protect=True)
        return _LOCAL_STATE_DPAPI_MAGIC + base64.b64encode(protected)
    if mode in {"dpapi", "windows-dpapi"}:
        raise OSError("LL_WEB_LOCAL_STATE_KEY_PROTECTION requires Windows DPAPI.")
    return base64.b64encode(key)


def _atomic_write_secret(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    try:
        os.chmod(path.parent, 0o700)
    except Exception:
        pass
    tmp = path.with_name(path.name + ".tmp-" + secrets.token_hex(4))
    fd = os.open(str(tmp), os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0), 0o600)
    try:
        _write_all_fd(fd, data)
        os.fsync(fd)
    finally:
        os.close(fd)
    os.replace(tmp, path)
    try:
        os.chmod(path, 0o600)
    except Exception:
        pass


def _local_state_aes_key() -> bytes:
    global _LOCAL_STATE_AES_KEY_CACHE
    with _C8_LOCAL_KEY_LOCK:
        if _LOCAL_STATE_AES_KEY_CACHE is None:
            _LOCAL_STATE_AES_KEY_CACHE = _c8_load_or_create_key(LOCAL_STATE_AES_KEY_PATH)
        return _LOCAL_STATE_AES_KEY_CACHE


def _encrypt_local_state_bytes(data: bytes, aad: bytes) -> bytes:
    if not data or _local_state_envelope_prefix_length(data):
        return data
    if not LOCAL_STATE_AES_ENABLED:
        raise RuntimeError("Plaintext local-state writes are disabled in the hardened build.")
    if AESGCM is None:
        raise RuntimeError("Authenticated local storage requires the cryptography package.")
    key = _local_state_aes_key()
    nonce = secrets.token_bytes(12)
    return _LOCAL_STATE_AES_MAGIC + base64.b64encode(nonce + AESGCM(key).encrypt(nonce, data, aad))


def _local_state_envelope_prefix_length(data: bytes) -> int:
    for prefix in (_LOCAL_STATE_AES_MAGIC, _LOCAL_STATE_AES_MAGIC.rstrip(b"\n") + b"\r\n"):
        if data.startswith(prefix):
            return len(prefix)
    return 0


def _decrypt_local_state_bytes(data: bytes, aad: bytes) -> bytes:
    prefix = _local_state_envelope_prefix_length(data)
    if not data or not prefix:
        return data  # Read-only migration support for existing plaintext state.
    if AESGCM is None:
        raise RuntimeError("The cryptography package is required to read encrypted state.")
    try:
        raw = base64.b64decode(data[prefix:].strip(), validate=True)
        if len(raw) < 28:
            raise ValueError("Incomplete envelope")
        return AESGCM(_local_state_aes_key()).decrypt(raw[:12], raw[12:], aad)
    except Exception as exc:
        raise RuntimeError("Local-state authentication failed; restore the original key and state from backup.") from exc


def _local_state_crypto_label() -> str:
    if not LOCAL_STATE_AES_ENABLED:
        return "disabled"
    if AESGCM is None:
        return "unavailable; install cryptography for AES-256-GCM"
    key = _local_state_aes_key()
    if len(key) == 32:
        protection = "Windows DPAPI" if os.name == "nt" and LOCAL_STATE_KEY_PROTECTION in {"", "auto", "dpapi", "windows-dpapi"} else "restricted key file"
        return f"AES-256-GCM; master key protected by {protection} ({LOCAL_STATE_AES_KEY_PATH})"
    return "unavailable; AES-256-GCM key could not be created"


def _normalize_ban_subject(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw or len(raw) > 100:
        raise ValueError("Enter one valid IP address or CIDR network.")
    try:
        if "/" in raw:
            return str(ipaddress.ip_network(raw, strict=False))
        return str(ipaddress.ip_address(raw))
    except Exception as exc:
        raise ValueError("Enter one valid IP address or CIDR network.") from exc


