def _visitor_first_nonempty(*values: Any) -> str:
    for value in values:
        if value is None:
            continue
        text = str(value).replace("\x00", "").strip()
        if text and text.lower() not in {"none", "null", "n/a", "na", "unknown"}:
            return text
    return ""


def _visitor_float(value: Any, lower: float, upper: float) -> Optional[float]:
    try:
        number = float(value)
        if not math.isfinite(number) or number < lower or number > upper:
            return None
        return number
    except Exception:
        return None


def _visitor_geo_ip_candidate(client_ip: str, forwarded_for: str = "") -> str:
    candidates: List[str] = []
    for item in str(forwarded_for or "").split(","):
        item = item.strip()
        if item:
            candidates.append(item)
    if client_ip:
        candidates.append(str(client_ip).strip())
    for candidate in candidates:
        try:
            ip_obj = ipaddress.ip_address(candidate)
            if ip_obj.is_global:
                return str(ip_obj)
        except Exception:
            continue
    return ""


def _visitor_fetch_geo_json(url: str, timeout: float, max_bytes: int = 250_000) -> Dict[str, Any]:
    try:
        req = urllib.request.Request(str(url), headers={
            "User-Agent": "C-8-Visitor-Audit/1.0",
            "Accept": "application/json,text/plain,*/*",
            "Accept-Encoding": "identity",
            "Connection": "close",
        })
        with _c8_urlopen(req, timeout=float(timeout)) as response:
            status = int(getattr(response, "status", 200) or 200)
            if status >= 400:
                return {}
            raw = response.read(int(max_bytes))
        if not raw:
            return {}
        data = json.loads(raw.decode("utf-8", errors="replace"))
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _visitor_ip_geo_lookup(ip: str) -> Dict[str, Any]:
    if os.environ.get("LL_WEB_VISITOR_IP_GEO", "1").strip().lower() in {"0", "false", "no", "off"}:
        return {}
    ip = str(ip or "").strip()
    if not ip:
        return {}
    try:
        ip_obj = ipaddress.ip_address(ip)
        if not ip_obj.is_global:
            return {}
    except Exception:
        return {}
    now = time.time()
    ttl = max(60.0, float(os.environ.get("LL_WEB_VISITOR_IP_GEO_CACHE_SECONDS", str(6 * 60 * 60)) or str(6 * 60 * 60)))
    with _VISITOR_IP_GEO_LOCK:
        cached = _VISITOR_IP_GEO_CACHE.get(ip)
        if cached and now - cached[0] <= ttl:
            return dict(cached[1])
    qip = urllib.parse.quote(ip, safe="")
    timeout = max(0.5, min(5.0, float(os.environ.get("LL_WEB_VISITOR_IP_GEO_TIMEOUT", "1.8") or "1.8")))
    providers = [
        ("ipwho.is", f"https://ipwho.is/{qip}"),
        ("ipapi.co", f"https://ipapi.co/{qip}/json/"),
        ("ip-api.com", f"http://ip-api.com/json/{qip}?fields=status,message,country,countryCode,regionName,city,lat,lon,timezone,isp,org,as,query"),
    ]
    for source, url in providers:
        obj = _visitor_fetch_geo_json(url, timeout=timeout)
        if not obj:
            continue
        if source == "ip-api.com" and str(obj.get("status") or "").lower() == "fail":
            continue
        if obj.get("success") is False or obj.get("error"):
            continue
        conn = obj.get("connection") if isinstance(obj.get("connection"), dict) else {}
        timezone_obj = obj.get("timezone") if isinstance(obj.get("timezone"), dict) else {}
        lat = _visitor_float(_visitor_first_nonempty(obj.get("lat"), obj.get("latitude")), -90, 90)
        lon = _visitor_float(_visitor_first_nonempty(obj.get("lon"), obj.get("longitude")), -180, 180)
        if lat is None or lon is None:
            continue
        city = _visitor_first_nonempty(obj.get("city"))
        region = _visitor_first_nonempty(obj.get("regionName"), obj.get("region"))
        country = _visitor_first_nonempty(obj.get("country"), obj.get("country_name"))
        country_code = _visitor_first_nonempty(obj.get("countryCode"), obj.get("country_code"))
        timezone_name = _visitor_first_nonempty(obj.get("timezone") if not isinstance(obj.get("timezone"), dict) else None, timezone_obj.get("id"))
        isp = _visitor_first_nonempty(obj.get("isp"), obj.get("org"), conn.get("isp"), conn.get("org"))
        asn = _visitor_first_nonempty(conn.get("asn"), obj.get("asn"), obj.get("as"))
        label = ", ".join(x for x in (city, region, country) if x) or "Approximate IP location"
        result: Dict[str, Any] = {
            "ip_geo_source": source,
            "ip_geo_ip": ip,
            "ip_geo_lat": round(lat, 6),
            "ip_geo_lon": round(lon, 6),
            "ip_geo_accuracy_km": 50,
            "ip_geo_city": city,
            "ip_geo_region": region,
            "ip_geo_country": country,
            "ip_geo_country_code": country_code,
            "ip_geo_timezone": timezone_name,
            "ip_geo_isp": isp,
            "ip_geo_asn": asn,
            "ip_geo_label": label,
            "ip_geo_approximate": True,
        }
        with _VISITOR_IP_GEO_LOCK:
            _VISITOR_IP_GEO_CACHE[ip] = (now, dict(result))
            if len(_VISITOR_IP_GEO_CACHE) > 2000:
                for old_key in sorted(_VISITOR_IP_GEO_CACHE, key=lambda k: _VISITOR_IP_GEO_CACHE[k][0])[:500]:
                    _VISITOR_IP_GEO_CACHE.pop(old_key, None)
        return result
    with _VISITOR_IP_GEO_LOCK:
        _VISITOR_IP_GEO_CACHE[ip] = (now, {})
    return {}


def record_visitor_event(
    event_type: str,
    client_ip: str,
    *,
    forwarded_for: str = "",
    user_agent: str = "",
    client_info: Any = None,
    visitor_id: str = "",
    path: str = "",
    method: str = "",
    referrer: str = "",
    username_attempted: str = "",
    success: Optional[bool] = None,
    details: Optional[Dict[str, Any]] = None,
) -> None:
    """Record site visits and authentication events without raw passwords or secret values."""
    if _privacy_request_is_suppressed(client_ip, forwarded_for, client_info, details or {}):
        return
    _prune_audit_retention(force=False)
    try:
        info = _sanitize_login_client_info(client_info)
        clean_details = _audit_sanitize_value(details or {})
        precise_location = False
        try:
            precise_location = (
                str(info.get("geo_permission") or "") == "granted"
                and math.isfinite(float(info.get("geo_lat")))
                and math.isfinite(float(info.get("geo_lon")))
            )
        except Exception:
            precise_location = False
        if precise_location:
            info["geo_source"] = "precise-browser"
        else:
            existing_ip_lat = _visitor_float(info.get("ip_geo_lat"), -90, 90)
            existing_ip_lon = _visitor_float(info.get("ip_geo_lon"), -180, 180)
            ip_geo = {
                key: value for key, value in info.items()
                if str(key).startswith("ip_geo_")
            } if existing_ip_lat is not None and existing_ip_lon is not None else {}
            if not ip_geo:
                ip_geo = _visitor_ip_geo_lookup(_visitor_geo_ip_candidate(client_ip, forwarded_for))
            if ip_geo:
                info.update(ip_geo)
                info["geo_source"] = "approximate-ip"
                info.setdefault("geo_error", "Precise browser geolocation was unavailable; approximate IP location was logged.")
                report = info.get("device_report") if isinstance(info.get("device_report"), dict) else {}
                report.update({
                    "location_source": "approximate-ip",
                    "location_message": "Precise browser geolocation was unavailable; approximate IP location was logged.",
                    "ip_geo_source": ip_geo.get("ip_geo_source"),
                    "ip_geo_ip": ip_geo.get("ip_geo_ip"),
                    "ip_geo_lat": ip_geo.get("ip_geo_lat"),
                    "ip_geo_lon": ip_geo.get("ip_geo_lon"),
                    "ip_geo_accuracy_km": ip_geo.get("ip_geo_accuracy_km"),
                    "ip_geo_city": ip_geo.get("ip_geo_city"),
                    "ip_geo_region": ip_geo.get("ip_geo_region"),
                    "ip_geo_country": ip_geo.get("ip_geo_country"),
                    "ip_geo_country_code": ip_geo.get("ip_geo_country_code"),
                    "ip_geo_timezone": ip_geo.get("ip_geo_timezone"),
                    "ip_geo_isp": ip_geo.get("ip_geo_isp"),
                    "ip_geo_asn": ip_geo.get("ip_geo_asn"),
                    "ip_geo_label": ip_geo.get("ip_geo_label"),
                    "ip_geo_approximate": True,
                })
                info["device_report"] = report
            else:
                info.setdefault("geo_source", "browser-unavailable")
        try:
            _c8_security_archive_event(event_type, client_ip, username_attempted, user_agent, info, clean_details)
        except Exception:
            pass
        with _DB_LOCK:
            with db_connection() as conn:
                _db_insert_row_with_integrity(conn, "visitor_access_log", {
                    "event_at": now_iso(),
                    "event_type": str(event_type or "visit")[:80],
                    "visitor_id": _clean_visitor_id(visitor_id),
                    "username_attempted": str(username_attempted or "")[:150],
                    "success": None if success is None else (1 if success else 0),
                    "remote_ip": str(client_ip or "")[:64],
                    "forwarded_for": str(forwarded_for or "")[:500],
                    "request_method": str(method or "")[:16],
                    "request_path": str(path or "")[:255],
                    "referrer": str(referrer or "")[:1000],
                    "user_agent": str(user_agent or info.get("user_agent") or "")[:1000],
                    "browser": str(info.get("browser") or "")[:180],
                    "platform_name": str(info.get("platform") or "")[:255],
                    "architecture": str(info.get("architecture") or "")[:64],
                    "bitness": str(info.get("bitness") or "")[:32],
                    "cpu_threads": info.get("cpu_threads"),
                    "device_memory_gb": info.get("device_memory_gb"),
                    "gpu_vendor": str(info.get("gpu_vendor") or "")[:255],
                    "gpu_renderer": str(info.get("gpu_renderer") or "")[:500],
                    "screen_info": str(info.get("screen") or "")[:80],
                    "timezone_name": str(info.get("timezone") or "")[:120],
                    "language_name": str(info.get("language") or info.get("languages") or "")[:120],
                    "device_json": json.dumps(json_safe(info, max_str=5000), ensure_ascii=False),
                    "details_json": json.dumps(json_safe(clean_details, max_str=5000), ensure_ascii=False),
                })
                conn.commit()
    except Exception:
        pass


def admin_visitors_overview(limit: int = 500, search: str = "") -> Dict[str, Any]:
    """Administrator-only visitor, device, IP, and failed-login report."""
    limit = max(1, min(int(limit or 500), 5000))
    params: List[Any] = []
    q = str(search or "").strip()[:300]
    where = ""
    if q:
        like = f"%{q}%"
        where = " WHERE (remote_ip LIKE ? OR forwarded_for LIKE ? OR visitor_id LIKE ? OR username_attempted LIKE ? OR event_type LIKE ? OR browser LIKE ? OR platform_name LIKE ? OR user_agent LIKE ? OR device_json LIKE ?)"
        params.extend([like] * 9)
    with db_connection() as conn:
        rows = db_fetchall(conn, f"""
            SELECT id, event_at, event_type, visitor_id, username_attempted, success,
                   remote_ip, forwarded_for, request_method, request_path, referrer,
                   user_agent, browser, platform_name, architecture, bitness,
                   cpu_threads, device_memory_gb, gpu_vendor, gpu_renderer,
                   screen_info, timezone_name, language_name, device_json, details_json
              FROM visitor_access_log
              {where}
             ORDER BY id DESC
             LIMIT {limit}
        """, tuple(params))
    events: List[Dict[str, Any]] = []
    unique_ips: set = set()
    unique_visitors: set = set()
    failed_logins = 0
    successful_logins = 0
    precise_locations = 0
    approximate_locations = 0
    for row in rows:
        def parse_json(name: str) -> Any:
            raw = _audit_decrypt_field("visitor_access_log", name, _row_get(row, name, ""))
            try:
                return json.loads(raw) if raw else {}
            except Exception:
                return raw
        event_type = str(_row_get(row, "event_type", "") or "")
        success_raw = _row_get(row, "success")
        success_value = None if success_raw is None else bool(success_raw)
        remote_ip = str(_row_get(row, "remote_ip", "") or "")
        if _privacy_value_has_suppressed_ip(remote_ip) or _privacy_value_has_suppressed_ip(row):
            continue
        if event_type == "login_denied":
            failed_logins += 1
        elif event_type == "login_success":
            successful_logins += 1
        visitor_id = str(_row_get(row, "visitor_id", "") or "")
        if remote_ip:
            unique_ips.add(remote_ip)
        if visitor_id:
            unique_visitors.add(visitor_id)
        device_data = parse_json("device_json")
        if not isinstance(device_data, dict):
            device_data = {}
        geo_permission = str(device_data.get("geo_permission") or "")
        geo_lat = device_data.get("geo_lat")
        geo_lon = device_data.get("geo_lon")
        geo_accuracy_m = device_data.get("geo_accuracy_m")
        geo_captured_at = str(device_data.get("geo_captured_at") or "")
        try:
            valid_precise_location = (
                geo_permission == "granted"
                and math.isfinite(float(geo_lat))
                and math.isfinite(float(geo_lon))
            )
        except Exception:
            valid_precise_location = False
        if valid_precise_location:
            precise_locations += 1
        ip_geo_lat = device_data.get("ip_geo_lat")
        ip_geo_lon = device_data.get("ip_geo_lon")
        ip_geo_accuracy_km = device_data.get("ip_geo_accuracy_km")
        ip_geo_source = str(device_data.get("ip_geo_source") or "")
        try:
            valid_ip_location = math.isfinite(float(ip_geo_lat)) and math.isfinite(float(ip_geo_lon))
        except Exception:
            valid_ip_location = False
        if valid_ip_location and not valid_precise_location:
            approximate_locations += 1
        events.append({
            "id": _row_get(row, "id"),
            "event_at": str(_row_get(row, "event_at", "") or ""),
            "event_type": event_type,
            "visitor_id": visitor_id,
            "username_attempted": str(_row_get(row, "username_attempted", "") or ""),
            "success": success_value,
            "remote_ip": remote_ip,
            "forwarded_for": str(_row_get(row, "forwarded_for", "") or ""),
            "method": str(_row_get(row, "request_method", "") or ""),
            "path": str(_row_get(row, "request_path", "") or ""),
            "referrer": str(_row_get(row, "referrer", "") or ""),
            "user_agent": str(_row_get(row, "user_agent", "") or ""),
            "browser": str(_row_get(row, "browser", "") or ""),
            "platform": str(_row_get(row, "platform_name", "") or ""),
            "architecture": str(_row_get(row, "architecture", "") or ""),
            "bitness": str(_row_get(row, "bitness", "") or ""),
            "cpu_threads": _row_get(row, "cpu_threads"),
            "device_memory_gb": _row_get(row, "device_memory_gb"),
            "gpu_vendor": str(_row_get(row, "gpu_vendor", "") or ""),
            "gpu_renderer": str(_row_get(row, "gpu_renderer", "") or ""),
            "screen": str(_row_get(row, "screen_info", "") or ""),
            "timezone": str(_row_get(row, "timezone_name", "") or ""),
            "language": str(_row_get(row, "language_name", "") or ""),
            "device_name": str(device_data.get("device_name") or ""),
            "device": device_data,
            "geo_permission": geo_permission,
            "geo_lat": geo_lat,
            "geo_lon": geo_lon,
            "geo_accuracy_m": geo_accuracy_m,
            "geo_altitude_m": device_data.get("geo_altitude_m"),
            "geo_heading_deg": device_data.get("geo_heading_deg"),
            "geo_speed_mps": device_data.get("geo_speed_mps"),
            "geo_captured_at": geo_captured_at,
            "geo_error": str(device_data.get("geo_error") or ""),
            "geo_source": str(device_data.get("geo_source") or ""),
            "ip_geo_lat": ip_geo_lat,
            "ip_geo_lon": ip_geo_lon,
            "ip_geo_accuracy_km": ip_geo_accuracy_km,
            "ip_geo_source": ip_geo_source,
            "ip_geo_ip": str(device_data.get("ip_geo_ip") or ""),
            "ip_geo_city": str(device_data.get("ip_geo_city") or ""),
            "ip_geo_region": str(device_data.get("ip_geo_region") or ""),
            "ip_geo_country": str(device_data.get("ip_geo_country") or ""),
            "ip_geo_country_code": str(device_data.get("ip_geo_country_code") or ""),
            "ip_geo_timezone": str(device_data.get("ip_geo_timezone") or ""),
            "ip_geo_isp": str(device_data.get("ip_geo_isp") or ""),
            "ip_geo_asn": str(device_data.get("ip_geo_asn") or ""),
            "ip_geo_label": str(device_data.get("ip_geo_label") or ""),
            "ip_geo_approximate": bool(device_data.get("ip_geo_approximate")),
            "details": parse_json("details_json"),
        })
    return {
        "ok": True,
        "generated_at": now_iso(),
        "returned_count": len(events),
        "unique_ips": len(unique_ips),
        "unique_visitors": len(unique_visitors),
        "failed_logins": failed_logins,
        "successful_logins": successful_logins,
        "precise_locations": precise_locations,
        "approximate_locations": approximate_locations,
        "events": events,
        "privacy_note": "Precise browser location is collected only after the visitor grants the browser geolocation permission. Raw passwords, authentication secrets, encryption keys, raw file contents, serial numbers, and activity outside this console are not collected. Failed login attempts retain only a coarse length bucket and a server-keyed HMAC correlation tag.",
    }


def _live_event_epoch(value: Any) -> float:
    try:
        text = str(value or "").strip()
        if not text:
            return 0.0
        return datetime.fromisoformat(text.replace("Z", "+00:00")).timestamp()
    except Exception:
        return 0.0


def _load_live_visitor_kicks_locked() -> None:
    global _LIVE_VISITOR_KICKS_LOADED
    if _LIVE_VISITOR_KICKS_LOADED:
        return
    _LIVE_VISITOR_KICKS_LOADED = True
    try:
        raw = LIVE_VISITOR_KICKS_PATH.read_bytes()
        payload = json.loads(_decrypt_local_state_bytes(raw, b"c8-visitor-kicks-v1").decode("utf-8"))
        rows = payload.get("kicks") if isinstance(payload, dict) else {}
        if isinstance(rows, dict):
            for visitor_id, row in rows.items():
                clean = _clean_visitor_id(visitor_id)
                if clean and isinstance(row, dict):
                    _LIVE_VISITOR_KICKS[clean] = dict(row)
    except Exception:
        pass


def _save_live_visitor_kicks_locked() -> None:
    try:
        LIVE_VISITOR_KICKS_PATH.parent.mkdir(parents=True, exist_ok=True)
        payload = {
            "ok": True,
            "updated_at": now_iso(),
            "kick_ttl_seconds": LIVE_VISITOR_KICK_TTL_SECONDS,
            "kicks": json_safe(_LIVE_VISITOR_KICKS, max_str=3000),
        }
        tmp = LIVE_VISITOR_KICKS_PATH.with_name(LIVE_VISITOR_KICKS_PATH.name + ".tmp-" + secrets.token_hex(4))
        data = json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8")
        tmp.write_bytes(_encrypt_local_state_bytes(data, b"c8-visitor-kicks-v1"))
        os.replace(tmp, LIVE_VISITOR_KICKS_PATH)
        try:
            os.chmod(LIVE_VISITOR_KICKS_PATH, 0o600)
        except Exception:
            pass
    except Exception:
        pass


def _live_visitor_kick_status(visitor_id: Any) -> Dict[str, Any]:
    clean = _clean_visitor_id(visitor_id)
    if not clean:
        return {}
    now = time.time()
    with _LIVE_VISITOR_KICK_LOCK:
        _load_live_visitor_kicks_locked()
        row = _LIVE_VISITOR_KICKS.get(clean)
        if not isinstance(row, dict):
            return {}
        try:
            expires = float(row.get("expires_at_epoch") or 0)
        except Exception:
            expires = 0.0
        if expires <= now:
            _LIVE_VISITOR_KICKS.pop(clean, None)
            _save_live_visitor_kicks_locked()
            return {}
        safe = dict(row)
        safe["visitor_id"] = clean
        safe["expires_at"] = _epoch_iso(expires)
        safe["remaining_seconds"] = max(0, int(expires - now))
        return json_safe(safe, max_str=2000)


def _live_visitor_kick_rows() -> List[Dict[str, Any]]:
    now = time.time()
    rows: List[Dict[str, Any]] = []
    changed = False
    with _LIVE_VISITOR_KICK_LOCK:
        _load_live_visitor_kicks_locked()
        for visitor_id, row in list(_LIVE_VISITOR_KICKS.items()):
            try:
                expires = float((row or {}).get("expires_at_epoch") or 0)
            except Exception:
                expires = 0.0
            if expires <= now:
                _LIVE_VISITOR_KICKS.pop(visitor_id, None)
                changed = True
                continue
            safe = dict(row or {})
            safe["visitor_id"] = visitor_id
            safe["expires_at"] = _epoch_iso(expires)
            safe["remaining_seconds"] = max(0, int(expires - now))
            rows.append(json_safe(safe, max_str=2000))
        if changed:
            _save_live_visitor_kicks_locked()
    return sorted(rows, key=lambda item: int(item.get("remaining_seconds") or 0), reverse=True)


def admin_kick_visitor(actor_session: Dict[str, Any], visitor_id: Any, reason: str = "") -> Dict[str, Any]:
    clean = _clean_visitor_id(visitor_id)
    if not clean:
        return {"ok": False, "status": "invalid_visitor_id", "error": "A valid visitor id is required."}
    now = time.time()
    row = {
        "visitor_id": clean,
        "kicked": True,
        "kicked_at": _epoch_iso(now),
        "kicked_by": str((actor_session or {}).get("username") or "")[:150],
        "reason": str(reason or "Ended by administrator.")[:500],
        "expires_at_epoch": now + LIVE_VISITOR_KICK_TTL_SECONDS,
        "ttl_seconds": LIVE_VISITOR_KICK_TTL_SECONDS,
    }
    with _LIVE_VISITOR_KICK_LOCK:
        _load_live_visitor_kicks_locked()
        _LIVE_VISITOR_KICKS[clean] = row
        _save_live_visitor_kicks_locked()
    return {"ok": True, "status": "kicked", "kick": _live_visitor_kick_status(clean)}


def _admin_live_location(event: Dict[str, Any]) -> Dict[str, Any]:
    def valid_number(value: Any) -> bool:
        try:
            return math.isfinite(float(value))
        except Exception:
            return False

    if str(event.get("geo_permission") or "") == "granted" and valid_number(event.get("geo_lat")) and valid_number(event.get("geo_lon")):
        return {
            "mode": "precise-browser",
            "label": "Precise browser location",
            "lat": event.get("geo_lat"),
            "lon": event.get("geo_lon"),
            "accuracy_m": event.get("geo_accuracy_m"),
            "captured_at": event.get("geo_captured_at"),
            "permission": event.get("geo_permission"),
            "source": event.get("geo_source") or "browser",
        }
    if valid_number(event.get("ip_geo_lat")) and valid_number(event.get("ip_geo_lon")):
        label = str(event.get("ip_geo_label") or "").strip()
        if not label:
            label = ", ".join(str(event.get(k) or "").strip() for k in ("ip_geo_city", "ip_geo_region", "ip_geo_country") if str(event.get(k) or "").strip()) or "Approximate IP location"
        return {
            "mode": "approximate-ip",
            "label": label,
            "lat": event.get("ip_geo_lat"),
            "lon": event.get("ip_geo_lon"),
            "accuracy_km": event.get("ip_geo_accuracy_km"),
            "permission": event.get("geo_permission") or "not-granted",
            "source": event.get("ip_geo_source") or "ip-geo",
            "city": event.get("ip_geo_city"),
            "region": event.get("ip_geo_region"),
            "country": event.get("ip_geo_country"),
            "isp": event.get("ip_geo_isp"),
            "asn": event.get("ip_geo_asn"),
        }
    return {
        "mode": "unavailable",
        "label": str(event.get("geo_error") or "No location value was reported."),
        "permission": event.get("geo_permission") or "not-requested",
    }


def _admin_live_device(event: Dict[str, Any]) -> Dict[str, Any]:
    device = event.get("device") if isinstance(event.get("device"), dict) else {}
    report = device.get("device_report") if isinstance(device.get("device_report"), dict) else {}
    return {
        "device_name": str(event.get("device_name") or report.get("device_name") or device.get("device_name") or "Browser-reported device"),
        "browser": str(event.get("browser") or device.get("browser") or ""),
        "platform": str(event.get("platform") or device.get("platform") or ""),
        "architecture": str(event.get("architecture") or device.get("architecture") or ""),
        "bitness": str(event.get("bitness") or device.get("bitness") or ""),
        "screen": str(event.get("screen") or device.get("screen") or ""),
        "timezone": str(event.get("timezone") or device.get("timezone") or ""),
        "language": str(event.get("language") or device.get("language") or device.get("languages") or ""),
        "cpu_threads": event.get("cpu_threads") if event.get("cpu_threads") is not None else device.get("cpu_threads"),
        "device_memory_gb": event.get("device_memory_gb") if event.get("device_memory_gb") is not None else device.get("device_memory_gb"),
        "gpu_vendor": str(event.get("gpu_vendor") or device.get("gpu_vendor") or ""),
        "gpu_renderer": str(event.get("gpu_renderer") or device.get("gpu_renderer") or ""),
        "user_agent": str(event.get("user_agent") or ""),
    }


def admin_live_overview(limit: int = 1000, visitor_window_seconds: Optional[int] = None) -> Dict[str, Any]:
    """Administrator-only live authenticated-session and remembered-visitor view."""
    limit = max(1, min(int(limit or 1000), 5000))
    window = max(30, min(int(visitor_window_seconds or LIVE_VISITOR_WINDOW_SECONDS), 24 * 60 * 60))
    now_epoch = time.time()
    session_report = list_online_sessions(include_stale=True)
    all_sessions = list(session_report.get("sessions") or [])
    live_sessions = [row for row in all_sessions if bool(row.get("online"))]
    visitor_report = admin_visitors_overview(limit=limit, search="")
    groups: Dict[str, Dict[str, Any]] = {}
    for event in visitor_report.get("events") or []:
        if not isinstance(event, dict):
            continue
        visitor_id = _clean_visitor_id(event.get("visitor_id"))
        remote_ip = str(event.get("remote_ip") or "")
        user_agent = str(event.get("user_agent") or "")
        if visitor_id:
            key = "visitor:" + visitor_id
        else:
            key = "anonymous:" + remote_ip + ":" + _server_hmac_tag("live_visitor_user_agent_key", user_agent, 12)
        ts = _live_event_epoch(event.get("event_at"))
        group = groups.get(key)
        if group is None:
            group = {
                "key": key,
                "visitor_id": visitor_id,
                "remembered": bool(visitor_id),
                "remote_ip": remote_ip,
                "forwarded_for": str(event.get("forwarded_for") or ""),
                "first_seen_epoch": ts or now_epoch,
                "last_seen_epoch": ts or 0,
                "event_count": 0,
                "page_visits": 0,
                "device_reports": 0,
                "login_events": 0,
                "event_types": set(),
                "paths": set(),
                "latest_event": event,
            }
            groups[key] = group
        group["event_count"] = int(group.get("event_count") or 0) + 1
        if str(event.get("event_type") or "") == "page_visit":
            group["page_visits"] = int(group.get("page_visits") or 0) + 1
        if str(event.get("event_type") or "") == "device_report":
            group["device_reports"] = int(group.get("device_reports") or 0) + 1
        if str(event.get("event_type") or "").startswith("login_"):
            group["login_events"] = int(group.get("login_events") or 0) + 1
        if ts:
            group["first_seen_epoch"] = min(float(group.get("first_seen_epoch") or ts), ts)
            if ts >= float(group.get("last_seen_epoch") or 0):
                group["last_seen_epoch"] = ts
                group["latest_event"] = event
                group["remote_ip"] = remote_ip
                group["forwarded_for"] = str(event.get("forwarded_for") or "")
        try:
            group["event_types"].add(str(event.get("event_type") or "event"))
            if event.get("path"):
                group["paths"].add(str(event.get("path") or "")[:255])
        except Exception:
            pass

    visitors: List[Dict[str, Any]] = []
    for group in groups.values():
        latest = group.get("latest_event") if isinstance(group.get("latest_event"), dict) else {}
        last_seen = float(group.get("last_seen_epoch") or 0)
        first_seen = float(group.get("first_seen_epoch") or last_seen or 0)
        visitor_id = str(group.get("visitor_id") or "")
        kick = _live_visitor_kick_status(visitor_id)
        page_visits = int(group.get("page_visits") or 0)
        device_reports = int(group.get("device_reports") or 0)
        visitors.append({
            "key": str(group.get("key") or ""),
            "visitor_id": visitor_id,
            "remembered": bool(group.get("remembered")),
            "live": bool(last_seen and (now_epoch - last_seen) <= window),
            "age_seconds": max(0, int(now_epoch - last_seen)) if last_seen else None,
            "first_seen": _epoch_iso(first_seen),
            "last_seen": _epoch_iso(last_seen),
            "event_count": int(group.get("event_count") or 0),
            "page_visits": page_visits,
            "device_reports": device_reports,
            "login_events": int(group.get("login_events") or 0),
            "revisit_count": max(0, max(page_visits, device_reports, int(group.get("event_count") or 0)) - 1),
            "event_types": sorted(list(group.get("event_types") or []))[:20],
            "paths": sorted(list(group.get("paths") or []))[:12],
            "remote_ip": str(group.get("remote_ip") or ""),
            "forwarded_for": str(group.get("forwarded_for") or ""),
            "username_attempted": str(latest.get("username_attempted") or ""),
            "latest_event": str(latest.get("event_type") or ""),
            "latest_path": str(latest.get("path") or ""),
            "device": _admin_live_device(latest),
            "location": _admin_live_location(latest),
            "kicked": bool(kick),
            "kick": kick,
        })

    visitors.sort(key=lambda item: (0 if item.get("live") else 1, -_live_event_epoch(item.get("last_seen"))))
    kicked = _live_visitor_kick_rows()
    return {
        "ok": True,
        "generated_at": now_iso(),
        "visitor_window_seconds": window,
        "user_session_count": len(all_sessions),
        "live_user_session_count": len(live_sessions),
        "visitor_count": len(visitors),
        "live_visitor_count": sum(1 for row in visitors if row.get("live")),
        "remembered_visitor_count": sum(1 for row in visitors if row.get("remembered")),
        "kicked_visitor_count": len(kicked),
        "user_sessions": all_sessions,
        "live_user_sessions": live_sessions,
        "visitors": visitors,
        "kicked_visitors": kicked,
        "session_report": session_report,
    }


def admin_activity_overview(limit: int = 5000, username: str = "", module: str = "", search: str = "") -> Dict[str, Any]:
    """Administrator-only activity viewer for actions performed inside the console."""
    limit = max(1, min(int(limit or 5000), 5000))
    clauses: List[str] = []
    params: List[Any] = []
    if str(username or "").strip():
        clauses.append("username = ?")
        params.append(str(username).strip()[:150])
    if str(module or "").strip():
        clauses.append("module_name = ?")
        params.append(str(module).strip()[:120])
    q = str(search or "").strip()
    if q:
        like = f"%{q[:300]}%"
        clauses.append("(username LIKE ? OR module_name LIKE ? OR action_name LIKE ? OR request_path LIKE ? OR target_summary LIKE ? OR payload_json LIKE ? OR remote_ip LIKE ?)")
        params.extend([like] * 7)
    where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
    with db_connection() as conn:
        rows = db_fetchall(conn, f"""
            SELECT id, created_at, username, user_id, role_name, session_id,
                   remote_ip, forwarded_for, user_agent, module_name,
                   action_name, request_path, status_name, target_summary,
                   payload_json, error_text
              FROM user_activity_log
              {where}
             ORDER BY id DESC
             LIMIT {limit}
        """, tuple(params))
    events: List[Dict[str, Any]] = []
    modules: set = set()
    users: set = set()
    for row in rows:
        def parse_json_field(name: str) -> Any:
            raw = _audit_decrypt_field("user_activity_log", name, _row_get(row, name, ""))
            try:
                return json.loads(raw) if raw else {}
            except Exception:
                return raw
        target = parse_json_field("target_summary")
        payload = parse_json_field("payload_json")
        audit_meta: Dict[str, Any] = {}
        if isinstance(target, dict) and isinstance(target.get("_audit"), dict):
            audit_meta.update(target.get("_audit") or {})
        if isinstance(payload, dict) and isinstance(payload.get("_audit"), dict):
            audit_meta.update(payload.get("_audit") or {})
        request_meta = payload.get("_request") if isinstance(payload, dict) and isinstance(payload.get("_request"), dict) else {}
        details_meta = payload.get("details") if isinstance(payload, dict) and isinstance(payload.get("details"), dict) else {}
        client_info = payload.get("client_info") if isinstance(payload, dict) and isinstance(payload.get("client_info"), dict) else {}
        if not client_info and isinstance(details_meta.get("client_info"), dict):
            client_info = details_meta.get("client_info") or {}
        security_signals = request_meta.get("security_signals") if isinstance(request_meta.get("security_signals"), list) else audit_meta.get("security_signals")
        if not isinstance(security_signals, list):
            security_signals = []
        request_detail = {
            "method": str(request_meta.get("method") or "")[:16],
            "path": str(request_meta.get("path") or _row_get(row, "request_path", "") or "")[:255],
            "query_present": bool(request_meta.get("query_present")),
            "host_allowed": request_meta.get("host_allowed"),
            "origin_checked": request_meta.get("origin_checked"),
            "remote_ip_family": str(request_meta.get("remote_ip_family") or "")[:32],
            "transport": str(request_meta.get("transport") or audit_meta.get("transport") or "")[:40],
            "tls_active": request_meta.get("tls_active"),
            "tls_version": str(request_meta.get("tls_version") or "")[:80],
            "cipher": str(request_meta.get("cipher") or "")[:180],
            "header_count": request_meta.get("header_count", audit_meta.get("header_count")),
            "cookie_count": request_meta.get("cookie_count", audit_meta.get("cookie_count")),
            "content_length_bucket": str(request_meta.get("content_length_bucket") or audit_meta.get("content_length_bucket") or "")[:80],
            "security_signals": [str(item)[:120] for item in security_signals[:20]],
            "request_fingerprint": str(request_meta.get("request_fingerprint") or audit_meta.get("request_fingerprint") or "")[:64],
        }
        request_detail = {k: v for k, v in request_detail.items() if v not in ("", None, [])}
        device_detail = {
            "device_name": str(client_info.get("device_name") or "")[:255],
            "browser": str(client_info.get("browser") or "")[:180],
            "platform": str(client_info.get("platform") or "")[:255],
            "screen": str(client_info.get("screen") or "")[:80],
            "timezone": str(client_info.get("timezone") or "")[:120],
            "language": str(client_info.get("language") or client_info.get("languages") or "")[:120],
            "cpu_threads": client_info.get("cpu_threads"),
            "device_memory_gb": client_info.get("device_memory_gb"),
            "gpu_vendor": str(client_info.get("gpu_vendor") or "")[:255],
            "gpu_renderer": str(client_info.get("gpu_renderer") or "")[:500],
            "geo_permission": str(client_info.get("geo_permission") or "")[:80],
        }
        device_detail = {k: v for k, v in device_detail.items() if v not in ("", None, [])}
        user_agent_raw = str(_row_get(row, "user_agent", "") or "")
        item = {
            "id": _row_get(row, "id"),
            "created_at": str(_row_get(row, "created_at", "") or ""),
            "username": str(_row_get(row, "username", "") or ""),
            "user_id": _row_get(row, "user_id"),
            "role": str(_row_get(row, "role_name", "") or ""),
            "session_id": str(_row_get(row, "session_id", "") or ""),
            "remote_ip": str(_row_get(row, "remote_ip", "") or ""),
            "forwarded_for": str(_row_get(row, "forwarded_for", "") or ""),
            "user_agent": str(_row_get(row, "user_agent", "") or ""),
            "module": str(_row_get(row, "module_name", "") or ""),
            "action": str(_row_get(row, "action_name", "") or ""),
            "path": str(_row_get(row, "request_path", "") or ""),
            "status": str(_row_get(row, "status_name", "") or ""),
            "request": request_detail,
            "device": device_detail,
            "target": target,
            "payload": payload,
            "audit": audit_meta,
            "request_fingerprint": str(audit_meta.get("request_fingerprint") or ""),
            "activity_correlation_tag": str(audit_meta.get("activity_correlation_tag") or ""),
            "tag_algorithm": str(audit_meta.get("tag_algorithm") or ""),
            "user_agent_sha256": str(audit_meta.get("user_agent_sha256") or (hashlib.sha256(user_agent_raw.encode("utf-8", errors="ignore")).hexdigest()[:24] if user_agent_raw else "")),
            "session_tag": str(audit_meta.get("session_id") or _row_get(row, "session_id", "") or ""),
            "security_signals": [str(item)[:120] for item in security_signals[:20]],
            "error": _audit_decrypt_field("user_activity_log", "error_text", _row_get(row, "error_text", "")),
        }
        if _privacy_value_has_suppressed_ip(item):
            continue
        if item["module"]:
            modules.add(item["module"])
        if item["username"]:
            users.add(item["username"])
        events.append(item)
    return {
        "ok": True,
        "generated_at": now_iso(),
        "returned_count": len(events),
        "limit": limit,
        "users": sorted(users, key=str.lower),
        "modules": sorted(modules, key=str.lower),
        "events": events,
        "redaction_policy": "Passwords, secrets, encryption material, raw uploaded files, and encryption/decryption text are never stored in the activity log.",
    }


def ipv4_to_decimal(ip: str) -> Any:
    """Ported from the uploaded main-menu IP Forensics utility, with validation added."""
    try:
        obj = ipaddress.ip_address(str(ip).strip())
        if obj.version != 4:
            return "N/A (not IPv4)"
        parts = list(map(int, str(obj).split(".")))
        decimal = 0
        for part in parts:
            decimal = decimal * 256 + part
        return decimal
    except Exception:
        return "N/A (not IPv4)"


def get_ip_version(ip: str) -> str:
    """Ported from the uploaded main-menu IP Forensics utility, with strict parsing."""
    try:
        return f"IPv{ipaddress.ip_address(str(ip).strip()).version}"
    except Exception:
        if ":" in str(ip):
            return "IPv6-like"
        if re.match(r"^\d{1,3}(\.\d{1,3}){3}$", str(ip)):
            return "IPv4-like"
        return "Unknown"


def derive_domain_from_hostname(hostname: str) -> str:
    """Lightweight port of the uploaded main-menu domain derivation helper."""
    try:
        h = (hostname or "").strip().rstrip(".")
        if not h or h.lower() in {"n/a", "na", "none", "unknown"}:
            return "N/A"
        if "://" in h:
            u = urllib.parse.urlparse(h)
            h = (u.netloc or u.path or h).strip()
        if "@" in h:
            h = h.rsplit("@", 1)[-1]
        h = h.strip("[]")
        if ":" in h and h.count(":") == 1:
            h = h.split(":", 1)[0]
        try:
            ipaddress.ip_address(h)
            return "N/A"
        except Exception:
            pass
        if h.startswith("*."):
            h = h[2:]
        parts = [p for p in h.split(".") if p]
        if len(parts) < 2:
            return h or "N/A"
        multi_suffix = TWO_PART_TLDS
        last2 = ".".join(parts[-2:])
        if last2 in multi_suffix and len(parts) >= 3:
            return ".".join(parts[-3:])
        return last2
    except Exception:
        return "N/A"


def infer_usage_type(as_org: str = "", isp: str = "", organization: str = "", *, is_mobile: bool = False,
                     is_hosting: bool = False, is_proxy: bool = False, is_tor: bool = False) -> str:
    """Ported/adapted from the uploaded main-menu AS/IP usage classifier."""
    try:
        s = " ".join(str(x or "") for x in [as_org, isp, organization]).lower()
        if is_tor:
            return "Tor Exit"
        if is_mobile or any(k in s for k in ["mobile", "cellular", "lte", "5g", "4g"]):
            return "Mobile"
        if is_proxy or any(k in s for k in ["vpn", "proxy", "tunnel", "wireguard", "openvpn"]):
            return "Proxy/VPN"
        if is_hosting or any(k in s for k in ["hosting", "datacenter", "data center", "colo", "colocation", "vps", "cloud", "aws", "amazon", "azure", "google", "gcp", "digitalocean", "linode", "ovh", "hetzner"]):
            return "Hosting/Cloud"
        if any(k in s for k in ["residential", "broadband", "cable", "dsl", "fiber", "ftth", "home", "telecom", "communications"]):
            return "Residential ISP"
        if any(k in s for k in ["university", "college", "edu", "research", "institute"]):
            return "Education/Research"
        if any(k in s for k in ["government", "gov", "municipal", "state", "county", "city"]):
            return "Government"
        if any(k in s for k in ["enterprise", "corporate", "business"]):
            return "Enterprise"
        return "Unknown"
    except Exception:
        return "Unknown"


def normalize_host_or_target(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        raise ValueError("Target is required.")
    if len(raw) > 253:
        raise ValueError("Target is too long.")
    if any(x in raw for x in ["\n", "\r", "\t", " ", ",", ";", "*"]):
        raise ValueError("Enter one host or IP only; lists, wildcards, and shell metacharacters are not accepted.")
    if "://" in raw:
        u = urllib.parse.urlparse(raw)
        if u.path and u.path != "/":
            raise ValueError("URL paths are not accepted for this single-target tool.")
        raw = u.hostname or u.netloc or u.path
    elif "/" in raw:
        raise ValueError("CIDR ranges and URL paths are not accepted for this single-target tool.")
    if "@" in raw:
        raw = raw.rsplit("@", 1)[-1]
    if raw.startswith("[") and "]" in raw:
        raw = raw[1: raw.index("]")]
    elif raw.count(":") == 1 and raw.rsplit(":", 1)[1].isdigit():
        raw = raw.rsplit(":", 1)[0]
    raw = raw.strip().strip(".")
    if not raw:
        raise ValueError("Target is empty after normalization.")
    return raw


def resolve_targets(host: str, limit: int = 6) -> List[Dict[str, str]]:
    out: List[Dict[str, str]] = []
    seen = set()
    try:
        ip = ipaddress.ip_address(host)
        return [{"family": f"IPv{ip.version}", "ip": str(ip), "source": "literal"}]
    except Exception:
        pass
    infos: List[Any] = []
    try:
        infos = socket.getaddrinfo(host, None, type=socket.SOCK_STREAM)
    except Exception:
        infos = []
    for fam, _stype, _proto, _canon, addr in infos:
        try:
            ip = addr[0]
            if ip in seen:
                continue
            seen.add(ip)
            ver = "IPv6" if fam == socket.AF_INET6 else "IPv4"
            out.append({"family": ver, "ip": ip, "source": "dns"})
            if len(out) >= limit:
                break
        except Exception:
            continue
    return out


def reverse_dns(ip: str) -> str:
    try:
        return socket.gethostbyaddr(ip)[0]
    except Exception:
        return "N/A"


def _rdap_fetch_json(url: str, timeout: float = 6.0) -> Optional[Dict[str, Any]]:
    try:
        req = urllib.request.Request(url, headers={
            "User-Agent": "GovStyleConsolePowered/2.0",
            "Accept": "application/json",
        })
        with _c8_urlopen(req, timeout=timeout) as r:
            if int(getattr(r, "status", 200)) >= 400:
                return None
            return json.loads(r.read(2_000_000).decode("utf-8", errors="replace"))
    except Exception:
        return None


def rdap_lookup(ip: str) -> Dict[str, Any]:
    result: Dict[str, Any] = {"available": False}
    try:
        ip_obj = ipaddress.ip_address(ip)
        if not ip_obj.is_global:
            result["note"] = "RDAP skipped for non-global address."
            return result
    except Exception as e:
        result["error"] = str(e)
        return result

    urls = [
        f"https://rdap.org/ip/{urllib.parse.quote(ip)}",
        f"https://rdap.arin.net/registry/ip/{urllib.parse.quote(ip)}",
        f"https://rdap.db.ripe.net/ip/{urllib.parse.quote(ip)}",
        f"https://rdap.apnic.net/ip/{urllib.parse.quote(ip)}",
        f"https://rdap.lacnic.net/rdap/ip/{urllib.parse.quote(ip)}",
        f"https://rdap.afrinic.net/rdap/ip/{urllib.parse.quote(ip)}",
    ]
    rdap: Optional[Dict[str, Any]] = None
    source = ""
    for url in urls:
        rdap = _rdap_fetch_json(url)
        if isinstance(rdap, dict) and rdap:
            source = url.split("/ip/")[0]
            break
    if not rdap:
        result["error"] = "No RDAP response from public endpoints."
        return result

    remarks: List[str] = []
    for remark in rdap.get("remarks") or []:
        try:
            desc = remark.get("description") if isinstance(remark, dict) else None
            if isinstance(desc, list):
                remarks.extend(str(x) for x in desc[:5])
        except Exception:
            pass

    entities: List[str] = []
    for ent in rdap.get("entities") or []:
        try:
            if isinstance(ent, dict):
                handle = ent.get("handle")
                roles = ",".join(ent.get("roles") or []) if isinstance(ent.get("roles"), list) else ""
                if handle:
                    entities.append(f"{handle} {roles}".strip())
        except Exception:
            pass

    cidrs = []
    try:
        for c0 in rdap.get("cidr0_cidrs") or []:
            if "v4prefix" in c0 and "length" in c0:
                cidrs.append(f"{c0.get('v4prefix')}/{c0.get('length')}")
            elif "v6prefix" in c0 and "length" in c0:
                cidrs.append(f"{c0.get('v6prefix')}/{c0.get('length')}")
    except Exception:
        pass

    return {
        "available": True,
        "source": source,
        "handle": rdap.get("handle") or "N/A",
        "name": rdap.get("name") or "N/A",
        "type": rdap.get("type") or "N/A",
        "country": rdap.get("country") or "N/A",
        "start_address": rdap.get("startAddress") or "N/A",
        "end_address": rdap.get("endAddress") or "N/A",
        "cidr": ", ".join(cidrs) if cidrs else "N/A",
        "parent_handle": rdap.get("parentHandle") or "N/A",
        "entities": entities[:12],
        "remarks": remarks[:12],
    }



_IPF_GENERIC_UNKNOWN_REASON = "No value was published by the field-specific registry, routing, DNS, HTTP, TLS, or service probe used for this item."


def _ipf_is_blankish(value: Any) -> bool:
    try:
        if value is None:
            return True
        s = str(value).strip()
        low = s.lower()
        return (
            (not s)
            or low in {"n/a", "n.a", "na", "none", "null", "unknown", "not provided"}
            or low == _IPF_GENERIC_UNKNOWN_REASON.lower()
            or "field-specific registry, routing, dns, http, tls, or service probe" in low
        )
    except Exception:
        return True


def _ipf_safe(value: Any, default: str = "N/A") -> Any:
    if _ipf_is_blankish(value):
        return default
    return value


def _ipf_first(*values: Any, default: str = "N/A") -> Any:
    for v in values:
        if not _ipf_is_blankish(v):
            return v
    return default


def _ipf_join(values: Any, limit: int = 50, sep: str = ", ") -> str:
    try:
        if values is None:
            return "N/A"
        if isinstance(values, dict):
            values = [f"{k}={v}" for k, v in values.items()]
        elif not isinstance(values, (list, tuple, set)):
            values = [values]
        out: List[str] = []
        for v in list(values)[:limit]:
            if _ipf_is_blankish(v):
                continue
            s = str(v).strip()
            if s and s not in out:
                out.append(s)
        return sep.join(out) if out else "N/A"
    except Exception:
        return "N/A"


def _ipf_bool(value: Any) -> str:
    if value is None or value == "N/A":
        return "N/A"
    return "True" if bool(value) else "False"


def _ipf_section(title: str, rows: List[Tuple[str, Any]]) -> Dict[str, Any]:
    return {"title": title, "rows": [{"label": str(k), "value": json_safe(_ipf_safe(v))} for k, v in rows]}


def _ipf_fetch_json(url: str, timeout: float = IPF_API_TIMEOUT_SECONDS, max_bytes: int = 2_000_000) -> Any:
    """Fetch public JSON with bounded retries for transient provider failures.

    The previous implementation swallowed every network error after one short
    attempt, which caused valid fields to be replaced by generic unavailable
    messages. This version retries only idempotent GET requests and still keeps
    a strict time/size bound.
    """
    attempts = max(1, min(4, int(os.environ.get("LL_WEB_IPF_API_RETRIES", "3") or "3")))
    last_error = None
    for attempt in range(attempts):
        try:
            req = urllib.request.Request(url, headers={
                "User-Agent": "C-8-IPForensics/3.0",
                "Accept": "application/json,text/plain,*/*",
                "Accept-Encoding": "identity",
                "Connection": "close",
            })
            with _c8_urlopen(req, timeout=float(timeout)) as r:
                status = int(getattr(r, "status", 200))
                if status in {408, 425, 429, 500, 502, 503, 504} and attempt + 1 < attempts:
                    time.sleep(min(1.5, 0.25 * (2 ** attempt)))
                    continue
                if status >= 400:
                    return {}
                body = r.read(int(max_bytes))
                if not body:
                    if attempt + 1 < attempts:
                        time.sleep(min(1.0, 0.2 * (2 ** attempt)))
                        continue
                    return {}
                obj = json.loads(body.decode("utf-8", errors="replace"))
                return obj if isinstance(obj, (dict, list)) else {}
        except urllib.error.HTTPError as e:
            last_error = e
            if int(getattr(e, "code", 0) or 0) in {408, 425, 429, 500, 502, 503, 504} and attempt + 1 < attempts:
                retry_after = 0.0
                try:
                    retry_after = min(2.0, float(e.headers.get("Retry-After", "0") or "0"))
                except Exception:
                    retry_after = 0.0
                time.sleep(max(retry_after, min(1.5, 0.25 * (2 ** attempt))))
                continue
            return {}
        except (TimeoutError, socket.timeout, urllib.error.URLError, ConnectionError, OSError, json.JSONDecodeError) as e:
            last_error = e
            if attempt + 1 < attempts:
                time.sleep(min(1.5, 0.25 * (2 ** attempt)))
                continue
        except Exception as e:
            last_error = e
            break
    return {}


def _ipf_fetch_json_quick(url: str, timeout: float = 2.5, max_bytes: int = 1_000_000) -> Any:
    """Single-attempt JSON fetch for core IPF fields that must not stall the UI."""
    try:
        req = urllib.request.Request(str(url), headers={
            "User-Agent": "C-8-IPForensics-Fast/3.1",
            "Accept": "application/json,text/plain,*/*",
            "Accept-Encoding": "identity",
            "Connection": "close",
        })
        kwargs: Dict[str, Any] = {"timeout": float(timeout)}
        if str(url).lower().startswith("https://"):
            kwargs["context"] = ssl.create_default_context()
        with _c8_urlopen(req, **kwargs) as r:
            status = int(getattr(r, "status", 200) or 200)
            if status >= 400:
                return {}
            raw = r.read(int(max_bytes))
        if not raw:
            return {}
        obj = json.loads(raw.decode("utf-8", errors="replace"))
        return obj if isinstance(obj, (dict, list)) else {}
    except Exception:
        return {}


def _ipf_fast_rdap_summary(rdap: Any, source_url: str = "https://rdap.org/ip/") -> Dict[str, Any]:
    """Parse the common RDAP network fields from one fast bootstrap response."""
    if not isinstance(rdap, dict) or not rdap:
        return {}

    def registry_from(url: str) -> str:
        u = str(url or "").lower()
        if "arin" in u:
            return "ARIN"
        if "ripe" in u:
            return "RIPE"
        if "apnic" in u:
            return "APNIC"
        if "lacnic" in u:
            return "LACNIC"
        if "afrinic" in u:
            return "AFRINIC"
        return "RDAP bootstrap"

    cidrs: List[str] = []
    try:
        for c0 in rdap.get("cidr0_cidrs") or []:
            if not isinstance(c0, dict):
                continue
            if "v4prefix" in c0 and "length" in c0:
                cidrs.append(str(ipaddress.ip_network(f"{c0.get('v4prefix')}/{c0.get('length')}", strict=False)))
            elif "v6prefix" in c0 and "length" in c0:
                cidrs.append(str(ipaddress.ip_network(f"{c0.get('v6prefix')}/{c0.get('length')}", strict=False)))
    except Exception:
        pass
    try:
        if not cidrs and rdap.get("startAddress") and rdap.get("endAddress"):
            start_ip = ipaddress.ip_address(str(rdap.get("startAddress")))
            end_ip = ipaddress.ip_address(str(rdap.get("endAddress")))
            cidrs = [str(n) for n in ipaddress.summarize_address_range(start_ip, end_ip)][:24]
    except Exception:
        pass

    org_names: List[str] = []
    org_handles: List[str] = []
    org_addresses: List[str] = []
    org_countries: List[str] = []
    roles_seen: List[str] = []
    for ent in rdap.get("entities") or []:
        if not isinstance(ent, dict):
            continue
        handle = str(ent.get("handle") or "").strip()
        roles = [str(x).lower() for x in (ent.get("roles") or [])]
        if handle and handle not in org_handles:
            org_handles.append(handle)
        if roles:
            role_text = ",".join(roles)
            if handle:
                role_text = f"{handle} ({role_text})"
            if role_text not in roles_seen:
                roles_seen.append(role_text)
        vals = _ipf_vcard_values(ent.get("vcardArray"))
        for n in (vals.get("org") or vals.get("fn") or []):
            if n and n not in org_names:
                org_names.append(n)
        for a in vals.get("adr") or []:
            if a and a not in org_addresses:
                org_addresses.append(a)
        country = ent.get("country")
        if country and str(country) not in org_countries:
            org_countries.append(str(country))

    remarks: List[str] = []
    for remark in rdap.get("remarks") or []:
        if isinstance(remark, dict):
            desc = remark.get("description")
            if isinstance(desc, list):
                remarks.extend(str(x) for x in desc[:8] if str(x).strip())
            elif desc:
                remarks.append(str(desc))

    links: List[str] = []
    for link in rdap.get("links") or []:
        if isinstance(link, dict) and link.get("href"):
            links.append(str(link.get("href")))

    start = rdap.get("startAddress") or "N/A"
    end = rdap.get("endAddress") or "N/A"
    net_range = f"{start} - {end}" if start != "N/A" and end != "N/A" else "N/A"
    return {
        "available": True,
        "registry": registry_from(source_url),
        "source_url": source_url,
        "handle": rdap.get("handle") or "N/A",
        "name": rdap.get("name") or "N/A",
        "type": rdap.get("type") or "N/A",
        "country": rdap.get("country") or "N/A",
        "start_address": start,
        "end_address": end,
        "net_range": net_range,
        "cidr": _ipf_join(cidrs, limit=24),
        "cidr_blocks": _ipf_join(cidrs, limit=24),
        "net_name": rdap.get("name") or "N/A",
        "net_handle": rdap.get("handle") or "N/A",
        "parent_network": rdap.get("parentHandle") or "N/A",
        "parent": rdap.get("parentHandle") or "N/A",
        "org_name": _ipf_join(org_names, limit=6),
        "org_handle": _ipf_join(org_handles, limit=10),
        "org_address": _ipf_join(org_addresses, limit=4, sep=" | "),
        "org_country": _ipf_join(org_countries, limit=4),
        "status": _ipf_join(rdap.get("status") or [], limit=12),
        "remarks": _ipf_join(remarks, limit=20, sep=" | "),
        "entities_roles": _ipf_join(roles_seen, limit=20, sep=" | "),
        "links": _ipf_join(links, limit=20, sep=" | "),
        "whois_server": rdap.get("port43") or rdap.get("whoisServer") or "N/A",
    }


def _ipf_fast_public_core_backfill(
    sections: List[Dict[str, Any]], ip: str, include_rdap: bool = True
) -> Dict[str, Any]:
    """Backfill core IPF rows from fast tokenless sources before detailed recovery runs."""
    sources: List[str] = []
    errors: Dict[str, str] = {}
    try:
        ip_obj = ipaddress.ip_address(str(ip))
        if not ip_obj.is_global:
            return {"sources": [], "errors": {}}
    except Exception:
        return {"sources": [], "errors": {"fast backfill": "invalid primary IP"}}

    qip = urllib.parse.quote(str(ip), safe="")
    urls: Dict[str, str] = {
        "ip-api.com": f"http://ip-api.com/json/{qip}?fields=status,message,continent,continentCode,country,countryCode,region,regionName,city,district,zip,lat,lon,timezone,offset,currency,isp,org,as,asname,reverse,mobile,proxy,hosting,query",
        "ipinfo.io": f"https://ipinfo.io/{qip}/json",
        "ipwho.is": f"https://ipwho.is/{qip}",
        "ipapi.co": f"https://ipapi.co/{qip}/json/",
    }
    if include_rdap:
        urls["rdap.org"] = f"https://rdap.org/ip/{qip}"

    data: Dict[str, Any] = {}

    def fetch(item: Tuple[str, str]) -> Tuple[str, Any, str]:
        name, url = item
        obj = _ipf_fetch_json_quick(url, timeout=IPF_FAST_PROVIDER_TIMEOUT_SECONDS)
        if not isinstance(obj, dict) or not obj:
            return name, {}, "empty or invalid response"
        if obj.get("status") == "fail":
            return name, {}, str(obj.get("message") or "provider returned fail")
        if obj.get("success") is False:
            return name, {}, str(obj.get("message") or obj.get("reason") or "provider returned success=false")
        if obj.get("error") and name != "rdap.org":
            return name, {}, str(obj.get("error"))[:180]
        return name, obj, ""

    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(5, len(urls))) as ex:
            for name, obj, err in ex.map(fetch, urls.items()):
                data[name] = obj
                if obj:
                    sources.append(name)
                elif err:
                    errors[name] = err
    except Exception:
        for item in urls.items():
            name, obj, err = fetch(item)
            data[name] = obj
            if obj:
                sources.append(name)
            elif err:
                errors[name] = err

    apilayer_key = str(os.environ.get("APILAYER_API_KEY") or os.environ.get("APILAYER_KEY") or "").strip()
    if apilayer_key:
        obj, err = _ipf_http_json_with_headers(
            f"https://api.apilayer.com/ip_to_location/{qip}",
            {"apikey": apilayer_key, "Accept": "application/json", "User-Agent": f"C8-IPForensics/{APP_VERSION}"},
            timeout=max(2.0, IPF_FAST_PROVIDER_TIMEOUT_SECONDS),
        )
        if isinstance(obj, dict) and obj and not obj.get("error"):
            data["apilayer.com"] = obj
            sources.append("APILayer IP to Location")
        elif err:
            errors["APILayer IP to Location"] = err

    if include_rdap and not data.get("rdap.org"):
        rdap_fallbacks = [
            ("rdap.org", f"https://rdap.org/ip/{qip}"),
            ("rdap.arin.net", f"https://rdap.arin.net/registry/ip/{qip}"),
            ("rdap.db.ripe.net", f"https://rdap.db.ripe.net/ip/{qip}"),
            ("rdap.apnic.net", f"https://rdap.apnic.net/ip/{qip}"),
            ("rdap.lacnic.net", f"https://rdap.lacnic.net/rdap/ip/{qip}"),
            ("rdap.afrinic.net", f"https://rdap.afrinic.net/rdap/ip/{qip}"),
        ]
        for name, url in rdap_fallbacks:
            obj = _ipf_fetch_json_quick(url, timeout=IPF_FAST_PROVIDER_TIMEOUT_SECONDS, max_bytes=3_000_000)
            if isinstance(obj, dict) and obj:
                data["rdap.org"] = obj
                urls["rdap.org"] = url
                if name not in sources:
                    sources.append(name)
                errors.pop("rdap.org", None)
                break

    providers = {k: v for k, v in data.items() if k != "rdap.org"}
    geo = _ipf_geo_merge(providers)
    ipapi = data.get("ip-api.com") or {}
    ipwho = data.get("ipwho.is") or {}
    ipinfo = data.get("ipinfo.io") or {}
    ipapico = data.get("ipapi.co") or {}
    apilayer = data.get("apilayer.com") or {}
    ap_conn = apilayer.get("connection") if isinstance(apilayer.get("connection"), dict) else {}
    rdap = _ipf_fast_rdap_summary(data.get("rdap.org"), urls.get("rdap.org", "https://rdap.org/ip/")) if include_rdap else {}
    conn = ipwho.get("connection") if isinstance(ipwho, dict) else {}
    if not isinstance(conn, dict):
        conn = {}
    sec = ipwho.get("security") if isinstance(ipwho, dict) else {}
    if not isinstance(sec, dict):
        sec = {}

    ipinfo_asn, ipinfo_as_org = _ipf_parse_asn(ipinfo.get("org"))
    as_number, as_org = _ipf_parse_asn(ap_conn.get("asn"), conn.get("asn"), ipapico.get("asn"), ipapi.get("as"), ipinfo.get("org"))
    if as_number == "N/A" and ipinfo_asn != "N/A":
        as_number = ipinfo_asn
    as_org = _ipf_first(ap_conn.get("isp"), conn.get("org"), conn.get("isp"), ipapi.get("asname"), ipinfo_as_org, ipapi.get("as"), rdap.get("org_name"), rdap.get("net_name"), default=as_org)
    isp = _ipf_first(ap_conn.get("isp"), ipapi.get("isp"), ipapico.get("org"), conn.get("isp"), conn.get("org"), ipinfo_as_org, ipinfo.get("org"), rdap.get("org_name"), rdap.get("net_name"))
    organization = _ipf_first(ipapi.get("org"), ipapico.get("org"), ap_conn.get("isp"), conn.get("org"), rdap.get("org_name"), ipinfo_as_org, ipinfo.get("org"), rdap.get("net_name"))
    hostname = _ipf_first(ipinfo.get("hostname"), ipapi.get("reverse"), ipwho.get("hostname") if isinstance(ipwho, dict) else None, reverse_dns(ip))
    domain_name = derive_domain_from_hostname(str(hostname))
    if domain_name == "N/A":
        domain_name = derive_domain_from_hostname(_ipf_first(conn.get("domain"), rdap.get("net_name")))

    is_mobile = bool(ipapi.get("mobile"))
    is_hosting = bool(ipapi.get("hosting")) or bool(ipwho.get("hosting") if isinstance(ipwho, dict) else False)
    is_proxy = bool(ipapi.get("proxy")) or bool(sec.get("vpn")) or bool(sec.get("proxy"))
    is_tor = bool(sec.get("tor"))
    usage_type = infer_usage_type(as_org, isp, organization, is_mobile=is_mobile, is_hosting=is_hosting, is_proxy=is_proxy, is_tor=is_tor)
    assignment = "Dynamic" if is_mobile else ("Static" if (is_hosting or is_proxy or is_tor) else "Unknown")
    prefix = _ipf_first(rdap.get("cidr"), rdap.get("cidr_blocks"))
    most_specific = str(prefix).split(",", 1)[0].strip() if prefix != "N/A" else "N/A"

    top_rows = {
        "Country": geo.get("country"),
        "Region Name": geo.get("region_name"),
        "Region Code": geo.get("region_code"),
        "City": geo.get("city"),
        "Static/Dynamic Assignment": assignment,
        "ISP": isp,
        "Organization": organization,
        "ASN Number": as_number,
        "AS Usage Type": usage_type,
        "Hostname": hostname,
        "Domain Name": domain_name,
        "Proxy Domain": domain_name if is_proxy else "N/A",
        "Usage Type": usage_type,
        "Net Range": rdap.get("net_range"),
        "CIDR": most_specific,
        "Net Name": rdap.get("net_name"),
        "Net Handle": rdap.get("net_handle"),
        "Parent": rdap.get("parent_network"),
        "Proxy/VPN": _ipf_bool(is_proxy),
        "TOR Node": _ipf_bool(is_tor),
        "Relay": _ipf_bool(is_proxy or is_hosting),
        "Hosting": _ipf_bool(is_hosting),
    }
    for label, value in top_rows.items():
        _ipf_set_row(sections, label, value)

    geo_rows = {
        "Postal / ZIP code": geo.get("postal"),
        "Country code": geo.get("country_code"),
        "District / suburb (if provided)": geo.get("district"),
        "Continent code": geo.get("continent_code"),
        "UTC offset": geo.get("utc_offset"),
        "Local currency": geo.get("currency"),
        "Latitude": geo.get("latitude"),
        "Longitude": geo.get("longitude"),
        "Time zone": geo.get("timezone"),
        "Continent": geo.get("continent"),
        "Geoname ID (if provider gives it)": geo.get("geoname_id"),
        "Geolocation confidence score": geo.get("confidence"),
        "Geolocation source/provider": geo.get("providers"),
    }
    for label, value in geo_rows.items():
        _ipf_set_row(sections, label, value, "2)")

    registry_rows = {
        "Registry (ARIN / RIPE / APNIC / LACNIC / AFRINIC)": rdap.get("registry"),
        "CIDR block(s)": rdap.get("cidr_blocks"),
        "Parent network": rdap.get("parent_network"),
        "Organization name": organization,
        "Org handle / ID": rdap.get("org_handle"),
        "Address (registrant org address, if published)": rdap.get("org_address"),
        "Country (org registration country)": _ipf_first(rdap.get("org_country"), rdap.get("country")),
        "Registration status": rdap.get("status"),
        "Remarks / comments": rdap.get("remarks"),
        "RDAP entities and roles": rdap.get("entities_roles"),
        "RDAP links": rdap.get("links"),
        "Registration source URL/reference": rdap.get("source_url"),
        "Whois server / referral": rdap.get("whois_server"),
    }
    for label, value in registry_rows.items():
        _ipf_set_row(sections, label, value, "3)")

    asn_rows = {
        "ASN name": _ipf_first(ipapi.get("asname"), as_org),
        "ASN organization": as_org,
        "ASN description": _ipf_first(ipapi.get("as"), ipinfo.get("org"), as_org),
        "ASN country": geo.get("country_code"),
        "ASN registry": rdap.get("registry"),
        "AS type / usage type": usage_type,
        "ASN contact / abuse info": rdap.get("org_handle"),
    }
    for label, value in asn_rows.items():
        _ipf_set_row(sections, label, value, "4)")

    bgp_rows = {
        "BGP prefix(es) for the IP": prefix,
        "Most specific prefix containing the IP": most_specific,
        "Origin AS (current)": as_number,
        "Covering prefixes": prefix,
    }
    for label, value in bgp_rows.items():
        _ipf_set_row(sections, label, value, "5)")

    _ipf_set_row(sections, "PTR record(s)", hostname, "7)")
    _ipf_set_row(sections, "DNS hostname count (current)", "1" if hostname != "N/A" else "N/A", "7)")
    _ipf_set_row(sections, "ASN/domain relationships", f"{as_number} / {as_org}", "19)")
    _ipf_set_row(sections, "Brand/organization domain associations", _ipf_first(domain_name, organization), "19)")
    _ipf_set_row(sections, "Hosting vs residential vs mobile vs enterprise vs education", usage_type, "16)")
    _ipf_set_row(sections, "Cloud provider detection", "True" if is_hosting else "False", "16)")
    _ipf_set_row(sections, "VPN endpoint detection", "True" if is_proxy else "False", "16)")
    _ipf_set_row(sections, "Proxy detection", "True" if is_proxy else "False", "16)")
    _ipf_set_row(sections, "TOR relay / exit / bridge detection", "True" if is_tor else "False", "16)")
    _ipf_set_row(sections, "Dynamic vs static assignment confidence", assignment, "16)")

    return {"sources": sources, "errors": errors}


def _ipf_http_text(url: str, timeout: float = 3.0, max_bytes: int = IPF_MAX_HTTP_BYTES) -> Tuple[Optional[int], Dict[str, str], str, str]:
    try:
        req = urllib.request.Request(url, headers={
            "User-Agent": "GovStyleConsolePowered-IPF/2.1",
            "Accept": "text/html,text/plain,*/*",
        }, method="GET")
        kwargs: Dict[str, Any] = {"timeout": float(timeout)}
        if url.lower().startswith("https://"):
            kwargs["context"] = ssl.create_default_context()
        with _c8_urlopen(req, **kwargs) as r:
            status = int(getattr(r, "status", 200))
            headers = {str(k): str(v) for k, v in r.headers.items()}
            body = r.read(int(max_bytes)).decode("utf-8", errors="replace")
            final_url = getattr(r, "url", url)
            return status, headers, body, str(final_url)
    except Exception as e:
        return None, {}, f"ERROR: {e}", url


def _ipf_hex_binary(ip: str) -> Tuple[str, str]:
    try:
        obj = ipaddress.ip_address(ip)
        n = int(obj)
        width = 32 if obj.version == 4 else 128
        hex_width = 8 if obj.version == 4 else 32
        return f"0x{n:0{hex_width}x}", f"{n:0{width}b}"
    except Exception:
        return "N/A", "N/A"


def _ipf_special_use(ip: str) -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    try:
        obj = ipaddress.ip_address(ip)
        tags = []
        if obj.is_private: tags.append("private")
        if obj.is_loopback: tags.append("loopback")
        if obj.is_link_local: tags.append("link-local")
        if obj.is_multicast: tags.append("multicast")
        if obj.is_reserved: tags.append("reserved")
        if obj.is_unspecified: tags.append("unspecified")
        if obj.is_global: tags.append("global")
        rfc = "N/A"
        if obj.version == 4:
            if obj in ipaddress.ip_network("10.0.0.0/8") or obj in ipaddress.ip_network("172.16.0.0/12") or obj in ipaddress.ip_network("192.168.0.0/16"):
                rfc = "RFC1918 private-use"
            elif obj in ipaddress.ip_network("127.0.0.0/8"):
                rfc = "RFC1122 loopback"
            elif obj in ipaddress.ip_network("169.254.0.0/16"):
                rfc = "RFC3927 link-local"
            elif obj in ipaddress.ip_network("192.0.2.0/24") or obj in ipaddress.ip_network("198.51.100.0/24") or obj in ipaddress.ip_network("203.0.113.0/24"):
                rfc = "RFC5737 documentation"
        else:
            if obj in ipaddress.ip_network("fc00::/7"):
                rfc = "RFC4193 unique-local"
            elif obj in ipaddress.ip_network("fe80::/10"):
                rfc = "RFC4291 link-local"
            elif obj in ipaddress.ip_network("2001:db8::/32"):
                rfc = "RFC3849 documentation"
        out.update({
            "canonical": str(obj),
            "special_use_classification": ", ".join(tags) if tags else "unclassified",
            "bogon_status": "False" if obj.is_global else "True",
            "rfc_special_purpose_tag": rfc,
            "address_scope": "global" if obj.is_global else (tags[0] if tags else "special/local"),
        })
    except Exception as e:
        out.update({"canonical": ip, "special_use_classification": f"error: {e}", "bogon_status": "N/A", "rfc_special_purpose_tag": "N/A", "address_scope": "N/A"})
    return out


def _ipf_parse_asn(*values: Any) -> Tuple[str, str]:
    as_number = "N/A"
    as_org = "N/A"
    for v in values:
        if _ipf_is_blankish(v):
            continue
        s = str(v).strip()
        m = re.search(r"\bAS\s*(\d+)\b", s, flags=re.I) or re.search(r"^\s*(\d{1,10})\s*$", s)
        if m and as_number == "N/A":
            as_number = "AS" + m.group(1)
            rest = re.sub(r"^\s*AS\s*\d+\s*", "", s, flags=re.I).strip()
            if rest:
                as_org = rest
        elif as_org == "N/A":
            as_org = s
    return as_number, as_org


def _ipf_vcard_values(vcard: Any) -> Dict[str, List[str]]:
    vals: Dict[str, List[str]] = {"fn": [], "org": [], "email": [], "tel": [], "adr": []}
    try:
        if not isinstance(vcard, list) or len(vcard) < 2 or not isinstance(vcard[1], list):
            return vals
        for item in vcard[1]:
            if not isinstance(item, list) or len(item) < 4:
                continue
            key = str(item[0] or "").lower()
            val = item[3]
            if key == "adr" and isinstance(val, list):
                s = ", ".join(str(x).strip() for x in val if str(x).strip())
            elif isinstance(val, list):
                s = ", ".join(str(x).strip() for x in val if str(x).strip())
            else:
                s = str(val or "").strip()
            if key in vals and s and s not in vals[key]:
                vals[key].append(s)
    except Exception:
        pass
    return vals


def rdap_lookup_deep(ip: str, include_rdap: bool = True) -> Dict[str, Any]:
    base: Dict[str, Any] = {
        "available": False, "registry": "N/A", "source_url": "N/A", "net_range": "N/A", "cidr": "N/A", "cidr_blocks": "N/A",
        "net_name": "N/A", "net_handle": "N/A", "parent_network": "N/A", "org_name": "N/A", "org_handle": "N/A",
        "org_address": "N/A", "org_country": "N/A", "status": "N/A", "created": "N/A", "updated": "N/A",
        "last_changed": "N/A", "abuse_email": "N/A", "abuse_phone": "N/A", "tech_contact": "N/A", "admin_contact": "N/A",
        "noc_contact": "N/A", "remarks": "N/A", "events": "N/A", "entities_roles": "N/A", "links": "N/A", "notices": "N/A",
        "whois_server": "N/A", "parent": "N/A", "handle": "N/A", "name": "N/A", "type": "N/A", "country": "N/A",
        "start_address": "N/A", "end_address": "N/A",
    }
    if not include_rdap:
        base["note"] = "RDAP disabled by user."
        return base
    try:
        ip_obj = ipaddress.ip_address(ip)
        if not ip_obj.is_global:
            base["note"] = "RDAP skipped for non-global address."
            return base
    except Exception as e:
        base["error"] = str(e)
        return base

    urls = [
        f"https://rdap.org/ip/{urllib.parse.quote(ip)}",
        f"https://rdap.arin.net/registry/ip/{urllib.parse.quote(ip)}",
        f"https://rdap.db.ripe.net/ip/{urllib.parse.quote(ip)}",
        f"https://rdap.apnic.net/ip/{urllib.parse.quote(ip)}",
        f"https://rdap.lacnic.net/rdap/ip/{urllib.parse.quote(ip)}",
        f"https://rdap.afrinic.net/rdap/ip/{urllib.parse.quote(ip)}",
    ]
    rdap = None
    source_url = "N/A"
    for url in urls:
        j = _ipf_fetch_json(url, timeout=IPF_API_TIMEOUT_SECONDS, max_bytes=3_000_000)
        if isinstance(j, dict) and j:
            rdap = j
            source_url = url
            break
    if not isinstance(rdap, dict):
        base["error"] = "No RDAP response from public endpoints."
        return base

    def registry_from(url: str) -> str:
        u = url.lower()
        if "arin" in u: return "ARIN"
        if "ripe" in u: return "RIPE"
        if "apnic" in u: return "APNIC"
        if "lacnic" in u: return "LACNIC"
        if "afrinic" in u: return "AFRINIC"
        return "Bootstrap/RDAP"

    cidrs: List[str] = []
    try:
        for c0 in rdap.get("cidr0_cidrs") or []:
            if not isinstance(c0, dict):
                continue
            if "v4prefix" in c0 and "length" in c0:
                cidrs.append(f"{c0.get('v4prefix')}/{c0.get('length')}")
            elif "v6prefix" in c0 and "length" in c0:
                cidrs.append(f"{c0.get('v6prefix')}/{c0.get('length')}")
    except Exception:
        pass
    try:
        if not cidrs and rdap.get("startAddress") and rdap.get("endAddress"):
            start_ip = ipaddress.ip_address(str(rdap.get("startAddress")))
            end_ip = ipaddress.ip_address(str(rdap.get("endAddress")))
            cidrs = [str(n) for n in ipaddress.summarize_address_range(start_ip, end_ip)][:12]
    except Exception:
        pass

    remarks: List[str] = []
    for remark in rdap.get("remarks") or []:
        if isinstance(remark, dict):
            desc = remark.get("description")
            if isinstance(desc, list):
                remarks.extend(str(x) for x in desc[:8])
            elif desc:
                remarks.append(str(desc))
    notices: List[str] = []
    for notice in rdap.get("notices") or []:
        if isinstance(notice, dict):
            title = notice.get("title")
            desc = notice.get("description")
            if title:
                notices.append(str(title))
            if isinstance(desc, list):
                notices.extend(str(x) for x in desc[:6])
    links: List[str] = []
    for link in rdap.get("links") or []:
        if isinstance(link, dict) and link.get("href"):
            links.append(str(link.get("href")))
    events: List[str] = []
    created = updated = last_changed = "N/A"
    for ev in rdap.get("events") or []:
        if isinstance(ev, dict):
            action = str(ev.get("eventAction") or "event").strip()
            date = str(ev.get("eventDate") or "").strip()
            if action or date:
                events.append(f"{action}={date}".strip("="))
            al = action.lower()
            if "registration" in al and created == "N/A": created = date or "N/A"
            if "last changed" in al or "last update" in al or "updated" in al:
                last_changed = date or last_changed
                updated = date or updated
    entities_roles: List[str] = []
    org_names: List[str] = []
    org_handles: List[str] = []
    org_addresses: List[str] = []
    org_countries: List[str] = []
    abuse_emails: List[str] = []
    abuse_phones: List[str] = []
    tech_contacts: List[str] = []
    admin_contacts: List[str] = []
    noc_contacts: List[str] = []
    for ent in rdap.get("entities") or []:
        if not isinstance(ent, dict):
            continue
        roles = [str(x).lower() for x in (ent.get("roles") or [])]
        role_text = ",".join(roles)
        handle = str(ent.get("handle") or "").strip()
        vals = _ipf_vcard_values(ent.get("vcardArray"))
        names = vals.get("org") or vals.get("fn") or []
        emails = vals.get("email") or []
        phones = vals.get("tel") or []
        addresses = vals.get("adr") or []
        if handle:
            entities_roles.append(f"{handle} ({role_text or 'role N/A'})")
            org_handles.append(handle)
        for n in names:
            if n not in org_names: org_names.append(n)
        for a in addresses:
            if a not in org_addresses: org_addresses.append(a)
        c = ent.get("country")
        if c and str(c) not in org_countries: org_countries.append(str(c))
        if "abuse" in roles:
            abuse_emails.extend(emails)
            abuse_phones.extend(phones)
        if "technical" in roles or "tech" in roles:
            tech_contacts.extend(names + emails + phones)
        if "administrative" in roles or "admin" in roles:
            admin_contacts.extend(names + emails + phones)
        if "noc" in roles:
            noc_contacts.extend(names + emails + phones)
    start = rdap.get("startAddress") or "N/A"
    end = rdap.get("endAddress") or "N/A"
    net_range = f"{start} - {end}" if start != "N/A" and end != "N/A" else "N/A"
    base.update({
        "available": True,
        "registry": registry_from(source_url),
        "source_url": source_url,
        "handle": rdap.get("handle") or "N/A",
        "name": rdap.get("name") or "N/A",
        "type": rdap.get("type") or "N/A",
        "country": rdap.get("country") or "N/A",
        "start_address": start,
        "end_address": end,
        "net_range": net_range,
        "cidr": _ipf_join(cidrs, limit=24),
        "cidr_blocks": _ipf_join(cidrs, limit=24),
        "net_name": rdap.get("name") or "N/A",
        "net_handle": rdap.get("handle") or "N/A",
        "parent": rdap.get("parentHandle") or "N/A",
        "parent_network": rdap.get("parentHandle") or "N/A",
        "org_name": _ipf_join(org_names, limit=4),
        "org_handle": _ipf_join(org_handles, limit=6),
        "org_address": _ipf_join(org_addresses, limit=4, sep=" | "),
        "org_country": _ipf_join(org_countries, limit=4),
        "status": _ipf_join(rdap.get("status") or [], limit=12),
        "created": created,
        "updated": updated,
        "last_changed": last_changed,
        "abuse_email": _ipf_join(abuse_emails, limit=10),
        "abuse_phone": _ipf_join(abuse_phones, limit=6),
        "tech_contact": _ipf_join(tech_contacts, limit=12),
        "admin_contact": _ipf_join(admin_contacts, limit=12),
        "noc_contact": _ipf_join(noc_contacts, limit=12),
        "remarks": _ipf_join(remarks, limit=20, sep=" | "),
        "events": _ipf_join(events, limit=20, sep=" | "),
        "entities_roles": _ipf_join(entities_roles, limit=30, sep=" | "),
        "links": _ipf_join(links, limit=30, sep=" | "),
        "notices": _ipf_join(notices, limit=20, sep=" | "),
        "whois_server": rdap.get("port43") or rdap.get("whoisServer") or "N/A",
        "raw_keys": sorted([str(k) for k in rdap.keys()])[:80],
    })
    return base


def _ipf_public_provider_data(ip: str, is_global: bool) -> Dict[str, Any]:
    if not is_global:
        return {}
    urls = {
        "ip-api.com": f"http://ip-api.com/json/{urllib.parse.quote(ip)}?fields=status,message,continent,continentCode,country,countryCode,region,regionName,city,district,zip,lat,lon,timezone,offset,currency,isp,org,as,asname,reverse,mobile,proxy,hosting,query",
        "ipinfo.io": f"https://ipinfo.io/{urllib.parse.quote(ip)}/json",
        "ipwho.is": f"https://ipwho.is/{urllib.parse.quote(ip)}",
        "ipapi.co": f"https://ipapi.co/{urllib.parse.quote(ip)}/json/",
        "geolocation-db.com": f"https://geolocation-db.com/json/{urllib.parse.quote(ip)}&position=true",
    }
    out: Dict[str, Any] = {}
    def fetch(item: Tuple[str, str]) -> Tuple[str, Any]:
        k, u = item
        return k, _ipf_fetch_json(u, timeout=IPF_API_TIMEOUT_SECONDS)
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(5, len(urls))) as ex:
            for k, v in ex.map(fetch, urls.items()):
                if isinstance(v, dict) and v.get("status") == "fail":
                    v = {}
                if isinstance(v, dict) and v.get("success") is False:
                    v = {}
                out[k] = v if isinstance(v, dict) else {}
    except Exception:
        for k, u in urls.items():
            v = _ipf_fetch_json(u, timeout=IPF_API_TIMEOUT_SECONDS)
            out[k] = v if isinstance(v, dict) else {}

    apilayer_key = str(os.environ.get("APILAYER_API_KEY") or os.environ.get("APILAYER_KEY") or "").strip()
    if apilayer_key:
        obj, err = _ipf_http_json_with_headers(
            f"https://api.apilayer.com/ip_to_location/{urllib.parse.quote(ip)}",
            {"apikey": apilayer_key, "Accept": "application/json", "User-Agent": f"C8-IPForensics/{APP_VERSION}"},
            timeout=max(5.0, IPF_API_TIMEOUT_SECONDS),
        )
        if isinstance(obj, dict) and obj and not obj.get("error"):
            out["apilayer.com"] = obj
        else:
            out["apilayer.com"] = {}
    return out


def _ipf_geo_merge(providers: Dict[str, Any]) -> Dict[str, Any]:
    ipapi = providers.get("ip-api.com") or {}
    ipwho = providers.get("ipwho.is") or {}
    ipinfo = providers.get("ipinfo.io") or {}
    ipapico = providers.get("ipapi.co") or {}
    geodb = providers.get("geolocation-db.com") or {}
    apilayer = providers.get("apilayer.com") or {}
    ap_conn = apilayer.get("connection") if isinstance(apilayer.get("connection"), dict) else {}
    ap_location = apilayer.get("location") if isinstance(apilayer.get("location"), dict) else {}
    ap_currencies = apilayer.get("currencies") if isinstance(apilayer.get("currencies"), list) else []
    ap_timezones = apilayer.get("timezones") if isinstance(apilayer.get("timezones"), list) else []
    ap_currency = (ap_currencies[0].get("code") if ap_currencies and isinstance(ap_currencies[0], dict) else None)
    ap_timezone = ap_timezones[0] if ap_timezones else None
    ipinfo_lat = ipinfo_lon = None
    try:
        loc = str(ipinfo.get("loc") or "")
        if "," in loc:
            ipinfo_lat, ipinfo_lon = [x.strip() for x in loc.split(",", 1)]
    except Exception:
        pass
    tzobj = ipwho.get("timezone") or {} if isinstance(ipwho, dict) else {}
    offset = _ipf_first(ipapico.get("utc_offset"), tzobj.get("utc"), default=None)
    if _ipf_is_blankish(offset):
        try:
            sec = int(float(ipapi.get("offset")))
            sign = "+" if sec >= 0 else "-"
            sec = abs(sec)
            offset = f"{sign}{sec//3600:02d}:{(sec%3600)//60:02d}"
        except Exception:
            offset = "N/A"
    geo = {
        "country": _ipf_first(apilayer.get("country_name"), ipapi.get("country"), ipwho.get("country"), ipinfo.get("country"), ipapico.get("country_name"), geodb.get("country_name")),
        "country_code": _ipf_first(apilayer.get("country_code"), ipapi.get("countryCode"), ipwho.get("country_code"), ipinfo.get("country"), ipapico.get("country_code"), geodb.get("country_code")),
        "region_name": _ipf_first(apilayer.get("region_name"), ipapi.get("regionName"), ipwho.get("region"), ipinfo.get("region"), ipapico.get("region"), geodb.get("state")),
        "region_code": _ipf_first(ipapi.get("region"), ipwho.get("region_code"), ipapico.get("region_code"), geodb.get("state_code")),
        "city": _ipf_first(apilayer.get("city"), ipapi.get("city"), ipwho.get("city"), ipinfo.get("city"), ipapico.get("city"), geodb.get("city")),
        "district": _ipf_first(ipapi.get("district"), ipapico.get("district")),
        "postal": _ipf_first(apilayer.get("zip"), ipapi.get("zip"), ipwho.get("postal"), ipinfo.get("postal"), ipapico.get("postal"), geodb.get("postal")),
        "latitude": _ipf_first(apilayer.get("latitude"), ipapi.get("lat"), ipwho.get("latitude"), ipinfo_lat, ipapico.get("latitude"), geodb.get("latitude")),
        "longitude": _ipf_first(apilayer.get("longitude"), ipapi.get("lon"), ipwho.get("longitude"), ipinfo_lon, ipapico.get("longitude"), geodb.get("longitude")),
        "timezone": _ipf_first(ap_timezone, ipapi.get("timezone"), tzobj.get("id"), ipinfo.get("timezone"), ipapico.get("timezone"), geodb.get("time_zone")),
        "utc_offset": _ipf_safe(offset),
        "currency": _ipf_first(ap_currency, ipapi.get("currency"), ipapico.get("currency")),
        "continent": _ipf_first(apilayer.get("continent_name"), ipapi.get("continent"), ipwho.get("continent"), ipapico.get("continent_name")),
        "continent_code": _ipf_first(apilayer.get("continent_code"), ipapi.get("continentCode"), ipwho.get("continent_code"), ipapico.get("continent_code")),
        "geoname_id": _ipf_first(ipwho.get("geoname_id")),
        "providers": ", ".join([k for k, v in providers.items() if isinstance(v, dict) and v]) or "N/A",
    }
    score = 0.2
    try:
        if geo["country"] != "N/A": score += 0.15
        if geo["region_name"] != "N/A": score += 0.15
        if geo["city"] != "N/A": score += 0.1
        if geo["latitude"] != "N/A" and geo["longitude"] != "N/A": score += 0.2
        if ipapi and ipwho and str(ipapi.get("countryCode") or "").upper() == str(ipwho.get("country_code") or "").upper(): score += 0.1
        if ipapi and ipwho and str(ipapi.get("city") or "").lower() == str(ipwho.get("city") or "").lower() and str(ipapi.get("city") or ""):
            score += 0.1
    except Exception:
        pass
    geo["confidence"] = f"{min(1.0, max(0.0, score)):.2f}"
    return geo


def _ipf_bgpview(ip: str, as_number: str = "N/A") -> Dict[str, Any]:
    out: Dict[str, Any] = {"prefixes": "N/A", "most_specific_prefix": "N/A", "origin_as": as_number, "asn_name": "N/A", "asn_description": "N/A", "asn_country": "N/A", "source": "BGPView API"}
    try:
        j = _ipf_fetch_json(f"https://api.bgpview.io/ip/{urllib.parse.quote(ip)}", timeout=IPF_API_TIMEOUT_SECONDS)
        data = j.get("data") if isinstance(j, dict) else {}
        prefixes = data.get("prefixes") or [] if isinstance(data, dict) else []
        pref_strings = []
        for p in prefixes[:30]:
            if not isinstance(p, dict):
                continue
            prefix = p.get("prefix")
            if prefix:
                pref_strings.append(str(prefix))
            asn_obj = p.get("asn") or {}
            if asn_obj and out.get("origin_as") in (None, "", "N/A"):
                a = asn_obj.get("asn")
                if a: out["origin_as"] = f"AS{a}"
            if asn_obj:
                out["asn_name"] = _ipf_first(out.get("asn_name"), asn_obj.get("name"))
                out["asn_description"] = _ipf_first(out.get("asn_description"), asn_obj.get("description"), asn_obj.get("name"))
                out["asn_country"] = _ipf_first(out.get("asn_country"), asn_obj.get("country_code"))
        out["prefixes"] = _ipf_join(pref_strings, limit=30)
        out["most_specific_prefix"] = pref_strings[0] if pref_strings else "N/A"
    except Exception:
        pass
    try:
        if _ipf_unknown_value(out.get("most_specific_prefix")) or _ipf_unknown_value(out.get("origin_as")):
            ni = _ipf_fetch_json(f"https://stat.ripe.net/data/network-info/data.json?resource={urllib.parse.quote(str(ip))}", timeout=IPF_API_TIMEOUT_SECONDS)
            nd = ni.get("data") if isinstance(ni, dict) else {}
            if isinstance(nd, dict):
                routed_prefix = str(nd.get("prefix") or "").strip()
                asns = nd.get("asns") or []
                if routed_prefix and "/" in routed_prefix:
                    out["most_specific_prefix"] = routed_prefix
                    out["prefixes"] = routed_prefix if _ipf_unknown_value(out.get("prefixes")) else out.get("prefixes")
                if isinstance(asns, list) and asns:
                    digits = re.sub(r"\D", "", str(asns[0]))
                    if digits:
                        out["origin_as"] = f"AS{digits}"
                out["source"] = "BGPView API + RIPEstat network-info fallback"
    except Exception:
        pass
    try:
        if not _ipf_unknown_value(out.get("most_specific_prefix")):
            po = _ipf_fetch_json(f"https://stat.ripe.net/data/prefix-overview/data.json?resource={urllib.parse.quote(str(out.get('most_specific_prefix')), safe='')}", timeout=IPF_API_TIMEOUT_SECONDS)
            pd = po.get("data") if isinstance(po, dict) else {}
            if isinstance(pd, dict):
                asns = pd.get("asns") or []
                for item in asns if isinstance(asns, list) else []:
                    if not isinstance(item, dict):
                        continue
                    digits = re.sub(r"\D", "", str(item.get("asn") or ""))
                    if digits and _ipf_unknown_value(out.get("origin_as")):
                        out["origin_as"] = f"AS{digits}"
                    holder = item.get("holder")
                    if holder:
                        out["asn_name"] = _ipf_first(out.get("asn_name"), holder)
                        out["asn_description"] = _ipf_first(out.get("asn_description"), holder)
                block = pd.get("block") or {}
                if isinstance(block, dict):
                    out["asn_country"] = _ipf_first(out.get("asn_country"), block.get("name"))
    except Exception:
        pass
    try:
        asn_digits = re.sub(r"\D", "", str(out.get("origin_as") or as_number or ""))
        if asn_digits:
            j2 = _ipf_fetch_json(f"https://api.bgpview.io/asn/{asn_digits}", timeout=IPF_API_TIMEOUT_SECONDS)
            d2 = j2.get("data") if isinstance(j2, dict) else {}
            if isinstance(d2, dict):
                out["asn_name"] = _ipf_first(out.get("asn_name"), d2.get("name"), d2.get("name_short"))
                out["asn_description"] = _ipf_first(out.get("asn_description"), d2.get("description_full"), d2.get("description_short"))
                out["asn_country"] = _ipf_first(out.get("asn_country"), d2.get("country_code"))
    except Exception:
        pass
    try:
        asn_digits = re.sub(r"\D", "", str(out.get("origin_as") or as_number or ""))
        if asn_digits and (_ipf_unknown_value(out.get("asn_name")) or _ipf_unknown_value(out.get("asn_description"))):
            ao = _ipf_fetch_json(f"https://stat.ripe.net/data/as-overview/data.json?resource=AS{asn_digits}", timeout=IPF_API_TIMEOUT_SECONDS)
            ad = ao.get("data") if isinstance(ao, dict) else {}
            if isinstance(ad, dict):
                holder = ad.get("holder")
                out["asn_name"] = _ipf_first(out.get("asn_name"), holder)
                out["asn_description"] = _ipf_first(out.get("asn_description"), holder)
    except Exception:
        pass
    return out


def _ipf_peeringdb(as_number: str) -> Dict[str, Any]:
    out = {
        "organization": "N/A", "as_profile": "N/A", "peering_policy": "N/A", "traffic_policy": "N/A",
        "ixp_memberships": "N/A", "ixps_where_present": "N/A", "facility_presence": "N/A", "pop_cities": "N/A",
        "route_server_participation": "N/A", "public_private_peering_notes": "N/A", "source": "N/A",
        "_status": "not attempted", "_errors": [],
    }
    asn_digits = re.sub(r"\D", "", str(as_number or ""))
    if not asn_digits:
        out["_status"] = "ASN unavailable; PeeringDB lookup deferred until ASN recovery."
        return out
    try:
        j = _ipf_fetch_json(f"https://www.peeringdb.com/api/net?asn={asn_digits}", timeout=IPF_API_TIMEOUT_SECONDS)
        rows = j.get("data") if isinstance(j, dict) else []
        if not rows:
            out["_status"] = f"PeeringDB returned no network record for AS{asn_digits}."
            out["source"] = f"PeeringDB API: no matching network record for AS{asn_digits}"
            return out
        n = rows[0]
        net_id = n.get("id")
        route_server = _ipf_first(n.get("route_server"), n.get("info_never_via_route_servers"), default="N/A")
        if isinstance(route_server, bool):
            route_server_text = "Never via route servers" if route_server else "Route-server restriction not published"
        else:
            route_server_text = str(route_server) if not _ipf_unknown_value(route_server) else "N/A"
        out.update({
            "organization": _ipf_first(n.get("name"), n.get("aka")),
            "as_profile": f"ASN={asn_digits}; name={_ipf_first(n.get('name'), 'N/A')}; info_type={_ipf_first(n.get('info_type'), 'N/A')}; scope={_ipf_first(n.get('info_scope'), 'N/A')}; prefixes4={_ipf_first(n.get('info_prefixes4'), 'N/A')}; prefixes6={_ipf_first(n.get('info_prefixes6'), 'N/A')}; ix_count={_ipf_first(n.get('ix_count'), 'N/A')}; fac_count={_ipf_first(n.get('fac_count'), 'N/A')}",
            "peering_policy": _ipf_first(n.get("policy_general"), n.get("policy_locations")),
            "traffic_policy": _ipf_first(n.get("info_traffic"), n.get("info_ratio"), n.get("policy_ratio")),
            "route_server_participation": route_server_text,
            "public_private_peering_notes": _ipf_join([n.get("policy_contracts"), n.get("policy_ratio"), n.get("notes")], limit=8, sep=" | "),
            "source": "PeeringDB API",
            "_status": f"PeeringDB network record loaded for AS{asn_digits} (net_id={net_id or 'N/A'}).",
        })
        if net_id:
            try:
                ix = _ipf_fetch_json(f"https://www.peeringdb.com/api/netixlan?net_id={int(net_id)}", timeout=IPF_API_TIMEOUT_SECONDS)
                ixrows = ix.get("data") if isinstance(ix, dict) else []
                ixnames = []
                rs_yes = 0
                rs_no = 0
                for r in (ixrows or [])[:100]:
                    nm = r.get("name") or r.get("ix_id") or r.get("ixlan_id")
                    if nm and str(nm) not in ixnames:
                        ixnames.append(str(nm))
                    if r.get("is_rs_peer") is True:
                        rs_yes += 1
                    elif r.get("is_rs_peer") is False:
                        rs_no += 1
                out["ixp_memberships"] = _ipf_join(ixnames, limit=100)
                if _ipf_unknown_value(out["ixp_memberships"]) and not _ipf_unknown_value(n.get("ix_count")):
                    out["ixp_memberships"] = f"{n.get('ix_count')} PeeringDB IX LAN memberships published; detailed IX names unavailable in this request"
                out["ixps_where_present"] = out["ixp_memberships"]
                if rs_yes or rs_no:
                    out["route_server_participation"] = f"{rs_yes} PeeringDB IX LAN rows marked route-server peer; {rs_no} marked direct/non-RS"
            except Exception as exc:
                out["_errors"].append(f"netixlan: {type(exc).__name__}: {exc}"[:220])
            try:
                nf = _ipf_fetch_json(f"https://www.peeringdb.com/api/netfac?net_id={int(net_id)}", timeout=IPF_API_TIMEOUT_SECONDS)
                nfrows = nf.get("data") if isinstance(nf, dict) else []
                facs = []
                cities = []
                for r in (nfrows or [])[:100]:
                    fac = _ipf_first(r.get("name"), r.get("fac_id"))
                    if not _ipf_unknown_value(fac) and str(fac) not in facs:
                        facs.append(str(fac))
                    city = _ipf_first(r.get("city"), default="")
                    country = _ipf_first(r.get("country"), default="")
                    loc = ", ".join(x for x in [str(city).strip(), str(country).strip()] if x and not _ipf_unknown_value(x))
                    if loc and loc not in cities:
                        cities.append(loc)
                out["facility_presence"] = _ipf_join(facs, limit=100)
                if _ipf_unknown_value(out["facility_presence"]) and not _ipf_unknown_value(n.get("fac_count")):
                    out["facility_presence"] = f"{n.get('fac_count')} PeeringDB facility presences published; detailed facility names unavailable in this request"
                out["pop_cities"] = _ipf_join(cities, limit=100)
                if _ipf_unknown_value(out["pop_cities"]) and not _ipf_unknown_value(n.get("info_scope")):
                    out["pop_cities"] = f"Scope={n.get('info_scope')}; facility count={_ipf_first(n.get('fac_count'), 'N/A')}"
            except Exception as exc:
                out["_errors"].append(f"netfac: {type(exc).__name__}: {exc}"[:220])
    except Exception as exc:
        out["_status"] = f"PeeringDB lookup failed for AS{asn_digits}: {type(exc).__name__}: {exc}"[:240]
        out["_errors"].append(out["_status"])
        out["source"] = "PeeringDB API lookup failed"
    return out


def _ipf_tor_status(ip: str, is_global: bool) -> Dict[str, str]:
    if not is_global:
        return {"tor_node": "False", "relay": "False", "details": "N/A"}
    try:
        j = _ipf_fetch_json(f"https://onionoo.torproject.org/details?search={urllib.parse.quote(ip)}", timeout=IPF_API_TIMEOUT_SECONDS)
        relays = j.get("relays") if isinstance(j, dict) else []
        bridges = j.get("bridges") if isinstance(j, dict) else []
        if relays:
            r0 = relays[0] or {}
            details = f"{r0.get('nickname','relay')} flags={_ipf_join(r0.get('flags') or [], limit=12)}"
            return {"tor_node": "True", "relay": "True", "details": details}
        if bridges:
            return {"tor_node": "True", "relay": "Bridge", "details": "Bridge match returned by Onionoo"}
        return {"tor_node": "False", "relay": "False", "details": "No Onionoo match"}
    except Exception:
        return {"tor_node": "N/A", "relay": "N/A", "details": "Onionoo lookup failed"}


def _ipf_passive_dns(ip: str, is_global: bool) -> Dict[str, Any]:
    out = {"current_names": [], "historical_names": [], "first_last": [], "sources": set(), "source_count": 0}
    if not is_global:
        return {"current_names": "N/A", "historical_names": "N/A", "first_last": "N/A", "source_count": "0", "sources": "N/A"}
    def add_name(name: Any, first: Any = None, last: Any = None, source: str = "") -> None:
        s = str(name or "").strip().rstrip(".")
        if not s or "." not in s:
            return
        if source:
            out["sources"].add(source)
        if last and s not in out["current_names"]:
            out["current_names"].append(s)
        if s not in out["historical_names"]:
            out["historical_names"].append(s)
        if first or last:
            out["first_last"].append(f"{s}: first={first or 'N/A'} last={last or 'N/A'} source={source or 'N/A'}")
    try:
        kind = "IPv6" if ":" in ip else "IPv4"
        headers = {"User-Agent": "GovStyleConsolePowered-IPF/2.1", "Accept": "application/json"}
        key = os.getenv("OTX_API_KEY") or os.getenv("ALIENVAULT_OTX_KEY")
        if key:
            headers["X-OTX-API-KEY"] = key
        req = urllib.request.Request(f"https://otx.alienvault.com/api/v1/indicators/{kind}/{urllib.parse.quote(ip)}/passive_dns", headers=headers)
        with _c8_urlopen(req, timeout=IPF_API_TIMEOUT_SECONDS) as r:
            j = json.loads(r.read(2_000_000).decode("utf-8", errors="replace"))
        records = j.get("passive_dns") or j.get("data") or [] if isinstance(j, dict) else []
        for rec in records[:200]:
            if isinstance(rec, dict):
                add_name(rec.get("hostname") or rec.get("host") or rec.get("domain") or rec.get("name"), rec.get("first") or rec.get("first_seen") or rec.get("first_seen_utc"), rec.get("last") or rec.get("last_seen") or rec.get("last_seen_utc"), "OTX")
    except Exception:
        pass
    try:
        ripe = _ipf_fetch_json(f"https://stat.ripe.net/data/reverse-dns-ip/data.json?resource={urllib.parse.quote(ip)}", timeout=IPF_API_TIMEOUT_SECONDS)
        data = ripe.get("data") if isinstance(ripe, dict) else {}
        names = data.get("result") or data.get("names") or data.get("records") or [] if isinstance(data, dict) else []
        if isinstance(names, dict):
            names = list(names.values())
        for item in (names or [])[:100]:
            if isinstance(item, dict):
                add_name(item.get("name") or item.get("hostname") or item.get("domain"), source="RIPEstat reverse-dns-ip")
            else:
                add_name(item, source="RIPEstat reverse-dns-ip")
    except Exception:
        pass
    out["source_count"] = len(out["sources"])
    return {
        "current_names": _ipf_join(out["current_names"], limit=80),
        "historical_names": _ipf_join(out["historical_names"], limit=120),
        "first_last": _ipf_join(out["first_last"], limit=120, sep=" | "),
        "source_count": str(out["source_count"]),
        "sources": _ipf_join(sorted(out["sources"]), limit=10),
    }


def _ipf_dns_google(name: str, qtype: str = "A") -> Dict[str, Any]:
    try:
        if _ipf_is_blankish(name):
            return {}
        return _ipf_fetch_json(f"https://dns.google/resolve?name={urllib.parse.quote(str(name).rstrip('.'))}&type={urllib.parse.quote(qtype)}", timeout=3.0, max_bytes=512_000)
    except Exception:
        return {}


def _ipf_dns_cloudflare(name: str, qtype: str = "A") -> Dict[str, Any]:
    try:
        if _ipf_is_blankish(name):
            return {}
        url = f"https://cloudflare-dns.com/dns-query?name={urllib.parse.quote(str(name).rstrip('.'))}&type={urllib.parse.quote(qtype)}"
        req = urllib.request.Request(url, headers={
            "User-Agent": "C-8-IPForensics-DNS/3.2",
            "Accept": "application/dns-json",
            "Accept-Encoding": "identity",
        })
        with _c8_urlopen(req, timeout=3.5) as response:
            raw = response.read(512_000)
        obj = json.loads(raw.decode("utf-8", errors="replace"))
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {}


def _ipf_ptr_profile(ip: str) -> Tuple[str, str, str]:
    try:
        ptr = ipaddress.ip_address(ip).reverse_pointer
    except Exception:
        ptr = "N/A"
    names: List[str] = []
    ttls: List[str] = []
    resolver_notes: List[str] = []

    def add_answers(obj: Any, source: str) -> None:
        if not isinstance(obj, dict):
            return
        answers = obj.get("Answer") or obj.get("answers") or []
        if not isinstance(answers, list):
            return
        found = 0
        for ans in answers:
            if not isinstance(ans, dict):
                continue
            typ = ans.get("type")
            if typ not in (None, 12, "12", "PTR", "ptr"):
                continue
            data = str(ans.get("data") or ans.get("value") or "").strip().rstrip(".")
            if data and data not in names:
                names.append(data)
                found += 1
            ttl = ans.get("TTL") if ans.get("TTL") is not None else ans.get("ttl")
            if ttl is not None:
                ttl_text = str(ttl)
                if ttl_text not in ttls:
                    ttls.append(ttl_text)
        if found:
            resolver_notes.append(source)

    if ptr != "N/A":
        try:
            add_answers(_ipf_dns_google(ptr, "PTR"), "Google DNS JSON")
        except Exception:
            pass
        if not names or not ttls:
            try:
                add_answers(_ipf_dns_cloudflare(ptr, "PTR"), "Cloudflare DNS JSON")
            except Exception:
                pass
        # Direct recursive DNS fallback. _ipf_dns_exchange is defined later in the module;
        # Python resolves it when this function is called after module initialization.
        if not names or not ttls:
            for resolver_ip, label in (("1.1.1.1", "Cloudflare DNS/UDP"), ("8.8.8.8", "Google DNS/UDP")):
                try:
                    resp = _ipf_dns_exchange(resolver_ip, ptr, 12, edns_size=1232, timeout=2.2)
                    if isinstance(resp, dict) and resp.get("valid"):
                        add_answers({"Answer": resp.get("answers") or []}, label)
                except Exception:
                    pass
                if names and ttls:
                    break
    try:
        if not names:
            host, aliases, _addrs = socket.gethostbyaddr(ip)
            for h in [host] + list(aliases or []):
                h = str(h or "").strip().rstrip(".")
                if h and h not in names:
                    names.append(h)
            if names:
                resolver_notes.append("system gethostbyaddr")
    except Exception:
        pass

    ttl_value = _ipf_join(ttls, limit=20)
    if _ipf_unknown_value(ttl_value):
        if names:
            ttl_value = "PTR hostname recovered, but no TTL was returned by Google DNS, Cloudflare DNS, or direct recursive DNS fallbacks."
        else:
            ttl_value = "No PTR answer/TTL returned by Google DNS, Cloudflare DNS, direct recursive DNS, or the system resolver."
    return ptr, _ipf_join(names, limit=40), ttl_value


def _ipf_forward_confirm(ip: str, names: List[str]) -> Tuple[str, str, str]:
    associated: List[str] = []
    try:
        for name in names[:20]:
            if _ipf_is_blankish(name):
                continue
            found = []
            try:
                for _fam, _typ, _proto, _canon, sockaddr in socket.getaddrinfo(name, None):
                    if sockaddr and sockaddr[0]:
                        found.append(str(sockaddr[0]))
            except Exception:
                pass
            if ip in found:
                associated.append(name)
        return ("True" if associated else "False"), _ipf_join(associated, limit=50), str(len(associated))
    except Exception:
        return "N/A", "N/A", "N/A"


def _ipf_name_pattern(hostname: str, usage: str) -> str:
    host = str(hostname or "").strip().lower().rstrip(".")
    usage_text = str(usage or "").strip().lower()
    if _ipf_is_blankish(host):
        if not _ipf_is_blankish(usage_text):
            return f"No PTR hostname published; network usage classification is {usage}."
        return "No PTR hostname was published, so a DNS naming-pattern classification cannot be made."

    s = f"{host} {usage_text}"
    bits: List[str] = []
    checks = [
        (("dns", "resolver", "ns1", "ns2", "nameserver"), "resolver/DNS naming"),
        (("mail", "smtp", "mx", "imap", "pop"), "mail/messaging naming"),
        (("cdn", "edge", "cache", "pop"), "CDN/edge/cache naming"),
        (("vpn", "proxy", "tor", "exit", "relay"), "proxy/VPN/Tor naming"),
        (("static", "business", "corp", "enterprise"), "static/business naming"),
        (("dynamic", "dhcp", "pool", "cust", "client", "residential", "broadband", "cable", "fiber", "dsl", "pppoe"), "dynamic/customer-access naming"),
        (("vps", "vm", "virtual", "cloud", "compute", "droplet", "instance"), "cloud/VPS/compute naming"),
        (("server", "srv", "host", "node", "web", "www"), "server/host naming"),
        (("gw", "gateway", "router", "core", "border", "transit", "peer"), "network-infrastructure naming"),
        (("mobile", "lte", "5g", "4g", "cell", "wireless"), "mobile/wireless access naming"),
    ]
    for keywords, label in checks:
        if any(k in s for k in keywords) and label not in bits:
            bits.append(label)

    numeric_labels = sum(1 for part in host.split(".") if re.search(r"\d", part))
    if numeric_labels >= 2 and any(sep in host for sep in ("-", ".")):
        if "numeric/address-derived hostname pattern" not in bits:
            bits.append("numeric/address-derived hostname pattern")
    try:
        ip_text = re.sub(r"[^0-9a-f:.]", "", host, flags=re.I)
        if ip_text and len(ip_text) >= 7:
            bits.append("reverse-DNS label appears address-derived")
    except Exception:
        pass

    if bits:
        return _ipf_join(bits, limit=12, sep=" | ")
    return f"Unclassified PTR/hostname pattern: {host} (no known resolver, mail, CDN, access, cloud, or infrastructure naming marker matched)."


def _tcp_probe_one(ip: str, port: int, timeout: float = IPF_PROBE_TIMEOUT_SECONDS) -> Dict[str, Any]:
    started = time.monotonic()
    try:
        with socket.create_connection((ip, int(port)), timeout=float(timeout)):
            return {"port": int(port), "open": True, "latency_ms": round((time.monotonic() - started) * 1000, 1)}
    except Exception as e:
        return {"port": int(port), "open": False, "error": str(e)[:160]}


SERVICE_NAME_FALLBACKS = {
    21: "ftp",
    22: "ssh",
    25: "smtp",
    53: "dns",
    80: "http",
    110: "pop3",
    123: "ntp",
    143: "imap",
    443: "https",
    445: "microsoft-ds/smb",
    465: "smtps",
    587: "submission",
    993: "imaps",
    995: "pop3s",
    3389: "rdp",
    5900: "vnc",
    6379: "redis",
    8080: "http-alt",
    8443: "https-alt",
    9200: "elasticsearch",
    11211: "memcached",
    27017: "mongodb",
}


_ORIGINAL_SOCKET_GETSERVBYPORT = socket.getservbyport


def _safe_socket_getservbyport(port: Any, proto: str = "tcp") -> str:
    """No-raise service-name lookup used by the web port and embedded analyzer."""
    try:
        port_int = int(port)
    except Exception:
        return "unknown"
    proto_text = str(proto or "tcp").lower()
    try:
        if 0 < port_int <= 65535:
            name = _ORIGINAL_SOCKET_GETSERVBYPORT(port_int, proto_text)
            if name:
                return str(name)
    except OSError:
        pass
    except Exception:
        pass
    return SERVICE_NAME_FALLBACKS.get(port_int, "unknown")


# Some platforms do not have service database entries for app ports such as
# 9200, 11211, 27017, or similar. The stock socket.getservbyport raises
# OSError("port/proto not found") there. The console treats that as an
# unknown label instead of aborting the whole IP Forensics run.
socket.getservbyport = _safe_socket_getservbyport


def _ipf_service_name(port: int, proto: str = "tcp") -> str:
    """Return a best-effort service label without raising on unknown port/proto pairs."""
    try:
        port_int = int(port)
    except Exception:
        return "unknown"
    try:
        if 0 < port_int <= 65535:
            name = socket.getservbyport(port_int, proto)
            if name:
                return str(name)
    except OSError:
        pass
    except Exception:
        pass
    return SERVICE_NAME_FALLBACKS.get(port_int, "unknown")


def _ipf_common_port_probe(ip: str, enabled: bool = True) -> Dict[str, Any]:
    if not enabled:
        return {"open_tcp_ports": [], "closed_count": 0, "notes": "Full-range service probe disabled by user.", "service_names": {}}
    ports = list(COMMON_SERVICE_PORTS)[:24]
    results: List[Dict[str, Any]] = []
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
            futs = [ex.submit(_tcp_probe_one, ip, p) for p in ports]
            for fut in concurrent.futures.as_completed(futs, timeout=max(3.0, IPF_PROBE_TIMEOUT_SECONDS * 4)):
                try:
                    results.append(fut.result())
                except Exception:
                    pass
    except Exception:
        for p in ports[:12]:
            results.append(_tcp_probe_one(ip, p))
    open_ports = sorted([int(r["port"]) for r in results if r.get("open")])
    service_names = {p: _ipf_service_name(p, "tcp") for p in open_ports}
    return {"open_tcp_ports": open_ports, "closed_count": max(0, len(results) - len(open_ports)), "notes": "Full-range TCP 1-65535 probe mode is handled by the main-menu engine when enabled.", "service_names": service_names, "raw": results[:50]}


def _ipf_http_profiles(ip: str, hostname: str, open_ports: List[int]) -> Dict[str, Any]:
    out: Dict[str, Any] = {}
    candidates: List[Tuple[str, int]] = []
    for p in [80, 8080]:
        if p in open_ports: candidates.append(("http", p))
    for p in [443, 8443]:
        if p in open_ports: candidates.append(("https", p))
    for scheme, port in candidates[:4]:
        url_host = hostname if hostname and hostname != "N/A" and not re.match(r"^\d+\.\d+\.\d+\.\d+$", hostname) else ip
        bracket_host = f"[{url_host}]" if ":" in url_host and not url_host.startswith("[") else url_host
        default_port = 443 if scheme == "https" else 80
        url = f"{scheme}://{bracket_host}" + (f":{port}" if port != default_port else "/")
        status, headers, text, final_url = _ipf_http_text(url, timeout=3.5)
        title = "N/A"
        try:
            m = re.search(r"<title[^>]*>(.*?)</title>", text or "", flags=re.I | re.S)
            if m:
                title = re.sub(r"\s+", " ", m.group(1)).strip()[:240]
        except Exception:
            pass
        lower_headers = {k.lower(): v for k, v in headers.items()}
        cookies = []
        try:
            for k, v in headers.items():
                if k.lower() == "set-cookie":
                    cookies.append(v.split(";", 1)[0])
        except Exception:
            pass
        out[str(port)] = {
            "reachable": bool(status),
            "status": status or "N/A",
            "url": url,
            "final_url": final_url,
            "redirected": "True" if final_url != url else "False",
            "server": lower_headers.get("server", "N/A"),
            "x_powered_by": lower_headers.get("x-powered-by", "N/A"),
            "via": lower_headers.get("via", "N/A"),
            "cdn_headers": _ipf_join([lower_headers.get("cf-cache-status"), lower_headers.get("x-cache"), lower_headers.get("x-served-by"), lower_headers.get("x-amz-cf-pop")], limit=8),
            "hsts": lower_headers.get("strict-transport-security", "N/A"),
            "csp": lower_headers.get("content-security-policy", "N/A"),
            "x_frame_options": lower_headers.get("x-frame-options", "N/A"),
            "x_content_type_options": lower_headers.get("x-content-type-options", "N/A"),
            "referrer_policy": lower_headers.get("referrer-policy", "N/A"),
            "permissions_policy": lower_headers.get("permissions-policy", "N/A"),
            "alt_svc": lower_headers.get("alt-svc", "N/A"),
            "content_type": lower_headers.get("content-type", "N/A"),
            "title": title,
            "response_size": len(text or ""),
            "cookie_names": _ipf_join(cookies, limit=20),
            "html_sha256": hashlib.sha256((text or "").encode("utf-8", errors="ignore")).hexdigest() if text and not str(text).startswith("ERROR:") else "N/A",
            "error": text[:200] if status is None else "N/A",
        }
    return out


def _ipf_tls_probe(ip: str, port: int, sni: str = "") -> Dict[str, Any]:
    out: Dict[str, Any] = {"reachable": False, "port": port, "error": "N/A"}
    try:
        context = ssl.create_default_context()
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE
        try:
            context.set_alpn_protocols(["h2", "http/1.1"])
        except Exception:
            pass
        server_hostname = sni if sni and not _ipf_is_blankish(sni) and not re.match(r"^\d+\.\d+\.\d+\.\d+$", sni) and ":" not in sni else None
        with socket.create_connection((ip, int(port)), timeout=3.0) as raw:
            with context.wrap_socket(raw, server_hostname=server_hostname) as ssock:
                der = ssock.getpeercert(binary_form=True)
                decoded: Dict[str, Any] = {}
                if der:
                    pem = ssl.DER_cert_to_PEM_cert(der)
                    tmp_path = None
                    try:
                        with tempfile.NamedTemporaryFile("w", delete=False, suffix=".pem") as tf:
                            tf.write(pem)
                            tmp_path = tf.name
                        decoded = ssl._ssl._test_decode_cert(tmp_path)  # type: ignore[attr-defined]
                    finally:
                        if tmp_path:
                            try: os.unlink(tmp_path)
                            except Exception: pass
                def dn(x: Any) -> str:
                    vals = []
                    try:
                        for rdn in x or []:
                            for k, v in rdn:
                                vals.append(f"{k}={v}")
                    except Exception:
                        pass
                    return _ipf_join(vals, limit=20)
                sans = []
                try:
                    for typ, val in decoded.get("subjectAltName") or []:
                        sans.append(f"{typ}:{val}")
                except Exception:
                    pass
                not_after = decoded.get("notAfter") or "N/A"
                days_left = "N/A"
                try:
                    if not_after != "N/A":
                        exp = datetime.fromtimestamp(ssl.cert_time_to_seconds(not_after), tz=timezone.utc)
                        days_left = str((exp - datetime.now(timezone.utc)).days)
                except Exception:
                    pass
                out.update({
                    "reachable": True,
                    "tls_ver": ssock.version() or "N/A",
                    "cipher": "/".join(str(x) for x in (ssock.cipher() or ())) or "N/A",
                    "alpn": ssock.selected_alpn_protocol() or "N/A",
                    "cert_subject": dn(decoded.get("subject")),
                    "cert_issuer": dn(decoded.get("issuer")),
                    "cert_san": _ipf_join(sans, limit=80),
                    "serial_number": decoded.get("serialNumber") or "N/A",
                    "cert_not_before": decoded.get("notBefore") or "N/A",
                    "cert_not_after": not_after,
                    "days_until_expiration": days_left,
                    "cert_sha1": hashlib.sha1(der).hexdigest() if der else "N/A",
                    "cert_sha256": hashlib.sha256(der).hexdigest() if der else "N/A",
                })
    except Exception as e:
        out["error"] = str(e)[:240]
    return out


def _ipf_tls_profiles(ip: str, hostname: str, open_ports: List[int]) -> Dict[str, Any]:
    out = {}
    for p in [443, 8443, 465, 993, 995]:
        if p in open_ports:
            out[str(p)] = _ipf_tls_probe(ip, p, hostname)
    return out


def _ipf_banner_probe(ip: str, port: int, send_data: bytes = b"", timeout: float = 2.0) -> str:
    try:
        with socket.create_connection((ip, int(port)), timeout=timeout) as s:
            s.settimeout(timeout)
            banner = b""
            try:
                banner += s.recv(512)
            except Exception:
                pass
            if send_data:
                try:
                    s.sendall(send_data)
                    time.sleep(0.2)
                    banner += s.recv(1024)
                except Exception:
                    pass
            return banner.decode("utf-8", errors="replace").strip()[:1000] or "N/A"
    except Exception as e:
        return f"N/A ({e})"


def _ipf_security_policy(domain: str, rdap: Dict[str, Any], as_number: str, prefix: str) -> Dict[str, Any]:
    out = {"abuse_policy_url": "N/A", "aup_url": "N/A", "noc_portal_url": "N/A", "security_txt_contact": "N/A", "security_txt_policy": "N/A", "disclosure_contact": "N/A", "takedown_contact": "N/A", "geofeed_url": "N/A", "rpki_policy_posture": "N/A", "irr_maintenance_quality": "N/A"}
    domains = []
    if domain and domain != "N/A":
        domains.append(domain)
    try:
        links = str(rdap.get("links") or "") + " " + str(rdap.get("remarks") or "") + " " + str(rdap.get("notices") or "")
        urls = re.findall(r"https?://[^\s'\"<>),;]+", links)
        abuse = [u for u in urls if re.search(r"abuse|complaint|report", u, re.I)]
        aup = [u for u in urls if re.search(r"aup|acceptable|terms", u, re.I)]
        noc = [u for u in urls if re.search(r"noc|support|contact", u, re.I)]
        geofeed = [u for u in urls if re.search(r"geofeed|csv", u, re.I)]
        if abuse: out["abuse_policy_url"] = _ipf_join(abuse, limit=8)
        if aup: out["aup_url"] = _ipf_join(aup, limit=8)
        if noc: out["noc_portal_url"] = _ipf_join(noc, limit=8)
        if geofeed: out["geofeed_url"] = _ipf_join(geofeed, limit=8)
    except Exception:
        pass
    for d in domains[:2]:
        for url in [f"https://{d}/.well-known/security.txt", f"https://{d}/security.txt"]:
            status, _headers, body, final = _ipf_http_text(url, timeout=2.5, max_bytes=64_000)
            if status and status < 400 and body:
                contacts = []
                policies = []
                for ln in body.splitlines():
                    if ln.lower().startswith("contact:"):
                        contacts.append(ln.split(":", 1)[1].strip())
                    elif ln.lower().startswith("policy:"):
                        policies.append(ln.split(":", 1)[1].strip())
                out["security_txt_contact"] = _ipf_join(contacts, limit=12)
                out["security_txt_policy"] = _ipf_join(policies, limit=12)
                if out["security_txt_contact"] != "N/A":
                    out["security_txt_contact"] += f" ({final})"
                break
        for key, paths in {"abuse_policy_url": ["/abuse", "/report-abuse"], "aup_url": ["/aup", "/acceptable-use-policy"], "noc_portal_url": ["/noc", "/support", "/contact"]}.items():
            if out[key] != "N/A":
                continue
            for path in paths:
                url = f"https://{d}{path}"
                status, _h, _b, final = _ipf_http_text(url, timeout=2.0, max_bytes=2048)
                if status and status < 400:
                    out[key] = final
                    break
    out["disclosure_contact"] = _ipf_first(out.get("security_txt_contact"), rdap.get("abuse_email"), rdap.get("tech_contact"))
    out["takedown_contact"] = _ipf_first(rdap.get("abuse_email"), out.get("security_txt_contact"), rdap.get("admin_contact"))
    try:
        asres = re.sub(r"\D", "", str(as_number or ""))
        pref = str(prefix or "").split(",")[0].strip()
        if asres and pref and "/" in pref:
            j = _ipf_fetch_json(f"https://stat.ripe.net/data/rpki-validation/data.json?resource=AS{asres}&prefix={urllib.parse.quote(pref)}", timeout=IPF_API_TIMEOUT_SECONDS)
            data = j.get("data") if isinstance(j, dict) else {}
            out["rpki_policy_posture"] = _ipf_first(data.get("status"), data.get("validator"), data.get("validating_roas")) if isinstance(data, dict) else "N/A"
    except Exception:
        pass
    return out


def _ipf_crtsh(domain: str) -> Dict[str, Any]:
    out = {
        "domains": "N/A", "entries": 0, "issuers": "N/A", "not_before": "N/A", "not_after": "N/A",
        "wildcard_count": 0, "expired_count": 0, "unique_name_sets": 0, "letsencrypt_count": 0,
        "reissue_summary": "No CT rows returned", "issuance_summary": "No CT rows returned",
    }
    if _ipf_is_blankish(domain) or "." not in str(domain):
        return out
    try:
        q = urllib.parse.quote("%." + str(domain).strip())
        j = _ipf_fetch_json(f"https://crt.sh/?q={q}&output=json", timeout=IPF_API_TIMEOUT_SECONDS, max_bytes=4_000_000)
        if not isinstance(j, list):
            return out
        names: List[str] = []
        issuers: List[str] = []
        nbs: List[str] = []
        nas: List[str] = []
        name_sets = set()
        wildcard_count = 0
        expired_count = 0
        letsencrypt_count = 0
        now_utc = datetime.now(timezone.utc)
        for rec in j[:500]:
            if not isinstance(rec, dict):
                continue
            raw_names = []
            for nm in str(rec.get("name_value") or "").splitlines():
                nm = nm.strip().rstrip(".")
                if not nm:
                    continue
                raw_names.append(nm.lower())
                if nm.startswith("*."):
                    wildcard_count += 1
                clean_nm = nm.lstrip("*.")
                if clean_nm and clean_nm not in names:
                    names.append(clean_nm)
            if raw_names:
                name_sets.add(tuple(sorted(set(raw_names))))
            issuer = str(rec.get("issuer_name") or "").strip()
            if issuer and issuer not in issuers:
                issuers.append(issuer)
            if "let's encrypt" in issuer.lower() or "letsencrypt" in issuer.lower():
                letsencrypt_count += 1
            nb = str(rec.get("not_before") or "").strip()
            na = str(rec.get("not_after") or "").strip()
            if nb: nbs.append(nb)
            if na:
                nas.append(na)
                try:
                    dt = datetime.fromisoformat(na.replace("Z", "+00:00"))
                    if dt.tzinfo is None: dt = dt.replace(tzinfo=timezone.utc)
                    if dt < now_utc: expired_count += 1
                except Exception:
                    pass
        count = len(j)
        first = min(nbs) if nbs else "N/A"
        last = max(nas) if nas else "N/A"
        issuance_summary = f"{count} crt.sh rows" + (f" spanning {first} to {last}" if first != "N/A" or last != "N/A" else "")
        reissue_summary = f"{count} CT rows across {len(name_sets)} unique certificate-name sets; duplicate rows/name sets may include renewals or multiple log submissions"
        out.update({
            "domains": _ipf_join(names, limit=160), "entries": count, "issuers": _ipf_join(issuers, limit=30),
            "not_before": first, "not_after": last, "wildcard_count": wildcard_count,
            "expired_count": expired_count, "unique_name_sets": len(name_sets), "letsencrypt_count": letsencrypt_count,
            "reissue_summary": reissue_summary, "issuance_summary": issuance_summary,
        })
    except Exception as exc:
        out["error"] = f"{type(exc).__name__}: {exc}"[:240]
    return out


def _ipf_ping_profile(ip: str, enabled: bool = True) -> Dict[str, Any]:
    if not enabled:
        return {"ping_reachability": "Disabled", "rtt": "N/A", "min_avg_max": "N/A", "packet_loss": "N/A", "ttl": "N/A", "estimated_hops": "N/A", "ping_notes": "Common probes disabled.", "raw_icmp_notes": "N/A"}
    try:
        res = system_ping_once_any(ip, timeout=PING_TIMEOUT_SECONDS + 1.5)
        output = str(res.get("output") or "")
        rtt = "N/A"
        ttl = "N/A"
        loss = "N/A"
        m = re.search(r"time[=<]\s*([0-9.]+)\s*ms", output, flags=re.I)
        if m: rtt = m.group(1) + " ms"
        m = re.search(r"ttl[= ](\d+)", output, flags=re.I)
        if m: ttl = m.group(1)
        m = re.search(r"(\d+(?:\.\d+)?)%\s*packet loss", output, flags=re.I)
        if m: loss = m.group(1) + "%"
        hops = "N/A"
        try:
            if ttl != "N/A":
                tv = int(ttl)
                init = 64 if tv <= 64 else (128 if tv <= 128 else 255)
                hops = str(max(0, init - tv))
        except Exception:
            pass
        return {"ping_reachability": "Reachable" if res.get("ok") else "No ICMP reply", "rtt": rtt, "min_avg_max": rtt, "packet_loss": loss, "ttl": ttl, "estimated_hops": hops, "ping_notes": _ipf_first(res.get("error"), res.get("errors"), "Single ICMP probe attempted"), "raw_icmp_notes": output[:1000] or "N/A"}
    except Exception as e:
        return {"ping_reachability": "N/A", "rtt": "N/A", "min_avg_max": "N/A", "packet_loss": "N/A", "ttl": "N/A", "estimated_hops": "N/A", "ping_notes": str(e), "raw_icmp_notes": "N/A"}


def _ipf_role_classification(usage_type: str, as_usage_type: str, is_hosting: bool, is_mobile: bool, is_proxy: bool, is_tor: bool, resolver_status: str) -> Dict[str, str]:
    text = f"{usage_type} {as_usage_type}".lower()
    resolver = "True" if "resolver" in str(resolver_status).lower() else "False"
    cloud = "True" if is_hosting or any(k in text for k in ["hosting", "cloud", "datacenter"]) else "False"
    cdn = "True" if "cdn" in text else "False"
    primary = "TOR" if is_tor else ("Proxy/VPN" if is_proxy else ("Public DNS Resolver" if resolver == "True" else ("Hosting/Datacenter" if is_hosting else ("Mobile" if is_mobile else usage_type or "Unknown"))))
    return {
        "primary_role": primary,
        "cloud_provider_detection": cloud,
        "cdn_detection": cdn,
        "waf_detection": "N/A",
        "reverse_proxy_detection": "N/A",
        "load_balancer_detection": "N/A",
        "public_dns_resolver_detection": resolver,
        "vpn_endpoint_detection": "True" if is_proxy else "False",
        "proxy_detection": "True" if is_proxy else "False",
        "tor_relay_exit_bridge_detection": "True" if is_tor else "False",
        "apple_google_relay_detection": "True" if re.search(r"apple|icloud|google", text) and is_proxy else "False",
        "satellite_isp_detection": "True" if re.search(r"starlink|viasat|hughes|satellite", text) else "False",
        "carrier_grade_nat_likelihood": "Likely" if is_mobile else "N/A",
        "dynamic_vs_static_assignment_confidence": "High static" if (is_hosting or is_proxy or is_tor) else ("Medium dynamic" if is_mobile else "Low/unknown"),
        "datacenter_vs_consumer_confidence_score": "0.80" if is_hosting else ("0.25" if is_mobile else "0.50"),
        "ics_ot_exposure_category": "N/A",
        "iot_device_likelihood": "N/A",
        "scanner_node_research_scanner_classification": "N/A",
    }



def _ll_resolve_ping_targets(host: str) -> List[Tuple[int, str, str]]:
    """Ported from the uploaded main-menu ICMP helper with single-target normalization."""
    out: List[Tuple[int, str, str]] = []
    seen = set()
    raw = normalize_host_or_target(host)
    try:
        ip_obj = ipaddress.ip_address(raw)
        fam = socket.AF_INET6 if ip_obj.version == 6 else socket.AF_INET
        return [(fam, str(ip_obj), "literal")]
    except Exception:
        pass
    try:
        infos = socket.getaddrinfo(raw, None, type=socket.SOCK_STREAM)
    except Exception:
        infos = []
    for fam, _stype, _proto, _canon, addr in infos:
        try:
            ip = addr[0]
            key = (fam, ip)
            if key in seen:
                continue
            seen.add(key)
            label = "IPv6" if fam == socket.AF_INET6 else "IPv4"
            out.append((fam, ip, label))
        except Exception:
            continue
    if not out:
        out.append((socket.AF_INET6 if ":" in raw else socket.AF_INET, raw, "raw"))
    return out


def build_system_ping_cmd_any(host: str, family: Optional[int] = None, timeout_seconds: Optional[float] = None) -> List[str]:
    """Build one platform ping command with a caller-bounded per-sample timeout."""
    h = normalize_host_or_target(host)
    plat = sys.platform
    probe_timeout = max(0.25, min(10.0, float(timeout_seconds if timeout_seconds is not None else PING_TIMEOUT_SECONDS)))
    timeout_s = max(1, int(probe_timeout + 0.999))
    timeout_ms = max(1, int(probe_timeout * 1000))
    is_v6 = family == socket.AF_INET6 or (":" in h and h.count(".") == 0)
    is_v4 = family == socket.AF_INET or bool(re.fullmatch(r"\d{1,3}(?:\.\d{1,3}){3}", h))
    if plat.startswith("win"):
        cmd = ["ping"]
        if is_v6:
            cmd.append("-6")
        elif is_v4:
            cmd.append("-4")
        cmd += ["-n", "1", "-w", str(timeout_ms), h]
        return cmd
    cmd = ["ping"]
    if is_v6:
        cmd.append("-6")
    elif is_v4:
        cmd.append("-4")
    cmd += ["-c", "1", "-W", str(timeout_s), h]
    return cmd


def system_ping_once_any(host: str, timeout: Optional[float] = None) -> Dict[str, Any]:
    """Single ICMP probe. No sweeps, no flood, no loop."""
    timeout = float(timeout or (PING_TIMEOUT_SECONDS + 1.2))
    normalized = normalize_host_or_target(host)
    targets = _ll_resolve_ping_targets(normalized)[:3]
    if not shutil.which("ping"):
        return {"ok": False, "error": "System ping command was not found.", "target": normalized}
    last_errors: List[str] = []
    for fam, ip, label in targets:
        cmd = build_system_ping_cmd_any(ip, fam, timeout_seconds=max(0.35, timeout - 0.25))
        started = time.monotonic()
        try:
            proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, shell=False)
            elapsed_ms = round((time.monotonic() - started) * 1000, 1)
            output = ((proc.stdout or "") + ("\n" + proc.stderr if proc.stderr else "")).strip()
            output = output[:5000]
            if proc.returncode == 0:
                return {
                    "ok": True,
                    "target": normalized,
                    "tested_ip": ip,
                    "family": label,
                    "latency_ms_wall": elapsed_ms,
                    "return_code": proc.returncode,
                    "command": " ".join(cmd[:-1] + [ip]),
                    "output": output,
                }
            last_errors.append(f"{ip}: rc={proc.returncode} {output[:240]}")
        except subprocess.TimeoutExpired:
            last_errors.append(f"{ip}: timed out")
        except Exception as e:
            last_errors.append(f"{ip}: {e}")
    return {"ok": False, "target": normalized, "errors": last_errors[:4]}


def enforce_ping_rate_limit(client: str) -> None:
    """Authenticated console users are not throttled by a per-client ICMP timer.

    The ICMP engine still has host caps, worker caps, cancellable jobs, socket timeouts,
    and the server-wide active-request guard, so removing this tiny timer does not make
    the probe engine unbounded.
    """
    return None


def parse_latency_from_ping_output_web(output: str) -> Optional[float]:
    """Ported from the main-menu pinger latency parser."""
    if not output:
        return None
    out = str(output).replace("\r", "\n")
    patterns = [
        r"time[=<]\s*([0-9]+(?:\.[0-9]+)?)\s*ms",
        r"Average\s*=\s*([0-9]+)ms",
        r"time[=<]\s*<?\s*([0-9]+)\s*ms",
        r"time[=<]\s*([0-9]+(?:\.[0-9]+)?)",
    ]
    for pat in patterns:
        m = re.search(pat, out, re.IGNORECASE)
        if m:
            try:
                return float(m.group(1))
            except Exception:
                pass
    return None


def expand_hosts_from_text(text: str, max_hosts: int = ICMP_MAX_HOSTS_DEFAULT) -> Tuple[List[str], List[str]]:
    """Main-menu-style host list expansion with a web safety cap.

    Accepts one hostname/IP per line, CIDR notation, and IPv4 last-octet ranges such as
    192.168.1.20-35. Returns (hosts, notes).
    """
    notes: List[str] = []
    lines = [l.strip() for l in str(text or "").splitlines() if l.strip()]
    out: List[str] = []
    seen = set()
    cap = max(1, int(max_hosts or ICMP_MAX_HOSTS_DEFAULT))

    def add_host(value: str) -> bool:
        s = value.strip()
        if not s or s in seen:
            return len(out) < cap
        if len(out) >= cap:
            return False
        seen.add(s)
        out.append(s)
        return len(out) < cap

    for p in lines:
        if len(out) >= cap:
            break
        if "/" in p:
            try:
                net = ipaddress.ip_network(p, strict=False)
                for ip in net.hosts():
                    if not add_host(str(ip)):
                        break
                if net.num_addresses > len(out):
                    notes.append(f"CIDR {p} expanded until cap {cap}.")
                continue
            except Exception:
                pass
        if p.count(".") == 3 and "-" in p:
            try:
                base, rng = p.rsplit(".", 1)
                start_s, end_s = rng.split("-", 1)
                start, end = int(start_s), int(end_s)
                if start > end:
                    start, end = end, start
                for o in range(max(0, start), min(255, end) + 1):
                    if not add_host(f"{base}.{o}"):
                        break
                if (end - start + 1) > cap:
                    notes.append(f"Range {p} expanded until cap {cap}.")
                continue
            except Exception:
                pass
        add_host(p)
    if len(lines) and len(out) >= cap:
        notes.append(f"Host list capped at {cap}.")
    return out, notes


def _icmp_resolve_targets(host: str) -> List[Dict[str, str]]:
    rows = []
    for fam, ip, label in _ll_resolve_ping_targets(host):
        rows.append({"family": "IPv6" if fam == socket.AF_INET6 else "IPv4", "ip": ip, "label": label})
    return rows


def _icmp_socket_targets(host: str, socktype: int) -> List[Tuple[int, str]]:
    """Resolve a host once for a whole scan instead of 65,535 getaddrinfo calls."""
    out: List[Tuple[int, str]] = []
    seen = set()
    try:
        for fam, _stype, _proto, _canon, addr in socket.getaddrinfo(host, None, type=socktype):
            ip = str(addr[0])
            key = (fam, ip)
            if key in seen:
                continue
            seen.add(key)
            out.append(key)
            if len(out) >= 4:
                break
    except Exception:
        pass
    if not out:
        for fam, ip, _label in _ll_resolve_ping_targets(host)[:4]:
            key = (fam, str(ip))
            if key not in seen:
                seen.add(key); out.append(key)
    return out


def _icmp_checksum_light(data: bytes) -> int:
    if len(data) & 1:
        data += b"\x00"
    total = 0
    for idx in range(0, len(data), 2):
        total += (data[idx] << 8) + data[idx + 1]
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def _icmp_raw_ping_lightweight(host: str, timeout: float = 0.9) -> Tuple[bool, Optional[float], str]:
    """Small IPv4 raw-ICMP probe that does not load the embedded IPF engine."""
    targets = _ll_resolve_ping_targets(host)[:3]
    notes: List[str] = []
    for fam, target, label in targets:
        if fam != socket.AF_INET:
            notes.append(f"{target}/{label}: raw IPv6 handled by system ping")
            continue
        sock = None
        ident = secrets.randbelow(65535) or 1
        seq = 1
        payload = b"C8ICMP33" + struct.pack("!d", time.time())
        header = struct.pack("!BBHHH", 8, 0, 0, ident, seq)
        checksum = _icmp_checksum_light(header + payload)
        packet = struct.pack("!BBHHH", 8, 0, checksum, ident, seq) + payload
        started = time.perf_counter()
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_ICMP)
            sock.settimeout(max(0.2, min(2.0, float(timeout))))
            sock.sendto(packet, (target, 0))
            deadline = time.monotonic() + max(0.2, min(2.0, float(timeout)))
            while time.monotonic() < deadline:
                data, addr = sock.recvfrom(2048)
                if len(data) < 28:
                    continue
                ihl = (data[0] & 0x0F) * 4
                if len(data) < ihl + 8:
                    continue
                icmp_type, _code, _sum, rx_ident, rx_seq = struct.unpack("!BBHHH", data[ihl:ihl+8])
                if icmp_type == 0 and rx_ident == ident and rx_seq == seq:
                    latency = (time.perf_counter() - started) * 1000.0
                    return True, round(latency, 3), f"raw-icmp reply from={addr[0]} bytes={len(data)}"
        except PermissionError as exc:
            return False, None, f"raw-icmp permission denied ({exc}); system ping fallback available"
        except socket.timeout:
            notes.append(f"{target}: raw-icmp timeout")
        except Exception as exc:
            notes.append(f"{target}: raw-icmp {type(exc).__name__}: {exc}")
        finally:
            try:
                if sock:
                    sock.close()
            except Exception:
                pass
    return False, None, " | ".join(notes[-4:]) or "raw-icmp unavailable"


def _mainmenu_raw_icmp_any(host: str) -> Tuple[bool, Optional[float], str]:
    # r33: ICMP Probe no longer compiles/loads the multi-megabyte IP Forensics
    # engine just to send an echo request. This materially lowers peak RSS.
    return _icmp_raw_ping_lightweight(host, timeout=min(1.0, PING_TIMEOUT_SECONDS))


def _icmp_consistent_ping_once(host: str, timeout: float = 1.4) -> Dict[str, Any]:
    """Return one logical ICMP sample with a reliable fallback order.

    Prefer the platform ping command because it works for ordinary unprivileged
    service accounts and handles IPv4/IPv6 consistently. If it is unavailable or
    produces no reply, try the lightweight raw IPv4 echo helper. A failed system
    ping plus a successful raw reply is still one successful logical sample.
    """
    timeout = max(0.35, min(3.5, float(timeout or 1.4)))
    system_result = system_ping_once_any(host, timeout=timeout + 0.45)
    if system_result.get("ok"):
        latency = parse_latency_from_ping_output_web(str(system_result.get("output") or ""))
        if latency is None:
            latency = system_result.get("latency_ms_wall")
        try:
            latency = round(float(latency), 3) if latency is not None else None
        except Exception:
            latency = None
        return {
            "ok": True,
            "method": "system-icmp",
            "latency_ms": latency,
            "tested_ip": str(system_result.get("tested_ip") or ""),
            "family": str(system_result.get("family") or ""),
            "raw": str(system_result.get("output") or "system ping reply")[:1200],
        }

    raw_ok, raw_latency, raw_note = _icmp_raw_ping_lightweight(host, timeout=min(1.25, timeout))
    if raw_ok:
        return {
            "ok": True,
            "method": "raw-icmp",
            "latency_ms": raw_latency,
            "tested_ip": "",
            "family": "IPv4",
            "raw": str(raw_note or "raw ICMP reply")[:1200],
        }

    errors = list(system_result.get("errors") or [])
    if system_result.get("error"):
        errors.append(str(system_result.get("error")))
    errors.append(str(raw_note or "raw ICMP did not receive a reply"))
    return {
        "ok": False,
        "method": "icmp-no-reply",
        "latency_ms": None,
        "tested_ip": str(system_result.get("tested_ip") or ""),
        "family": str(system_result.get("family") or ""),
        "raw": " | ".join(x for x in errors if x)[:1600] or "No ICMP echo reply was observed.",
    }


def _icmp_latency_series(
    host: str,
    samples: int = 3,
    cancel_event: Optional[threading.Event] = None,
    sample_gap: Optional[float] = None,
) -> Dict[str, Any]:
    """Collect a bounded series of independent logical ping samples.

    The series records every attempt (including losses), uses a stable fallback
    order for each sample, and computes min/average/max plus mean absolute
    consecutive jitter. Cancellation is cooperative between samples.
    """
    samples = max(1, min(8, int(samples or 3)))
    gap = ICMP_SERIES_GAP_SECONDS if sample_gap is None else max(0.0, min(0.75, float(sample_gap)))
    latencies: List[float] = []
    failures: List[str] = []
    sample_rows: List[Dict[str, Any]] = []
    method_counts: Dict[str, int] = {}
    tested_ip = ""
    family = ""
    attempted = 0
    consecutive_losses = 0
    max_consecutive_losses = 0

    for index in range(samples):
        if cancel_event is not None and cancel_event.is_set():
            break
        if C8_LOW_MEMORY_MODE and _c8_memory_pressure(0.78 if C8_ULTRA_LOW_MEMORY_MODE else 0.86):
            failures.append("stopped early: server memory pressure")
            break
        if index and gap > 0 and cancel_event is not None:
            if cancel_event.wait(gap):
                break
        elif index and gap > 0:
            time.sleep(gap)

        attempted += 1
        res = _icmp_consistent_ping_once(host, timeout=min(1.8, PING_TIMEOUT_SECONDS))
        method = str(res.get("method") or "icmp")
        method_counts[method] = int(method_counts.get(method, 0)) + 1
        tested_ip = str(res.get("tested_ip") or tested_ip)
        family = str(res.get("family") or family)
        row = {
            "sequence": attempted,
            "ok": bool(res.get("ok")),
            "method": method,
            "latency_ms": res.get("latency_ms"),
            "raw": str(res.get("raw") or "")[:500],
        }
        sample_rows.append(row)
        if res.get("ok"):
            consecutive_losses = 0
            try:
                if res.get("latency_ms") is not None:
                    latencies.append(float(res.get("latency_ms")))
            except Exception:
                pass
        else:
            consecutive_losses += 1
            max_consecutive_losses = max(max_consecutive_losses, consecutive_losses)
            failures.append(str(res.get("raw") or "no ICMP reply")[:300])

    sent = attempted
    received = sum(1 for row in sample_rows if row.get("ok"))
    jitter = None
    if len(latencies) >= 2:
        diffs = [abs(latencies[i] - latencies[i - 1]) for i in range(1, len(latencies))]
        jitter = sum(diffs) / len(diffs) if diffs else 0.0
    loss = round((1.0 - (received / sent)) * 100.0, 1) if sent else 0.0
    if received == sent and sent:
        stability = "stable"
    elif received:
        stability = "intermittent-loss"
    elif sent:
        stability = "no-icmp-reply"
    else:
        stability = "cancelled"
    return {
        "samples_requested": samples,
        "samples_sent": sent,
        "samples_received": received,
        "packet_loss_percent": loss,
        "min_ms": round(min(latencies), 3) if latencies else None,
        "avg_ms": round(sum(latencies) / len(latencies), 3) if latencies else None,
        "max_ms": round(max(latencies), 3) if latencies else None,
        "jitter_ms": round(jitter, 3) if jitter is not None else None,
        "latencies_ms": [round(v, 3) for v in latencies],
        "tested_ip": tested_ip,
        "family": family,
        "failures": failures[:5],
        "success": bool(received),
        "stability": stability,
        "method_counts": method_counts,
        "max_consecutive_losses": max_consecutive_losses,
        "samples": sample_rows,
    }


def _icmp_tcp_port_check(host: str, port: int, timeout: float, resolved: Optional[List[Tuple[int, str]]] = None) -> Dict[str, Any]:
    start = time.perf_counter()
    targets = list(resolved or _icmp_socket_targets(host, socket.SOCK_STREAM))
    if not targets:
        return {"port": int(port), "ok": False, "latency_ms": None, "raw": "resolve-empty"}
    last = ""
    for fam, ip in targets:
        sock = None
        try:
            sock = socket.socket(fam, socket.SOCK_STREAM)
            sock.settimeout(timeout)
            addr = (ip, int(port), 0, 0) if fam == socket.AF_INET6 else (ip, int(port))
            code = sock.connect_ex(addr)
            if code == 0:
                latency = (time.perf_counter() - start) * 1000.0
                return {"port": int(port), "ok": True, "latency_ms": round(latency, 3), "raw": f"tcp-connect port={port} ip={ip}"}
            last = f"connect_ex={code}"
        except Exception as e:
            last = str(e)
        finally:
            try:
                if sock:
                    sock.close()
            except Exception:
                pass
    return {"port": int(port), "ok": False, "latency_ms": None, "raw": f"tcp-all-addrs-failed last={last}"}


def _icmp_tcp_fallback(host: str, mode: str = "common", cancel_event: Optional[threading.Event] = None) -> Dict[str, Any]:
    """Memory-bounded TCP reachability/inventory scanner with cooperative cancellation."""
    mode = str(mode or "common").lower()
    common_ports = [80, 443, 22, 53, 445, 3389, 8080, 8443, 8000, 8008, 25, 110, 143, 993, 995, 3306, 5432, 5900, 6379, 9200]
    if mode == "off":
        return {"enabled": False, "success": False, "raw": "TCP fallback disabled", "ports_attempted": 0, "open_ports": []}
    full = mode == "full"
    ports_iter = iter(range(1, 65536) if full else common_ports)
    label = "full TCP inventory 1-65535" if full else "common TCP fallback subset"
    workers = max(1, min(256, int(ICMP_TCP_SCAN_WORKERS_DEFAULT)))
    timeout = max(0.05, min(3.0, float(ICMP_TCP_CONNECT_TIMEOUT_SECONDS)))
    deadline = None if full else (time.monotonic() + max(1.0, float(ICMP_FALLBACK_BUDGET_SECONDS)))
    resolved = _icmp_socket_targets(host, socket.SOCK_STREAM)
    attempted = 0
    open_ports: List[int] = []
    last_raw: List[str] = []
    started = time.monotonic()
    cancelled = False
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers, thread_name_prefix="c8-icmp-tcp") as ex:
            pending: Dict[Any, int] = {}
            exhausted = False
            while True:
                if cancel_event is not None and cancel_event.is_set():
                    cancelled = True; break
                if deadline is not None and time.monotonic() >= deadline:
                    break
                if C8_LOW_MEMORY_MODE and _c8_memory_pressure(0.80 if C8_ULTRA_LOW_MEMORY_MODE else 0.88):
                    cancelled = True
                    last_raw.append("stopped: server memory pressure")
                    break
                while not exhausted and len(pending) < workers:
                    if cancel_event is not None and cancel_event.is_set():
                        cancelled = True; break
                    try:
                        port = next(ports_iter)
                    except StopIteration:
                        exhausted = True; break
                    fut = ex.submit(_icmp_tcp_port_check, host, int(port), timeout, resolved)
                    pending[fut] = int(port); attempted += 1
                if cancelled:
                    break
                if not pending:
                    break
                done, _ = concurrent.futures.wait(pending.keys(), timeout=0.12, return_when=concurrent.futures.FIRST_COMPLETED)
                if not done:
                    continue
                for fut in done:
                    port = pending.pop(fut, None)
                    try:
                        res = fut.result()
                    except Exception as e:
                        if len(last_raw) < 12: last_raw.append(f"{port}:tcp-exec-exc:{e}")
                        continue
                    if res.get("ok"):
                        p = int(res.get("port") or port or 0)
                        if p and p not in open_ports: open_ports.append(p)
                        if not full:
                            return {"enabled":True,"profile":label,"success":True,"port":p,"open_ports":[p],"open_port_count":1,"service":_ipf_service_name(p,"tcp"),"service_names":{p:_ipf_service_name(p,"tcp")},"latency_ms":res.get("latency_ms"),"raw":res.get("raw"),"ports_attempted":attempted,"complete":True,"cancelled":False,"resolved_scan_targets":[ip for _fam,ip in resolved],"elapsed_ms":round((time.monotonic()-started)*1000,1)}
                    elif len(last_raw) < 12:
                        last_raw.append(f"{res.get('port')}:{res.get('raw')}")
                if exhausted and not pending:
                    break
            for fut in list(pending):
                fut.cancel()
    except Exception as e:
        return {"enabled":True,"profile":label,"success":False,"raw":f"tcp-scan-exc:{e}","ports_attempted":attempted,"open_ports":sorted(open_ports),"complete":False,"cancelled":cancelled}
    open_ports = sorted(set(open_ports))
    complete = bool(full and attempted >= 65535 and not cancelled)
    elapsed = max(0.001, time.monotonic()-started)
    service_names = {p:_ipf_service_name(p,"tcp") for p in open_ports}
    raw = (f"full TCP 1-65535 complete={complete}; attempted={attempted}; open={','.join(map(str,open_ports)) or 'none'}" if full else (("tcp-fallback-budget-exhausted " if attempted < len(common_ports) else "tcp-all-failed ") + "; ".join(last_raw[-8:])))
    return {"enabled":True,"profile":label,"success":bool(open_ports),"port":open_ports[0] if open_ports else None,"open_ports":open_ports,"open_port_count":len(open_ports),"service":_ipf_service_name(open_ports[0],"tcp") if open_ports else "","service_names":service_names,"latency_ms":None,"raw":raw,"ports_attempted":attempted,"complete":complete if full else attempted>=len(common_ports),"cancelled":cancelled,"scan_rate_ports_per_second":round(attempted/elapsed,1),"resolved_scan_targets":[ip for _fam,ip in resolved],"elapsed_ms":round(elapsed*1000,1)}


def _icmp_udp_port_check(host: str, port: int, timeout: float, resolved: Optional[List[Tuple[int, str]]] = None) -> Dict[str, Any]:
    start = time.perf_counter()
    sock = None
    try:
        targets = list(resolved or _icmp_socket_targets(host, socket.SOCK_DGRAM))
        if not targets:
            return {"port": int(port), "ok": False, "raw": "resolve-empty"}
        fam, ip = targets[0]
        sock = socket.socket(fam, socket.SOCK_DGRAM)
        sock.settimeout(timeout)
        addr = (ip, int(port), 0, 0) if fam == socket.AF_INET6 else (ip, int(port))
        payload = b"\x00\x00\x01\x00\x00\x01\x00\x00\x00\x00\x00\x00\x00\x00\x01\x00\x01" if int(port) == 53 else b"\x00"
        sock.sendto(payload, addr)
        try:
            data, raddr = sock.recvfrom(2048)
            lat = (time.perf_counter() - start) * 1000.0
            return {"port": int(port), "ok": True, "latency_ms": round(lat, 3), "raw": f"udp-recv from={raddr} bytes={len(data)}"}
        except socket.timeout:
            return {"port": int(port), "ok": False, "raw": "udp-no-response"}
        except ConnectionRefusedError:
            return {"port": int(port), "ok": False, "raw": "udp-refused"}
    except Exception as e:
        return {"port": int(port), "ok": False, "raw": f"udp-exc:{e}"}
    finally:
        try:
            if sock: sock.close()
        except Exception:
            pass


def _icmp_udp_probe(host: str, enabled: bool = False, cancel_event: Optional[threading.Event] = None) -> Dict[str, Any]:
    """Full UDP response scan with bounded workers, one DNS resolution, and cancellation."""
    if not enabled:
        return {"enabled":False,"success":False,"raw":"UDP scan disabled","open_ports":[]}
    timeout = max(0.05, min(2.0, float(ICMP_UDP_TIMEOUT_SECONDS)))
    workers = max(1, min(128, int(ICMP_UDP_SCAN_WORKERS_DEFAULT)))
    resolved = _icmp_socket_targets(host, socket.SOCK_DGRAM)
    attempted = 0; responsive: List[int] = []; last_raw: List[str] = []
    started = time.monotonic(); cancelled = False
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers, thread_name_prefix="c8-icmp-udp") as ex:
            port_iter = iter(range(1,65536)); pending: Dict[Any,int] = {}; exhausted=False
            while True:
                if cancel_event is not None and cancel_event.is_set(): cancelled=True; break
                if C8_LOW_MEMORY_MODE and _c8_memory_pressure(0.80 if C8_ULTRA_LOW_MEMORY_MODE else 0.88):
                    cancelled=True; last_raw.append("stopped: server memory pressure"); break
                while not exhausted and len(pending) < workers:
                    if cancel_event is not None and cancel_event.is_set(): cancelled=True; break
                    try: port=next(port_iter)
                    except StopIteration: exhausted=True; break
                    fut=ex.submit(_icmp_udp_port_check,host,int(port),timeout,resolved); pending[fut]=int(port); attempted+=1
                if cancelled: break
                if not pending: break
                done,_=concurrent.futures.wait(pending.keys(),timeout=0.12,return_when=concurrent.futures.FIRST_COMPLETED)
                if not done: continue
                for fut in done:
                    port=pending.pop(fut,None)
                    try: res=fut.result()
                    except Exception as e:
                        if len(last_raw)<12:last_raw.append(f"{port}:udp-exec-exc:{e}")
                        continue
                    if res.get("ok"):
                        p=int(res.get("port") or port or 0)
                        if p and p not in responsive: responsive.append(p)
                    elif len(last_raw)<12:last_raw.append(f"{res.get('port')}:{res.get('raw')}")
                if exhausted and not pending: break
            for fut in list(pending): fut.cancel()
    except Exception as e:
        return {"enabled":True,"profile":"full UDP response scan 1-65535","success":False,"raw":f"udp-scan-exc:{e}","ports_attempted":attempted,"open_ports":sorted(responsive),"complete":False,"cancelled":cancelled}
    responsive=sorted(set(responsive)); elapsed=max(0.001,time.monotonic()-started); complete=attempted>=65535 and not cancelled
    return {"enabled":True,"profile":"full UDP response scan 1-65535","success":bool(responsive),"port":responsive[0] if responsive else None,"open_ports":responsive,"open_port_count":len(responsive),"service_names":{p:_ipf_service_name(p,"udp") for p in responsive},"latency_ms":None,"raw":f"full UDP 1-65535 complete={complete}; attempted={attempted}; responsive={','.join(map(str,responsive)) or 'none'}; no-response UDP ports remain open|filtered/unknown","ports_attempted":attempted,"no_response_or_filtered_count":max(0,attempted-len(responsive)),"complete":complete,"cancelled":cancelled,"scan_rate_ports_per_second":round(attempted/elapsed,1),"resolved_scan_targets":[ip for _fam,ip in resolved],"elapsed_ms":round(elapsed*1000,1)}


def _icmp_reverse_dns(host: str) -> Dict[str, Any]:
    start = time.perf_counter()
    try:
        # Prefer first resolved target for DNS names.
        targets = _ll_resolve_ping_targets(host)
        target = targets[0][1] if targets else host
        name, aliases, addrs = socket.gethostbyaddr(str(target))
        lat = (time.perf_counter() - start) * 1000.0
        return {"success": True, "target": str(target), "ptr": name, "aliases": aliases[:5], "addrs": addrs[:5], "latency_ms": round(lat, 3)}
    except Exception as e:
        return {"success": False, "raw": f"reverse-dns-exc:{e}"}


def icmp_probe_host_mainmenu_style(
    host: str,
    profile: str = "mainmenu",
    tcp_fallback: str = "common",
    udp_fallback: bool = False,
    cancel_event: Optional[threading.Event] = None,
    series_samples: Optional[int] = None,
    include_rdns: bool = True,
) -> Dict[str, Any]:
    normalized = normalize_host_or_target(host)
    if _privacy_value_has_suppressed_ip(normalized):
        raise ValueError("This IP is suppressed by the configured privacy policy.")
    if not normalized:
        raise ValueError("host is required")
    if any(x in normalized for x in [",", ";", "\n", "\r", "\t"]):
        raise ValueError("one host per line only")

    profile = str(profile or "mainmenu").lower()
    if profile not in {"continuous", "diagnostic", "icmp", "mainmenu", "full"}:
        profile = "diagnostic"
    full_inventory = profile == "full"
    diagnostic = profile == "diagnostic"
    continuous = profile == "continuous"
    if full_inventory:
        tcp_fallback = "full"
        udp_fallback = True
    elif diagnostic:
        tcp_fallback = "common"
        udp_fallback = False
    elif continuous:
        tcp_fallback = "off"
        udp_fallback = False

    if series_samples is None:
        if continuous:
            sample_count = 1
        elif profile == "icmp":
            sample_count = ICMP_STABLE_SERIES_SAMPLES
        elif diagnostic:
            sample_count = ICMP_STABLE_SERIES_SAMPLES
        elif full_inventory:
            sample_count = 3
        else:
            sample_count = 2
    else:
        sample_count = max(1, min(8, int(series_samples)))

    started = time.monotonic()
    resolved = _icmp_resolve_targets(normalized)
    if any(_privacy_value_has_suppressed_ip(row.get("ip")) for row in resolved if isinstance(row, dict)):
        raise ValueError("This IP is suppressed by the configured privacy policy.")

    steps: List[Dict[str, Any]] = []
    latency_series = _icmp_latency_series(
        normalized,
        sample_count,
        cancel_event=cancel_event,
        sample_gap=0.0 if continuous and sample_count == 1 else ICMP_SERIES_GAP_SECONDS,
    )
    steps.append({
        "method": "icmp-series",
        "ok": bool(latency_series.get("success")),
        "latency_ms": latency_series.get("avg_ms"),
        "raw": (
            f"sent={latency_series.get('samples_sent')} received={latency_series.get('samples_received')} "
            f"loss={latency_series.get('packet_loss_percent')}% jitter={latency_series.get('jitter_ms')}ms "
            f"stability={latency_series.get('stability')} methods={latency_series.get('method_counts')}"
        ),
    })

    if profile in {"icmp", "continuous"}:
        is_up = bool(latency_series.get("success"))
        rdns = _icmp_reverse_dns(normalized) if include_rdns else {"success": False, "skipped": True, "raw": "reverse DNS cached/skipped for repeated sample"}
        latency = latency_series.get("avg_ms")
        raw_summary = (
            f"ICMP: sent={latency_series.get('samples_sent')} received={latency_series.get('samples_received')} "
            f"loss={latency_series.get('packet_loss_percent')}% avg={latency_series.get('avg_ms')}ms "
            f"jitter={latency_series.get('jitter_ms')}ms stability={latency_series.get('stability')}"
        )
        return {
            "host": normalized,
            "status": "UP" if is_up else ("CANCELLED" if cancel_event is not None and cancel_event.is_set() else "DOWN"),
            "up": is_up,
            "method": "continuous-icmp" if continuous else "icmp-metrics",
            "latency_ms": round(float(latency), 3) if latency is not None else None,
            "icmp_metrics": latency_series,
            "resolved_targets": resolved,
            "reverse_dns": rdns,
            "steps": steps,
            "raw": raw_summary[:6000],
            "elapsed_ms": round((time.monotonic() - started) * 1000, 1),
            "timestamp": now_iso(),
        }

    if cancel_event is not None and cancel_event.is_set():
        return {
            "host": normalized,
            "status": "CANCELLED",
            "up": False,
            "method": "cancelled",
            "latency_ms": latency_series.get("avg_ms"),
            "icmp_metrics": latency_series,
            "resolved_targets": resolved,
            "steps": steps,
            "raw": "Cancelled before fallback scans.",
            "elapsed_ms": round((time.monotonic() - started) * 1000, 1),
            "timestamp": now_iso(),
        }

    tcp_res = {"enabled": False, "success": False, "raw": "TCP scan skipped", "open_ports": []}
    if profile in {"diagnostic", "mainmenu", "full"} and tcp_fallback != "off":
        tcp_res = _icmp_tcp_fallback(normalized, mode=tcp_fallback, cancel_event=cancel_event)
        steps.append({
            "method": "tcp-full" if tcp_fallback == "full" else "tcp-common",
            "ok": bool(tcp_res.get("success")),
            "latency_ms": tcp_res.get("latency_ms"),
            "raw": tcp_res.get("raw"),
            "port": tcp_res.get("port"),
            "open_ports": tcp_res.get("open_ports") or [],
        })
        if profile == "mainmenu" and tcp_res.get("success"):
            rdns = _icmp_reverse_dns(normalized) if include_rdns else {"success": False, "skipped": True}
            return {
                "host": normalized,
                "status": "UP",
                "up": True,
                "method": "tcp-fallback",
                "latency_ms": latency_series.get("avg_ms") if latency_series.get("success") else tcp_res.get("latency_ms"),
                "icmp_metrics": latency_series,
                "open_port": tcp_res.get("port"),
                "open_tcp_ports": tcp_res.get("open_ports") or [],
                "service": tcp_res.get("service"),
                "resolved_targets": resolved,
                "reverse_dns": rdns,
                "tcp_fallback": tcp_res,
                "steps": steps,
                "raw": tcp_res.get("raw"),
                "elapsed_ms": round((time.monotonic() - started) * 1000, 1),
                "timestamp": now_iso(),
            }

    udp_res = _icmp_udp_probe(normalized, enabled=bool(udp_fallback and profile in {"mainmenu", "full"}), cancel_event=cancel_event)
    if udp_res.get("enabled"):
        steps.append({
            "method": "udp-full" if full_inventory else "udp-fallback",
            "ok": bool(udp_res.get("success")),
            "latency_ms": udp_res.get("latency_ms"),
            "raw": udp_res.get("raw"),
            "port": udp_res.get("port"),
            "open_ports": udp_res.get("open_ports") or [],
        })

    rdns = _icmp_reverse_dns(normalized) if include_rdns else {"success": False, "skipped": True}
    if include_rdns:
        steps.append({"method": "reverse-dns", "ok": bool(rdns.get("success")), "latency_ms": rdns.get("latency_ms"), "raw": rdns.get("raw") or rdns.get("ptr")})
    open_tcp = list(tcp_res.get("open_ports") or [])
    open_udp = list(udp_res.get("open_ports") or [])
    is_up = bool(latency_series.get("success") or tcp_res.get("success") or udp_res.get("success"))
    latency = latency_series.get("avg_ms") if latency_series.get("success") else (tcp_res.get("latency_ms") or udp_res.get("latency_ms"))
    method = "full-range-inventory" if full_inventory else ("diagnostic" if diagnostic else ("reverse-dns" if rdns.get("success") and not is_up else "none"))
    if rdns.get("success") and not is_up and profile == "mainmenu":
        is_up = True
        method = "reverse-dns"
    raw_summary = (
        f"FULL RANGE: ICMP loss={latency_series.get('packet_loss_percent')}%; TCP open={open_tcp or 'none'}; "
        f"UDP responsive={open_udp or 'none'}; UDP silence=open|filtered/unknown"
        if full_inventory else
        f"DIAGNOSTIC: ICMP sent={latency_series.get('samples_sent')} received={latency_series.get('samples_received')} "
        f"loss={latency_series.get('packet_loss_percent')}% avg={latency_series.get('avg_ms')}ms jitter={latency_series.get('jitter_ms')}ms; "
        f"TCP common open={open_tcp or 'none'}; PTR={rdns.get('ptr') or 'none'}"
    )
    return {
        "host": normalized,
        "status": "UP" if is_up else ("CANCELLED" if (tcp_res.get("cancelled") or udp_res.get("cancelled")) else "DOWN"),
        "up": is_up,
        "method": method,
        "latency_ms": round(float(latency), 3) if latency is not None else None,
        "icmp_metrics": latency_series,
        "open_port": open_tcp[0] if open_tcp else None,
        "open_udp_port": open_udp[0] if open_udp else None,
        "open_tcp_ports": open_tcp,
        "open_udp_ports": open_udp,
        "open_tcp_count": len(open_tcp),
        "open_udp_count": len(open_udp),
        "resolved_targets": resolved,
        "reverse_dns": rdns,
        "tcp_fallback": tcp_res,
        "udp_fallback": udp_res,
        "steps": steps,
        "raw": raw_summary[:6000],
        "elapsed_ms": round((time.monotonic() - started) * 1000, 1),
        "timestamp": now_iso(),
    }


def icmp_probe_batch(payload: Dict[str, Any], client: str = "unknown") -> Dict[str, Any]:
    enforce_ping_rate_limit(client)
    raw_hosts = str(payload.get("hosts_text") or payload.get("host") or "").strip()
    max_hosts = int(payload.get("max_hosts") or ICMP_MAX_HOSTS_DEFAULT)
    max_hosts = max(1, min(ICMP_MAX_HOSTS_DEFAULT, max_hosts))
    profile = str(payload.get("profile") or "diagnostic").lower()
    tcp_fallback = str(payload.get("tcp_fallback") or "common").lower()
    udp_fallback = bool(payload.get("udp_fallback", False))
    hosts, notes = expand_hosts_from_text(raw_hosts, max_hosts=max_hosts)
    if not hosts:
        raise ValueError("Enter at least one host/IP/CIDR/range.")
    if profile == "full" and len(hosts) > ICMP_FULL_RANGE_MAX_HOSTS:
        notes.append(f"Full-range mode scans every TCP and UDP port; this cycle is capped to the first {ICMP_FULL_RANGE_MAX_HOSTS} hosts.")
        hosts = hosts[:ICMP_FULL_RANGE_MAX_HOSTS]
    workers = max(1, min(ICMP_MAX_WORKERS_DEFAULT, int(payload.get("workers") or ICMP_MAX_WORKERS_DEFAULT), len(hosts)))
    rows: List[Dict[str, Any]] = []
    started = time.monotonic()
    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as ex:
        futs = [ex.submit(icmp_probe_host_mainmenu_style, h, profile, tcp_fallback, udp_fallback) for h in hosts]
        for fut in concurrent.futures.as_completed(futs):
            try:
                rows.append(fut.result())
            except Exception as e:
                rows.append({"host": "<unknown>", "status": "ERROR", "up": False, "method": "error", "latency_ms": None, "raw": str(e), "timestamp": now_iso()})
    rows.sort(key=lambda r: str(r.get("host") or ""))
    audit("icmp", "probe_batch", {"client": client, "hosts": len(hosts), "profile": profile, "tcp_fallback": tcp_fallback, "udp_fallback": udp_fallback})
    return {
        "ok": True,
        "profile": profile,
        "tcp_fallback": tcp_fallback,
        "udp_fallback": udp_fallback,
        "hosts_requested": len(hosts),
        "host_cap": max_hosts,
        "notes": notes,
        "rows": rows,
        "elapsed_ms": round((time.monotonic() - started) * 1000, 1),
        "main_menu_mapping": "Host expansion + raw ICMP -> system ping -> TCP fallback -> UDP fallback -> reverse DNS status cycle",
    }



def _icmp_cleanup_jobs() -> None:
    now = time.monotonic()
    with _ICMP_JOBS_LOCK:
        stale = []
        for jid, job in list(_ICMP_JOBS.items()):
            created = float(job.get("created_monotonic") or now)
            finished = job.get("status") in {"complete", "cancelled", "error"}
            age = now - created
            if (finished and age > ICMP_JOB_TTL_SECONDS) or age > (ICMP_JOB_TTL_SECONDS * 3):
                stale.append(jid)
        for jid in stale:
            _ICMP_JOBS.pop(jid, None)


def _icmp_job_public(job: Dict[str, Any]) -> Dict[str, Any]:
    rows = list(job.get("rows") or [])
    if len(rows) > ICMP_JOB_POLL_ROWS_LIMIT:
        rows = rows[-ICMP_JOB_POLL_ROWS_LIMIT:]
    total = int(job.get("total") or 0)
    completed = int(job.get("completed") or 0)
    started_at = float(job.get("started_monotonic") or time.monotonic())
    elapsed_until = float(job.get("finished_monotonic") or time.monotonic())
    return {
        "ok": True,
        "job_id": job.get("job_id"),
        "status": job.get("status"),
        "profile": job.get("profile"),
        "tcp_fallback": job.get("tcp_fallback"),
        "udp_fallback": job.get("udp_fallback"),
        "hosts_requested": total,
        "completed": completed,
        "progress": round((completed / total) * 100.0, 1) if total else 0.0,
        "notes": list(job.get("notes") or []),
        "rows": rows,
        "errors": list(job.get("errors") or [])[-20:],
        "repeat_count": int(job.get("repeat_count") or 1),
        "rate_hz": float(job.get("rate_hz") or 0.0),
        "elapsed_ms": round(max(0.0, elapsed_until - started_at) * 1000.0, 1),
        "cancel_requested": bool(job.get("cancel_event") and job["cancel_event"].is_set()),
        "main_menu_mapping": "background job: host expansion + raw ICMP -> system ping -> TCP fallback -> UDP fallback -> reverse DNS; browser polls partial rows",
    }


def _icmp_fast_repeat_settings(payload: Dict[str, Any], hosts: List[str], profile: str, tcp_fallback: str, udp_fallback: bool, notes: List[str]) -> Tuple[int, float]:
    def _bounded_int(value: Any, default: int, low: int, high: int) -> int:
        try:
            parsed = int(value)
        except Exception:
            parsed = default
        return max(low, min(high, parsed))

    def _bounded_float(value: Any, default: float, low: float, high: float) -> float:
        try:
            parsed = float(value)
        except Exception:
            parsed = default
        return max(low, min(high, parsed))

    continuous = profile == "continuous"
    default_repeat = ICMP_CONTINUOUS_REPEAT_DEFAULT if continuous else ICMP_FAST_REPEAT_DEFAULT
    default_rate = ICMP_CONTINUOUS_RATE_HZ_DEFAULT if continuous else ICMP_FAST_RATE_HZ_DEFAULT
    requested_repeat = _bounded_int(payload.get("repeat_count"), default_repeat, 1, ICMP_FAST_REPEAT_MAX)
    requested_rate = _bounded_float(payload.get("rate_hz"), default_rate, 0.5 if continuous else 1.0, 5.0 if continuous else 20.0)
    fast_allowed = len(hosts) == 1 and profile in {"icmp", "continuous"} and tcp_fallback == "off" and not udp_fallback
    if requested_repeat > 1 and not fast_allowed:
        notes.append("Repeated ICMP streaming is limited to one host with ICMP-only/Continuous profile and fallback probes off.")
    if continuous and len(hosts) != 1:
        notes.append("Continuous Ping requires one host so samples remain evenly spaced; using one bounded sample per host for this job.")
    return (requested_repeat, requested_rate) if fast_allowed else (1, requested_rate)


def _icmp_job_worker(job_id: str, payload: Dict[str, Any], client: str) -> None:
    with _ICMP_JOBS_LOCK:
        job = _ICMP_JOBS.get(job_id)
        if not job:
            return
        job["status"] = "running"
        job["started_monotonic"] = time.monotonic()
        cancel_event = job["cancel_event"]
    try:
        raw_hosts = str(payload.get("hosts_text") or payload.get("host") or "").strip()
        max_hosts = int(payload.get("max_hosts") or ICMP_MAX_HOSTS_DEFAULT)
        max_hosts = max(1, min(ICMP_MAX_HOSTS_DEFAULT, max_hosts))
        profile = str(payload.get("profile") or "diagnostic").lower()
        tcp_fallback = str(payload.get("tcp_fallback") or "common").lower()
        udp_fallback = bool(payload.get("udp_fallback", False))
        hosts, notes = expand_hosts_from_text(raw_hosts, max_hosts=max_hosts)
        if not hosts:
            raise ValueError("Enter at least one host/IP/CIDR/range.")
        if profile == "full" and len(hosts) > ICMP_FULL_RANGE_MAX_HOSTS:
            notes.append(f"Full-range mode scans every TCP and UDP port; this cycle is capped to the first {ICMP_FULL_RANGE_MAX_HOSTS} hosts.")
            hosts = hosts[:ICMP_FULL_RANGE_MAX_HOSTS]
        repeat_count, rate_hz = _icmp_fast_repeat_settings(payload, hosts, profile, tcp_fallback, udp_fallback, notes)
        total_probes = len(hosts) * repeat_count
        workers = 1 if repeat_count > 1 else max(1, min(ICMP_MAX_WORKERS_DEFAULT, int(payload.get("workers") or ICMP_MAX_WORKERS_DEFAULT), len(hosts)))
        with _ICMP_JOBS_LOCK:
            job = _ICMP_JOBS.get(job_id)
            if not job:
                return
            job.update({"total": total_probes, "host_count": len(hosts), "notes": notes, "profile": profile, "tcp_fallback": tcp_fallback, "udp_fallback": udp_fallback, "workers": workers, "repeat_count": repeat_count, "rate_hz": rate_hz})
        if repeat_count > 1:
            host = hosts[0]
            interval = 1.0 / max(0.5, rate_hz)
            # Lightweight ICMP no longer needs the embedded IP Forensics engine.
            next_start = time.monotonic()
            burst_started = next_start
            with _ICMP_JOBS_LOCK:
                job = _ICMP_JOBS.get(job_id)
                if not job:
                    return
                job["started_monotonic"] = next_start
            for sequence in range(1, repeat_count + 1):
                if cancel_event.is_set():
                    break
                delay = next_start - time.monotonic()
                if delay > 0 and cancel_event.wait(delay):
                    break
                probe_started = time.monotonic()
                try:
                    row = icmp_probe_host_mainmenu_style(
                        host, profile, tcp_fallback, udp_fallback,
                        cancel_event=cancel_event, series_samples=1, include_rdns=(sequence == 1),
                    )
                except Exception as e:
                    row = {"host": host, "status": "ERROR", "up": False, "method": "error", "latency_ms": None, "raw": str(e), "timestamp": now_iso()}
                row["sequence"] = sequence
                row["rate_hz"] = rate_hz
                row["burst_offset_ms"] = 0.0 if sequence == 1 else round((probe_started - burst_started) * 1000.0, 1)
                with _ICMP_JOBS_LOCK:
                    job = _ICMP_JOBS.get(job_id)
                    if not job:
                        return
                    job.setdefault("rows", []).append(row)
                    job["completed"] = int(job.get("completed") or 0) + 1
                    job["last_update"] = now_iso()
                next_start = max(next_start + interval, probe_started + interval, time.monotonic())
            with _ICMP_JOBS_LOCK:
                job = _ICMP_JOBS.get(job_id)
                if job:
                    job["status"] = "cancelled" if cancel_event.is_set() else "complete"
                    job["finished_at"] = now_iso()
                    job["finished_monotonic"] = time.monotonic()
            audit("icmp", "probe_job", {"client": client, "job_id": job_id, "hosts": len(hosts), "profile": profile, "tcp_fallback": tcp_fallback, "udp_fallback": udp_fallback, "repeat_count": repeat_count, "rate_hz": rate_hz})
            return
        ex = concurrent.futures.ThreadPoolExecutor(max_workers=workers)
        futures = []
        try:
            for h in hosts:
                with _ICMP_JOBS_LOCK:
                    job = _ICMP_JOBS.get(job_id)
                    if not job or job["cancel_event"].is_set():
                        break
                futures.append(ex.submit(icmp_probe_host_mainmenu_style, h, profile, tcp_fallback, udp_fallback, cancel_event))
            for fut in concurrent.futures.as_completed(futures):
                with _ICMP_JOBS_LOCK:
                    job = _ICMP_JOBS.get(job_id)
                    cancel = bool(job and job["cancel_event"].is_set())
                if cancel:
                    break
                try:
                    row = fut.result()
                except Exception as e:
                    row = {"host": "<unknown>", "status": "ERROR", "up": False, "method": "error", "latency_ms": None, "raw": str(e), "timestamp": now_iso()}
                with _ICMP_JOBS_LOCK:
                    job = _ICMP_JOBS.get(job_id)
                    if not job:
                        return
                    job.setdefault("rows", []).append(row)
                    job["completed"] = int(job.get("completed") or 0) + 1
                    job["last_update"] = now_iso()
            with _ICMP_JOBS_LOCK:
                job = _ICMP_JOBS.get(job_id)
                if job:
                    job["status"] = "cancelled" if job["cancel_event"].is_set() else "complete"
                    job["finished_at"] = now_iso()
                    job["finished_monotonic"] = time.monotonic()
        finally:
            try:
                ex.shutdown(wait=False, cancel_futures=True)
            except TypeError:
                ex.shutdown(wait=False)
        audit("icmp", "probe_job", {"client": client, "job_id": job_id, "hosts": len(hosts), "profile": profile, "tcp_fallback": tcp_fallback, "udp_fallback": udp_fallback})
    except Exception as e:
        with _ICMP_JOBS_LOCK:
            job = _ICMP_JOBS.get(job_id)
            if job:
                job["status"] = "error"
                job.setdefault("errors", []).append(str(e))
                job["finished_at"] = now_iso()
                job["finished_monotonic"] = time.monotonic()


def icmp_job_start(payload: Dict[str, Any], client: str = "unknown") -> Dict[str, Any]:
    enforce_ping_rate_limit(client)
    _icmp_cleanup_jobs()
    job_id = uuid.uuid4().hex
    cancel_event = threading.Event()
    job = {
        "job_id": job_id,
        "client": client,
        "status": "queued",
        "created_at": now_iso(),
        "created_monotonic": time.monotonic(),
        "started_monotonic": time.monotonic(),
        "rows": [],
        "errors": [],
        "notes": [],
        "completed": 0,
        "total": 0,
        "profile": str(payload.get("profile") or "diagnostic").lower(),
        "tcp_fallback": str(payload.get("tcp_fallback") or "common").lower(),
        "udp_fallback": bool(payload.get("udp_fallback", False)),
        "cancel_event": cancel_event,
    }
    with _ICMP_JOBS_LOCK:
        _ICMP_JOBS[job_id] = job
    thread = threading.Thread(target=_icmp_job_worker, args=(job_id, dict(payload), client), daemon=True, name=f"icmp-job-{job_id[:8]}")
    thread.start()
    return _icmp_job_public(job)


def icmp_job_status(job_id: str, client: str = "unknown") -> Dict[str, Any]:
    _icmp_cleanup_jobs()
    jid = str(job_id or "").strip()
    with _ICMP_JOBS_LOCK:
        job = _ICMP_JOBS.get(jid)
        if not job:
            raise ValueError("Unknown or expired ICMP job id.")
        if job.get("client") not in {client, "unknown"} and client != "127.0.0.1":
            raise ValueError("ICMP job belongs to a different client.")
        return _icmp_job_public(dict(job))


def icmp_job_cancel(job_id: str, client: str = "unknown") -> Dict[str, Any]:
    jid = str(job_id or "").strip()
    with _ICMP_JOBS_LOCK:
        job = _ICMP_JOBS.get(jid)
        if not job:
            raise ValueError("Unknown or expired ICMP job id.")
        if job.get("client") not in {client, "unknown"} and client != "127.0.0.1":
            raise ValueError("ICMP job belongs to a different client.")
        ev = job.get("cancel_event")
        if ev:
            ev.set()
        job["status"] = "cancelled" if job.get("status") in {"queued", "running"} else job.get("status")
        job["last_update"] = now_iso()
        return _icmp_job_public(dict(job))


IPDB_TABLE = _safe_sql_identifier(os.environ.get("LL_WEB_IPDB_TABLE") or "ip_records", "ip_records")
IPDB_LIST_LIMIT = max(1, min(10000, int(os.environ.get("LL_WEB_IPDB_LIST_LIMIT", "5000"))))
IPDB_RECORD_FIELDS = (
    "id", "primary_ip", "secondary_ip", "username", "alias", "gender", "notes",
    "image_data", "image_name", "image_mime", "created_at", "updated_at",
    "created_by_username", "created_by_ip", "updated_by_username", "updated_by_ip",
    "is_redacted", "redacted_at", "redacted_by_username", "redaction_note",
)


def _ipdb_env(name: str, fallback: str = "") -> str:
    aliases = [f"LL_WEB_IPDB_MYSQL_{name}", f"LL_IPDB_MYSQL_{name}", f"IPDB_MYSQL_{name}"]
    if name == "DATABASE":
        aliases += ["LL_WEB_IPDB_DB_NAME", "LL_IPDB_DB_NAME", "IPDB_DB_NAME"]
    elif name == "USER":
        aliases += ["LL_WEB_IPDB_DB_USER", "LL_IPDB_DB_USER", "IPDB_DB_USER"]
    elif name == "PASSWORD":
        aliases += ["LL_WEB_IPDB_DB_PASSWORD", "LL_IPDB_DB_PASSWORD", "IPDB_DB_PASSWORD"]
    elif name == "HOST":
        aliases += ["LL_WEB_IPDB_DB_HOST", "LL_IPDB_DB_HOST", "IPDB_DB_HOST"]
    elif name == "PORT":
        aliases += ["LL_WEB_IPDB_DB_PORT", "LL_IPDB_DB_PORT", "IPDB_DB_PORT"]
    elif name == "TIMEOUT":
        aliases += ["LL_WEB_IPDB_DB_TIMEOUT", "LL_IPDB_DB_TIMEOUT", "IPDB_DB_TIMEOUT"]
    for key in aliases:
        value = os.environ.get(key)
        if value not in (None, ""):
            return str(value).strip()
    return str(fallback).strip()


def _ipdb_main_menu_config() -> Dict[str, Any]:
    parsed = main_menu_db_settings()
    if not parsed.get("available"):
        return {}
    ssl_disabled = bool(parsed.get("ssl_disabled"))
    return {
        "host": str(parsed.get("host") or "").strip(),
        "port": int(parsed.get("port") or 3306),
        "user": str(parsed.get("user") or "").strip(),
        "password": str(parsed.get("password") or ""),
        "database": str(parsed.get("database") or "").strip(),
        "timeout": int(parsed.get("timeout") or 10),
        "sslmode": "DISABLED" if ssl_disabled else "VERIFY_IDENTITY",
        "source_name": str(parsed.get("source_name") or "Main Menu configuration"),
    }


def _ipdb_explicit_mysql_config() -> Dict[str, Any]:
    cfg = {
        "host": _ipdb_env("HOST"),
        "port": int(_ipdb_env("PORT", "3306") or "3306"),
        "user": _ipdb_env("USER"),
        "password": _ipdb_env("PASSWORD"),
        "database": _ipdb_env("DATABASE"),
        "timeout": int(_ipdb_env("TIMEOUT", "10") or "10"),
        "sslmode": _ipdb_env("SSLMODE", "VERIFY_IDENTITY").upper(),
    }
    return cfg if all(cfg.get(k) not in (None, "") for k in ("host", "user", "password", "database")) else {}


def _ipdb_source_config() -> Dict[str, Any]:
    return {
        "engine": "mysql",
        "source": "app_mysql",
        "source_label": "MySQL Database",
        "config": _mysql_config(),
        "config_source": "built-in MySQL configuration",
    }


def _ipdb_source_read_only(source: Optional[Dict[str, Any]] = None) -> bool:
    source = source or _ipdb_source_config()
    raw = os.environ.get("LL_WEB_IPDB_READ_ONLY")
    if raw not in (None, ""):
        return str(raw).strip().lower() not in {"0", "false", "no", "off"}
    # Main Menu/MySQL display is read-only by default. Browser routes are also read-only.
    return str(source.get("engine") or "") == "mysql"


def ipdb_source_status() -> Dict[str, Any]:
    source = _ipdb_source_config()
    cfg = source.get("config") or {}
    database = f"mysql://{cfg.get('user') or '<user>'}:***@{cfg.get('host') or '<host>'}:{cfg.get('port') or MYSQL_DEFAULT_PORT}/{cfg.get('database') or '<database>'}"
    return {
        "source": source.get("source"),
        "source_label": source.get("source_label"),
        "engine": "mysql",
        "table": IPDB_TABLE,
        "database": database,
        "config_source": "MySQL-only configuration",
        "read_only": _ipdb_source_read_only(source),
        "limit": IPDB_LIST_LIMIT,
    }


def _ipdb_db_connect(source: Dict[str, Any]) -> Any:
    return _mysql_connect_compatible(dict(source.get("config") or _mysql_config()))


@contextmanager
def ipdb_connection() -> Any:
    source = _ipdb_source_config()
    conn = _ipdb_db_connect(source)
    try:
        yield conn, source
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _ipdb_sql(sql: str, source: Dict[str, Any]) -> str:
    return str(sql).replace("?", "%s")


def _ipdb_execute(conn: Any, source: Dict[str, Any], sql: str, params: Tuple[Any, ...] = (), dictionary: bool = False) -> Any:
    if source.get("engine") == "mysql":
        cur = _mysql_cursor(conn, dictionary=dictionary)
        cur.execute(_ipdb_sql(sql, source), tuple(params or ()))
        return cur
    return conn.execute(str(sql), tuple(params or ()))


def _ipdb_fetchone(conn: Any, source: Dict[str, Any], sql: str, params: Tuple[Any, ...] = ()) -> Any:
    return _ipdb_execute(conn, source, sql, params, dictionary=True).fetchone()


def _ipdb_fetchall(conn: Any, source: Dict[str, Any], sql: str, params: Tuple[Any, ...] = ()) -> List[Any]:
    return list(_ipdb_execute(conn, source, sql, params, dictionary=True).fetchall())


def _ipdb_ident(name: str, source: Dict[str, Any]) -> str:
    safe = _safe_sql_identifier(name, "")
    if not safe:
        raise ValueError("Unsafe IP Database identifier.")
    quote = "`" if source.get("engine") == "mysql" else '"'
    return quote + safe + quote


def _ipdb_table_columns(conn: Any, source: Dict[str, Any]) -> set:
    if source.get("engine") == "mysql":
        cur = _ipdb_execute(conn, source, f"SHOW COLUMNS FROM {_ipdb_ident(IPDB_TABLE, source)}", (), dictionary=True)
        rows = cur.fetchall()
        return {str((_row_get(row, "Field", _row_get(row, "field", ""))) or "") for row in rows}
    return {str(row[1]) for row in conn.execute(f"PRAGMA table_info({_ipdb_ident(IPDB_TABLE, source)})").fetchall()}


def _ipdb_projection(columns: set, source: Dict[str, Any]) -> str:
    required = {"id", "primary_ip", "username"}
    missing = sorted(required - set(columns))
    if missing:
        raise RuntimeError(f"Main Menu IP Database table `{IPDB_TABLE}` is missing required column(s): {', '.join(missing)}")
    pieces: List[str] = []
    defaults = {"gender": "Unknown", "image_name": "", "image_mime": "", "is_redacted": "0", "redacted_at": "", "redacted_by_username": "", "redaction_note": ""}
    for field in IPDB_RECORD_FIELDS:
        alias = _ipdb_ident(field, source)
        if field in columns:
            pieces.append(_ipdb_ident(field, source))
        elif field in defaults:
            literal = str(defaults[field]).replace("'", "''")
            pieces.append(f"'{literal}' AS {alias}")
        else:
            pieces.append(f"NULL AS {alias}")
    return ", ".join(pieces)


def _ipdb_require_app_write_source() -> Dict[str, Any]:
    source = _ipdb_source_config()
    if _ipdb_source_read_only(source):
        raise RuntimeError("The MySQL IP Database source is read-only in this console.")
    return source


IPDB_ALLOWED_GENDERS = ("Unknown", "Female", "Male", "F2M", "M2F", "Femboy")
IPDB_IMAGE_MAX_BYTES = int(os.environ.get("LL_WEB_IPDB_IMAGE_MAX_BYTES", str(MAX_UPLOAD_BYTES)))


def _ipdb_actor_username() -> str:
    for key in ("LL_SESSION_USERNAME", "USER", "USERNAME", "LOGNAME"):
        try:
            v = str(os.environ.get(key) or "").strip()
            if v:
                return v[:255]
        except Exception:
            pass
    try:
        import getpass
        return str(getpass.getuser() or "local-web-console")[:255]
    except Exception:
        return "local-web-console"


def _ipdb_viewer_hostname() -> str:
    try:
        return socket.gethostname()[:255]
    except Exception:
        return ""


def _ipdb_viewer_os_user() -> str:
    try:
        import getpass
        return str(getpass.getuser() or "")[:255]
    except Exception:
        return ""


def _ipdb_local_ip() -> str:
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.settimeout(0.4)
        s.connect(("8.8.8.8", 80))
        ip = s.getsockname()[0]
        s.close()
        return ip
    except Exception:
        try:
            return socket.gethostbyname(socket.gethostname())
        except Exception:
            return "Unknown"


def _ipdb_clean_gender(value: Any) -> str:
    raw = str(value or "Unknown").strip()
    for g in IPDB_ALLOWED_GENDERS:
        if raw.lower() == g.lower():
            return g
    return "Unknown"


def _ipdb_image_mime(data: bytes) -> str:
    if data.startswith(b"\xff\xd8\xff"):
        return "image/jpeg"
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        return "image/png"
    if data.startswith(b"BM"):
        return "image/bmp"
    return "application/octet-stream"


def _ipdb_decode_image_b64(value: str) -> Tuple[Optional[bytes], str]:
    raw = str(value or "").strip()
    if not raw:
        return None, ""
    if "," in raw and raw[:64].lower().startswith("data:"):
        raw = raw.split(",", 1)[1]
    if len(raw) > ((IPDB_IMAGE_MAX_BYTES + 2) // 3) * 4 + 4:
        raise C8SecurityInputError("Encoded image is too large.")
    try:
        data = base64.b64decode(raw, validate=True)
    except Exception as e:
        raise ValueError(f"Image data could not be decoded: {e}")
    if len(data) > IPDB_IMAGE_MAX_BYTES:
        raise ValueError(f"Image is too large for IP Database. Limit: {IPDB_IMAGE_MAX_BYTES // (1024 * 1024)} MB.")
    mime = _ipdb_image_mime(data)
    if mime not in {"image/jpeg", "image/png", "image/bmp"}:
        raise ValueError("Image must be PNG, JPG/JPEG, or BMP, matching the main-menu image picker.")
    try:
        _ensure_pillow_available()
        if PIL_AVAILABLE:
            with _c8_image_open(BytesIO(data)) as img:
                img.verify()
    except Exception as e:
        raise ValueError(f"Image bytes did not validate: {e}")
    return data, mime


def _ipdb_bytes(v: Any) -> bytes:
    if v is None:
        return b""
    if isinstance(v, bytes):
        return v
    if isinstance(v, bytearray):
        return bytes(v)
    if isinstance(v, memoryview):
        return v.tobytes()
    return bytes(v) if isinstance(v, (bytes, bytearray, memoryview)) else b""


def _ipdb_relative_time(value: Any) -> str:
    s = str(value or "").strip()
    if not s:
        return "N/A"
    try:
        dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        delta = datetime.now(timezone.utc) - dt.astimezone(timezone.utc)
        seconds = max(0, int(delta.total_seconds()))
        if seconds < 60:
            return f"{seconds}s ago"
        if seconds < 3600:
            return f"{seconds // 60}m ago"
        if seconds < 86400:
            return f"{seconds // 3600}h ago"
        return f"{seconds // 86400}d ago"
    except Exception:
        return "N/A"


def _ipdb_image_thumb_data_url(data: bytes, mime: str = "", max_side: int = 96) -> str:
    if not data:
        return ""
    _ensure_pillow_available()
    if PIL_AVAILABLE:
        try:
            with _c8_image_open(BytesIO(data)) as img:  # type: ignore[union-attr]
                source = ImageOps.exif_transpose(img).copy()

            def encode_thumb(side: int, quality: int) -> str:
                thumb = source.copy()
                thumb.thumbnail((side, side))
                if thumb.mode not in {"RGB", "L"}:
                    bg = Image.new("RGB", thumb.size, "white")  # type: ignore[union-attr]
                    if "A" in thumb.getbands():
                        bg.paste(thumb, mask=thumb.getchannel("A"))
                    else:
                        bg.paste(thumb)
                    thumb = bg
                elif thumb.mode != "RGB":
                    thumb = thumb.convert("RGB")
                out = BytesIO()
                thumb.save(out, format="JPEG", quality=quality, optimize=True)
                return "data:image/jpeg;base64,%s" % base64.b64encode(out.getvalue()).decode("ascii")

            best = ""
            for side, quality in [(max_side, 82), (80, 76), (72, 72), (64, 68), (56, 64), (48, 60)]:
                best = encode_thumb(side, quality)
                if len(best) <= 2800:
                    return best
            return best
        except Exception:
            pass
    if len(data) <= 768 * 1024 and (mime or _ipdb_image_mime(data)) in {"image/jpeg", "image/png", "image/bmp"}:
        return "data:%s;base64,%s" % (mime or _ipdb_image_mime(data), base64.b64encode(data).decode("ascii"))
    return ""


IPDB_REDACTED_VALUE = "REDACTED"
IPDB_REDACTION_STATE_PATH = RUNTIME_DIR / "ipdb_redactions.json"
IPDB_REDACTION_STATE_LOCK = threading.RLock()


def _ipdb_local_redactions_load() -> Dict[str, Any]:
    with IPDB_REDACTION_STATE_LOCK:
        try:
            raw = json.loads(IPDB_REDACTION_STATE_PATH.read_text(encoding="utf-8"))
            return raw if isinstance(raw, dict) else {}
        except FileNotFoundError:
            return {}
        except Exception:
            return {}


def _ipdb_local_redaction_get(record_id: Any) -> Optional[Dict[str, Any]]:
    try:
        key = str(int(record_id))
    except (TypeError, ValueError):
        return None
    row = _ipdb_local_redactions_load().get(key)
    return dict(row) if isinstance(row, dict) else None


def _ipdb_local_redaction_set(record_id: int, redacted: bool, actor: str, note: str) -> Dict[str, Any]:
    """Persist the website-owned IP + Notes redaction state atomically.

    This sidecar is deliberately independent of the Main Menu MySQL table so the
    REDACT FOR USERS button still works when that source is read-only.
    """
    rid = int(record_id)
    state = {
        "is_redacted": bool(redacted),
        "redaction_scope": "ip+notes" if redacted else "",
        "redacted_at": now_iso() if redacted else None,
        "redacted_by_username": str(actor or "admin")[:255] if redacted else None,
        "redaction_note": str(note or "")[:500] if redacted else "",
    }
    with IPDB_REDACTION_STATE_LOCK:
        data = _ipdb_local_redactions_load()
        data[str(rid)] = state
        IPDB_REDACTION_STATE_PATH.parent.mkdir(parents=True, exist_ok=True)
        tmp = IPDB_REDACTION_STATE_PATH.with_suffix(".tmp")
        tmp.write_text(
            json.dumps(data, ensure_ascii=False, sort_keys=True, separators=(",", ":")),
            encoding="utf-8",
        )
        try:
            os.chmod(tmp, 0o600)
        except OSError:
            pass
        os.replace(tmp, IPDB_REDACTION_STATE_PATH)
        try:
            os.chmod(IPDB_REDACTION_STATE_PATH, 0o600)
        except OSError:
            pass
    return dict(state)


def _ipdb_apply_local_redaction_state(row: Any) -> Dict[str, Any]:
    d = dict(row or {})
    # Privacy-suppression redactions are authoritative and may not be undone by
    # an ordinary website redaction override.
    if _truthy_db(d.get("is_redacted")) and str(d.get("redacted_by_username") or "").strip().lower() == "privacy-suppression":
        return d
    local = _ipdb_local_redaction_get(d.get("id"))
    if local is None:
        return d
    d["is_redacted"] = 1 if bool(local.get("is_redacted")) else 0
    d["redaction_scope"] = str(local.get("redaction_scope") or ("ip+notes" if local.get("is_redacted") else ""))
    d["redacted_at"] = local.get("redacted_at")
    d["redacted_by_username"] = local.get("redacted_by_username")
    d["redaction_note"] = local.get("redaction_note") or ""
    return d


def _ipdb_redact_actor_fields(d: Dict[str, Any]) -> Dict[str, Any]:
    d["created_by_username"] = IPDB_REDACTED_VALUE
    d["created_by_ip"] = IPDB_REDACTED_VALUE
    d["updated_by_username"] = IPDB_REDACTED_VALUE
    d["updated_by_ip"] = IPDB_REDACTED_VALUE
    return d


def _ipdb_record_is_redacted(data: Dict[str, Any]) -> bool:
    return _truthy_db(data.get("is_redacted"))


def _ipdb_apply_viewer_redaction(data: Dict[str, Any]) -> Dict[str, Any]:
    """Apply the redaction that a non-admin viewer is allowed to see.

    REDACT FOR USERS masks the primary IP, secondary IP, and Notes fields for
    non-admin viewers while leaving identity fields useful for selecting the
    record. Privacy-suppression records remain fully redacted.
    """
    if not _ipdb_record_is_redacted(data):
        data["is_redacted"] = False
        return data

    data["is_redacted"] = True
    actor = str(data.get("redacted_by_username") or "").strip().lower()
    full_privacy_redaction = actor == "privacy-suppression"

    if full_privacy_redaction:
        data["redaction_notice"] = "This IP Database record is suppressed by the server privacy policy."
        for field in ("primary_ip", "secondary_ip", "username", "alias", "gender", "notes"):
            data[field] = IPDB_REDACTED_VALUE
        data["image_present"] = False
        data["image_bytes"] = 0
        data["image_sha256"] = ""
        data["image_mime"] = ""
        data["image_name"] = IPDB_REDACTED_VALUE
        data.pop("image_thumb_url", None)
        data.pop("image_data_url", None)
    else:
        data["redaction_scope"] = "ip+notes"
        data["redaction_notice"] = "IP addresses and Notes in this IP Database record were redacted by an administrator."
        data["primary_ip"] = IPDB_REDACTED_VALUE
        data["secondary_ip"] = IPDB_REDACTED_VALUE
        data["notes"] = IPDB_REDACTED_VALUE

    data["redacted_by_username"] = IPDB_REDACTED_VALUE
    data["redaction_note"] = IPDB_REDACTED_VALUE
    return data


def _ipdb_record_public(row: Any, include_image: bool = False, include_thumbnail: bool = False, viewer_is_admin: bool = True) -> Dict[str, Any]:
    d = dict(row)
    img = _ipdb_bytes(d.pop("image_data", None))
    d["image_present"] = bool(img)
    d["image_bytes"] = len(img)
    d["image_sha256"] = hashlib.sha256(img).hexdigest() if img else ""
    d["image_mime"] = d.get("image_mime") or (_ipdb_image_mime(img) if img else "")
    d["image_name"] = d.get("image_name") or ""
    if include_thumbnail and img:
        d["image_thumb_url"] = _ipdb_image_thumb_data_url(img, d["image_mime"])
    if include_image and img:
        d["image_data_url"] = "data:%s;base64,%s" % (d["image_mime"] or _ipdb_image_mime(img), base64.b64encode(img).decode("ascii"))
    d["is_redacted"] = _ipdb_record_is_redacted(d)
    if d["is_redacted"] and not viewer_is_admin:
        _ipdb_apply_viewer_redaction(d)
    _ipdb_redact_actor_fields(d)
    return d


def _ipdb_get_record(record_id: Any, include_image: bool = False, viewer_is_admin: bool = True) -> Dict[str, Any]:
    rid = int(record_id)
    with _DB_LOCK:
        with ipdb_connection() as (conn, source):
            columns = _ipdb_table_columns(conn, source)
            projection = _ipdb_projection(columns, source)
            row = _ipdb_fetchone(
                conn, source,
                f"SELECT {projection} FROM {_ipdb_ident(IPDB_TABLE, source)} WHERE {_ipdb_ident('id', source)} = ? LIMIT 1",
                (rid,),
            )
    if row is None:
        raise ValueError("IP Database record not found.")
    row = _ipdb_apply_local_redaction_state(row)
    return _ipdb_record_public(row, include_image=include_image, viewer_is_admin=viewer_is_admin)


def _ipdb_image_blob(record_id: Any, viewer_is_admin: bool = True) -> Tuple[bytes, str]:
    rid = int(record_id)
    with _DB_LOCK:
        with ipdb_connection() as (conn, source):
            columns = _ipdb_table_columns(conn, source)
            if "image_data" not in columns:
                raise ValueError("The Main Menu IP Database table has no image_data column.")
            select_fields = [_ipdb_ident("id", source), _ipdb_ident("image_data", source)]
            if "image_mime" in columns:
                select_fields.append(_ipdb_ident("image_mime", source))
            if "is_redacted" in columns:
                select_fields.append(_ipdb_ident("is_redacted", source))
            row = _ipdb_fetchone(
                conn, source,
                f"SELECT {', '.join(select_fields)} FROM {_ipdb_ident(IPDB_TABLE, source)} WHERE {_ipdb_ident('id', source)} = ? LIMIT 1",
                (rid,),
            )
    if row is None:
        raise ValueError("IP Database record not found.")
    row = _ipdb_apply_local_redaction_state(row)
    if (
        _truthy_db(_row_get(row, "is_redacted"))
        and str(_row_get(row, "redacted_by_username") or "").strip().lower() == "privacy-suppression"
        and not viewer_is_admin
    ):
        raise PermissionError("This IP Database image is suppressed by the server privacy policy.")
    img = _ipdb_bytes(_row_get(row, "image_data"))
    if not img:
        raise ValueError("No image is stored for this IP Database record.")
    return img, (_row_get(row, "image_mime") or _ipdb_image_mime(img) or "application/octet-stream")


def _ipdb_profile_text(data: Dict[str, Any]) -> str:
    rows = [
        ("ID", data.get("id")),
        ("Redaction", "Active" if data.get("is_redacted") else "None"),
        ("Redacted At", data.get("redacted_at")),
        ("Redacted By", data.get("redacted_by_username")),
        ("Primary IP", data.get("primary_ip")),
        ("Secondary IP", data.get("secondary_ip")),
        ("Username", data.get("username")),
        ("Alias", data.get("alias")),
        ("Gender", data.get("gender")),
        ("Created At", f"{data.get('created_at') or 'N/A'} ({_ipdb_relative_time(data.get('created_at'))})"),
        ("Last Edited", f"{data.get('updated_at') or 'N/A'} ({_ipdb_relative_time(data.get('updated_at'))})"),
        ("Created By Username", IPDB_REDACTED_VALUE),
        ("Created By IP", IPDB_REDACTED_VALUE),
        ("Updated By Username", IPDB_REDACTED_VALUE),
        ("Updated By IP", IPDB_REDACTED_VALUE),
        ("Image Stored", "Yes" if data.get("image_present") else "No"),
        ("Image Name", data.get("image_name")),
        ("Image Bytes", data.get("image_bytes")),
        ("Image SHA-256", data.get("image_sha256")),
    ]
    lines = ["IPDB FULL PROFILE", "=" * 64]
    for label, value in rows:
        lines.append(f"{label}: {value if value not in (None, '') else 'N/A'}")
    lines.extend(["", "NOTES", "=" * 64, str(data.get("notes") or "")])
    return "\n".join(lines)


def _ipdb_log_full_profile_view(data: Dict[str, Any], viewer_ip: str = "unknown") -> None:
    if _privacy_request_is_suppressed(viewer_ip, data):
        return
    try:
        ts = now_iso()
        actor = _ipdb_actor_username()
        hostname = _ipdb_viewer_hostname()
        os_user = _ipdb_viewer_os_user()
        payload = {
            "event_type": "full_ipdb_profile_view",
            "viewer_username": actor,
            "viewer_user_id": None,
            "viewer_hostname": hostname,
            "viewer_os_user": os_user,
            "viewer_ip": viewer_ip,
            "ipdb_record_id": data.get("id"),
            "profile_username": data.get("username"),
            "profile_alias": data.get("alias"),
            "primary_ip": data.get("primary_ip"),
            "secondary_ip": data.get("secondary_ip"),
            "created_at": data.get("created_at"),
            "created_at_age": _ipdb_relative_time(data.get("created_at")),
            "updated_at": data.get("updated_at"),
            "updated_at_age": _ipdb_relative_time(data.get("updated_at")),
            "created_by_username": data.get("created_by_username"),
            "created_by_ip": data.get("created_by_ip"),
            "updated_by_username": data.get("updated_by_username"),
            "updated_by_ip": data.get("updated_by_ip"),
        }
        with _DB_LOCK:
            with db_connection() as conn:
                db_execute(
                    conn,
                    """INSERT INTO ipdb_full_profile_access_log(
                        timestamp, viewer_username, viewer_user_id, viewer_hostname, viewer_os_user,
                        event_type, ipdb_record_id, profile_username, profile_alias,
                        primary_ip, secondary_ip, created_at_value, created_at_age,
                        updated_at_value, updated_at_age, created_by_username, created_by_ip,
                        updated_by_username, updated_by_ip, details
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (
                        ts,
                        actor,
                        None,
                        hostname,
                        os_user,
                        "full_ipdb_profile_view",
                        data.get("id"),
                        data.get("username"),
                        data.get("alias"),
                        data.get("primary_ip"),
                        data.get("secondary_ip"),
                        data.get("created_at"),
                        payload.get("created_at_age"),
                        data.get("updated_at"),
                        payload.get("updated_at_age"),
                        data.get("created_by_username"),
                        data.get("created_by_ip"),
                        data.get("updated_by_username"),
                        data.get("updated_by_ip"),
                        json.dumps(payload, ensure_ascii=False, default=str),
                    ),
                )
                conn.commit()
    except Exception:
        pass


def ipdb_logs(record_id: Optional[Any] = None, limit: int = 25) -> List[Dict[str, Any]]:
    limit = max(1, min(int(limit or 25), 100))
    with _DB_LOCK:
        with db_connection() as conn:
            if record_id not in (None, "", 0, "0"):
                rows = db_fetchall(
                    conn,
                    "SELECT * FROM ipdb_full_profile_access_log WHERE ipdb_record_id = ? ORDER BY id DESC LIMIT ?",
                    (int(record_id), limit),
                )
            else:
                rows = db_fetchall(conn, "SELECT * FROM ipdb_full_profile_access_log ORDER BY id DESC LIMIT ?", (limit,))
    logs = [dict(r) for r in rows if not _privacy_value_has_suppressed_ip(r)]
    for row in logs:
        _ipdb_redact_actor_fields(row)
        try:
            details = json.loads(str(row.get("details") or "{}"))
            if isinstance(details, dict):
                _ipdb_redact_actor_fields(details)
                row["details"] = json.dumps(details, ensure_ascii=False, default=str)
        except Exception:
            pass
    return logs


def ipdb_list(search: str = "", viewer_is_admin: bool = True) -> List[Dict[str, Any]]:
    search = str(search or "").strip().lower()
    if _privacy_value_has_suppressed_ip(search):
        return []

    with _DB_LOCK:
        with ipdb_connection() as (conn, source):
            columns = _ipdb_table_columns(conn, source)
            projection = _ipdb_projection(columns, source)
            table = _ipdb_ident(IPDB_TABLE, source)

            # Admin search can use the source directly. Non-admin search must not
            # use hidden IP fields as a matching oracle, so it filters the public
            # redacted representation below instead.
            if search and viewer_is_admin:
                like = f"%{search}%"
                searchable = [
                    field for field in ("primary_ip", "secondary_ip", "username", "alias", "gender", "notes")
                    if field in columns
                ]
                if searchable:
                    clauses = [
                        f"LOWER(COALESCE({_ipdb_ident(field, source)}, '')) LIKE ?"
                        for field in searchable
                    ]
                    rows = _ipdb_fetchall(
                        conn,
                        source,
                        f"SELECT {projection} FROM {table} WHERE ({' OR '.join(clauses)}) "
                        f"ORDER BY {_ipdb_ident('id', source)} ASC LIMIT {IPDB_LIST_LIMIT}",
                        tuple(like for _ in searchable),
                    )
                else:
                    rows = []
            else:
                rows = _ipdb_fetchall(
                    conn,
                    source,
                    f"SELECT {projection} FROM {table} ORDER BY {_ipdb_ident('id', source)} ASC LIMIT {IPDB_LIST_LIMIT}",
                )

    merged_rows = [_ipdb_apply_local_redaction_state(row) for row in rows]
    records: List[Dict[str, Any]] = []
    for row in merged_rows:
        public = _ipdb_record_public(
            row,
            include_image=False,
            include_thumbnail=True,
            viewer_is_admin=viewer_is_admin,
        )
        if search and not viewer_is_admin:
            # Search only what this viewer is actually allowed to know.
            safe_fields = ("primary_ip", "secondary_ip", "username", "alias", "gender", "notes")
            haystack = "\n".join(str(public.get(field) or "").lower() for field in safe_fields)
            if search not in haystack:
                continue
        records.append(public)

    for number, record in enumerate(records, start=1):
        record["display_id"] = number
    return records


def ipdb_add(payload: Dict[str, Any], client_ip: str = "unknown") -> Dict[str, Any]:
    _ipdb_require_app_write_source()
    if _privacy_request_is_suppressed(payload, client_ip):
        raise ValueError("This IP is suppressed by the configured privacy policy.")
    primary_raw = str(payload.get("primary_ip") or "").strip()
    if not primary_raw:
        raise ValueError("Primary IP is required, matching the main-menu IP Database dialog.")
    try:
        primary = normalize_host_or_target(primary_raw)[:255]
    except Exception:
        primary = primary_raw[:255]
    secondary_raw = str(payload.get("secondary_ip") or "").strip()
    try:
        secondary = normalize_host_or_target(secondary_raw)[:255] if secondary_raw else ""
    except Exception:
        secondary = secondary_raw[:255] if secondary_raw else ""
    username = str(payload.get("username") or "").strip()[:255]
    if not username:
        raise ValueError("Username is required, matching the main-menu IP Database dialog.")
    alias = str(payload.get("alias") or "").strip()[:255]
    gender = _ipdb_clean_gender(payload.get("gender"))
    notes = str(payload.get("notes") or "").strip()[:12000]
    img, detected_mime = _ipdb_decode_image_b64(str(payload.get("image_data_b64") or ""))
    image_name = str(payload.get("image_name") or "").strip()[:255] if img else ""
    image_mime = detected_mime or (str(payload.get("image_mime") or "").strip()[:80] if img else "")
    ts = now_iso()
    actor = _ipdb_actor_username()
    created_by_ip = _ipdb_local_ip()
    with _DB_LOCK:
        with db_connection() as conn:
            cur = db_execute(
                conn,
                """INSERT INTO ip_records(
                    primary_ip, secondary_ip, username, alias, gender, notes, image_data, image_name, image_mime,
                    created_at, updated_at, created_by_username, created_by_ip, updated_by_username, updated_by_ip
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (primary, secondary, username, alias, gender, notes, img, image_name, image_mime, ts, None, actor, created_by_ip, None, None),
            )
            conn.commit()
            new_id = cur.lastrowid
    audit("ip_database", "add", {"id": new_id, "primary_ip": primary, "username": username, "gender": gender, "image_present": bool(img), "created_by_username": actor, "created_by_ip": created_by_ip})
    return {"ok": True, "id": new_id, "records": ipdb_list("")}


def ipdb_update(payload: Dict[str, Any], client_ip: str = "unknown") -> Dict[str, Any]:
    _ipdb_require_app_write_source()
    if _privacy_request_is_suppressed(payload, client_ip):
        raise ValueError("This IP is suppressed by the configured privacy policy.")
    rid = int(payload.get("id"))
    existing = _ipdb_get_record(rid, include_image=False)
    primary_raw = str(payload.get("primary_ip") or existing.get("primary_ip") or "").strip()
    if not primary_raw:
        raise ValueError("Primary IP is required.")
    try:
        primary = normalize_host_or_target(primary_raw)[:255]
    except Exception:
        primary = primary_raw[:255]
    secondary_raw = str(payload.get("secondary_ip") if "secondary_ip" in payload else existing.get("secondary_ip") or "").strip()
    try:
        secondary = normalize_host_or_target(secondary_raw)[:255] if secondary_raw else ""
    except Exception:
        secondary = secondary_raw[:255] if secondary_raw else ""
    username = str(payload.get("username") or existing.get("username") or "").strip()[:255]
    if not username:
        raise ValueError("Username is required.")
    alias = str(payload.get("alias") if "alias" in payload else existing.get("alias") or "").strip()[:255]
    gender = _ipdb_clean_gender(payload.get("gender") if "gender" in payload else existing.get("gender"))
    notes = str(payload.get("notes") if "notes" in payload else existing.get("notes") or "").strip()[:12000]
    update_image = bool(payload.get("replace_image")) and bool(str(payload.get("image_data_b64") or "").strip())
    clear_image = bool(payload.get("clear_image"))
    image_sql = ""
    values: List[Any] = []
    if update_image:
        img, detected_mime = _ipdb_decode_image_b64(str(payload.get("image_data_b64") or ""))
        image_name = str(payload.get("image_name") or "").strip()[:255]
        image_sql = ", image_data = ?, image_name = ?, image_mime = ?"
        values.extend([img, image_name, detected_mime])
    elif clear_image:
        image_sql = ", image_data = NULL, image_name = '', image_mime = ''"
    ts = now_iso()
    actor = _ipdb_actor_username()
    updated_by_ip = _ipdb_local_ip()
    with _DB_LOCK:
        with db_connection() as conn:
            db_execute(
                conn,
                f"""UPDATE ip_records SET
                    primary_ip = ?, secondary_ip = ?, username = ?, alias = ?, gender = ?, notes = ?,
                    updated_at = ?, updated_by_username = ?, updated_by_ip = ?{image_sql}
                    WHERE id = ?""",
                tuple([primary, secondary, username, alias, gender, notes, ts, actor, updated_by_ip] + values + [rid]),
            )
            conn.commit()
    audit("ip_database", "update", {"id": rid, "primary_ip": primary, "username": username, "gender": gender, "updated_by_username": actor, "updated_by_ip": updated_by_ip, "image_replaced": update_image, "image_cleared": clear_image})
    return {"ok": True, "id": rid, "record": _ipdb_get_record(rid, include_image=True), "records": ipdb_list("")}


def ipdb_profile(record_id: Any, viewer_ip: str = "unknown", include_logs: bool = False, viewer_is_admin: bool = True) -> Dict[str, Any]:
    full_data = _ipdb_get_record(record_id, include_image=False, viewer_is_admin=True)
    if _privacy_value_has_suppressed_ip(full_data):
        raise ValueError("This record is suppressed by the configured privacy policy.")
    data = full_data if viewer_is_admin else _ipdb_get_record(record_id, include_image=False, viewer_is_admin=False)
    # Never copy clear IPDB fields into the access log when a non-admin views a
    # redacted record. The log receives the same redacted representation shown
    # to that viewer. Administrators still get the normal administrative audit.
    log_data = full_data if viewer_is_admin else data
    _ipdb_log_full_profile_view(log_data, viewer_ip=viewer_ip)
    logs = ipdb_logs(data.get("id"), limit=25) if include_logs else []
    public_record = _ipdb_get_record(record_id, include_image=False, viewer_is_admin=False) if viewer_is_admin else data
    return {
        "ok": True,
        "record": data,
        "public_record": public_record,
        "profile_text": _ipdb_profile_text(data),
        "logs": logs,
        "logs_admin_only": not include_logs,
    }


def _ipdb_parse_redaction_state(value: Any) -> bool:
    """Parse an explicit redact/unredact value without Python truthiness surprises."""
    if isinstance(value, bool):
        return value
    if isinstance(value, int) and value in (0, 1):
        return bool(value)
    raw = str(value or "").strip().lower()
    if raw in {"1", "true", "yes", "y", "on"}:
        return True
    if raw in {"0", "false", "no", "n", "off"}:
        return False
    raise ValueError("Redaction state must be true or false.")


def _ipdb_admin_identity(admin_session: Dict[str, Any]) -> str:
    """Validate an authenticated administrator session and return its actor name."""
    if not isinstance(admin_session, dict):
        raise PermissionError("Valid administrator session required.")

    role = str(
        admin_session.get("role")
        or admin_session.get("user_role")
        or ""
    ).strip().lower()

    # Do not use bool(value) here: bool("false") is True.
    admin_flag = _truthy_db(admin_session.get("is_admin"))
    legacy_admin_flag = _truthy_db(admin_session.get("admin"))
    if role != "admin" and not admin_flag and not legacy_admin_flag:
        raise PermissionError("Administrator privileges are required to redact IP Database records.")

    return str(
        admin_session.get("username")
        or admin_session.get("user")
        or "admin"
    ).replace("\x00", "").strip()[:255] or "admin"


def _ipdb_ensure_redaction_columns(conn: Any, source: Dict[str, Any]) -> set:
    """Ensure the configured IPDB table has every redaction column.

    Older deployments may have an ip_records table created before redaction was
    added. Repairing it here makes the button self-healing instead of depending
    on a one-time startup migration having succeeded.
    """
    columns = _ipdb_table_columns(conn, source)
    ddl_by_column = {
        "is_redacted": "TINYINT(1) NOT NULL DEFAULT 0",
        "redacted_at": "VARCHAR(40) NULL",
        "redacted_by_username": "VARCHAR(255) NULL",
        "redaction_note": "VARCHAR(500) NULL",
    }
    missing = [name for name in ddl_by_column if name not in columns]
    if not missing:
        return columns
    table = _ipdb_ident(IPDB_TABLE, source)
    try:
        for name in missing:
            _ipdb_execute(
                conn,
                source,
                f"ALTER TABLE {table} ADD COLUMN {_ipdb_ident(name, source)} {ddl_by_column[name]}",
            )
        conn.commit()
    except Exception as exc:
        try:
            conn.rollback()
        except Exception:
            pass
        raise RuntimeError(
            "IP Database redaction schema is incomplete and could not be repaired: "
            + ", ".join(missing)
            + f". Database error: {exc}"
        ) from exc
    columns = _ipdb_table_columns(conn, source)
    still_missing = [name for name in ddl_by_column if name not in columns]
    if still_missing:
        raise RuntimeError(
            "IP Database redaction columns are still missing after migration: "
            + ", ".join(still_missing)
        )
    return columns


def _ipdb_verify_redaction_after_commit(record_id: int, expected: bool) -> Dict[str, Any]:
    """Re-open the DB and verify the committed state, not just the transaction view."""
    last_record: Optional[Dict[str, Any]] = None
    for delay in (0.0, 0.05, 0.15):
        if delay:
            time.sleep(delay)
        with ipdb_connection() as (verify_conn, verify_source):
            verify_columns = _ipdb_table_columns(verify_conn, verify_source)
            projection = _ipdb_projection(verify_columns, verify_source)
            row = _ipdb_fetchone(
                verify_conn,
                verify_source,
                f"SELECT {projection} FROM {_ipdb_ident(IPDB_TABLE, verify_source)} "
                f"WHERE {_ipdb_ident('id', verify_source)} = ? LIMIT 1",
                (int(record_id),),
            )
        if row is None:
            raise RuntimeError("IP Database record disappeared after the redaction commit.")
        last_record = dict(row)
        if _ipdb_record_is_redacted(last_record) == bool(expected):
            return last_record
    actual = _ipdb_record_is_redacted(last_record or {})
    raise RuntimeError(
        f"IP Database redaction did not persist after commit (expected {bool(expected)}, got {actual})."
    )


def ipdb_set_redaction(
    record_id: Any,
    redacted: Any,
    admin_session: Dict[str, Any],
    note: str = "",
    client_ip: str = "unknown",
) -> Dict[str, Any]:
    """Set or remove IP + Notes redaction for non-admin IP Database viewers.

    The website-owned sidecar is authoritative and is written first. This keeps
    the button reliable even when the source MySQL account is intentionally
    read-only. Optional source synchronization can be enabled with
    LL_WEB_IPDB_SYNC_REDACTION_TO_SOURCE=1.
    """
    actor = _ipdb_admin_identity(admin_session)
    try:
        rid = int(record_id)
    except (TypeError, ValueError):
        raise ValueError("A valid IP Database record id is required.")
    if rid <= 0:
        raise ValueError("A valid IP Database record id is required.")

    redacted_state = _ipdb_parse_redaction_state(redacted)
    clean_note = str(note or "").replace("\x00", "").strip()[:500] if redacted_state else ""

    # Confirm the source record exists using read-only access.
    with _DB_LOCK:
        with ipdb_connection() as (read_conn, read_source):
            read_columns = _ipdb_table_columns(read_conn, read_source)
            projection = _ipdb_projection(read_columns, read_source)
            raw_before = _ipdb_fetchone(
                read_conn,
                read_source,
                f"SELECT {projection} FROM {_ipdb_ident(IPDB_TABLE, read_source)} "
                f"WHERE {_ipdb_ident('id', read_source)} = ? LIMIT 1",
                (rid,),
            )
    if raw_before is None:
        raise ValueError("IP Database record not found.")

    # Critical path: persist the local enforcement state first.
    local_state = _ipdb_local_redaction_set(rid, redacted_state, actor, clean_note)
    local_verify = _ipdb_local_redaction_get(rid)
    if local_verify is None or bool(local_verify.get("is_redacted")) != redacted_state:
        raise RuntimeError("IP/Notes redaction could not be persisted by the website.")

    # Re-read through the same functions used by real viewers and verify that
    # the IP and Notes fields are actually hidden before returning success.
    admin_record = _ipdb_get_record(rid, include_image=False, viewer_is_admin=True)
    public_record = _ipdb_get_record(rid, include_image=False, viewer_is_admin=False)
    if bool(admin_record.get("is_redacted")) != redacted_state:
        raise RuntimeError("IP/Notes redaction state verification failed.")
    if redacted_state:
        for field in ("primary_ip", "secondary_ip", "notes"):
            if str(public_record.get(field) or "") != IPDB_REDACTED_VALUE:
                raise RuntimeError(f"Public {field} was not redacted.")

    # Source-table synchronization is deliberately opt-in. It is not required
    # for enforcement and failure never rolls back a working website redaction.
    sync_source = str(os.environ.get("LL_WEB_IPDB_SYNC_REDACTION_TO_SOURCE", "0") or "0").strip().lower() in {
        "1", "true", "yes", "on"
    }
    mysql_committed = False
    mysql_error = ""
    if sync_source:
        try:
            ts = now_iso() if redacted_state else None
            with _DB_LOCK:
                with ipdb_connection() as (conn, source):
                    columns = _ipdb_ensure_redaction_columns(conn, source)
                    table = _ipdb_ident(IPDB_TABLE, source)
                    id_col = _ipdb_ident("id", source)
                    _ipdb_execute(
                        conn,
                        source,
                        f"""
                        UPDATE {table}
                        SET
                            {_ipdb_ident('is_redacted', source)} = ?,
                            {_ipdb_ident('redacted_at', source)} = ?,
                            {_ipdb_ident('redacted_by_username', source)} = ?,
                            {_ipdb_ident('redaction_note', source)} = ?
                        WHERE {id_col} = ?
                        """,
                        (1 if redacted_state else 0, ts, actor if redacted_state else None, clean_note, rid),
                    )
                    conn.commit()
            _ipdb_verify_redaction_after_commit(rid, redacted_state)
            mysql_committed = True
        except Exception as exc:
            mysql_error = str(exc)[:1000]

    audit(
        "ip_database",
        "redact_ips_notes" if redacted_state else "unredact_ips_notes",
        {
            "id": rid,
            "redacted": redacted_state,
            "redaction_scope": "ip+notes",
            "redacted_by_username": actor,
            "redaction_note": clean_note,
            "client_ip": str(client_ip or "unknown")[:255],
            "local_overlay": True,
            "mysql_sync_enabled": sync_source,
            "mysql_committed": mysql_committed,
            "mysql_error": mysql_error,
        },
    )

    return {
        "ok": True,
        "id": rid,
        "redacted": redacted_state,
        "committed": True,
        "write_verified": True,
        "redaction_scope": "ip+notes",
        "enforcement": "website-sidecar",
        "mysql_sync_enabled": sync_source,
        "mysql_committed": mysql_committed,
        "mysql_error": mysql_error,
        "record": admin_record,
        "public_record": public_record,
        "records": ipdb_list("", viewer_is_admin=True),
    }


def ipdb_delete(record_id: Any, client_ip: str = "unknown") -> Dict[str, Any]:
    _ipdb_require_app_write_source()
    rid = int(record_id)
    try:
        before = _ipdb_get_record(rid, include_image=False)
    except Exception:
        before = {"id": rid}
    with _DB_LOCK:
        with db_connection() as conn:
            db_execute(conn, "DELETE FROM ip_records WHERE id = ?", (rid,))
            conn.commit()
    audit("ip_database", "delete", {"id": rid, "deleted_snapshot": before, "viewer_ip": client_ip})
    return {"ok": True, "records": ipdb_list("")}


def ipdb_count() -> int:
    with _DB_LOCK:
        with ipdb_connection() as (conn, source):
            columns = _ipdb_table_columns(conn, source)
            if not {"id", "primary_ip", "username"}.issubset(columns):
                return 0
            row = _ipdb_fetchone(conn, source, f"SELECT COUNT(*) AS record_count FROM {_ipdb_ident(IPDB_TABLE, source)}")
    return int(_row_get(row, "record_count", 0) or 0)


def _ipdb_default_import_paths() -> List[Path]:
    paths: List[Path] = []
    raw = os.environ.get("LL_WEB_IPDB_IMPORT_JSON") or os.environ.get("LL_WEB_IPDB_SEED_JSON") or ""
    if raw.strip():
        paths.append(Path(raw.strip()))
    try:
        paths.append(Path.cwd() / "admin" / "203.json")
    except Exception:
        pass
    try:
        here = Path(__file__).resolve().parent
        paths.append(here / "admin" / "203.json")
        paths.append(here / "menu beta.3" / "admin" / "203.json")
    except Exception:
        pass
    out: List[Path] = []
    seen = set()
    for path in paths:
        try:
            key = str(path.resolve()).lower()
        except Exception:
            key = str(path).lower()
        if key not in seen:
            seen.add(key)
            out.append(path)
    return out


def _ipdb_find_default_import_path() -> Optional[Path]:
    for path in _ipdb_default_import_paths():
        try:
            if path.exists() and path.is_file():
                return path
        except Exception:
            continue
    return None


def _ipdb_import_row_payload(row: Dict[str, Any]) -> Tuple[List[str], List[Any], Optional[str]]:
    primary_raw = str(row.get("primary_ip") or "").strip()
    username = str(row.get("username") or "").strip()[:255]
    if not primary_raw or not username:
        return [], [], "missing primary_ip or username"
    try:
        primary = normalize_host_or_target(primary_raw)[:255]
    except Exception:
        primary = primary_raw[:255]
    secondary_raw = str(row.get("secondary_ip") or "").strip()
    try:
        secondary = normalize_host_or_target(secondary_raw)[:255] if secondary_raw else ""
    except Exception:
        secondary = secondary_raw[:255] if secondary_raw else ""
    img = None
    image_mime = ""
    image_error = None
    image_raw = str(row.get("image_data_b64") or "").strip()
    if image_raw:
        try:
            img, image_mime = _ipdb_decode_image_b64(image_raw)
        except Exception as e:
            image_error = str(e)
            img = None
            image_mime = ""
    columns = [
        "primary_ip",
        "secondary_ip",
        "username",
        "alias",
        "gender",
        "notes",
        "image_data",
        "image_name",
        "image_mime",
        "created_at",
        "updated_at",
        "created_by_username",
        "created_by_ip",
        "updated_by_username",
        "updated_by_ip",
    ]
    values = [
        primary,
        secondary,
        username,
        str(row.get("alias") or "").strip()[:255],
        _ipdb_clean_gender(row.get("gender")),
        str(row.get("notes") or "").strip()[:12000],
        img,
        str(row.get("image_name") or f"203-record-{row.get('id') or 'image'}.png").strip()[:255] if img else "",
        image_mime if img else "",
        str(row.get("created_at") or now_iso()).strip()[:40],
        str(row.get("updated_at") or "").strip()[:40] or None,
        str(row.get("created_by_username") or "").strip()[:255],
        str(row.get("created_by_ip") or "").strip()[:255],
        str(row.get("updated_by_username") or "").strip()[:255],
        str(row.get("updated_by_ip") or "").strip()[:255],
    ]
    return columns, values, image_error


def ipdb_import_json(path: Any, replace: bool = False, preserve_ids: bool = True) -> Dict[str, Any]:
    _ipdb_require_app_write_source()
    source = Path(str(path or "")).expanduser()
    if not source.exists() or not source.is_file():
        raise ValueError(f"IPDB import file was not found: {source}")
    raw = json.loads(source.read_text(encoding="utf-8", errors="ignore"))
    if isinstance(raw, dict):
        if isinstance(raw.get("records"), list):
            rows = raw["records"]
        elif isinstance(raw.get("ip_records"), list):
            rows = raw["ip_records"]
        else:
            raise ValueError("IPDB import JSON object must contain `records` or `ip_records`.")
    elif isinstance(raw, list):
        rows = raw
    else:
        raise ValueError("IPDB import JSON must be a list or object.")
    rows = [r for r in rows if isinstance(r, dict)]
    imported = 0
    skipped = 0
    image_warnings: List[Dict[str, Any]] = []
    with _DB_LOCK:
        with db_connection() as conn:
            if replace:
                db_execute(conn, "DELETE FROM ipdb_full_profile_access_log")
                db_execute(conn, "DELETE FROM ip_records")
            for row in rows:
                columns, values, image_error = _ipdb_import_row_payload(row)
                if not columns:
                    skipped += 1
                    continue
                explicit_id = row.get("id") if preserve_ids else None
                if explicit_id not in (None, ""):
                    try:
                        explicit_id = int(explicit_id)
                    except Exception:
                        explicit_id = None
                if explicit_id is not None:
                    existing = db_fetchone(conn, "SELECT id FROM ip_records WHERE id = ? LIMIT 1", (explicit_id,))
                    if existing:
                        skipped += 1
                        continue
                    columns = ["id"] + columns
                    values = [explicit_id] + values
                placeholders = ", ".join("?" for _ in columns)
                db_execute(conn, f"INSERT INTO ip_records ({', '.join(_db_ident(c) for c in columns)}) VALUES ({placeholders})", tuple(values))
                imported += 1
                if image_error:
                    image_warnings.append({"id": row.get("id"), "username": row.get("username"), "error": image_error[:240]})
            conn.commit()
    result = {
        "ok": True,
        "source": str(source),
        "rows_seen": len(rows),
        "imported": imported,
        "skipped": skipped,
        "record_count": ipdb_count(),
        "database": db_descriptor(redact=True),
        "image_warnings": image_warnings[:20],
        "image_warning_count": len(image_warnings),
    }
    audit("ip_database", "import_json", {"source": str(source), "imported": imported, "skipped": skipped, "replace": replace})
    return result


def ipdb_seed_default_if_empty() -> Dict[str, Any]:
    source = _ipdb_source_config()
    if source.get("engine") == "mysql":
        return {"ok": True, "seeded": False, "reason": "live Main Menu MySQL source; JSON seed disabled", "record_count": ipdb_count()}
    if os.environ.get("LL_WEB_IPDB_AUTO_IMPORT", "1").strip().lower() in {"0", "false", "no", "off"}:
        return {"ok": True, "seeded": False, "reason": "auto import disabled", "record_count": ipdb_count()}
    count = ipdb_count()
    if count > 0:
        return {"ok": True, "seeded": False, "reason": "ip_records already has data", "record_count": count}
    path = _ipdb_find_default_import_path()
    if not path:
        return {"ok": True, "seeded": False, "reason": "no default import file found", "record_count": 0}
    result = ipdb_import_json(path, replace=False, preserve_ids=True)
    result["seeded"] = True
    return result


