def _osint_repo_candidates(repo_dir: str) -> List[Path]:
    roots = [
        OSINT_TOOLS_ROOT,
        Path.cwd() / "osint_tools",
        Path.cwd() / "tools" / "osint",
        Path.cwd(),
        Path(__file__).resolve().parent / "osint_tools",
        Path(__file__).resolve().parent,
    ]
    out: List[Path] = []
    seen = set()
    for root in roots:
        try:
            p = (root / repo_dir).resolve()
            k = str(p).lower()
            if k not in seen:
                seen.add(k)
                out.append(p)
        except Exception:
            continue
    return out


def _osint_repo_script(spec: Dict[str, Any]) -> Optional[Path]:
    script = str(spec.get("script") or "").strip()
    if not script:
        return None
    for root in _osint_repo_candidates(str(spec.get("repo_dir") or "")):
        p = root / script
        try:
            if p.is_file():
                return p
        except Exception:
            continue
    return None


def _osint_executable_names(command: str) -> List[str]:
    base = str(command or "").strip()
    if not base:
        return []
    names = [base]
    if sys.platform.startswith("win") and not Path(base).suffix:
        names.extend([base + ".exe", base + ".cmd", base + ".bat", base + ".ps1"])
    return names



OSINT_REDACTED_ENGINE_NAME = "REDACTED"
OSINT_MANAGED_ENGINE_GROUP = "managed"


def _osint_engine_alias_maps() -> Tuple[Dict[str, str], Dict[str, str]]:
    """Return deterministic public aliases for every non-core registry entry."""
    real_to_alias: Dict[str, str] = {}
    alias_to_real: Dict[str, str] = {}
    index = 1
    for spec in OSINT_ENGINE_SPECS:
        eid = str(spec.get("id") or "").strip().lower()
        if not eid or eid == "c8core":
            continue
        alias = f"registry-{index:02d}"
        real_to_alias[eid] = alias
        alias_to_real[alias] = eid
        index += 1
    return real_to_alias, alias_to_real


def _osint_external_redaction_tokens() -> List[str]:
    tokens: List[str] = []
    for spec in OSINT_ENGINE_SPECS:
        eid = str(spec.get("id") or "").strip()
        if not eid or eid.lower() == "c8core":
            continue
        candidates: List[Any] = [
            eid,
            spec.get("name"),
            spec.get("command"),
            spec.get("pip_package"),
            spec.get("repo"),
            spec.get("source_url"),
            spec.get("repo_dir"),
            spec.get("script"),
            *_osint_module_candidates(spec),
        ]
        for value in candidates:
            value = str(value or "").strip()
            if value and value.lower() not in {"c-8 core", "c8core"} and value not in tokens:
                tokens.append(value)
    return sorted(tokens, key=len, reverse=True)


def _osint_redact_text(value: Any) -> str:
    text_value = str(value or "")
    for token in _osint_external_redaction_tokens():
        try:
            text_value = re.sub(re.escape(token), OSINT_REDACTED_ENGINE_NAME, text_value, flags=re.IGNORECASE)
        except Exception:
            text_value = text_value.replace(token, OSINT_REDACTED_ENGINE_NAME)
    return text_value


def _osint_redact_nested(value: Any) -> Any:
    if isinstance(value, dict):
        return {str(k): _osint_redact_nested(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_osint_redact_nested(v) for v in value]
    if isinstance(value, tuple):
        return [_osint_redact_nested(v) for v in value]
    if isinstance(value, str):
        return _osint_redact_text(value)
    return value


def _osint_resolve_engine_request(engines: Optional[List[str]], is_admin: bool) -> List[str]:
    """Resolve admin IDs or public aliases without exposing real engine IDs to operators."""
    requested = [str(x).strip().lower() for x in (engines or []) if str(x).strip()]
    engine_map = {str(e.get("id") or "").strip().lower(): e for e in OSINT_ENGINE_SPECS}
    _real_to_alias, alias_to_real = _osint_engine_alias_maps()
    selected: List[str] = []

    def add(eid: str) -> None:
        spec = engine_map.get(eid)
        if spec and bool(spec.get("run_supported")) and eid not in selected:
            selected.append(eid)

    if not requested:
        for eid, spec in engine_map.items():
            if bool(spec.get("default_selected")):
                add(eid)
    else:
        for item in requested:
            if item == "c8core":
                add("c8core")
            elif item == OSINT_MANAGED_ENGINE_GROUP:
                for eid, spec in engine_map.items():
                    if eid != "c8core" and bool(spec.get("run_supported")) and (bool(spec.get("server_bootstrap")) or bool(spec.get("default_selected"))):
                        add(eid)
            elif is_admin and item in engine_map:
                add(item)
            elif not is_admin and item in alias_to_real:
                add(alias_to_real[item])

    # C-8 Core is always available and always included.
    if "c8core" not in selected:
        selected.insert(0, "c8core")
    return selected


def _osint_redacted_engine_record(record: Dict[str, Any]) -> Dict[str, Any]:
    row = dict(record or {})
    eid = str(row.get("id") or row.get("engine_id") or "").strip().lower()
    if eid == "c8core" or str(row.get("name") or row.get("engine_name") or "").strip().lower() == "c-8 core":
        return row
    real_to_alias, _alias_to_real = _osint_engine_alias_maps()
    alias = real_to_alias.get(eid, "registry-redacted")
    status = str(row.get("status") or row.get("registry_status") or "unknown")
    public = _osint_redact_nested(row)
    public["id"] = alias
    public["engine_id"] = alias
    public["name"] = OSINT_REDACTED_ENGINE_NAME
    public["engine_name"] = OSINT_REDACTED_ENGINE_NAME
    public["repo"] = ""
    public["source_url"] = ""
    public["scope"] = "VPS-managed public-source engine"
    public["install_hint"] = "Managed by the VPS"
    public["executable"] = ""
    public["executable_path"] = ""
    public["script"] = ""
    public["module"] = ""
    public["version"] = ""
    public["version_text"] = ""
    public["install_path"] = ""
    public["install_type"] = ""
    public["last_error"] = "Engine unavailable." if status.lower() in {"error", "install-failed", "disabled"} else ""
    public["registry_redacted"] = True
    return public


def _osint_redacted_installation(record: Dict[str, Any]) -> Dict[str, Any]:
    row = dict(record or {})
    eid = str(row.get("id") or "").strip().lower()
    if eid == "c8core":
        return row
    public = _osint_redacted_engine_record(row)
    status = str(row.get("status") or "unknown")
    public["reason"] = "VPS-managed engine preparation status is restricted."
    public["steps"] = [
        {
            "ok": bool(step.get("ok")),
            "command": "VPS-managed preparation",
            "output": "Preparation completed." if step.get("ok") else "Preparation failed.",
            "error": "" if step.get("ok") else "Preparation failed.",
        }
        for step in (row.get("steps") or []) if isinstance(step, dict)
    ]
    public["status"] = status
    return public


def _osint_redacted_result(record: Dict[str, Any]) -> Dict[str, Any]:
    row = dict(record or {})
    eid = str(row.get("id") or "").strip().lower()
    if eid == "c8core":
        return row
    public = _osint_redacted_engine_record(row)
    public["status"] = row.get("status")
    public["returncode"] = row.get("returncode")
    public["duration_ms"] = row.get("duration_ms")
    public["started_at"] = row.get("started_at")
    public["command"] = "VPS-managed engine execution"
    public["reason"] = _osint_redact_text(row.get("reason") or "")
    public["output"] = _osint_redact_text(row.get("output") or "")
    public["found_links"] = list(row.get("found_links") or [])
    reports: List[Dict[str, Any]] = []
    for index, report in enumerate(row.get("reports") or [], start=1):
        if not isinstance(report, dict):
            continue
        suffix = Path(str(report.get("name") or "")).suffix[:12]
        reports.append({
            "name": f"report_{index}{suffix}",
            "relative_path": f"report_{index}{suffix}",
            "size": report.get("size"),
            "snippet": _osint_redact_text(report.get("snippet") or ""),
        })
    public["reports"] = reports
    return public


def _osint_response_for_role(payload: Dict[str, Any], is_admin: bool) -> Dict[str, Any]:
    if is_admin:
        result = dict(payload)
        result["registry_redacted"] = False
        return result

    result = dict(payload)
    real_to_alias, _alias_to_real = _osint_engine_alias_maps()
    result["engines"] = [_osint_redacted_engine_record(x) for x in (payload.get("engines") or []) if isinstance(x, dict)]
    result["installations"] = [_osint_redacted_installation(x) for x in (payload.get("installations") or []) if isinstance(x, dict)]
    result["results"] = [_osint_redacted_result(x) for x in (payload.get("results") or []) if isinstance(x, dict)]
    result["registry"] = [_osint_redacted_engine_record(x) for x in (payload.get("registry") or []) if isinstance(x, dict)]
    result["selected_engines"] = [
        "c8core" if str(eid).lower() == "c8core" else real_to_alias.get(str(eid).lower(), "registry-redacted")
        for eid in (payload.get("selected_engines") or [])
    ]

    external_names = [
        str(spec.get("name") or "").lower()
        for spec in OSINT_ENGINE_SPECS
        if str(spec.get("id") or "").lower() != "c8core"
    ]
    external_urls = {
        str(spec.get("repo") or "").strip().lower()
        for spec in OSINT_ENGINE_SPECS
        if str(spec.get("id") or "").lower() != "c8core" and str(spec.get("repo") or "").strip()
    } | {
        str(spec.get("source_url") or "").strip().lower()
        for spec in OSINT_ENGINE_SPECS
        if str(spec.get("id") or "").lower() != "c8core" and str(spec.get("source_url") or "").strip()
    }
    safe_links: List[Dict[str, Any]] = []
    for link in payload.get("links") or []:
        if not isinstance(link, dict):
            continue
        label = str(link.get("label") or "").lower()
        url = str(link.get("url") or "").strip().lower()
        if any(name and name in label for name in external_names) or url in external_urls:
            continue
        safe_links.append(link)
    result["links"] = safe_links
    result["shared_install_root"] = ""
    result["run_directory"] = ""
    result["registry_redacted"] = True
    result["note"] = "Engine registry names and implementation details are redacted for non-admin users. C-8 Core remains identified."
    return result






def _osint_run_install_command(cmd: List[str], cwd: Optional[Path] = None, timeout: Optional[float] = None) -> Dict[str, Any]:
    started = time.time()
    env = os.environ.copy()
    env.setdefault("PYTHONIOENCODING", "utf-8")
    env.setdefault("PIP_DISABLE_PIP_VERSION_CHECK", "1")
    flags = 0
    if sys.platform.startswith("win"):
        flags = 0x08000000
    try:
        proc = subprocess.run(
            cmd,
            cwd=str(cwd) if cwd else None,
            env=env,
            stdin=subprocess.DEVNULL,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=max(10.0, min(600.0, float(timeout or OSINT_INSTALL_TIMEOUT_SECONDS))),
            shell=False,
            creationflags=flags,
        )
        output = _osint_shorten((proc.stdout or "") + (("\n\nSTDERR:\n" + proc.stderr) if proc.stderr else ""), 16000)
        return {"ok": proc.returncode == 0, "returncode": proc.returncode, "command": " ".join(cmd), "duration_ms": int((time.time() - started) * 1000), "output": output}
    except subprocess.TimeoutExpired as e:
        output = _osint_shorten(((e.stdout or "") if isinstance(e.stdout, str) else "") + "\n" + ((e.stderr or "") if isinstance(e.stderr, str) else ""), 16000)
        return {"ok": False, "returncode": None, "command": " ".join(cmd), "duration_ms": int((time.time() - started) * 1000), "output": output, "error": "install timeout"}
    except Exception as e:
        return {"ok": False, "returncode": None, "command": " ".join(cmd), "duration_ms": int((time.time() - started) * 1000), "output": "", "error": str(e)}


def _osint_pip_install_cmd(package_or_req: str, requirements: bool = False) -> List[str]:
    cmd = [sys.executable, "-m", "pip", "install", "--disable-pip-version-check"]
    try:
        in_venv = bool(getattr(sys, "base_prefix", sys.prefix) != sys.prefix)
    except Exception:
        in_venv = False
    if not in_venv:
        cmd.append("--user")
    if requirements:
        cmd.extend(["-r", package_or_req])
    else:
        cmd.extend(["--upgrade", package_or_req])
    return cmd


def _osint_download_repo_zip(spec: Dict[str, Any], dest: Path) -> Dict[str, Any]:
    zip_url = str(spec.get("zip_url") or "").strip()
    if not zip_url:
        return {"ok": False, "error": "No zip fallback URL configured."}
    started = time.time()
    tmp_dir = Path(tempfile.mkdtemp(prefix="osint_repo_", dir=str(TEMP_WORKSPACE)))
    zip_path = tmp_dir / "repo.zip"
    try:
        req = urllib.request.Request(zip_url, headers={"User-Agent": "LocalOSINTConsole/1.0"})
        with _c8_urlopen(req, timeout=min(120.0, max(15.0, OSINT_INSTALL_TIMEOUT_SECONDS))) as r:
            data = r.read(96 * 1024 * 1024)
        zip_path.write_bytes(data)
        with zipfile.ZipFile(zip_path, "r") as zf:
            _c8_check_zip(zf)
            for info in zf.infolist():
                target = Path(tmp_dir) / _c8_archive_name(info.filename)
                if info.is_dir():
                    target.mkdir(parents=True, exist_ok=True)
                else:
                    target.parent.mkdir(parents=True, exist_ok=True)
                    target.write_bytes(_c8_zip_read(zf, info))
        roots = [p for p in tmp_dir.iterdir() if p.is_dir()]
        if not roots:
            return {"ok": False, "error": "Downloaded zip did not contain a repository folder."}
        src = roots[0]
        dest.parent.mkdir(parents=True, exist_ok=True)
        if dest.exists():
            return {"ok": False, "error": f"Destination already exists without expected script: {dest}"}
        shutil.move(str(src), str(dest))
        return {"ok": True, "command": f"download {zip_url}", "duration_ms": int((time.time() - started) * 1000), "output": f"Downloaded and extracted to {dest}"}
    except Exception as e:
        return {"ok": False, "command": f"download {zip_url}", "duration_ms": int((time.time() - started) * 1000), "output": "", "error": str(e)}
    finally:
        try:
            shutil.rmtree(tmp_dir, ignore_errors=True)
        except Exception:
            pass




def _osint_engine_map() -> Dict[str, Dict[str, Any]]:
    return {str(e["id"]): e for e in OSINT_ENGINE_SPECS}


def _osint_unique_strings(values: Any, limit: int = 50) -> List[str]:
    out: List[str] = []
    seen = set()
    try:
        iterable = values if isinstance(values, (list, tuple, set)) else [values]
        for value in iterable:
            s = str(value or "").strip()
            if not s:
                continue
            key = s.lower()
            if key in seen:
                continue
            seen.add(key)
            out.append(s)
            if len(out) >= limit:
                break
    except Exception:
        pass
    return out


def _osint_chunked(values: Any, size: int) -> List[List[str]]:
    items = _osint_unique_strings(values, limit=500)
    step = max(1, int(size or 1))
    return [items[i:i + step] for i in range(0, len(items), step)]


def _osint_term_hits(text: str, terms: Any, limit: int = 40) -> List[str]:
    raw = str(text or "").lower()
    searchable = re.sub(r"[^a-z0-9]+", " ", raw)
    hits: List[str] = []
    for term in terms or []:
        t = str(term or "").strip().lower()
        if not t:
            continue
        needle = re.sub(r"[^a-z0-9]+", " ", t).strip()
        if not needle:
            continue
        if (" " in needle and needle in searchable) or re.search(rf"(?<![a-z0-9]){re.escape(needle)}(?![a-z0-9])", searchable):
            hits.append(t)
            if len(hits) >= limit:
                break
    return _osint_unique_strings(hits, limit=limit)


def _osint_url_hostname(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    probe = raw if "://" in raw else "//" + raw
    try:
        parsed = urllib.parse.urlsplit(probe)
        host = str(parsed.hostname or "").strip().rstrip(".").lower()
        return host.encode("idna").decode("ascii") if host else ""
    except Exception:
        return ""


def _osint_social_sites_in_text(value: str, limit: int = 30) -> List[str]:
    raw = str(value or "").lower()
    host = _osint_url_hostname(raw)
    hits: List[str] = []
    for site in SOCIAL_SITE_DOMAINS:
        s = str(site or "").lower()
        if not s:
            continue
        if host and (host == s or host.endswith("." + s)):
            hits.append(s)
        elif re.search(rf"(?<![a-z0-9.-]){re.escape(s)}(?![a-z0-9.-])", raw):
            hits.append(s)
        if len(hits) >= limit:
            break
    return _osint_unique_strings(hits, limit=limit)


def _osint_social_profile_links(handle: str, limit: int = 120) -> List[Dict[str, str]]:
    h = urllib.parse.quote(str(handle or "").strip().lstrip("@"), safe="")
    if not h:
        return []
    links: List[Dict[str, str]] = []
    seen = set()
    for item in SOCIAL_PROFILE_PATTERNS:
        try:
            url = str(item.get("url") or "").format(handle=h)
            label = str(item.get("label") or item.get("site") or "Profile candidate").strip()
            key = url.lower()
            if url and key not in seen:
                seen.add(key)
                links.append({"label": label, "url": url})
                if len(links) >= limit:
                    break
        except Exception:
            continue
    return links


def _osint_public_profile_host_allowed(url: str) -> Tuple[bool, str]:
    host = _osint_url_hostname(url)
    if not host:
        return False, "missing-host"
    if host in {"localhost", "127.0.0.1", "::1"} or host.endswith(".local") or host.endswith(".internal"):
        return False, "local-host-blocked"
    try:
        ip = ipaddress.ip_address(host.strip("[]"))
        if not ip.is_global:
            return False, "non-public-ip-blocked"
        return True, host
    except Exception:
        pass
    try:
        addresses = {
            str(row[4][0]).split("%", 1)[0]
            for row in socket.getaddrinfo(host, None, type=socket.SOCK_STREAM)
            if row and len(row) > 4 and row[4]
        }
        if not addresses:
            return False, "host-resolution-empty"
        for value in addresses:
            if not ipaddress.ip_address(value).is_global:
                return False, "host-resolves-to-non-public-ip"
    except Exception:
        return False, "host-resolution-failed"
    return True, host


def _osint_profile_absence_seen(text: str) -> bool:
    low = str(text or "").lower()
    return any(marker in low for marker in SOCIAL_ABSENCE_MARKERS)


def _osint_profile_positive_seen(handle: str, title: str, body: str, final_url: str) -> bool:
    h = str(handle or "").strip().lower().lstrip("@")
    title_l = str(title or "").lower()
    body_l = str(body or "").lower()
    url_l = str(final_url or "").lower()
    if h and (f"/{h}" in url_l or f"@{h}" in url_l or f"={h}" in url_l):
        if any(marker in (title_l + " " + body_l[:8000]) for marker in SOCIAL_OPEN_PROFILE_MARKERS):
            return True
    if h and (h in title_l or f"@{h}" in title_l):
        return True
    if h and re.search(rf"(?<![a-z0-9._-])@?{re.escape(h)}(?![a-z0-9._-])", body_l[:24000]):
        if any(marker in body_l[:24000] for marker in SOCIAL_OPEN_PROFILE_MARKERS):
            return True
    return False


def _osint_extract_html_title(text: str) -> str:
    try:
        m = re.search(r"<title[^>]*>(.*?)</title>", str(text or ""), flags=re.I | re.S)
        if not m:
            return ""
        title = re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", m.group(1))).strip()
        return title[:180]
    except Exception:
        return ""


def _osint_http_probe(url: str, method: str = "GET", max_bytes: int = 96 * 1024) -> Dict[str, Any]:
    ok, host_or_reason = _osint_public_profile_host_allowed(url)
    if not ok:
        return {"ok": False, "status_code": 0, "final_url": url, "body": "", "error": host_or_reason}
    try:
        req = urllib.request.Request(str(url), headers={
            "User-Agent": "C-8-OSINT-PublicProfileCheck/1.0",
            "Accept": "text/html,application/xhtml+xml,application/json;q=0.8,text/plain;q=0.7,*/*;q=0.5",
            "Accept-Encoding": "identity",
            "Connection": "close",
        }, method=str(method or "GET").upper())
        class _PublicRedirectHandler(urllib.request.HTTPRedirectHandler):
            def redirect_request(self, request, fp, code, msg, headers, newurl):
                redirect_ok, redirect_reason = _osint_public_profile_host_allowed(newurl)
                if not redirect_ok:
                    raise urllib.error.HTTPError(newurl, 403, redirect_reason, headers, fp)
                return super().redirect_request(request, fp, code, msg, headers, newurl)

        opener = _c8_build_opener(_PublicRedirectHandler())
        with opener.open(req, timeout=OSINT_PROFILE_VERIFY_TIMEOUT_SECONDS) as r:
            status = int(getattr(r, "status", 200) or 200)
            final_url = str(getattr(r, "url", url) or url)
            final_ok, final_reason = _osint_public_profile_host_allowed(final_url)
            if not final_ok:
                return {"ok": False, "status_code": 0, "final_url": final_url, "body": "", "error": final_reason}
            body = b""
            if str(method or "GET").upper() != "HEAD":
                body = r.read(max(1024, int(max_bytes)))
            text = body.decode("utf-8", errors="replace") if body else ""
            return {"ok": status < 400, "status_code": status, "final_url": final_url, "body": text, "error": ""}
    except urllib.error.HTTPError as e:
        body_text = ""
        try:
            body_text = e.read(24 * 1024).decode("utf-8", errors="replace")
        except Exception:
            body_text = ""
        return {"ok": False, "status_code": int(getattr(e, "code", 0) or 0), "final_url": str(getattr(e, "url", url) or url), "body": body_text, "error": str(e)[:240]}
    except Exception as e:
        return {"ok": False, "status_code": 0, "final_url": url, "body": "", "error": str(e)[:240]}


def _osint_probe_public_profile(link: Dict[str, str], handle: str) -> Dict[str, Any]:
    label = str((link or {}).get("label") or "").strip()[:120]
    url = str((link or {}).get("url") or "").strip()
    host = _osint_url_hostname(url)
    started = time.time()
    base = {"label": label, "url": url, "host": host, "checked_at": now_iso()}
    if not url.lower().startswith(("http://", "https://")):
        return {**base, "status": "skipped", "status_code": 0, "reason": "non-http-url", "duration_ms": 0}
    head = _osint_http_probe(url, method="HEAD", max_bytes=0)
    status_code = int(head.get("status_code") or 0)
    if status_code in {405, 501, 0} or (200 <= status_code < 400):
        res = _osint_http_probe(url, method="GET")
    else:
        res = head
    status_code = int(res.get("status_code") or status_code or 0)
    body = str(res.get("body") or "")
    title = _osint_extract_html_title(body)
    final_url = str(res.get("final_url") or url)
    duration_ms = int((time.time() - started) * 1000)
    combined = (title + " " + body[:24000]).lower()
    if status_code in {404, 410} or _osint_profile_absence_seen(combined):
        status = "not_found"
        reason = "public page indicates no matching profile"
    elif status_code in {401, 403, 429, 999}:
        status = "blocked"
        reason = "site denied or rate-limited unauthenticated public check"
    elif 200 <= status_code < 400 and _osint_profile_positive_seen(handle, title, body, final_url):
        status = "open"
        reason = "public profile page returned account-like markers"
    elif 200 <= status_code < 400:
        status = "maybe_open"
        reason = "public page returned but account markers were inconclusive"
    elif status_code:
        status = "error"
        reason = f"http-status-{status_code}"
    else:
        status = "error"
        reason = str(res.get("error") or "request failed")[:180]
    return {
        **base,
        "status": status,
        "status_code": status_code,
        "final_url": final_url,
        "title": title,
        "reason": reason,
        "duration_ms": duration_ms,
    }


def _osint_verify_social_profiles(handle: str, links: Optional[List[Dict[str, str]]] = None, limit: Optional[int] = None) -> List[Dict[str, Any]]:
    h = _osint_username_target(handle)
    if not h:
        return []
    max_checks = OSINT_PROFILE_VERIFY_DEFAULT_MAX if limit is None else max(0, min(120, int(limit or 0)))
    if max_checks <= 0:
        return []
    candidates = links or _osint_social_profile_links(h, limit=max_checks)
    candidates = candidates[:max_checks]
    results: List[Dict[str, Any]] = []
    workers = max(1, min(OSINT_PROFILE_VERIFY_WORKERS, len(candidates) or 1))
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as ex:
            future_map = {ex.submit(_osint_probe_public_profile, link, h): idx for idx, link in enumerate(candidates)}
            for fut in concurrent.futures.as_completed(future_map):
                idx = future_map[fut]
                try:
                    item = fut.result()
                except Exception as e:
                    link = candidates[idx]
                    item = {
                        "label": str(link.get("label") or "")[:120],
                        "url": str(link.get("url") or ""),
                        "host": _osint_url_hostname(str(link.get("url") or "")),
                        "status": "error",
                        "status_code": 0,
                        "reason": str(e)[:180],
                        "checked_at": now_iso(),
                        "duration_ms": 0,
                    }
                item["_order"] = idx
                results.append(item)
    except Exception as e:
        return [{"status": "error", "reason": str(e)[:180], "checked_at": now_iso()}]
    status_rank = {"open": 0, "maybe_open": 1, "blocked": 2, "not_found": 3, "error": 4, "skipped": 5}
    results.sort(key=lambda x: (status_rank.get(str(x.get("status")), 9), int(x.get("_order") or 0)))
    for item in results:
        item.pop("_order", None)
    return results


def _osint_normalize_discovered_url(value: Any) -> str:
    raw = str(value or "").strip().strip("\"'<>[]{}()")
    if not raw or len(raw) > 2048:
        return ""
    try:
        parsed = urllib.parse.urlsplit(raw)
        if parsed.scheme.lower() not in {"http", "https"} or not parsed.hostname:
            return ""
        return urllib.parse.urlunsplit((parsed.scheme.lower(), parsed.netloc, parsed.path or "/", parsed.query, ""))
    except Exception:
        return ""


def _osint_validate_discovered_link(url: str, target: str = "") -> Dict[str, Any]:
    normalized = _osint_normalize_discovered_url(url)
    started = time.time()
    base = {
        "url": normalized or str(url or "")[:2048],
        "host": _osint_url_hostname(normalized),
        "checked_at": now_iso(),
    }
    if not normalized:
        return {**base, "status": "filtered", "status_code": 0, "reason": "invalid-http-url", "duration_ms": 0}
    allowed, reason = _osint_public_profile_host_allowed(normalized)
    if not allowed:
        return {**base, "status": "filtered", "status_code": 0, "reason": reason, "duration_ms": 0}

    head = _osint_http_probe(normalized, method="HEAD", max_bytes=0)
    status_code = int(head.get("status_code") or 0)
    if status_code in {0, 405, 501} or 200 <= status_code < 400:
        result = _osint_http_probe(normalized, method="GET", max_bytes=64 * 1024)
    else:
        result = head
    status_code = int(result.get("status_code") or status_code or 0)
    final_url = _osint_normalize_discovered_url(result.get("final_url") or normalized) or normalized
    title = _osint_extract_html_title(str(result.get("body") or ""))
    combined = (title + " " + str(result.get("body") or "")[:24000]).lower()
    handle = _osint_username_target(target)
    is_social = bool(_osint_social_sites_in_text(final_url, limit=1))
    duration_ms = int((time.time() - started) * 1000)

    if status_code in {404, 410} or _osint_profile_absence_seen(combined):
        status, reason = "filtered", "page-not-found"
    elif status_code in {401, 403, 429, 999}:
        status, reason = "blocked", "public-check-denied-or-rate-limited"
    elif 200 <= status_code < 400 and is_social and handle and not _osint_profile_positive_seen(handle, title, combined, final_url):
        status, reason = "filtered", "profile-identity-not-confirmed"
    elif 200 <= status_code < 400:
        status, reason = "valid", "public-link-confirmed"
    else:
        status, reason = "error", str(result.get("error") or f"http-status-{status_code}")[:180]
    return {
        **base,
        "url": final_url,
        "host": _osint_url_hostname(final_url),
        "status": status,
        "status_code": status_code,
        "title": title,
        "reason": reason,
        "duration_ms": duration_ms,
    }


def _osint_filter_discovered_links(urls: Any, target: str = "", limit: Optional[int] = None) -> Dict[str, Any]:
    max_checks = OSINT_LINK_VERIFY_MAX if limit is None else max(0, min(120, int(limit or 0)))
    if max_checks <= 0:
        return {"candidate_count": 0, "checked_count": 0, "valid_count": 0, "filtered_count": 0, "status_counts": {}, "links": [], "records": []}
    candidates: List[str] = []
    seen = set()
    for value in urls or []:
        normalized = _osint_normalize_discovered_url(value)
        key = normalized.lower()
        if normalized and key not in seen:
            seen.add(key)
            candidates.append(normalized)
        if len(candidates) >= max_checks:
            break
    records: List[Dict[str, Any]] = []
    if candidates:
        workers = max(1, min(OSINT_LINK_VERIFY_WORKERS, len(candidates)))
        with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
            future_map = {executor.submit(_osint_validate_discovered_link, url, target): index for index, url in enumerate(candidates)}
            for future in concurrent.futures.as_completed(future_map):
                index = future_map[future]
                try:
                    record = future.result()
                except Exception as exc:
                    record = {"url": candidates[index], "host": _osint_url_hostname(candidates[index]), "status": "error", "status_code": 0, "reason": str(exc)[:180], "duration_ms": 0}
                record["_order"] = index
                records.append(record)
    rank = {"valid": 0, "blocked": 1, "filtered": 2, "error": 3}
    records.sort(key=lambda item: (rank.get(str(item.get("status") or ""), 9), int(item.get("_order") or 0)))
    for record in records:
        record.pop("_order", None)
    valid_links: List[str] = []
    valid_seen = set()
    for record in records:
        if str(record.get("status")) != "valid":
            continue
        value = str(record.get("url") or "")
        key = value.lower()
        if value and key not in valid_seen:
            valid_seen.add(key)
            valid_links.append(value)
    counts: Dict[str, int] = {}
    for record in records:
        status = str(record.get("status") or "error")
        counts[status] = counts.get(status, 0) + 1
    return {
        "candidate_count": len(candidates),
        "checked_count": len(records),
        "valid_count": len(valid_links),
        "filtered_count": len(records) - len(valid_links),
        "status_counts": counts,
        "links": valid_links,
        "records": records,
    }


def _osint_target_signals(q: str, kind: str) -> Dict[str, Any]:
    target = str(q or "").strip()
    if not target:
        return {}
    handle = _osint_username_target(target)
    domainish = derive_domain_from_hostname(target)
    if domainish == "N/A" or " " in domainish or "." not in domainish:
        domainish = ""
    elif not target.lstrip().startswith("@"):
        handle = ""
    brand_hits = _osint_term_hits(target, BRAND_TERMS)
    profile_hits = _osint_term_hits(target, PROFILE_PATH_TERMS)
    username_context_hits = _osint_term_hits(target, USERNAME_CONTEXT_TERMS)
    public_record_hits = _osint_term_hits(target, PUBLIC_RECORD_TERMS)
    domain_intel_hits = _osint_term_hits(target, DOMAIN_INTEL_TERMS)
    social_hits = _osint_social_sites_in_text(target)
    score = 0
    if handle:
        score += 25
    if domainish:
        score += 25
    if social_hits:
        score += 25
    if profile_hits:
        score += min(20, len(profile_hits) * 4)
    if brand_hits:
        score += min(20, len(brand_hits) * 4)
    if username_context_hits or public_record_hits or domain_intel_hits:
        score += min(15, (len(username_context_hits) + len(public_record_hits) + len(domain_intel_hits)) * 3)
    detected = str(kind or "").lower()
    if detected in {"handle", "username", "domain", "email", "ip", "organization"}:
        score += 10
    return {
        "handle_candidate": handle,
        "domain_candidate": domainish,
        "social_profile_sites": social_hits,
        "profile_path_terms": profile_hits[:20],
        "brand_terms": brand_hits[:20],
        "username_context_terms": username_context_hits[:20],
        "public_record_terms": public_record_hits[:20],
        "domain_intel_terms": domain_intel_hits[:20],
        "confidence": min(100, score),
        "classification": detected or "unknown",
    }


def _osint_clean_query(query: str) -> str:
    q = str(query or "").strip()
    if not q or len(q) > 240:
        raise ValueError("Enter one authorized query, 1-240 characters.")
    if any(x in q for x in ["\n", "\r", "\t", "\x00"]):
        raise ValueError("Use one query at a time.")
    return q


def _osint_username_target(q: str) -> str:
    candidate = str(q or "").strip().lstrip("@")
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{1,63}", candidate):
        return candidate
    return ""


def _osint_is_email(q: str) -> bool:
    return bool(re.fullmatch(r"[^@\s]{1,96}@[^@\s]{1,160}\.[^@\s]{2,32}", str(q or "").strip()))


def _osint_detect_kind(q: str, kind: str) -> str:
    k = str(kind or "auto").strip().lower()[:24]
    if k and k != "auto":
        return k
    try:
        ipaddress.ip_address(q)
        return "ip"
    except Exception:
        pass
    if _osint_is_email(q):
        return "email"
    domainish = derive_domain_from_hostname(q)
    if domainish != "N/A" and "." in domainish and " " not in q:
        return "domain"
    if _osint_username_target(q):
        return "handle"
    if _osint_term_hits(q, BRAND_TERMS, limit=4):
        return "organization"
    return "keyword"


def _osint_build_links(q: str, kind: str) -> List[Dict[str, str]]:
    """Build direct public-source and search links for one bounded target."""
    enc = urllib.parse.quote_plus(q)
    exact = f'"{q}"'
    links: List[Dict[str, str]] = [
        {"label": "Google exact search", "url": "https://www.google.com/search?" + urllib.parse.urlencode({"q": exact})},
        {"label": "Bing exact search", "url": "https://www.bing.com/search?" + urllib.parse.urlencode({"q": exact})},
        {"label": "DuckDuckGo exact search", "url": "https://duckduckgo.com/?" + urllib.parse.urlencode({"q": exact})},
        {"label": "Brave exact search", "url": "https://search.brave.com/search?" + urllib.parse.urlencode({"q": exact})},
        {"label": "Yahoo exact search", "url": "https://search.yahoo.com/search?" + urllib.parse.urlencode({"p": exact})},
        {"label": "Mojeek exact search", "url": "https://www.mojeek.com/search?" + urllib.parse.urlencode({"q": exact})},
        {"label": "Startpage exact search", "url": "https://www.startpage.com/sp/search?" + urllib.parse.urlencode({"query": exact})},
        {"label": "Google News", "url": "https://news.google.com/search?" + urllib.parse.urlencode({"q": q})},
        {"label": "GitHub search", "url": f"https://github.com/search?q={enc}&type=users"},
        {"label": "GitHub code search", "url": f"https://github.com/search?q=%22{enc}%22&type=code"},
        {"label": "GitLab search", "url": "https://gitlab.com/search?" + urllib.parse.urlencode({"search": q})},
        {"label": "Reddit search", "url": "https://www.reddit.com/search/?" + urllib.parse.urlencode({"q": q})},
        {"label": "YouTube search", "url": "https://www.youtube.com/results?" + urllib.parse.urlencode({"search_query": q})},
        {"label": "Internet Archive text search", "url": "https://archive.org/search?" + urllib.parse.urlencode({"query": q})},
    ]
    if kind == "ip":
        ipq = urllib.parse.quote(q, safe="")
        links.extend([
            {"label": "Public RDAP for IP", "url": f"https://rdap.org/ip/{ipq}"},
            {"label": "BGPView IP lookup", "url": f"https://bgpview.io/ip/{ipq}"},
            {"label": "RIPEstat IP lookup", "url": f"https://stat.ripe.net/{ipq}"},
            {"label": "Shodan host page", "url": f"https://www.shodan.io/host/{ipq}"},
            {"label": "VirusTotal IP page", "url": f"https://www.virustotal.com/gui/ip-address/{ipq}"},
            {"label": "AbuseIPDB IP page", "url": f"https://www.abuseipdb.com/check/{ipq}"},
            {"label": "GreyNoise IP page", "url": f"https://viz.greynoise.io/ip/{ipq}"},
        ])
    else:
        domainish = derive_domain_from_hostname(q)
        if kind == "domain" or (domainish != "N/A" and "." in domainish and " " not in q):
            d = urllib.parse.quote(domainish, safe="")
            links.extend([
                {"label": "RDAP domain lookup", "url": f"https://rdap.org/domain/{d}"},
                {"label": "ICANN lookup", "url": f"https://lookup.icann.org/en/lookup?name={d}"},
                {"label": "Certificate Transparency search", "url": f"https://crt.sh/?q={urllib.parse.quote_plus(domainish)}"},
                {"label": "Wayback Machine", "url": f"https://web.archive.org/web/*/{d}/*"},
                {"label": "urlscan domain search", "url": f"https://urlscan.io/search/#{urllib.parse.quote_plus('domain:' + domainish)}"},
                {"label": "VirusTotal domain page", "url": f"https://www.virustotal.com/gui/domain/{d}"},
                {"label": "DNSdumpster", "url": "https://dnsdumpster.com/"},
            ])
    handle = _osint_username_target(q)
    if kind in {"handle", "username", "email", "keyword"} and handle:
        links.extend(_osint_social_profile_links(handle))
        h = urllib.parse.quote_plus(handle)
        h_path = urllib.parse.quote(handle, safe="")
        links.extend([
            {"label": "Google @handle exact", "url": "https://www.google.com/search?" + urllib.parse.urlencode({"q": f'"@{handle}"'})},
            {"label": "Google handle profile context", "url": "https://www.google.com/search?" + urllib.parse.urlencode({"q": f'"{handle}" (profile OR username OR handle OR bio OR followers)'})},
            {"label": "Bing @handle exact", "url": "https://www.bing.com/search?" + urllib.parse.urlencode({"q": f'"@{handle}"'})},
            {"label": "DuckDuckGo handle profile context", "url": "https://duckduckgo.com/?" + urllib.parse.urlencode({"q": f'"{handle}" (profile OR username OR handle)'})},
            {"label": "GitLab user search", "url": f"https://gitlab.com/search?search={h}&scope=users"},
            {"label": "GitHub repository search", "url": f"https://github.com/search?q={h}&type=repositories"},
            {"label": "GitHub issue search", "url": f"https://github.com/search?q={h}&type=issues"},
            {"label": "Reddit people search", "url": f"https://www.reddit.com/search/?q={h}&type=people"},
            {"label": "YouTube search", "url": f"https://www.youtube.com/results?search_query={h}"},
            {"label": "Twitch search", "url": f"https://www.twitch.tv/search?term={h}"},
            {"label": "Steam community search", "url": f"https://steamcommunity.com/search/users/#text={h_path}"},
        ])
    if kind == "organization":
        links.extend([
            {"label": "OpenCorporates search", "url": "https://opencorporates.com/companies?" + urllib.parse.urlencode({"q": q})},
            {"label": "SEC EDGAR search", "url": "https://www.sec.gov/edgar/search/#/q=" + urllib.parse.quote(q, safe="")},
            {"label": "UK Companies House search", "url": "https://find-and-update.company-information.service.gov.uk/search?" + urllib.parse.urlencode({"q": q})},
        ])
    # Preserve repository references for installed/managed OSINT engines.
    links.extend({"label": e["name"] + " repository", "url": str(e["source_url"])} for e in OSINT_ENGINE_SPECS)
    # Stable dedupe by URL.
    out: List[Dict[str, str]] = []
    seen = set()
    for row in links:
        url = str(row.get("url") or "").strip()
        if not url or url in seen:
            continue
        seen.add(url)
        out.append(row)
    return out


