# Normalize one accidental spaced token at declaration time; all generated handle
# tokens must satisfy the username-safe character policy below.
OSINT_POP_CULTURE_TOKENS = tuple(x.replace(" ", "") for x in OSINT_POP_CULTURE_TOKENS)

OSINT_USERNAME_SUBSTITUTIONS: Dict[str, Tuple[str, ...]] = {
    "a": ("4",), "b": ("8", "6"), "c": ("k",), "e": ("3",), "f": ("ph",), "g": ("9", "6"),
    "i": ("1", "y"), "k": ("c",), "l": ("1", "i"), "m": ("rn",), "o": ("0",), "q": ("9",),
    "s": ("5", "z"), "t": ("7",), "u": ("v",), "v": ("u",), "x": ("ks",), "y": ("i",), "z": ("2", "s"),
    "0": ("o",), "1": ("i", "l"), "2": ("z",), "3": ("e",), "4": ("a",),
    "5": ("s",), "6": ("b", "g"), "7": ("t",), "8": ("b",), "9": ("g", "q"),
}

def _osint_clean_affix_list(values: Any, limit: int = OSINT_AFFIX_ITEM_MAX) -> List[str]:
    """Normalize user-supplied username prefixes/suffixes into a small safe token list."""
    if isinstance(values, str):
        raw_values = re.split(r"[,;\n\r]+", values)
    elif isinstance(values, (list, tuple, set)):
        raw_values = list(values)
    else:
        raw_values = []
    out: List[str] = []
    seen = set()
    for raw in raw_values:
        token = str(raw or "").strip().lstrip("@").lower()
        token = re.sub(r"\s+", "", token)
        if not token or len(token) > 24 or not re.fullmatch(r"[a-z0-9][a-z0-9._-]{0,23}", token):
            continue
        key = token.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(token)
        if len(out) >= max(1, int(limit)):
            break
    return out


def _osint_handle_substitution_variants(base: str, limit: int = OSINT_SUBSTITUTION_MAX) -> List[Dict[str, str]]:
    """Generate bounded ASCII username substitutions for public-search discovery."""
    base = str(base or "").strip().lstrip("@")
    if not base:
        return []
    cap = max(1, min(OSINT_SUBSTITUTION_MAX, int(limit or OSINT_SUBSTITUTION_MAX)))
    out: List[Dict[str, str]] = []
    seen = {base.lower()}

    def add(value: str, rule: str) -> None:
        value = str(value or "").strip().lstrip("@")
        if not value or len(value) > 64 or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{1,63}", value):
            return
        key = value.lower()
        if key in seen or len(out) >= cap:
            return
        seen.add(key)
        out.append({"value": value, "rule": rule})

    # Single-position lookalike/spelling substitutions in both directions.
    plans: List[Tuple[int, str, str]] = []
    for index, ch in enumerate(base):
        for replacement in OSINT_USERNAME_SUBSTITUTIONS.get(ch.lower(), ()):
            plans.append((index, replacement, f"{ch}->{replacement}"))
            add(base[:index] + replacement + base[index + 1:], f"{ch}->{replacement}")
            if len(out) >= cap:
                return out

    # Common separator substitutions/removal and a compact no-separator form.
    for index, ch in enumerate(base):
        if ch not in "._-":
            continue
        for replacement in ("", "_", ".", "-"):
            if replacement == ch:
                continue
            add(base[:index] + replacement + base[index + 1:], f"separator {ch}->{replacement or 'none'}")
            if len(out) >= cap:
                return out
    if any(ch in base for ch in "._-"):
        add(re.sub(r"[._-]+", "", base), "remove all separators")
        add(re.sub(r"[._-]+", "_", base), "normalize separators to _")
        add(re.sub(r"[._-]+", ".", base), "normalize separators to .")
        add(re.sub(r"[._-]+", "-", base), "normalize separators to -")

    # Alternate spelling rules frequently seen in reused public handles.
    spelling_rules = (
        ("ph", "f"), ("f", "ph"), ("ck", "k"), ("k", "ck"), ("qu", "q"),
        ("oo", "u"), ("ee", "i"), ("ie", "y"), ("y", "ie"), ("tion", "shun"),
    )
    lower = base.lower()
    for old, new in spelling_rules:
        pos = lower.find(old)
        while pos >= 0:
            add(base[:pos] + new + base[pos + len(old):], f"spelling {old}->{new}")
            if len(out) >= cap:
                return out
            pos = lower.find(old, pos + 1)

    # Drop a single vowel from longer handles, or collapse a repeated character.
    if len(base) >= 5:
        for i, ch in enumerate(base):
            if ch.lower() in "aeiou" and 0 < i < len(base) - 1:
                add(base[:i] + base[i + 1:], f"drop vowel {ch}")
                if len(out) >= cap:
                    return out
        for i in range(1, len(base)):
            if base[i].lower() == base[i - 1].lower():
                add(base[:i] + base[i + 1:], f"collapse repeated {base[i]}")
                if len(out) >= cap:
                    return out

    # Insert a common separator at alpha/numeric boundaries.
    for i in range(1, len(base)):
        if base[i - 1].isalnum() and base[i].isalnum() and (base[i - 1].isdigit() != base[i].isdigit()):
            for sep in ("_", ".", "-"):
                add(base[:i] + sep + base[i:], f"insert {sep} at alpha/number boundary")
                if len(out) >= cap:
                    return out

    # Deterministic two-position substitutions catch common leetspeak variants
    # without allowing an exponential candidate explosion.
    pair_budget = min(64, max(0, cap - len(out)))
    made = 0
    for left in range(len(plans)):
        i, repl_i, rule_i = plans[left]
        for right in range(left + 1, len(plans)):
            j, repl_j, rule_j = plans[right]
            if i == j:
                continue
            if i < j:
                value = base[:i] + repl_i + base[i + 1:j] + repl_j + base[j + 1:]
            else:
                value = base[:j] + repl_j + base[j + 1:i] + repl_i + base[i + 1:]
            before = len(out)
            add(value, f"{rule_i}, {rule_j}")
            if len(out) > before:
                made += 1
            if made >= pair_budget or len(out) >= cap:
                return out
    return out

def _osint_handle_variants(
    q: str,
    kind: str,
    prefixes: Any = None,
    suffixes: Any = None,
    include_defaults: bool = True,
    combine_affixes: bool = False,
    include_substitutions: bool = True,
    max_variants: int = OSINT_VARIANT_MAX,
) -> List[Dict[str, str]]:
    """Build bounded public-search handle variants; never used for authentication guessing."""
    detected = str(kind or "").strip().lower()
    handle = _osint_username_target(q)
    if not handle or detected not in {"handle", "username", "keyword"}:
        return []
    base = handle.lstrip("@").strip()
    prefix_items = _osint_clean_affix_list(prefixes)
    suffix_items = _osint_clean_affix_list(suffixes)
    locations: List[str] = []
    area_codes: List[str] = []
    pop_culture: List[str] = []
    if include_defaults:
        prefix_items = _osint_unique_strings([*prefix_items, *OSINT_DEFAULT_PREFIXES], OSINT_AFFIX_ITEM_MAX)
        suffix_items = _osint_unique_strings([*suffix_items, *OSINT_DEFAULT_SUFFIXES], OSINT_AFFIX_ITEM_MAX)
        locations = _osint_unique_strings(OSINT_LOCATION_TOKENS, 256)
        area_codes = _osint_unique_strings(OSINT_AREA_CODE_TOKENS, 256)
        pop_culture = _osint_unique_strings(OSINT_POP_CULTURE_TOKENS, 256)

    limit = max(1, min(OSINT_VARIANT_MAX, int(max_variants or OSINT_VARIANT_MAX)))
    out: List[Dict[str, str]] = []
    seen = {base.lower()}

    def add(value: str, source: str, affix: str = "", separator: str = "") -> None:
        value = str(value or "").strip().lstrip("@")
        if not value or len(value) > 64 or not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{1,63}", value):
            return
        key = value.lower()
        if key in seen or len(out) >= limit:
            return
        seen.add(key)
        out.append({"value": value, "source": source, "affix": affix, "separator": separator})

    # Put substitutions first so they cannot be starved by a large affix dictionary.
    if include_substitutions:
        for row in _osint_handle_substitution_variants(base):
            add(str(row.get("value") or ""), "substitution", str(row.get("rule") or ""), "")
            if len(out) >= limit:
                return out

    # Interleave every built-in family so prefix/suffix, location, area-code and
    # pop-culture candidates all get representation inside the fixed variant budget.
    separators = ("", "_", ".", "-")
    width = max(len(prefix_items), len(suffix_items), len(locations), len(area_codes), len(pop_culture), 1)
    for sep in separators:
        for index in range(width):
            if index < len(prefix_items):
                affix = prefix_items[index]
                add(f"{affix}{sep}{base}", "prefix", affix, sep)
            if index < len(suffix_items):
                affix = suffix_items[index]
                add(f"{base}{sep}{affix}", "suffix", affix, sep)
            if index < len(locations):
                token = locations[index]
                add(f"{base}{sep}{token}", "location", token, sep)
                if index % 3 == 0:
                    add(f"{token}{sep}{base}", "location-prefix", token, sep)
            if index < len(area_codes):
                code = area_codes[index]
                add(f"{base}{sep}{code}", "area-code", code, sep)
                if index % 5 == 0:
                    add(f"{code}{sep}{base}", "area-code-prefix", code, sep)
            if index < len(pop_culture):
                token = pop_culture[index]
                add(f"{base}{sep}{token}", "pop-culture", token, sep)
                if index % 4 == 0:
                    add(f"{token}{sep}{base}", "pop-culture-prefix", token, sep)
            if len(out) >= limit:
                return out

    if combine_affixes and len(out) < limit:
        # Keep combinations bounded and rotate through different families.
        combo_suffixes = _osint_unique_strings([*suffix_items[:32], *locations[:32], *area_codes[:32], *pop_culture[:32]], 128)
        for pre in prefix_items[:32]:
            for suf in combo_suffixes:
                for sep in ("", "_", ".", "-"):
                    add(f"{pre}{sep}{base}{sep}{suf}", "prefix+suffix", f"{pre} / {suf}", sep)
                    if len(out) >= limit:
                        return out
    return out

def _osint_clean_dork_scope(scope: str) -> str:
    """Accept only a hostname/IP scope, never arbitrary search operators."""
    value = str(scope or "").strip()
    if not value:
        return ""
    probe = value if "://" in value else "//" + value
    try:
        parsed = urllib.parse.urlsplit(probe)
        host = str(parsed.hostname or "").strip().rstrip(".").lower()
    except Exception:
        host = ""
    if not host:
        raise ValueError("Search scope must be a domain or IP address, such as example.com.")
    try:
        ipaddress.ip_address(host)
        return host
    except Exception:
        pass
    try:
        host = host.encode("idna").decode("ascii")
    except Exception:
        raise ValueError("Search scope is not a valid domain or IP address.")
    label = r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?"
    if len(host) > 253 or not re.fullmatch(rf"{label}(?:\.{label})+", host):
        raise ValueError("Search scope is not a valid public domain or IP address.")
    return host


def _osint_search_provider_urls(query: str) -> Dict[str, str]:
    query = str(query or "").strip()
    return {
        "Google": "https://www.google.com/search?" + urllib.parse.urlencode({"q": query}),
        "Bing": "https://www.bing.com/search?" + urllib.parse.urlencode({"q": query}),
        "DuckDuckGo": "https://duckduckgo.com/?" + urllib.parse.urlencode({"q": query}),
        "Brave": "https://search.brave.com/search?" + urllib.parse.urlencode({"q": query}),
        "Yahoo": "https://search.yahoo.com/search?" + urllib.parse.urlencode({"p": query}),
        "Mojeek": "https://www.mojeek.com/search?" + urllib.parse.urlencode({"q": query}),
        "Startpage": "https://www.startpage.com/sp/search?" + urllib.parse.urlencode({"query": query}),
    }


def _osint_build_dorks(q: str, kind: str, mode: str = "balanced", scope: str = "", prefixes: Any = None, suffixes: Any = None, include_default_affixes: bool = True, combine_affixes: bool = False, include_substitutions: bool = True) -> List[Dict[str, Any]]:
    """Build broad but bounded public-search queries; never scrape search-engine result pages."""
    target = str(q or "").strip()
    if not target:
        return []
    selected_mode = str(mode or "balanced").strip().lower()
    if selected_mode not in OSINT_DORK_MODES:
        selected_mode = "balanced"
    scope_host = _osint_clean_dork_scope(scope)
    clean_target = target.replace('"', " ").strip()
    phrase = f'"{clean_target}"'
    handle = _osint_username_target(target)
    domainish = derive_domain_from_hostname(target)
    if domainish == "N/A" or " " in str(domainish):
        domainish = ""
    elif not target.lstrip().startswith("@"):
        handle = ""
    variants = _osint_handle_variants(
        target, kind, prefixes=prefixes, suffixes=suffixes,
        include_defaults=include_default_affixes, combine_affixes=combine_affixes,
        include_substitutions=include_substitutions,
    )

    rows: List[Dict[str, Any]] = []
    seen = set()

    mode_groups = {
        "mentions": {"mentions", "news", "archives", "scoped"},
        "profiles": {"profiles", "social", "variants", "scoped"},
        "social": {"social", "profiles", "variants", "scoped"},
        "variants": {"variants", "profiles", "social", "scoped"},
        "documents": {"documents", "registries", "scoped"},
        "code": {"code", "security", "scoped"},
        "domain": {"domain", "security", "archives", "registries", "scoped"},
        "news": {"news", "mentions"},
        "archives": {"archives", "domain", "documents", "scoped"},
        "registries": {"registries", "documents", "domain", "scoped"},
        "security": {"security", "domain", "code", "scoped"},
    }
    balanced_groups = {"mentions", "profiles", "social", "documents", "code", "domain", "news", "archives", "registries", "security", "scoped"}

    def allowed(group: str) -> bool:
        if selected_mode == "everything":
            return True
        if selected_mode == "balanced":
            return group in balanced_groups
        return group in mode_groups.get(selected_mode, balanced_groups)

    def add(group: str, title: str, query: str, note: str, priority: int = 50) -> None:
        query = re.sub(r"\s+", " ", str(query or "")).strip()
        if not query or not allowed(group):
            return
        key = query.lower()
        if key in seen:
            return
        seen.add(key)
        rows.append({
            "id": f"dork-{len(rows) + 1:03d}",
            "group": group,
            "title": title,
            "query": query,
            "note": note,
            "priority": int(priority),
            "providers": _osint_search_provider_urls(query),
        })

    def term_or(terms: Any) -> str:
        out: List[str] = []
        for term in terms or []:
            t = str(term or "").strip()
            if not t:
                continue
            out.append(f'"{t}"' if re.search(r"[^A-Za-z0-9_-]", t) else t)
        return " OR ".join(out)

    year = datetime.now(timezone.utc).year
    # Core mentions / disambiguation.
    add("mentions", "Exact public mention", phrase, "Exact indexed references to the target.", 100)
    add("mentions", "Page-title mention", f'intitle:{phrase}', "Pages with the target in the indexed title.", 96)
    add("mentions", "URL-path mention", f'inurl:{phrase}', "Pages with the target in the indexed URL path.", 94)
    add("mentions", "Page-text mention", f'intext:{phrase}', "Pages with the target in indexed body text.", 92)
    add("mentions", "Identity / alias context", f'{phrase} (alias OR username OR handle OR profile OR bio OR "also known as")', "Public context for manual disambiguation.", 90)
    add("mentions", "Contact / about context", f'{phrase} (contact OR about OR biography OR team OR staff OR author)', "Public about/contact references.", 84)
    add("mentions", f"Recent references {year}", f'{phrase} {year}', "Current-year indexed references.", 82)
    add("mentions", f"Recent references {year-1}", f'{phrase} {year-1}', "Previous-year indexed references.", 80)

    # Profiles / social.
    add("profiles", "Public profile paths", f'{phrase} (inurl:profile OR inurl:user OR inurl:member OR inurl:people OR inurl:author)', "Likely public profile pages.", 98)
    add("profiles", "Profile title / URL", f'(intitle:{phrase} OR inurl:{clean_target}) (profile OR user OR member OR author)', "Public profile-oriented title and URL matching.", 94)
    add("social", "Major social/profile sites", f'{phrase} (site:github.com OR site:reddit.com OR site:medium.com OR site:x.com OR site:instagram.com OR site:tiktok.com)', "Cross-site public profile references.", 96)
    add("social", "Creator / streaming sites", f'{phrase} (site:youtube.com OR site:twitch.tv OR site:patreon.com OR site:soundcloud.com OR site:bandcamp.com)', "Public creator and streaming profiles.", 82)
    add("social", "Link-in-bio pages", f'{phrase} (site:linktr.ee OR site:about.me OR site:carrd.co OR site:beacons.ai OR site:solo.to)', "Public link aggregation/profile pages.", 78)
    add("social", "Community / forum references", f'{phrase} (site:reddit.com OR site:stackoverflow.com OR site:news.ycombinator.com OR site:medium.com)', "Public community mentions.", 76)
    for idx, markers in enumerate(_osint_chunked([f"inurl:{x}" for x in PROFILE_PATH_TERMS], 10)[:4], start=1):
        add("profiles", f"Expanded profile URL markers {idx}", f'{phrase} ({" OR ".join(markers)})', "Broader profile, author, staff, and directory URL patterns.", 72)
    profile_seed = f'("{handle}" OR "@{handle}")' if handle else phrase
    for idx, sites in enumerate(_osint_chunked(SOCIAL_SITE_DOMAINS, 8)[:7], start=1):
        add("social", f"Social/profile platform batch {idx}", f'{profile_seed} ({" OR ".join("site:" + s for s in sites)})', "Expanded public social/profile platform coverage.", 70)

    # Username variants stay public-search only.
    if variants:
        variant_values = [str(item.get("value") or "") for item in variants if item.get("value")]
        for idx, batch in enumerate(_osint_chunked(variant_values, 6)[:10], start=1):
            variant_or = " OR ".join(f'"{value}"' for value in batch)
            add("variants", f"Username variants / substitutions {idx}", f'({variant_or}) (profile OR username OR handle OR bio)', "Bounded public-search variants from built-in affixes and optional ASCII substitutions.", 68)
        if selected_mode in {"variants", "everything"}:
            for item in variants[:36]:
                value = str(item.get("value") or "")
                add("variants", f"Exact variant: {value}", f'"{value}"', f"Exact public mention for a {item.get('source') or 'handle'} variant.", 62)

    # Documents / datasets / registries.
    add("documents", "Public documents", f'{phrase} (filetype:pdf OR filetype:doc OR filetype:docx OR filetype:ppt OR filetype:pptx)', "Indexed reports, documents, and presentations.", 88)
    add("documents", "Public spreadsheets and data", f'{phrase} (filetype:csv OR filetype:xls OR filetype:xlsx)', "Indexed public data files mentioning the target.", 84)
    add("documents", "Public text / structured data", f'{phrase} (filetype:txt OR filetype:json OR filetype:xml)', "Indexed public text and structured-data files.", 74)
    add("documents", "Reports / filings / presentations", f'{phrase} (report OR filing OR audit OR presentation OR minutes OR agenda) (filetype:pdf OR filetype:pptx OR filetype:docx)', "Formal public documents.", 80)
    add("registries", "Public registry context", f'{phrase} (registry OR registration OR filing OR licence OR license OR incorporation OR company)', "Public registry and filing references.", 80)
    add("registries", "OpenCorporates indexed results", f'{phrase} site:opencorporates.com', "Public company-registry index references.", 74)
    add("registries", "Government open-data references", f'{phrase} (site:data.gov OR site:gov.uk OR site:europa.eu)', "Public government/open-data references.", 70)
    add("registries", "SEC / corporate filings", f'{phrase} (site:sec.gov OR site:find-and-update.company-information.service.gov.uk)', "Public corporate filing references.", 72)

    # Public code / technical footprint. No credential/secret search terms are generated.
    add("code", "Public source-code references", f'{phrase} (site:github.com OR site:gitlab.com OR site:codeberg.org)', "Public repository references only.", 86)
    add("code", "Public package references", f'{phrase} (site:npmjs.com OR site:pypi.org OR site:rubygems.org OR site:packagist.org OR site:crates.io)', "Public package-registry references.", 78)
    add("code", "README / documentation references", f'{phrase} (README OR documentation OR docs OR wiki) (site:github.com OR site:gitlab.com OR site:readthedocs.io)', "Public project documentation.", 72)
    add("code", "Issues / pull requests", f'{phrase} (issue OR "pull request" OR discussion) (site:github.com OR site:gitlab.com)', "Public development discussions.", 70)

    # News and archives.
    add("news", "News / press references", f'{phrase} (news OR press OR announcement OR interview OR coverage)', "Public news and press references.", 86)
    add("news", "Current-year news", f'{phrase} {year} (news OR press OR announcement)', "Current-year news coverage.", 80)
    add("news", "Previous-year news", f'{phrase} {year-1} (news OR press OR announcement)', "Previous-year news coverage.", 76)
    add("archives", "Archive / historical references", f'{phrase} (archive OR archived OR snapshot OR history OR historical OR wayback)', "Indexed historical/archive references.", 78)
    add("archives", "Internet Archive indexed mentions", f'{phrase} site:archive.org', "Public Internet Archive text/index references.", 72)
    add("archives", "Wayback indexed mentions", f'{phrase} site:web.archive.org', "Search-engine indexed Wayback references.", 70)

    # Defensive/public security context only.
    add("security", "Security advisories", f'{phrase} (security OR advisory OR vulnerability OR CVE OR incident OR patch)', "Public defensive security references.", 80)
    add("security", "Public security reports", f'{phrase} (site:nvd.nist.gov OR site:cve.org OR site:cert.org OR site:cisa.gov)', "Public vulnerability/advisory references.", 74)
    add("security", "Trust / policy references", f'{phrase} (security OR privacy OR abuse OR compliance OR disclosure OR "security.txt")', "Public security/contact policy references.", 70)

    # Existing context dictionaries add breadth without unrestricted operators.
    for idx, terms in enumerate(_osint_chunked(USERNAME_CONTEXT_TERMS, 8)[:3], start=1):
        add("profiles", f"Username context terms {idx}", f'{phrase} ({term_or(terms)})', "Profile-page wording that can confirm a handle/bio context.", 66)
    for idx, terms in enumerate(_osint_chunked(PUBLIC_RECORD_TERMS, 8)[:4], start=1):
        add("documents", f"Public-record terms {idx}", f'{phrase} ({term_or(terms)})', "Public-record and registry wording for manual verification.", 64)

    detected = str(kind or "").lower()
    if detected in {"handle", "username"} and handle:
        add("profiles", "Username and @handle", f'("{handle}" OR "@{handle}")', "Exact username forms.", 100)
        add("profiles", "Username in profile URLs", f'(inurl:{handle} OR intitle:"{handle}") (profile OR user OR member OR author)', "Profile-oriented URL/title matching.", 96)
        add("social", "Handle on developer platforms", f'("{handle}" OR "@{handle}") (site:github.com OR site:gitlab.com OR site:stackoverflow.com)', "Public developer-profile references.", 86)
        add("social", "Handle on creator platforms", f'("{handle}" OR "@{handle}") (site:youtube.com OR site:twitch.tv OR site:soundcloud.com OR site:bandcamp.com)', "Public creator-profile references.", 82)
    elif detected == "email" and _osint_is_email(target):
        local_part, mail_domain = target.rsplit("@", 1)
        add("mentions", "Exact email mention", phrase, "Publicly indexed occurrences of the complete address.", 100)
        add("mentions", "Mailbox and domain correlation", f'"{local_part}" "{mail_domain}"', "Pages containing both mailbox and domain terms.", 92)
        add("code", "Email in public repositories", f'{phrase} (site:github.com OR site:gitlab.com OR site:codeberg.org)', "Public repository references to the address.", 82)
        add("domain", "Email-domain references", f'"{mail_domain}" -site:{mail_domain}', "Third-party indexed references to the email domain.", 80)
        if len(local_part) >= 4:
            add("profiles", "Mailbox local-part profile context", f'"{local_part}" (profile OR username OR handle OR bio) "{mail_domain}"', "Public profile references correlated with the email domain.", 70)
        add("security", "Email-domain security policy", f'"{mail_domain}" (SPF OR DMARC OR DKIM OR "MTA-STS" OR "TLS-RPT")', "Public mail-security references for the domain.", 72)
    elif detected == "ip":
        add("domain", "IP routing context", f'{phrase} (BGP OR ASN OR route OR prefix OR peering OR RPKI)', "Public routing and network references.", 94)
        add("security", "IP reputation context", f'{phrase} (abuse OR blacklist OR scanner OR malware OR reputation OR botnet)', "Public reputation/abuse references; verify every result.", 88)
        add("security", "IP security-report references", f'{phrase} (site:abuseipdb.com OR site:virustotal.com OR site:greynoise.io OR site:shodan.io)', "Public threat-intelligence/reputation pages.", 82)
        add("code", "IP in public repositories", f'{phrase} (site:github.com OR site:gitlab.com OR site:codeberg.org)', "Public code/configuration references.", 78)
        add("archives", "Historical IP references", f'{phrase} (archive OR historical OR "last seen" OR "first seen")', "Public historical references to the address.", 70)
    elif detected == "domain" and domainish:
        add("domain", "Indexed pages on domain", f'site:{domainish}', "Pages indexed under the target domain.", 100)
        add("domain", "Non-root / subdomain pages", f'site:{domainish} -site:www.{domainish}', "Indexed pages likely to expose non-www hosts/subdomains.", 92)
        add("domain", "Documents on domain", f'site:{domainish} (filetype:pdf OR filetype:docx OR filetype:xlsx OR filetype:pptx OR filetype:csv)', "Public indexed documents hosted by the domain.", 90)
        add("domain", "External domain mentions", f'"{domainish}" -site:{domainish}', "Third-party references outside the target domain.", 88)
        add("code", "Domain in public repositories", f'"{domainish}" (site:github.com OR site:gitlab.com OR site:codeberg.org)', "Public source-code references to the domain.", 84)
        add("domain", "Brand-domain association", f'"{domainish}" (official OR brand OR company OR organization OR "parent company" OR subsidiary OR acquisition)', "Public pages connecting the domain to an organization.", 80)
        add("security", "Domain certificate / DNS context", f'"{domainish}" (certificate OR TLS OR DNS OR nameserver OR CAA OR DNSSEC OR "certificate transparency")', "Public PKI/DNS references.", 84)
        add("security", "Domain security policy", f'site:{domainish} (security OR privacy OR abuse OR compliance OR "security.txt" OR disclosure)', "Public security/contact policy pages on the domain.", 82)
        add("archives", "Domain archive references", f'"{domainish}" (wayback OR archive OR snapshot OR historical)', "Public historical references to the domain.", 76)
        add("news", "Domain news references", f'"{domainish}" (news OR press OR breach OR outage OR acquisition OR launch)', "Public current-event references involving the domain.", 74)
        for idx, terms in enumerate(_osint_chunked(DOMAIN_INTEL_TERMS, 8)[:4], start=1):
            add("domain", f"Domain intelligence terms {idx}", f'"{domainish}" ({term_or(terms)})', "Domain, DNS, RDAP, certificate, and security metadata references.", 68)
    elif detected == "organization":
        add("documents", "Organization reports", f'{phrase} (report OR filing OR audit OR presentation OR annual) (filetype:pdf OR filetype:pptx)', "Public reports, filings, audits, and presentations.", 94)
        add("news", "Organization press references", f'{phrase} (press OR news OR announcement OR interview OR acquisition OR partnership)', "Public media and announcement references.", 92)
        add("domain", "Organization web properties", f'{phrase} (official OR website OR domain OR "about us" OR "contact us" OR careers)', "Likely official web-property references.", 88)
        add("security", "Organization security / policy pages", f'{phrase} (privacy OR terms OR security OR abuse OR compliance OR legal OR disclosure)', "Public policy and security-contact metadata.", 84)
        add("registries", "Organization corporate registries", f'{phrase} (site:opencorporates.com OR site:sec.gov OR site:find-and-update.company-information.service.gov.uk)', "Public corporate-registry references.", 88)
        add("registries", "Organization procurement / grants", f'{phrase} (procurement OR tender OR contract OR grant OR vendor OR supplier)', "Public procurement and grant references.", 76)
        add("social", "Organization social accounts", f'{phrase} (site:linkedin.com OR site:x.com OR site:youtube.com OR site:github.com)', "Public organization profiles.", 74)
        for idx, terms in enumerate(_osint_chunked(PUBLIC_RECORD_TERMS, 8)[:5], start=1):
            add("registries", f"Organization public-record terms {idx}", f'{phrase} ({term_or(terms)})', "Public registries, reports, filings, grants, tenders, and transparency references.", 66)
    else:
        add("news", "Keyword news context", f'{phrase} (news OR report OR analysis OR announcement)', "Public news/report references.", 76)
        add("documents", "Keyword document context", f'{phrase} (filetype:pdf OR filetype:docx OR filetype:pptx OR filetype:csv)', "Public documents and datasets.", 72)
        add("social", "Keyword community context", f'{phrase} (site:reddit.com OR site:github.com OR site:medium.com OR site:youtube.com)', "Public community/platform references.", 68)

    if scope_host:
        add("scoped", "Scoped exact mention", f'site:{scope_host} {phrase}', f"Restricts results to {scope_host}.", 100)
        add("scoped", "Scoped title mention", f'site:{scope_host} intitle:{phrase}', f"Title matches restricted to {scope_host}.", 92)
        add("scoped", "Scoped URL mention", f'site:{scope_host} inurl:{clean_target}', f"URL-path matches restricted to {scope_host}.", 88)
        add("scoped", "Scoped public documents", f'site:{scope_host} {phrase} (filetype:pdf OR filetype:docx OR filetype:xlsx OR filetype:pptx OR filetype:csv)', f"Public documents restricted to {scope_host}.", 86)
        add("scoped", "Scoped security/policy context", f'site:{scope_host} {phrase} (security OR privacy OR contact OR policy OR disclosure)', f"Public policy/security references restricted to {scope_host}.", 74)
        if variants:
            scoped_values = [str(item.get("value") or "") for item in variants[:18] if item.get("value")]
            if scoped_values:
                scoped_or = " OR ".join(f'"{value}"' for value in scoped_values)
                add("scoped", "Scoped handle variants", f'site:{scope_host} ({scoped_or})', f"Username variants and substitutions restricted to {scope_host}.", 72)

    # Sort the strongest queries first while retaining stable generation order within a priority.
    rows.sort(key=lambda row: (-int(row.get("priority") or 0), str(row.get("id") or "")))
    if selected_mode == "everything":
        cap = OSINT_DORK_RESULT_MAX
    elif selected_mode == "variants":
        cap = min(OSINT_DORK_RESULT_MAX, 108)
    elif selected_mode == "balanced":
        cap = min(OSINT_DORK_RESULT_MAX, 84)
    else:
        cap = min(OSINT_DORK_RESULT_MAX, 96)
    return rows[:cap]


def _osint_extract_urls(text: str, limit: int = 150) -> List[str]:
    seen = set()
    out: List[str] = []
    for m in re.findall(r"https?://[^\s<>'\"\]\)]+", text or ""):
        url = m.rstrip(".,;:")
        key = url.lower()
        if key not in seen:
            seen.add(key)
            out.append(url)
            if len(out) >= limit:
                break
    return out


def _osint_shorten(text: str, limit: int = OSINT_OUTPUT_MAX_CHARS) -> str:
    s = str(text or "")
    if len(s) <= limit:
        return s
    return s[:limit] + f"\n\n[truncated after {limit} characters]"


def _osint_collect_reports(run_dir: Path) -> List[Dict[str, Any]]:
    reports: List[Dict[str, Any]] = []
    allowed = {".txt", ".csv", ".json", ".ndjson", ".html", ".htm", ".log"}
    try:
        files = [p for p in run_dir.rglob("*") if p.is_file()]
    except Exception:
        return reports
    for p in sorted(files, key=lambda x: str(x).lower())[:40]:
        try:
            size = p.stat().st_size
            if p.suffix.lower() not in allowed or size > 2 * 1024 * 1024:
                continue
            snippet = p.read_text(encoding="utf-8", errors="replace")[:3000]
            reports.append({"name": p.name, "relative_path": str(p.relative_to(run_dir)), "size": size, "snippet": snippet})
        except Exception:
            continue
    return reports









