def _ff_safe_name(name: str) -> str:
    value = Path(str(name or "upload.bin")).name.replace("\x00", "")[:220]
    return value or "upload.bin"


def _ff_mask_value(value: str) -> str:
    value = str(value or "")
    if len(value) <= 8:
        return "*" * max(1, len(value))
    return value[:4] + "…" + value[-4:]


def _ff_magic(data: bytes) -> Dict[str, str]:
    if data.startswith(b"MZ"):
        return {"kind": "PE executable", "mime": "application/vnd.microsoft.portable-executable"}
    if data.startswith(b"\x7fELF"):
        return {"kind": "ELF executable", "mime": "application/x-elf"}
    if data.startswith(b"%PDF-"):
        return {"kind": "PDF document", "mime": "application/pdf"}
    if data.startswith(b"PK\x03\x04"):
        return {"kind": "ZIP / OOXML archive", "mime": "application/zip"}
    if data.startswith(b"\x1f\x8b"):
        return {"kind": "GZIP archive", "mime": "application/gzip"}
    if data.startswith(b"7z\xbc\xaf\x27\x1c"):
        return {"kind": "7-Zip archive", "mime": "application/x-7z-compressed"}
    if data.startswith(b"Rar!\x1a\x07"):
        return {"kind": "RAR archive", "mime": "application/vnd.rar"}
    if data.startswith(b"SQLite format 3\x00"):
        return {"kind": "SQLite database", "mime": "application/vnd.sqlite3"}
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        return {"kind": "PNG image", "mime": "image/png"}
    if data.startswith(b"\xff\xd8\xff"):
        return {"kind": "JPEG image", "mime": "image/jpeg"}
    if data.startswith(b"#!"):
        return {"kind": "Script / text executable", "mime": "text/plain"}
    sample = data[:4096]
    if sample:
        printable = sum(1 for b in sample if b in b"\t\r\n" or 32 <= b <= 126)
        if printable / len(sample) >= 0.86:
            return {"kind": "Text / script", "mime": "text/plain"}
    return {"kind": "Binary / unknown", "mime": "application/octet-stream"}


def _ff_pe_info(data: bytes) -> Dict[str, Any]:
    out: Dict[str, Any] = {"detected": False, "sections": [], "import_dlls": []}
    if len(data) < 0x40 or data[:2] != b"MZ":
        return out
    try:
        pe = struct.unpack_from("<I", data, 0x3C)[0]
        if pe < 0 or pe + 24 > len(data) or data[pe:pe+4] != b"PE\x00\x00":
            return out
        machine, section_count, timestamp, _ptr, _num, opt_size, characteristics = struct.unpack_from("<HHIIIHH", data, pe + 4)
        opt = pe + 24
        if opt + opt_size > len(data):
            opt_size = max(0, len(data) - opt)
        magic = struct.unpack_from("<H", data, opt)[0] if opt + 2 <= len(data) else 0
        is64 = magic == 0x20B
        entry = struct.unpack_from("<I", data, opt + 16)[0] if opt + 20 <= len(data) else 0
        image_base_off = opt + (24 if is64 else 28)
        image_base = 0
        if is64 and image_base_off + 8 <= len(data): image_base = struct.unpack_from("<Q", data, image_base_off)[0]
        elif not is64 and image_base_off + 4 <= len(data): image_base = struct.unpack_from("<I", data, image_base_off)[0]
        out.update({
            "detected": True,
            "machine": hex(machine),
            "section_count": int(section_count),
            "timestamp": int(timestamp),
            "characteristics": hex(characteristics),
            "pe_type": "PE32+" if is64 else ("PE32" if magic == 0x10B else hex(magic)),
            "entry_point_rva": hex(entry),
            "image_base": hex(image_base),
        })
        section_table = opt + opt_size
        sections = []
        for idx in range(min(int(section_count), 96)):
            off = section_table + idx * 40
            if off + 40 > len(data): break
            raw_name = data[off:off+8].split(b"\x00", 1)[0]
            name = raw_name.decode("ascii", "replace") or f"section_{idx}"
            virtual_size, virtual_address, raw_size, raw_ptr = struct.unpack_from("<IIII", data, off + 8)
            chars = struct.unpack_from("<I", data, off + 36)[0]
            chunk = data[raw_ptr:raw_ptr+min(raw_size, 512*1024)] if raw_ptr < len(data) else b""
            sec_entropy = 0.0
            if chunk:
                counts = [0] * 256
                for b in chunk: counts[b] += 1
                total = len(chunk)
                sec_entropy = -sum((c/total) * math.log2(c/total) for c in counts if c)
            sections.append({
                "name": name, "virtual_size": virtual_size, "virtual_address": hex(virtual_address),
                "raw_size": raw_size, "raw_offset": raw_ptr, "characteristics": hex(chars),
                "executable": bool(chars & 0x20000000), "writable": bool(chars & 0x80000000),
                "readable": bool(chars & 0x40000000), "entropy": round(sec_entropy, 4),
            })
        out["sections"] = sections

        def rva_to_offset(rva: int) -> Optional[int]:
            for s in sections:
                va = int(str(s["virtual_address"]), 16)
                span = max(int(s["virtual_size"]), int(s["raw_size"]))
                if va <= rva < va + max(span, 1):
                    off = int(s["raw_offset"]) + (rva - va)
                    return off if 0 <= off < len(data) else None
            return rva if 0 <= rva < len(data) else None

        dd_base = opt + (112 if is64 else 96)
        if dd_base + 16 <= opt + opt_size and dd_base + 16 <= len(data):
            import_rva, _import_size = struct.unpack_from("<II", data, dd_base + 8)
            import_off = rva_to_offset(import_rva) if import_rva else None
            dlls = []
            if import_off is not None:
                for i in range(128):
                    d = import_off + i * 20
                    if d + 20 > len(data): break
                    orig, tstamp, fwd, name_rva, thunk = struct.unpack_from("<IIIII", data, d)
                    if not any((orig, tstamp, fwd, name_rva, thunk)): break
                    noff = rva_to_offset(name_rva)
                    if noff is None: continue
                    raw = data[noff:noff+260].split(b"\x00", 1)[0]
                    name = raw.decode("ascii", "replace").strip()
                    if name and name not in dlls: dlls.append(name[:180])
            out["import_dlls"] = dlls[:128]
    except Exception as exc:
        out["error"] = f"{type(exc).__name__}: {exc}"[:500]
    return out


def _ff_elf_info(data: bytes) -> Dict[str, Any]:
    out: Dict[str, Any] = {"detected": False}
    if len(data) < 20 or not data.startswith(b"\x7fELF"):
        return out
    try:
        cls = data[4]
        endian = data[5]
        order = "<" if endian == 1 else ">"
        machine = struct.unpack_from(order + "H", data, 18)[0]
        out.update({"detected": True, "class": "ELF64" if cls == 2 else "ELF32" if cls == 1 else str(cls), "endianness": "little" if endian == 1 else "big", "machine": int(machine)})
    except Exception as exc:
        out["error"] = f"{type(exc).__name__}: {exc}"[:500]
    return out


def _ff_archive_triage(data: bytes, filename: str) -> Dict[str, Any]:
    report: Dict[str, Any] = {"is_archive": False, "members": [], "suspicious_members": [], "office_macros": False, "external_relationships": []}
    try:
        bio = BytesIO(data)
        if not zipfile.is_zipfile(bio):
            return report
        report["is_archive"] = True
        bio.seek(0)
        with zipfile.ZipFile(bio) as zf:
            _c8_check_zip(zf)
            infos = zf.infolist()
            report["member_count"] = len(infos)
            total_u = 0
            total_c = 0
            for info in infos[:600]:
                total_u += int(info.file_size or 0); total_c += int(info.compress_size or 0)
                ratio = (float(info.file_size) / max(1.0, float(info.compress_size))) if info.file_size else 0.0
                row = {"name": info.filename[:400], "size": int(info.file_size), "compressed": int(info.compress_size), "ratio": round(ratio, 2)}
                report["members"].append(row)
                lower = info.filename.lower()
                if lower.endswith((".exe", ".dll", ".scr", ".cpl", ".ps1", ".vbs", ".js", ".jse", ".hta", ".lnk", ".iso", ".img")):
                    report["suspicious_members"].append(row)
                if "vbaproject.bin" in lower or lower.endswith("/vba.bin"):
                    report["office_macros"] = True
                if ratio > 250 and info.file_size > 5 * 1024 * 1024:
                    report.setdefault("high_compression_members", []).append(row)
                if lower.endswith(".rels") and info.file_size <= 1024 * 1024:
                    try:
                        rel = _c8_zip_read(zf, info)[:1024*1024].decode("utf-8", "replace")
                        for m in re.finditer(r'(?i)TargetMode=["\']External["\'][^>]*Target=["\']([^"\']+)', rel):
                            target = m.group(1)[:500]
                            if target not in report["external_relationships"]:
                                report["external_relationships"].append(target)
                    except Exception:
                        pass
            report["listed_uncompressed_bytes"] = total_u
            report["listed_compressed_bytes"] = total_c
            report["overall_ratio"] = round(total_u / max(1, total_c), 2)
    except Exception as exc:
        report["error"] = f"{type(exc).__name__}: {exc}"[:500]
    return report


_FF_YARA_PACKAGE = "yara-python==4.5.4"
_FF_YARA_DEPENDENCY_DIR = Path(
    os.environ.get("LL_WEB_YARA_DEPENDENCY_DIR", "").strip()
    or (Path.home() / ".c8-console" / "runtime" / "file-forensics" /
        (str(sys.implementation.cache_tag or "python") + getattr(sys, "abiflags", "") +
         "-" + sys.platform + "-" + platform.machine()))
)
_FF_YARA_LOCK = threading.Lock()
_FF_YARA_MODULE = None
_FF_YARA_RULES = None
_FF_YARA_INSTALL_ATTEMPTED = False
_FF_YARA_IMPORT_ERROR = ""
_FF_YARA_INSTALL_ERROR = ""


def _ff_import_yara() -> Any:
    """Load and exercise the native binding before marking the engine ready."""
    import importlib
    global _FF_YARA_MODULE, _FF_YARA_RULES, _FF_YARA_IMPORT_ERROR
    if _FF_YARA_DEPENDENCY_DIR.is_dir():
        dependency_path = str(_FF_YARA_DEPENDENCY_DIR.resolve())
        if dependency_path not in sys.path:
            sys.path.insert(0, dependency_path)
    importlib.invalidate_caches()
    module = importlib.import_module("yara")
    if not callable(getattr(module, "compile", None)) or not hasattr(module, "Rules"):
        raise ImportError("The imported yara module is not the yara-python native binding.")
    rules = module.compile(source=_FF_BUILTIN_YARA, includes=False)
    rules.match(data=b"", timeout=1)
    _FF_YARA_MODULE, _FF_YARA_RULES = module, rules
    _FF_YARA_IMPORT_ERROR = ""
    return module


def _ff_run_yara_pip(command: List[str], timeout: int, pythonpath: str = "") -> Tuple[int, str]:
    # Keep build output off the console and out of unbounded in-memory buffers.
    env = {**os.environ, "PYTHONIOENCODING": "utf-8", "MAKEFLAGS": "-j1"}
    if pythonpath:
        env["PYTHONPATH"] = pythonpath
    with tempfile.TemporaryFile() as output:
        result = subprocess.run(
            command, stdin=subprocess.DEVNULL, stdout=output, stderr=subprocess.STDOUT,
            timeout=timeout, check=False, env=env,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        output.seek(max(0, output.tell() - 6000))
        return result.returncode, output.read().decode("utf-8", "replace").strip()


def _ff_try_ubuntu_yara() -> Tuple[Any, str]:
    """Use Ubuntu's compiled binding when apt targets this exact Python version."""
    if sys.platform != "linux" or getattr(os, "geteuid", lambda: 1)() != 0:
        return None, ""
    apt = shutil.which("apt-get")
    distro_python = Path("/usr/bin/python3")
    if not apt or not distro_python.is_file():
        return None, ""
    try:
        release = Path("/etc/os-release").read_text(encoding="utf-8")
        if not re.search(r"(?m)^ID=['\"]?ubuntu['\"]?\s*$", release):
            return None, ""
        version_check = subprocess.run(
            [str(distro_python), "-c", "import sys; print(f'{sys.version_info.major}.{sys.version_info.minor}')"],
            capture_output=True, text=True, timeout=6, check=False,
        )
        expected_version = f"{sys.version_info.major}.{sys.version_info.minor}"
        if version_check.returncode or version_check.stdout.strip() != expected_version:
            return None, ""
        print("C-8 File Forensics: trying Ubuntu's prebuilt python3-yara package...", flush=True)
        env = {**os.environ, "DEBIAN_FRONTEND": "noninteractive"}

        def run_apt(args: List[str], timeout: int) -> Tuple[int, str]:
            with tempfile.TemporaryFile() as output:
                result = subprocess.run(
                    [apt, *args], stdin=subprocess.DEVNULL, stdout=output,
                    stderr=subprocess.STDOUT, timeout=timeout, check=False, env=env,
                )
                output.seek(max(0, output.tell() - 1200))
                return result.returncode, output.read().decode("utf-8", "replace").strip()

        install_args = ["install", "-y", "--no-install-recommends", "python3-yara"]
        code, output = run_apt(install_args, 180)
        if code and "unable to locate package" in output.lower():
            update_code, update_output = run_apt(["update", "-qq"], 180)
            if update_code:
                return None, f"Ubuntu package index update failed: {update_output[-500:]}"
            code, output = run_apt(install_args, 180)
        if code:
            return None, f"Ubuntu python3-yara installation failed: {output[-650:]}"
        sys.modules.pop("yara", None)
        try:
            return _ff_import_yara(), ""
        except Exception as exc:
            return None, f"Ubuntu installed python3-yara, but this Python cannot load it: {exc}"
    except (OSError, subprocess.TimeoutExpired, UnicodeError) as exc:
        return None, f"Ubuntu python3-yara setup failed: {exc}"


def _ff_ensure_yara() -> Any:
    """Install once on first use, into a folder for this Python ABI only.

    --target avoids system-Python/PEP 668 changes. Prefer a wheel; if no wheel
    exists (for example on a newer Python), allow pip's normal source build.
    No uploaded content, rule source, or request field enters the command.
    """
    import importlib.util
    global _FF_YARA_INSTALL_ATTEMPTED, _FF_YARA_IMPORT_ERROR, _FF_YARA_INSTALL_ERROR
    if _FF_YARA_MODULE is not None:
        return _FF_YARA_MODULE
    with _FF_YARA_LOCK:
        if _FF_YARA_MODULE is not None:
            return _FF_YARA_MODULE
        try:
            return _ff_import_yara()
        except Exception as exc:
            _FF_YARA_IMPORT_ERROR = f"{type(exc).__name__}: {exc}"[:800]
        auto_install = os.environ.get("LL_WEB_YARA_AUTO_INSTALL", "1").strip().lower() not in {"0", "false", "no", "off", "disabled"}
        if not auto_install:
            _FF_YARA_INSTALL_ERROR = "Automatic YARA setup is disabled by LL_WEB_YARA_AUTO_INSTALL."
            return None
        if _FF_YARA_INSTALL_ATTEMPTED:
            return None
        _FF_YARA_INSTALL_ATTEMPTED = True
        try:
            _FF_YARA_DEPENDENCY_DIR.mkdir(mode=0o700, parents=True, exist_ok=True)
            distro_error = ""
            if sys.version_info >= (3, 14):
                distro_module, distro_error = _ff_try_ubuntu_yara()
                if distro_module is not None:
                    _FF_YARA_INSTALL_ERROR = ""
                    print("C-8 File Forensics: YARA is ready from Ubuntu's package.", flush=True)
                    return distro_module
            pip_command = [sys.executable, "-m", "pip"]
            bundled_pip = ""
            if importlib.util.find_spec("pip") is None:
                external_pip = shutil.which("pip3") or shutil.which("pip")
                if external_pip:
                    pip_command = [external_pip, "--python", sys.executable]
                else:
                    # Run the ensurepip wheel using this interpreter without
                    # modifying the system's externally managed Python.
                    try:
                        import ensurepip
                        wheels = sorted((Path(ensurepip.__file__).parent / "_bundled").glob("pip-*.whl"))
                    except ImportError:
                        wheels = []
                    if not wheels:
                        raise RuntimeError(
                            "pip is missing for this Python. Install its pip/venv package, then restart the server. "
                            + distro_error
                        )
                    bundled_pip = str(wheels[-1])
            command = pip_command + [
                "--isolated", "install", "--disable-pip-version-check", "--no-input",
                "--no-deps", "--no-compile", "--upgrade", "--timeout", "15", "--retries", "1",
                "--index-url", "https://pypi.org/simple", "--target", str(_FF_YARA_DEPENDENCY_DIR),
            ]
            print("C-8 File Forensics: preparing yara-python for this Python runtime...", flush=True)
            code, output = _ff_run_yara_pip(command + ["--only-binary=:all:", _FF_YARA_PACKAGE], 120, bundled_pip)
            if code and any(message in output.lower() for message in ("no matching distribution", "could not find a version")):
                print("C-8 File Forensics: no compatible YARA wheel; trying a source build...", flush=True)
                code, output = _ff_run_yara_pip(command + [_FF_YARA_PACKAGE], 240, bundled_pip)
            if code:
                raise RuntimeError((distro_error + " | " if distro_error else "") + (output[-2000:] or f"YARA installation exited with status {code}."))
            # A different package named 'yara' may already have been imported.
            sys.modules.pop("yara", None)
            module = _ff_import_yara()
            _FF_YARA_INSTALL_ERROR = ""
            print("C-8 File Forensics: YARA is ready.", flush=True)
            return module
        except subprocess.TimeoutExpired:
            _FF_YARA_INSTALL_ERROR = "YARA setup timed out. Check package-index access and build tools, then restart the server to retry."
        except Exception as exc:
            _FF_YARA_INSTALL_ERROR = f"{type(exc).__name__}: {exc}"[:2400]
        if _FF_YARA_INSTALL_ERROR:
            print(f"C-8 File Forensics: YARA setup failed: {_FF_YARA_INSTALL_ERROR[:700]}", file=sys.stderr, flush=True)
        return None


def _ff_yara_scan(data: bytes, custom_source: str = "") -> Dict[str, Any]:
    custom_source = str(custom_source or "")
    report: Dict[str, Any] = {
        "engine": "unavailable", "available": False, "scan_complete": False,
        "builtin_status": "not_run", "custom_status": "not_run" if custom_source.strip() else "not_requested",
        "builtin_matches": [], "custom_matches": [], "custom_rule_error": "",
    }
    yara = _ff_ensure_yara()
    if yara is None:
        import shlex
        command = [sys.executable, "-m", "pip", "install", "--upgrade", "--target", str(_FF_YARA_DEPENDENCY_DIR), _FF_YARA_PACKAGE]
        report.update({
            "reason": "YARA did not run because its Python binding could not be loaded. Independent built-in static signatures still ran.",
            "import_error": _FF_YARA_IMPORT_ERROR, "install_error": _FF_YARA_INSTALL_ERROR,
            "install_attempted": _FF_YARA_INSTALL_ATTEMPTED,
            "install_command": subprocess.list2cmdline(command) if os.name == "nt" else shlex.join(command),
            "setup_hint": "Run the install command on the server with the same Python, then restart. A source build needs a C compiler and that Python's development headers.",
        })
        if custom_source.strip():
            report["custom_rule_error"] = "Custom rules were not scanned because YARA is unavailable."
        return report
    report.update({"engine": "yara-python", "available": True, "version": str(getattr(yara, "__version__", "unknown"))})
    try:
        report["builtin_matches"] = [str(m) for m in _FF_YARA_RULES.match(data=data, timeout=5)][:100]
        report["builtin_status"] = "complete"
    except Exception as exc:
        report["builtin_status"] = "error"
        report["builtin_error"] = f"{type(exc).__name__}: {exc}"[:800]
    if custom_source.strip():
        try:
            if len(custom_source) > FILE_FORENSICS_MAX_YARA_CHARS:
                raise ValueError("Custom YARA source exceeds the 65,536-character limit.")
            # Uploaded rules must not read include files from the server.
            custom = yara.compile(source=custom_source, includes=False)
            report["custom_matches"] = [str(m) for m in custom.match(data=data, timeout=5)][:100]
            report["custom_status"] = "complete"
        except Exception as exc:
            report["custom_status"] = "error"
            report["custom_rule_error"] = f"{type(exc).__name__}: {exc}"[:1200]
    report["scan_complete"] = report["builtin_status"] == "complete" and report["custom_status"] in {"complete", "not_requested"}
    return report


def _ff_builtin_signatures(data: bytes, text: str) -> List[Dict[str, Any]]:
    matches: List[Dict[str, Any]] = []
    lower = text.lower()
    groups = [
        ("Process injection API cluster", ["virtualallocex", "writeprocessmemory", "createremotethread", "ntcreatethreadex"], 2, "HIGH"),
        ("Credential access API cluster", ["minidumpwritedump", "cryptunprotectdata", "credenumerate", "lsass.exe"], 2, "HIGH"),
        ("Downloader / encoded script cluster", ["downloadstring", "invoke-webrequest", "frombase64string", "powershell", "-enc"], 3, "HIGH"),
        ("Windows LOLBin cluster", ["mshta", "regsvr32", "rundll32", "certutil", "bitsadmin"], 2, "MEDIUM"),
    ]
    for name, needles, threshold, severity in groups:
        hits = [n for n in needles if n in lower]
        if len(hits) >= threshold:
            matches.append({"name": name, "severity": severity, "matched_indicators": hits})
    if data.startswith(b"%PDF-"):
        pdf_hits = [x for x in ("/javascript", "/openaction", "/launch", "/embeddedfile", "/richmedia") if x in lower]
        if pdf_hits:
            matches.append({"name": "PDF active-content indicators", "severity": "MEDIUM", "matched_indicators": pdf_hits})
    return matches


def file_forensics_scan(payload: Dict[str, Any]) -> Dict[str, Any]:
    filename = _ff_safe_name(payload.get("filename") or "upload.bin")
    raw_b64 = str(payload.get("data_b64") or "")
    if not raw_b64:
        raise ValueError("Select a file to analyze.")
    try:
        data = base64.b64decode(raw_b64, validate=True)
    except Exception as exc:
        raise ValueError(f"Invalid uploaded file encoding: {exc}")
    if not data:
        raise ValueError("The uploaded file is empty.")
    if len(data) > FILE_FORENSICS_MAX_BYTES:
        raise ValueError(f"File Forensics is limited to {FILE_FORENSICS_MAX_BYTES // (1024*1024)} MiB on this server.")

    findings: List[Dict[str, Any]] = []
    seen = set()
    counts = {"CRITICAL":0, "HIGH":0, "MEDIUM":0, "LOW":0, "INFO":0}
    weights = {"CRITICAL":25, "HIGH":12, "MEDIUM":6, "LOW":2, "INFO":0}
    def add(sev: str, category: str, title: str, evidence: str, impact: str, fix: str):
        sev = str(sev or "INFO").upper()
        if sev not in counts: sev = "INFO"
        fp = (sev, category, title, str(evidence))
        if fp in seen: return
        seen.add(fp); counts[sev] += 1
        findings.append({"severity":sev, "category":category, "title":title, "evidence":str(evidence)[:1800], "impact":impact, "recommendation":fix})

    hashes = {
        "md5": hashlib.md5(data).hexdigest(),
        "sha1": hashlib.sha1(data).hexdigest(),
        "sha256": hashlib.sha256(data).hexdigest(),
        "sha512": hashlib.sha512(data).hexdigest(),
    }
    magic = _ff_magic(data)
    entropy = _entropy_for_bytes(data, max_bytes=min(len(data), 2 * 1024 * 1024))
    pe = _ff_pe_info(data)
    elf = _ff_elf_info(data)
    archive = _ff_archive_triage(data, filename)
    pattern_report = _extract_strings_and_patterns(data, max_scan=min(len(data), 3 * 1024 * 1024), max_items=100)
    # Search a larger text projection than the display sample, without returning raw binary content.
    ascii_parts = []
    for m in re.finditer(rb"[\x20-\x7e]{5,}", data[:4*1024*1024]):
        try: ascii_parts.append(m.group(0).decode("latin1", "ignore")[:500])
        except Exception: pass
        if len(ascii_parts) >= 5000: break
    text_projection = "\n".join(ascii_parts)

    suffix = Path(filename).suffix.lower()
    lower_name = filename.lower()
    if re.search(r"(?i)\.(pdf|docx?|xlsx?|pptx?|jpg|png|txt)\.(exe|scr|com|bat|cmd|js|vbs|ps1)$", lower_name):
        add("HIGH", "File Identity", "Double-extension executable/script filename", filename, "Double extensions can disguise executable content as a document or image.", "Rename and verify the file source; do not execute it until independently validated.")
    if any(ch in filename for ch in ("\u202e", "\u202d", "\u2066", "\u2067", "\u2068", "\u2069")):
        add("HIGH", "File Identity", "Bidirectional Unicode control character in filename", repr(filename), "BiDi controls can visually disguise the real extension or filename.", "Remove the control characters and verify the actual extension before opening the file.")
    if pe.get("detected") and suffix not in {".exe", ".dll", ".sys", ".scr", ".cpl", ".com", ".ocx", ".mui"}:
        add("HIGH", "File Identity", "PE executable content does not match filename extension", f"Detected PE content in {filename}", "Executable content with a non-executable extension can bypass casual inspection.", "Treat the file as executable and verify its origin/signature before use.")
    if data.startswith(b"%PDF-") and suffix and suffix != ".pdf":
        add("MEDIUM", "File Identity", "PDF signature does not match filename extension", filename, "Extension/signature mismatches can indicate renaming or delivery tricks.", "Verify the file source and normalize the extension before handling.")

    if float(entropy.get("entropy") or 0) >= 7.35 and (pe.get("detected") or elf.get("detected")):
        add("MEDIUM", "Packing / Obfuscation", "Executable has high entropy", f"Entropy {entropy.get('entropy')}", "High entropy can indicate compression, encryption, or packing; legitimate software can also trigger this.", "Inspect section entropy, code signing, provenance, and sandbox results before reaching a conclusion.")

    if pe.get("detected"):
        for sec in pe.get("sections") or []:
            if sec.get("executable") and sec.get("writable"):
                add("HIGH", "PE Structure", "Writable + executable PE section", f"{sec.get('name')} characteristics={sec.get('characteristics')}", "RWX sections weaken memory protections and can be associated with packers or self-modifying code.", "Validate the binary provenance and inspect the section contents in a dedicated reverse-engineering environment.")
            if str(sec.get("name") or "").lower() in {"upx0","upx1","upx2",".aspack",".petite",".mpress"}:
                add("MEDIUM", "PE Structure", "Known packer-like section name", str(sec.get("name")), "Packing can make static inspection harder; it is not by itself proof of maliciousness.", "Confirm whether packing is expected for this software and perform controlled deeper analysis if needed.")
        api_hits = [api for api in _FF_SUSPICIOUS_APIS if api.lower() in text_projection.lower()]
        if len(api_hits) >= 2:
            add("HIGH", "PE Behavior Indicators", "Multiple sensitive Windows APIs referenced", ", ".join(api_hits[:16]), "The API combination can support injection, credential access, persistence, or downloading behavior.", "Review call sites/imports and validate the binary in an isolated analysis environment before execution.")

    if archive.get("office_macros"):
        add("HIGH", "Office / Archive", "Office macro project detected", "vbaProject.bin or equivalent macro content is present.", "Macros can execute code when permitted by Office security settings.", "Only enable macros from trusted, validated sources; inspect the macro project separately.")
    if archive.get("external_relationships"):
        add("MEDIUM", "Office / Archive", "Office document contains external relationships", ", ".join((archive.get("external_relationships") or [])[:10]), "External relationships can cause remote content retrieval or tracking when a document is opened.", "Review and remove unnecessary external relationships before distributing the document.")
    if archive.get("suspicious_members"):
        add("HIGH", "Archive", "Archive contains executable/script-like members", ", ".join(x.get("name","") for x in archive.get("suspicious_members",[])[:15]), "Executable content inside an archive can be used to disguise delivery payloads.", "Extract only in an isolated environment and verify each member before execution.")
    if archive.get("high_compression_members"):
        add("MEDIUM", "Archive", "Very high compression-ratio member detected", ", ".join(x.get("name","") for x in archive.get("high_compression_members",[])[:8]), "Extreme compression ratios can indicate resource-exhaustion archive content.", "Apply extraction quotas and inspect the archive in a constrained environment.")

    if data.startswith(b"%PDF-"):
        low = text_projection.lower()
        for token, title, sev in (("/javascript","PDF contains JavaScript indicator","MEDIUM"),("/openaction","PDF contains automatic OpenAction","HIGH"),("/launch","PDF contains Launch action","HIGH"),("/embeddedfile","PDF contains embedded-file indicator","MEDIUM")):
            if token in low:
                add(sev, "PDF", title, token, "Active or embedded PDF features can expand document attack surface.", "Inspect the object/action structure with a dedicated PDF analyzer before trusting the document.")

    ext_is_script = suffix in {".ps1", ".psm1", ".bat", ".cmd", ".vbs", ".vbe", ".js", ".jse", ".hta", ".sh", ".bash", ".py", ".pl", ".rb"} or magic.get("kind") == "Script / text executable"
    if ext_is_script or magic.get("kind") == "Text / script":
        for sev, title, rx in _FF_SCRIPT_PATTERNS:
            m = re.search(rx, text_projection)
            if m:
                evidence = re.sub(r"\s+", " ", m.group(0))[:500]
                add(sev, "Script Behavior", title, evidence, "This command pattern can download, decode, execute, persist, or proxy code; legitimate administration scripts can also contain it.", "Review the surrounding script logic and provenance before running it.")

    builtins = _ff_builtin_signatures(data, text_projection)
    for hit in builtins:
        add(hit.get("severity","MEDIUM"), "Built-in Detection", hit.get("name","Static signature match"), ", ".join(hit.get("matched_indicators") or []), "A cluster of static indicators matched a defensive rule; this is triage evidence, not a malware verdict.", "Correlate with provenance, code signatures, reverse engineering, and controlled sandbox results.")

    yara_report = _ff_yara_scan(data, str(payload.get("custom_yara") or ""))
    for rule in (yara_report.get("builtin_matches") or []):
        add("MEDIUM", "YARA", f"Built-in YARA match: {rule}", rule, "The file matched a static YARA rule.", "Review the rule logic and file context before deciding whether the match represents malicious content.")
    for rule in (yara_report.get("custom_matches") or []):
        add("MEDIUM", "YARA", f"Custom YARA match: {rule}", rule, "The file matched a user-supplied YARA rule.", "Review the custom rule and matched file in context.")

    score = min(100, sum(weights.get(f["severity"], 0) for f in findings))
    level = "critical" if score >= 75 else "high" if score >= 45 else "moderate" if score >= 20 else "low"
    report = {
        "ok": True, "tool": "File Forensics", "mode": "static-only",
        "summary": {"filename":filename, "size_bytes":len(data), "detected_kind":magic.get("kind"), "risk_score":score, "risk_level":level, "findings":len(findings), "counts":counts, "yara_matches":len(yara_report.get("builtin_matches") or []) + len(yara_report.get("custom_matches") or [])},
        "identity": {"filename":filename, "extension":suffix, "detected":magic, "guessed_mime":mimetypes.guess_type(filename)[0] or ""},
        "hashes": hashes, "entropy": entropy, "pe": pe, "elf": elf, "archive": archive,
        "indicators": {"patterns": (pattern_report.get("patterns") or {}), "sample_strings": (pattern_report.get("sample_strings") or [])[:60]},
        "yara": yara_report, "builtin_signatures": builtins, "findings": findings,
        "scope": "Static file triage only. The uploaded file is decoded in memory for hashing/signature/structure analysis and is never executed, imported as code, or launched.",
    }
    audit("file_forensics", "static_scan", {"filename":filename, "size":len(data), "sha256":hashes["sha256"], "findings":len(findings), "risk_score":score, "yara_matches":report["summary"]["yara_matches"]})
    return report


def _sf_cfg_finding(severity: str, category: str, title: str, source: str, evidence: str, impact: str, recommendation: str) -> Dict[str, Any]:
    return {"severity":severity, "category":category, "title":title, "url":source, "evidence":str(evidence)[:1600], "impact":impact, "recommendation":recommendation}


def _sf_mask_config_secret(value: str) -> str:
    value = str(value or "").strip().strip('"\'')
    return _ff_mask_value(value) if value else "<present>"


def site_cloud_security_analyze(text: str, filename: str = "cloud-config") -> Dict[str, Any]:
    text = str(text or "")[:SITE_CONFIG_MAX_CHARS]
    filename = _ff_safe_name(filename or "cloud-config")
    source = f"uploaded:{filename}"
    findings: List[Dict[str, Any]] = []
    seen = set()
    providers = set()
    def add(sev, cat, title, evidence, impact, fix):
        fp=(sev,cat,title,str(evidence))
        if fp in seen:return
        seen.add(fp); findings.append(_sf_cfg_finding(sev,cat,title,source,evidence,impact,fix))
    lower=text.lower()
    if any(k in lower for k in ("arn:aws:", "aws_", "s3", "iam", "ec2", "cloudformation")): providers.add("AWS")
    if any(k in lower for k in ("microsoft.compute", "microsoft.storage", "azure", "tenantid", "subscriptionid", "azurerm_")): providers.add("Azure")
    if any(k in lower for k in ("google_project", "google_compute", "gcp", "allusers", "service_account")): providers.add("GCP")
    if "terraform" in lower or re.search(r"(?m)^\s*resource\s+\"", text): providers.add("Terraform/IaC")

    # Secret-like values are only reported in masked form.
    secret_patterns = (
        ("AWS access key identifier", r"\b(AKIA|ASIA)[0-9A-Z]{16}\b"),
        ("Private key material", r"-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----"),
        ("Cloud credential assignment", r"(?im)^\s*[\"']?(?:aws_secret_access_key|secret_access_key|client_secret|clientsecret|password|api[_-]?key|token)[\"']?\s*[:=]\s*[\"']?([^\s\"'#,}]{8,})"),
    )
    for label, rx in secret_patterns:
        for m in re.finditer(rx, text):
            raw = m.group(1) if m.lastindex else m.group(0)
            add("CRITICAL" if "Private key" in label else "HIGH", "Cloud / Secrets", f"Credential-like material present: {label}", f"Masked value: {_sf_mask_config_secret(raw)}", "Secrets stored in infrastructure/configuration files can be copied through source control, backups, logs, or artifacts.", "Remove plaintext credentials, rotate/revoke exposed values, and use the cloud provider's secret-management/identity features.")

    if re.search(r'(?is)["\']Principal["\']\s*:\s*(?:["\']\*["\']|\{[^}]*["\']AWS["\']\s*:\s*["\']\*["\'])', text):
        add("HIGH", "Cloud / IAM", "Policy contains wildcard public Principal", 'Principal: "*"', "A public principal can grant access to anyone if the statement conditions do not sufficiently restrict it.", "Scope principals to the required accounts/services and verify restrictive conditions.")
    if re.search(r'(?is)["\']Action["\']\s*:\s*(?:["\']\*["\']|\[[^\]]*["\']\*["\'])', text):
        add("HIGH", "Cloud / IAM", "Policy grants wildcard Action", 'Action includes "*"', "Wildcard actions can grant far more permissions than the workload needs.", "Replace wildcard actions with the minimum API operations required.")
    if re.search(r'(?is)["\']Resource["\']\s*:\s*(?:["\']\*["\']|\[[^\]]*["\']\*["\'])', text):
        add("MEDIUM", "Cloud / IAM", "Policy uses wildcard Resource", 'Resource includes "*"', "Broad resource scope increases blast radius when permissions are abused or misconfigured.", "Restrict resources to the specific ARNs/IDs the workload requires.")
    if re.search(r'(?i)\b(allUsers|allAuthenticatedUsers)\b', text):
        add("HIGH", "Cloud / IAM", "GCP-style public IAM member detected", "allUsers/allAuthenticatedUsers", "Public IAM bindings can expose cloud resources broadly.", "Remove public members unless intentionally required and use narrower identities or authenticated frontends.")

    # Internet-exposed network rules, with stronger severity on common administration/data ports.
    if re.search(r"(?i)(0\.0\.0\.0/0|::/0)", text):
        ports = set(int(x) for x in re.findall(r"(?i)[\"']?(?:from_port|to_port|port|destinationPortRange|destination_port_range)[\"']?\s*[:=]\s*[\"']?(\d{1,5})", text) if int(x) <= 65535)
        sensitive = sorted(ports & {22,23,2375,2376,3306,5432,6379,9200,9300,27017,3389,5900})
        add("HIGH" if sensitive else "MEDIUM", "Cloud / Network", "Internet-wide network rule detected", f"CIDR 0.0.0.0/0 or ::/0" + (f"; sensitive ports: {sensitive}" if sensitive else ""), "Internet-wide ingress increases exposed attack surface.", "Restrict source CIDRs, place administration/data services behind private networking/VPN/bastions, and expose only required application ports.")

    public_checks = (
        ("HIGH", "Publicly accessible cloud resource enabled", r"(?i)[\"']?(publicly_accessible|publiclyAccessible)[\"']?\s*[:=]\s*true\b"),
        ("HIGH", "Public network access enabled", r"(?i)[\"']?publicNetworkAccess[\"']?\s*[:=]\s*[\"']?Enabled\b"),
        ("HIGH", "Blob/container public access allowed", r"(?i)[\"']?allowBlobPublicAccess[\"']?\s*[:=]\s*true\b"),
        ("HIGH", "S3 public-access blocking disabled", r"(?i)[\"']?(block_public_acls|block_public_policy|ignore_public_acls|restrict_public_buckets)[\"']?\s*[:=]\s*false\b"),
        ("MEDIUM", "HTTPS-only protection disabled", r"(?i)[\"']?httpsOnly[\"']?\s*[:=]\s*false\b"),
    )
    for sev,title,rx in public_checks:
        if re.search(rx,text):
            add(sev,"Cloud / Exposure",title,re.search(rx,text).group(0)[:400],"The configuration can make a cloud service reachable or usable more broadly than intended.","Confirm whether public access is required; otherwise disable it and use private endpoints/network controls.")
    if re.search(r"(?i)[\"']?(minimumTlsVersion|min_tls_version|ssl_min_protocol_version)[\"']?\s*[:=]\s*[\"']?(TLS)?1\.[01]\b", text):
        add("MEDIUM","Cloud / Transport","Legacy minimum TLS version configured","TLS 1.0/1.1 style minimum found","Legacy TLS versions have weaker security properties and compatibility with modern security baselines.","Set the service minimum to TLS 1.2 or newer when supported.")

    score = min(100, sum({"CRITICAL":25,"HIGH":12,"MEDIUM":6,"LOW":2,"INFO":0}.get(f["severity"],0) for f in findings))
    return {"enabled":True,"filename":filename,"providers":sorted(providers),"findings":findings,"finding_count":len(findings),"risk_score":score,"note":"Static configuration/IaC review only; no cloud credentials are used and no cloud API changes are made."}


def site_container_security_analyze(text: str, filename: str = "container-config") -> Dict[str, Any]:
    text = str(text or "")[:SITE_CONFIG_MAX_CHARS]
    filename = _ff_safe_name(filename or "container-config")
    source = f"uploaded:{filename}"
    lower = text.lower()
    findings: List[Dict[str, Any]] = []
    seen = set()
    def add(sev, cat, title, evidence, impact, fix):
        fp=(sev,cat,title,str(evidence))
        if fp in seen:return
        seen.add(fp); findings.append(_sf_cfg_finding(sev,cat,title,source,evidence,impact,fix))
    kind = "Dockerfile" if re.search(r"(?mi)^\s*FROM\s+", text) else ("Kubernetes" if re.search(r"(?mi)^\s*kind\s*:\s*(Deployment|Pod|DaemonSet|StatefulSet|Job|CronJob)\b", text) else ("Compose/YAML" if re.search(r"(?mi)^\s*(services|version)\s*:", text) else "Container configuration"))

    if kind == "Dockerfile":
        from_rows = re.findall(r"(?mi)^\s*FROM\s+([^\s]+)", text)
        for image in from_rows:
            base = image.split("@",1)[0]
            tag = base.rsplit(":",1)[1] if ":" in base.rsplit("/",1)[-1] else ""
            if not tag or tag.lower() == "latest":
                add("MEDIUM","Container / Supply Chain","Unpinned or latest base image",image,"Mutable image tags can change underneath a build and make provenance/reproducibility weaker.","Pin a vetted image version, preferably by immutable digest for production builds.")
        users = re.findall(r"(?mi)^\s*USER\s+([^\r\n#]+)", text)
        if not users:
            add("MEDIUM","Container / Privilege","Dockerfile does not declare a non-root USER","No USER instruction found.","Containers commonly run as root by default, increasing impact if the process is compromised.","Create a dedicated unprivileged user and switch to it before the final runtime command.")
        elif str(users[-1]).strip().lower() in {"root","0","0:0"}:
            add("HIGH","Container / Privilege","Container explicitly runs as root",users[-1].strip(),"Root inside the container can increase impact, especially with host mounts/capabilities.","Run the application as a dedicated non-root UID/GID unless root is strictly required.")
        if not re.search(r"(?mi)^\s*HEALTHCHECK\b", text):
            add("LOW","Container / Reliability","No Docker HEALTHCHECK declared","No HEALTHCHECK instruction found.","Health signals help orchestrators detect failed or wedged processes.","Add a lightweight health check appropriate for the service, or define health checks in the orchestrator.")
        for m in re.finditer(r"(?mi)^\s*(ENV|ARG)\s+([^\r\n]+)", text):
            line=m.group(2)
            if re.search(r"(?i)(password|passwd|secret|token|api[_-]?key|private[_-]?key|client[_-]?secret)\s*[= ]\s*\S+", line):
                add("HIGH","Container / Secrets","Secret-like value embedded in Docker build configuration",re.sub(r"(?i)(=|\s)([^\s]{5,})",lambda x:x.group(1)+"<masked>",line)[:500],"Build arguments/environment values can persist in image metadata, layers, CI logs, or source control.","Use BuildKit/runtime secret mechanisms and inject secrets at runtime from a protected secret store.")
        if re.search(r"(?mi)^\s*ADD\s+https?://", text):
            add("MEDIUM","Container / Build","Remote URL used with Docker ADD",re.search(r"(?mi)^\s*ADD\s+https?://[^\r\n]+",text).group(0)[:500],"Remote build inputs can change and weaken reproducibility/provenance.","Fetch dependencies with explicit verification/checksums in a controlled RUN step or vendor them through trusted artifact storage.")
        if re.search(r"(?i)(curl|wget)[^\r\n]{0,300}\|\s*(sh|bash|zsh)", text):
            add("HIGH","Container / Build","Remote script piped directly to a shell",re.search(r"(?i)(curl|wget)[^\r\n]{0,300}\|\s*(sh|bash|zsh)",text).group(0)[:500],"Piping network content directly to a shell executes whatever the remote endpoint serves at build time.","Download a version-pinned artifact, verify its checksum/signature, then execute it explicitly.")
        if re.search(r"(?i)chmod\s+(?:-R\s+)?777\b", text):
            add("MEDIUM","Container / Permissions","World-writable permissions configured","chmod 777 detected","World-writable files/directories can allow unintended modification inside the container.","Use the minimum owner/group permissions required by the application.")
        if re.search(r"(?mi)^\s*EXPOSE\s+.*\b(22|2375|2376|3306|5432|6379|9200|27017|3389)\b", text):
            add("MEDIUM","Container / Network","Sensitive administration/data-service port exposed by image",re.search(r"(?mi)^\s*EXPOSE\s+.*\b(22|2375|2376|3306|5432|6379|9200|27017|3389)\b.*",text).group(0)[:500],"Exposing sensitive service ports can encourage unsafe publication by deployment tooling.","Expose only application ports that must be reachable and keep administration/data planes private.")

    common_checks = (
        ("CRITICAL","Container / Privilege","Privileged container enabled",r"(?im)^\s*privileged\s*:\s*true\b","Privileged mode grants broad host-level capabilities.","Remove privileged mode and grant only the specific capability/device access required."),
        ("HIGH","Container / Host Access","Docker socket mounted into container",r"(?i)(/var/run/docker\.sock|//var/run/docker\.sock)","Access to the Docker socket can effectively provide host/container-control privileges.","Do not mount the Docker socket into ordinary workloads; use a narrowly scoped proxy if absolutely required."),
        ("HIGH","Container / Host Access","Host network namespace enabled",r"(?im)^\s*(hostNetwork\s*:\s*true|network_mode\s*:\s*[\"']?host)","Host networking removes network namespace isolation and exposes host interfaces directly to the workload.","Use isolated container networking unless host networking is specifically justified."),
        ("HIGH","Container / Host Access","Host PID namespace enabled",r"(?im)^\s*(hostPID\s*:\s*true|pid\s*:\s*[\"']?host)","Host PID access exposes host process visibility and can increase breakout impact.","Keep PID namespaces isolated unless the workload is a tightly controlled system agent."),
        ("HIGH","Container / Privilege","Privilege escalation explicitly allowed",r"(?im)^\s*allowPrivilegeEscalation\s*:\s*true\b","Processes may gain more privileges than their parent process.","Set allowPrivilegeEscalation: false where compatible."),
        ("HIGH","Container / Privilege","runAsNonRoot explicitly disabled",r"(?im)^\s*runAsNonRoot\s*:\s*false\b","The workload permits root execution.","Set runAsNonRoot: true and configure a non-root runAsUser/group."),
        ("HIGH","Container / Capabilities","Powerful Linux capability added",r"(?i)\b(SYS_ADMIN|SYS_PTRACE|NET_ADMIN|DAC_READ_SEARCH|SYS_MODULE)\b","These capabilities substantially expand what a compromised process can do.","Drop all capabilities by default and add back only the minimal required set."),
        ("HIGH","Container / Host Access","Host root/path mount detected",r"(?i)(?:-\s*)?/:/(?:host|rootfs|mnt/host)(?:[:\s]|$)|hostPath\s*:\s*\n\s*path\s*:\s*/\s*$","Mounting sensitive host paths weakens container isolation and can expose host data/configuration.","Remove broad hostPath/root mounts or constrain them to the smallest read-only path required."),
    )
    for sev,cat,title,rx,impact,fix in common_checks:
        m=re.search(rx,text)
        if m:add(sev,cat,title,re.sub(r"\s+"," ",m.group(0))[:500],impact,fix)

    # Mutable image tags in Compose/Kubernetes.
    if kind != "Dockerfile":
        for image in re.findall(r"(?im)^\s*image\s*:\s*[\"']?([^\s\"']+)", text):
            leaf=image.rsplit("/",1)[-1]
            if "@sha256:" not in image and (":" not in leaf or leaf.lower().endswith(":latest")):
                add("MEDIUM","Container / Supply Chain","Unpinned or latest runtime image",image,"Mutable tags make deployments less reproducible and can unexpectedly pull changed content.","Pin vetted versions or immutable image digests in production manifests.")
        if re.search(r"(?im)^\s*(environment|env)\s*:", text) and re.search(r"(?i)(password|secret|token|api[_-]?key|client[_-]?secret)\s*[:=]\s*[^\s$<{][^\r\n]{3,}", text):
            m=re.search(r"(?i)(password|secret|token|api[_-]?key|client[_-]?secret)\s*[:=]\s*([^\r\n]+)", text)
            add("HIGH","Container / Secrets","Secret-like value embedded in runtime manifest",f"{m.group(1)}=<masked>" if m else "secret-like environment entry","Plaintext secrets in Compose/Kubernetes manifests can leak through source control, CI logs, or deployment metadata.","Reference a protected secret store/Kubernetes Secret mechanism and avoid committing secret values to manifests.")

    score=min(100,sum({"CRITICAL":25,"HIGH":12,"MEDIUM":6,"LOW":2,"INFO":0}.get(f["severity"],0) for f in findings))
    return {"enabled":True,"filename":filename,"kind":kind,"findings":findings,"finding_count":len(findings),"risk_score":score,"note":"Static Docker/Compose/Kubernetes configuration review only; no containers are built or executed."}


def site_forensics_scan(payload: Dict[str, Any]) -> Dict[str, Any]:
    if not bool(payload.get("authorized")):
        raise PermissionError("Confirm that you own the target/configuration or have explicit authorization to assess it.")
    target = str(payload.get("target") or "").strip()
    cloud_enabled = bool(payload.get("cloud_security", True))
    container_enabled = bool(payload.get("container_security", True))
    cloud_text = str(payload.get("cloud_config") or "")[:SITE_CONFIG_MAX_CHARS]
    container_text = str(payload.get("container_config") or "")[:SITE_CONFIG_MAX_CHARS]
    cloud_name = str(payload.get("cloud_config_name") or "cloud-config")[:180]
    container_name = str(payload.get("container_config_name") or "container-config")[:180]

    if target:
        base = website_security_forensics_scan(payload)
    else:
        if not ((cloud_enabled and cloud_text.strip()) or (container_enabled and container_text.strip())):
            raise ValueError("Enter an authorized public website or provide a cloud/container configuration file for config-only analysis.")
        base = {
            "ok":True,"tool":"Site Forensics","mode":"config-only",
            "summary":{"target":"Config-only analysis","resolved_ips":[],"pages_scanned":0,"requests_sent":0,"findings":0,"counts":{"CRITICAL":0,"HIGH":0,"MEDIUM":0,"LOW":0,"INFO":0},"score":100,"grade":"A","extended":False,"max_pages":0,"surface_ports":0,"api_endpoints":0,"secret_indicators":0,"dependencies":0,"dependency_vulnerabilities":0,"surface_changed":False},
            "surface":{},"change_monitor":{"changed":False,"changes":[]},"dns":{},"tls":{},"api":{},"secrets":{},"dependencies":{},"vulnerability_intel":{},"pages":[],"findings":[],"log":[]
        }

    cloud_report = site_cloud_security_analyze(cloud_text, cloud_name) if cloud_enabled and cloud_text.strip() else {"enabled":cloud_enabled,"provided":False,"findings":[],"finding_count":0,"risk_score":0}
    container_report = site_container_security_analyze(container_text, container_name) if container_enabled and container_text.strip() else {"enabled":container_enabled,"provided":False,"findings":[],"finding_count":0,"risk_score":0}

    merged = list(base.get("findings") or [])
    seen = {(str(x.get("severity")),str(x.get("category")),str(x.get("title")),str(x.get("evidence"))) for x in merged}
    for item in list(cloud_report.get("findings") or []) + list(container_report.get("findings") or []):
        fp=(str(item.get("severity")),str(item.get("category")),str(item.get("title")),str(item.get("evidence")))
        if fp not in seen:
            seen.add(fp); merged.append(item)
    counts={"CRITICAL":0,"HIGH":0,"MEDIUM":0,"LOW":0,"INFO":0}
    for f in merged:
        sev=str(f.get("severity") or "INFO").upper(); counts[sev if sev in counts else "INFO"] += 1
    weights={"CRITICAL":20,"HIGH":10,"MEDIUM":5,"LOW":2,"INFO":0}
    score=max(0,100-sum(weights.get(str(f.get("severity") or "INFO").upper(),0) for f in merged))
    grade="A" if score>=90 else "B" if score>=80 else "C" if score>=70 else "D" if score>=60 else "F"
    summary=dict(base.get("summary") or {})
    summary.update({"findings":len(merged),"counts":counts,"score":score,"grade":grade,"cloud_findings":int(cloud_report.get("finding_count") or 0),"container_findings":int(container_report.get("finding_count") or 0)})
    base.update({"tool":"Site Forensics","summary":summary,"findings":merged,"cloud_security":cloud_report,"container_security":container_report})
    base["scope"]="Authorized defensive site/configuration assessment only. Web checks remain bounded and low-impact; cloud/container analyzers perform static configuration review only. No cloud credential use, exploit payloads, authentication bypass, brute force, container execution, or destructive actions."
    audit("site_forensics","scan",{"target":target or "config-only","findings":len(merged),"score":score,"cloud_findings":summary["cloud_findings"],"container_findings":summary["container_findings"]})
    return base

def _human_size(num: int) -> str:
    try:
        n = float(num)
        for unit in ["B", "KB", "MB", "GB", "TB"]:
            if abs(n) < 1024.0 or unit == "TB":
                return f"{n:.2f} {unit}" if unit != "B" else f"{int(n)} B"
            n /= 1024.0
    except Exception:
        return str(num)
    return str(num)


def _entropy_for_bytes(data: bytes, max_bytes: int = 1024 * 1024) -> Dict[str, Any]:
    sample = data[:max_bytes]
    if not sample:
        return {"sample_bytes": 0, "entropy": 0.0, "classification": "empty"}
    counts = [0] * 256
    for b in sample:
        counts[b] += 1
    ent = 0.0
    total = len(sample)
    for c in counts:
        if c:
            p = c / total
            ent -= p * math.log2(p)
    if ent >= 7.5:
        cls = "high / compressed-or-encrypted-like"
    elif ent >= 5.0:
        cls = "medium"
    else:
        cls = "low / structured-or-text-like"
    return {"sample_bytes": total, "entropy": round(ent, 6), "classification": cls}


_ASCII_RE = re.compile(rb"[\x20-\x7E]{4,}")
_URL_TEXT_RE = re.compile(r"\bhttps?://[^\s<>'\"`]+", re.I)
_EMAIL_TEXT_RE = re.compile(r"\b[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}\b", re.I)
_IPV4_TEXT_RE = re.compile(r"\b(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)\b")
_DOMAIN_TEXT_RE = re.compile(r"\b(?:[A-Za-z0-9-]+\.)+[A-Za-z]{2,}\b")


def _extract_strings_and_patterns(data: bytes, max_scan: int = 2 * 1024 * 1024, max_items: int = 80) -> Dict[str, Any]:
    sample = data[:max_scan]
    strings = []
    for m in _ASCII_RE.finditer(sample):
        try:
            val = m.group(0).decode("utf-8", errors="replace").strip()
        except Exception:
            continue
        if val and val not in strings:
            strings.append(val[:240])
        if len(strings) >= max_items:
            break
    joined = "\n".join(strings)
    def uniq(regex, limit=40):
        out = []
        for x in regex.findall(joined):
            x = str(x)[:240]
            if x and x not in out:
                out.append(x)
            if len(out) >= limit:
                break
        return out
    return {
        "scan_bytes": len(sample),
        "string_sample_count": len(strings),
        "sample_strings": strings[:max_items],
        "patterns": {
            "urls": uniq(_URL_TEXT_RE),
            "emails": uniq(_EMAIL_TEXT_RE),
            "ipv4": uniq(_IPV4_TEXT_RE),
            "domains": uniq(_DOMAIN_TEXT_RE),
        },
    }


def _archive_metadata_from_bytes(data: bytes) -> Dict[str, Any]:
    info = {}
    try:
        if zipfile.is_zipfile(BytesIO(data)):
            with zipfile.ZipFile(BytesIO(data)) as zf:
                members = _c8_check_zip(zf)
                info["zip"] = {"member_count": len(members), "listed_members": [
                    {"name": x.filename, "size": x.file_size, "compressed": x.compress_size,
                     "modified": "%04d-%02d-%02d %02d:%02d:%02d" % x.date_time} for x in members[:300]],
                    "listed_uncompressed_bytes": sum(x.file_size for x in members[:300])}
            return info
    except Exception as exc:
        info["zip_error"] = str(exc)
        return info
    try:
        expanded = _c8_bounded_inflate(data, _c8_archive_budget(), 31) if data.startswith(b"\x1f\x8b") else data
        with tarfile.open(fileobj=BytesIO(expanded), mode="r:") as tf:
            members = []
            count = total = 0
            for entry in tf:
                count += 1
                total += entry.size
                if count > 2000 or total > _c8_archive_budget():
                    raise C8SecurityInputError("Archive index exceeds the resource budget.")
                if len(members) < 300:
                    members.append({"name": entry.name, "size": entry.size, "type": str(entry.type), "mtime": entry.mtime})
            info["tar"] = {"member_count": count, "listed_members": members}
    except tarfile.ReadError:
        pass
    except Exception as exc:
        info["tar_error"] = str(exc)
    return info


def _meta_unique_text(values: List[str], limit: int = 160, max_len: int = 1200) -> List[str]:
    out: List[str] = []
    seen = set()
    for value in values:
        text = re.sub(r"\s+", " ", str(value or "")).strip()
        if not text:
            continue
        key = text.casefold()
        if key in seen:
            continue
        seen.add(key)
        out.append(text[:max_len])
        if len(out) >= limit:
            break
    return out


def _meta_utf16_strings(data: bytes, max_scan: Optional[int] = None, max_items: int = 100) -> List[str]:
    if max_scan is None:
        max_scan = (1 if C8_LOW_MEMORY_MODE else 4) * 1024 * 1024
    sample = memoryview(data)[:max_scan]
    found: List[str] = []
    # Common hidden-text encoding in Office/PDF/binary payloads.
    for endian in ("little", "big"):
        if endian == "little":
            rx = re.compile(rb"(?:[\x20-\x7e]\x00){4,}")
            enc = "utf-16-le"
        else:
            rx = re.compile(rb"(?:\x00[\x20-\x7e]){4,}")
            enc = "utf-16-be"
        for match in rx.finditer(sample):
            try:
                text = match.group(0).decode(enc, errors="ignore").strip()
            except Exception:
                continue
            if text:
                found.append(text)
            if len(found) >= max_items * 2:
                break
    return _meta_unique_text(found, max_items, 500)


def _meta_xml_visible_text(raw: bytes, max_chars: int = 20000) -> str:
    try:
        text = raw[:max(65536, max_chars * 8)].decode("utf-8", errors="replace")
    except Exception:
        return ""
    # Keep XML text nodes while dropping markup. This intentionally surfaces
    # comments/notes/custom XML that normal document rendering may hide.
    text = re.sub(r"<[^>]+>", " ", text)
    text = unescape(text)
    return re.sub(r"\s+", " ", text).strip()[:max_chars]


def _meta_ooxml_hidden_text(data: bytes) -> Dict[str, Any]:
    report: Dict[str, Any] = {"detected": False, "sources": [], "text_samples": [], "comments_or_notes": [], "custom_xml": []}
    try:
        bio = BytesIO(data)
        if not zipfile.is_zipfile(bio):
            return report
        bio.seek(0)
        with zipfile.ZipFile(bio) as zf:
            _c8_check_zip(zf)
            names = zf.namelist()
            lower = {n.lower(): n for n in names}
            if not any(k in lower for k in ("[content_types].xml", "word/document.xml", "xl/workbook.xml", "ppt/presentation.xml")):
                return report
            report["detected"] = True
            text_items: List[str] = []
            notes: List[str] = []
            custom: List[str] = []
            source_rows: List[Dict[str, Any]] = []
            wanted = []
            for name in names:
                ln = name.lower()
                is_text = (
                    ln == "word/document.xml" or ln.startswith("word/header") or ln.startswith("word/footer")
                    or ln in {"word/comments.xml", "word/footnotes.xml", "word/endnotes.xml"}
                    or ln.startswith("ppt/slides/") or ln.startswith("ppt/notesslides/") or "comments" in ln
                    or ln == "xl/sharedstrings.xml" or ln.startswith("xl/worksheets/")
                    or ln.startswith("docprops/") or ln.startswith("customxml/")
                )
                if is_text and ln.endswith((".xml", ".rels")):
                    wanted.append(name)
            for name in wanted[:80 if C8_LOW_MEMORY_MODE else 160]:
                try:
                    zi = zf.getinfo(name)
                    if zi.file_size > ((512 * 1024) if C8_LOW_MEMORY_MODE else (2 * 1024 * 1024)):
                        continue
                    raw = _c8_zip_read(zf, name)
                    text = _meta_xml_visible_text(raw, 12000)
                    if not text:
                        continue
                    source_rows.append({"member": name, "bytes": zi.file_size, "text_chars": len(text)})
                    ln = name.lower()
                    if "comment" in ln or "notes" in ln or "footnote" in ln or "endnote" in ln or "header" in ln or "footer" in ln:
                        notes.append(f"{name}: {text[:1400]}")
                    elif ln.startswith("customxml/"):
                        custom.append(f"{name}: {text[:1400]}")
                    else:
                        text_items.append(f"{name}: {text[:1400]}")
                except Exception:
                    continue
            report["sources"] = source_rows[:160]
            report["text_samples"] = _meta_unique_text(text_items, 80, 1500)
            report["comments_or_notes"] = _meta_unique_text(notes, 80, 1500)
            report["custom_xml"] = _meta_unique_text(custom, 60, 1500)
    except Exception as exc:
        report["error"] = str(exc)[:500]
    return report


def _meta_trailing_payload(data: bytes, fname: str) -> Dict[str, Any]:
    ext = Path(fname).suffix.lower()
    end = None
    marker = ""
    try:
        if data.startswith(b"\xff\xd8"):
            p = data.rfind(b"\xff\xd9")
            if p >= 0:
                end, marker = p + 2, "JPEG EOI"
        elif data.startswith(b"\x89PNG\r\n\x1a\n"):
            pos = 8
            while pos + 12 <= len(data):
                size = int.from_bytes(data[pos:pos+4], "big")
                ctype = data[pos+4:pos+8]
                nxt = pos + 12 + size
                if nxt > len(data): break
                pos = nxt
                if ctype == b"IEND":
                    end, marker = pos, "PNG IEND"
                    break
        elif data.startswith(b"%PDF-") or ext == ".pdf":
            p = data.rfind(b"%%EOF")
            if p >= 0:
                end, marker = p + 5, "PDF %%EOF"
                while end < len(data) and data[end] in b"\r\n \t": end += 1
        elif data[:6] in (b"GIF87a", b"GIF89a"):
            p = data.rfind(b";")
            if p >= 0:
                end, marker = p + 1, "GIF trailer"
        elif data[:4] == b"PK\x03\x04":
            p = data.rfind(b"PK\x05\x06")
            if p >= 0 and p + 22 <= len(data):
                comment_len = int.from_bytes(data[p+20:p+22], "little")
                end, marker = min(len(data), p + 22 + comment_len), "ZIP EOCD"
    except Exception:
        end = None
    if end is None or end >= len(data):
        return {"marker": marker or "not determined", "trailing_bytes": 0, "present": False}
    trailing = data[end:]
    printable = re.sub(rb"[^\x20-\x7e\r\n\t]", b".", trailing[:1024]).decode("ascii", errors="replace")
    return {
        "marker": marker,
        "present": bool(trailing),
        "trailing_bytes": len(trailing),
        "trailing_sha256": hashlib.sha256(trailing).hexdigest() if trailing else "",
        "preview": printable[:1000],
    }


def _meta_pdf_forensics(reader: Any, data: bytes) -> Dict[str, Any]:
    out: Dict[str, Any] = {
        "extracted_text_samples": [], "annotations": [], "form_fields": {}, "attachments": [],
        "security_indicators": {}, "page_dimensions": [],
    }
    try:
        samples = []
        annotations = []
        dims = []
        for idx, page in enumerate(reader.pages[:60 if C8_LOW_MEMORY_MODE else 120]):
            try:
                txt = page.extract_text() or ""
                txt = re.sub(r"\s+", " ", txt).strip()
                if txt:
                    samples.append(f"page {idx+1}: {txt[:1800]}")
            except Exception:
                pass
            try:
                box = page.mediabox
                dims.append({"page": idx+1, "width": float(box.width), "height": float(box.height), "rotation": int(page.get("/Rotate", 0) or 0)})
            except Exception:
                pass
            try:
                for ref in (page.get("/Annots") or [])[:40]:
                    obj = ref.get_object() if hasattr(ref, "get_object") else ref
                    row = {}
                    for key in ("/Subtype", "/Contents", "/Subj", "/T", "/NM"):
                        if obj.get(key) is not None:
                            row[key.lstrip("/")] = str(obj.get(key))[:1000]
                    if row:
                        row["page"] = idx + 1
                        annotations.append(row)
            except Exception:
                pass
        out["extracted_text_samples"] = _meta_unique_text(samples, 120, 2000)
        out["annotations"] = annotations[:160]
        out["page_dimensions"] = dims[:60 if C8_LOW_MEMORY_MODE else 120]
    except Exception:
        pass
    try:
        fields = reader.get_fields() or {}
        clean_fields = {}
        for name, row in list(fields.items())[:160]:
            clean_fields[str(name)[:200]] = {
                "value": str((row or {}).get("/V", ""))[:1200],
                "default": str((row or {}).get("/DV", ""))[:1200],
                "type": str((row or {}).get("/FT", ""))[:100],
            }
        out["form_fields"] = clean_fields
    except Exception:
        pass
    try:
        attachments = getattr(reader, "attachments", None)
        if isinstance(attachments, dict):
            rows = []
            for name, values in list(attachments.items())[:80]:
                if not isinstance(values, (list, tuple)): values = [values]
                total = sum(len(v) for v in values if isinstance(v, (bytes, bytearray)))
                rows.append({"name": str(name)[:300], "count": len(values), "bytes": total})
            out["attachments"] = rows
    except Exception:
        pass
    indicators = {}
    for label, token in (
        ("javascript", b"/JavaScript"), ("js_action", b"/JS"), ("open_action", b"/OpenAction"),
        ("additional_actions", b"/AA"), ("embedded_file", b"/EmbeddedFile"),
        ("launch_action", b"/Launch"), ("uri_action", b"/URI"),
    ):
        indicators[label] = data.count(token)
    out["security_indicators"] = indicators
    return out


def _metadata_hidden_text_forensics(fname: str, data: bytes, meta: Dict[str, Any]) -> Dict[str, Any]:
    ascii_items = []
    try:
        ascii_items = list((meta.get("strings_and_patterns") or {}).get("sample_strings") or [])
    except Exception:
        pass
    utf16_items = _meta_utf16_strings(data)
    combined = _meta_unique_text(ascii_items + utf16_items, 180, 600)
    pattern_text = "\n".join(combined)
    def matches(rx, limit=80):
        vals = []
        for item in rx.findall(pattern_text):
            val = item if isinstance(item, str) else str(item)
            if val not in vals: vals.append(val[:300])
            if len(vals) >= limit: break
        return vals
    out = {
        "ascii_string_samples": _meta_unique_text(ascii_items, 100, 600),
        "utf16_string_samples": utf16_items,
        "indicators": {
            "urls": matches(_URL_TEXT_RE), "emails": matches(_EMAIL_TEXT_RE),
            "ipv4": matches(_IPV4_TEXT_RE), "domains": matches(_DOMAIN_TEXT_RE),
        },
        "ooxml": _meta_ooxml_hidden_text(data),
        "trailing_payload": _meta_trailing_payload(data, fname),
    }
    return out


def metadata_view(filename: str, data_b64: str) -> Dict[str, Any]:
    data = decode_upload_b64(data_b64)
    data_b64 = ""  # release the large base64 input before deeper analysis
    fname = safe_filename(filename)
    ext = Path(fname).suffix.lower()
    mime = mimetypes.guess_type(fname)[0] or "application/octet-stream"
    hashes = {
        "md5": hashlib.md5(data).hexdigest(),
        "sha1": hashlib.sha1(data).hexdigest(),
        "sha256": hashlib.sha256(data).hexdigest(),
        "sha512": hashlib.sha512(data).hexdigest(),
    }
    meta: Dict[str, Any] = {
        "basic": {
            "filename": fname,
            "extension": ext or "N/A",
            "mime_guess": mime,
            "size_bytes": len(data),
            "size_human": _human_size(len(data)),
            "analysis_time_utc": now_iso(),
        },
        "hashes": hashes,
        "signature": {
            "magic_hex_64": data[:64].hex(),
            "ascii_preview_256": data[:256].decode("utf-8", errors="replace"),
            "null_byte_count_first_4096": data[:4096].count(b"\x00"),
        },
        "entropy": _entropy_for_bytes(data),
        "strings_and_patterns": _extract_strings_and_patterns(data),
        "archive_container": _archive_metadata_from_bytes(fname, data),
        "pil_available": PIL_AVAILABLE,
    }
    if _is_image_filename(fname) or data.startswith((b"\xff\xd8\xff", b"\x89PNG\r\n\x1a\n", b"GIF87a", b"GIF89a", b"BM")):
        _ensure_pillow_available()
    meta["pil_available"] = bool(PIL_AVAILABLE)
    if PIL_AVAILABLE:
        try:
            with _c8_image_open(BytesIO(data)) as im:  # type: ignore[union-attr]
                _im_info = getattr(im, "info", {}) or {}
                _text_info = {}
                for _k, _v in list(_im_info.items())[:200]:
                    if isinstance(_v, (str, int, float, bool)):
                        _text_info[str(_k)] = str(_v)[:4000]
                    elif isinstance(_v, (bytes, bytearray)):
                        _text_info[str(_k)] = {"bytes": len(_v), "sha256": hashlib.sha256(bytes(_v)).hexdigest()}
                meta["image"] = {
                    "format": im.format,
                    "mode": im.mode,
                    "width": im.size[0],
                    "height": im.size[1],
                    "frames": getattr(im, "n_frames", 1),
                    "info_keys": sorted([str(k) for k in _im_info.keys()])[:200],
                    "info_values": _text_info,
                    "icc_profile_present": bool(_im_info.get("icc_profile")),
                    "icc_profile_bytes": len(_im_info.get("icc_profile") or b"") if isinstance(_im_info.get("icc_profile"), (bytes, bytearray)) else 0,
                    "xmp_present": bool(_im_info.get("xmp") or _im_info.get("XML:com.adobe.xmp")),
                    "comment": str(_im_info.get("comment") or "")[:4000],
                    "has_transparency": bool("transparency" in _im_info or (im.mode in {"RGBA", "LA"})),
                }
                try:
                    exif_obj = im.getexif()
                except Exception:
                    exif_obj = None
                if exif_obj:
                    tags = getattr(ExifTags, "TAGS", {}) if ExifTags else {}
                    gps_tags = getattr(ExifTags, "GPSTAGS", {}) if ExifTags else {}
                    exif_out: Dict[str, Any] = {}
                    gps_out: Dict[str, Any] = {}
                    for tag_id, value in list(exif_obj.items())[:500]:
                        name = tags.get(tag_id, tag_id)
                        if name == "GPSInfo" and isinstance(value, dict):
                            for gps_id, gps_value in value.items():
                                gps_name = gps_tags.get(gps_id, gps_id)
                                gps_out[str(gps_name)] = json_safe(gps_value)
                        else:
                            exif_out[str(name)] = json_safe(value)
                    if gps_out:
                        exif_out["GPSInfo"] = gps_out
                    meta["exif"] = exif_out
                else:
                    meta["exif"] = {}
        except Exception as e:
            meta["image_error"] = str(e)

    # PDF metadata, XMP presence, page-level metadata references.
    if ext == ".pdf" or data[:5] == b"%PDF-":
        _ensure_pypdf_available()
    if PYPDF_AVAILABLE and (ext == ".pdf" or data[:5] == b"%PDF-"):
        try:
            reader = PdfReader(BytesIO(data), strict=False)  # type: ignore[misc]
            if getattr(reader, "is_encrypted", False):
                try:
                    reader.decrypt("")
                except Exception:
                    pass
            docinfo = {}
            try:
                md = getattr(reader, "metadata", None)
                if md:
                    for k, v in dict(md).items():
                        docinfo[str(k)] = json_safe(v)
            except Exception:
                pass
            root_has_xmp = False
            try:
                root_has_xmp = bool(reader.trailer.get("/Root", {}).get("/Metadata"))
            except Exception:
                root_has_xmp = False
            page_metadata_refs = 0
            try:
                for page in reader.pages:
                    if page.get("/Metadata") is not None:
                        page_metadata_refs += 1
            except Exception:
                pass
            meta["pdf"] = {
                "pypdf_available": True,
                "encrypted": bool(getattr(reader, "is_encrypted", False)),
                "page_count": len(reader.pages),
                "document_info": docinfo,
                "root_xmp_metadata_present": root_has_xmp,
                "page_metadata_reference_count": page_metadata_refs,
                "forensics": _meta_pdf_forensics(reader, data),
            }
        except Exception as e:
            meta["pdf_error"] = str(e)

    # Office Open XML / ZIP metadata indicators.
    try:
        bio = BytesIO(data)
        if zipfile.is_zipfile(bio):
            bio.seek(0)
            with zipfile.ZipFile(bio) as zf:
                names = zf.namelist()
                lower = [n.lower() for n in names]
                docprops = [n for n in names if n.lower().startswith("docprops/")]
                customxml = [n for n in names if n.lower().startswith("customxml/")]
                macos = [n for n in names if n.startswith("__MACOSX/") or n.lower().endswith(".ds_store")]
                media = [n for n in names if n.lower().endswith((".jpg", ".jpeg", ".png", ".webp", ".tif", ".tiff", ".bmp"))]
                is_ooxml = any(x in lower for x in ("[content_types].xml", "word/document.xml", "xl/workbook.xml", "ppt/presentation.xml"))
                meta["zip_metadata_indicators"] = {
                    "is_zip": True,
                    "looks_like_office_ooxml": bool(is_ooxml),
                    "docprops_members": docprops[:80],
                    "customxml_members": customxml[:80],
                    "macos_metadata_members": macos[:80],
                    "embedded_media_count": len(media),
                }
    except Exception as e:
        meta["zip_metadata_indicator_error"] = str(e)

    meta["hidden_text_forensics"] = _metadata_hidden_text_forensics(fname, data, meta)
    meta["forensic_summary"] = {
        "hidden_text_samples": len((meta.get("hidden_text_forensics") or {}).get("ascii_string_samples") or []) + len((meta.get("hidden_text_forensics") or {}).get("utf16_string_samples") or []),
        "ooxml_hidden_sources": len(((meta.get("hidden_text_forensics") or {}).get("ooxml") or {}).get("sources") or []),
        "trailing_payload_present": bool(((meta.get("hidden_text_forensics") or {}).get("trailing_payload") or {}).get("present")),
        "pdf_annotations": len(((meta.get("pdf") or {}).get("forensics") or {}).get("annotations") or []),
        "pdf_attachments": len(((meta.get("pdf") or {}).get("forensics") or {}).get("attachments") or []),
    }
    audit("metadata", "view_forensics", {"filename": fname, "bytes": len(data), "hidden_text": meta["forensic_summary"]["hidden_text_samples"]})
    return json_safe(meta, max_str=12000)


def _is_image_filename(name: str) -> bool:
    return Path(str(name or "")).suffix.lower() in {".jpg", ".jpeg", ".png", ".webp", ".bmp", ".tif", ".tiff", ".gif"}


def _sanitize_png_without_pillow(data: bytes) -> Tuple[bytes, List[str], str]:
    if not data.startswith(b"\x89PNG\r\n\x1a\n"):
        raise ValueError("Input is not a valid PNG signature.")
    pos = 8
    out = bytearray(data[:8])
    dropped: List[str] = []
    keep_ancillary = {b"tRNS", b"sRGB", b"gAMA", b"cHRM", b"bKGD"}
    saw_iend = False
    while pos + 12 <= len(data):
        length = int.from_bytes(data[pos:pos+4], "big")
        end = pos + 12 + length
        if length < 0 or end > len(data):
            raise ValueError("PNG chunk structure is invalid.")
        chunk_type = data[pos+4:pos+8]
        chunk = data[pos:end]
        critical = bool(chunk_type and 65 <= chunk_type[0] <= 90)
        if critical or chunk_type in keep_ancillary:
            out.extend(chunk)
        else:
            dropped.append(chunk_type.decode("latin-1", errors="replace"))
        pos = end
        if chunk_type == b"IEND":
            saw_iend = True
            break
    if not saw_iend:
        raise ValueError("PNG IEND chunk was not found.")
    actions = ["rebuilt PNG chunk stream without metadata-oriented ancillary chunks"]
    if dropped:
        actions.append("dropped PNG chunks: " + ", ".join(sorted(set(dropped))))
    actions.append("discarded bytes after PNG IEND")
    return bytes(out), actions, "image/png"


def _sanitize_jpeg_without_pillow(data: bytes) -> Tuple[bytes, List[str], str]:
    if not data.startswith(b"\xff\xd8"):
        raise ValueError("Input is not a valid JPEG signature.")
    out = bytearray(b"\xff\xd8")
    pos = 2
    dropped: List[str] = []
    # Preserve image-critical markers, JFIF APP0, and Adobe APP14. Strip EXIF/XMP,
    # ICC, IPTC/Photoshop APP blocks, comments, and unrecognized APP metadata.
    while pos < len(data):
        if data[pos] != 0xFF:
            # Unexpected before SOS: retain remaining bytes to avoid corruption.
            out.extend(data[pos:])
            break
        while pos < len(data) and data[pos] == 0xFF:
            pos += 1
        if pos >= len(data):
            break
        marker = data[pos]
        pos += 1
        if marker == 0xD9:  # EOI
            out.extend(b"\xff\xd9")
            break
        if marker == 0xDA:  # SOS; compressed scan follows.
            if pos + 2 > len(data):
                raise ValueError("JPEG SOS segment is truncated.")
            seglen = int.from_bytes(data[pos:pos+2], "big")
            if seglen < 2 or pos + seglen > len(data):
                raise ValueError("JPEG SOS segment length is invalid.")
            out.extend(b"\xff\xda")
            out.extend(data[pos:pos+seglen])
            scan_start = pos + seglen
            # Keep compressed stream only through the final EOI, dropping trailing payloads.
            eoi = data.rfind(b"\xff\xd9", scan_start)
            if eoi >= scan_start:
                out.extend(data[scan_start:eoi+2])
            else:
                out.extend(data[scan_start:])
            break
        if marker in {0x01} or 0xD0 <= marker <= 0xD7:
            out.extend(bytes((0xFF, marker)))
            continue
        if pos + 2 > len(data):
            raise ValueError("JPEG segment is truncated.")
        seglen = int.from_bytes(data[pos:pos+2], "big")
        if seglen < 2 or pos + seglen > len(data):
            raise ValueError("JPEG segment length is invalid.")
        segment = data[pos:pos+seglen]
        keep = marker == 0xE0 or marker == 0xEE or not (0xE0 <= marker <= 0xEF or marker == 0xFE)
        if keep:
            out.extend(bytes((0xFF, marker)))
            out.extend(segment)
        else:
            dropped.append("COM" if marker == 0xFE else f"APP{marker-0xE0}")
        pos += seglen
    actions = ["rebuilt JPEG marker stream without EXIF/XMP/ICC/IPTC/comment application metadata"]
    if dropped:
        actions.append("dropped JPEG markers: " + ", ".join(sorted(set(dropped))))
    actions.append("discarded bytes after JPEG EOI where present")
    return bytes(out), actions, "image/jpeg"


def _sanitize_webp_without_pillow(data: bytes) -> Tuple[bytes, List[str], str]:
    if len(data) < 12 or data[:4] != b"RIFF" or data[8:12] != b"WEBP":
        raise ValueError("Input is not a valid WebP RIFF container.")
    pos = 12
    chunks: List[Tuple[bytes, bytes]] = []
    dropped: List[str] = []
    while pos + 8 <= len(data):
        ctype = data[pos:pos+4]
        size = int.from_bytes(data[pos+4:pos+8], "little")
        start = pos + 8
        end = start + size
        padded_end = end + (size & 1)
        if end > len(data) or padded_end > len(data):
            raise ValueError("WebP chunk structure is invalid.")
        payload = bytearray(data[start:end])
        if ctype in {b"EXIF", b"XMP ", b"ICCP"}:
            dropped.append(ctype.decode("latin-1").strip())
        else:
            if ctype == b"VP8X" and payload:
                payload[0] &= ~0x2C  # clear ICC, EXIF and XMP feature bits
            chunks.append((ctype, bytes(payload)))
        pos = padded_end
    body = bytearray(b"WEBP")
    for ctype, payload in chunks:
        body.extend(ctype)
        body.extend(len(payload).to_bytes(4, "little"))
        body.extend(payload)
        if len(payload) & 1:
            body.append(0)
    out = b"RIFF" + len(body).to_bytes(4, "little") + bytes(body)
    actions = ["rebuilt WebP RIFF container without EXIF/XMP/ICC chunks"]
    if dropped:
        actions.append("dropped WebP chunks: " + ", ".join(sorted(set(dropped))))
    return out, actions, "image/webp"


def _sanitize_image_bytes(fname: str, data: bytes) -> Tuple[bytes, List[str], str]:
    if not PIL_AVAILABLE:
        _ensure_pillow_available()
    if not PIL_AVAILABLE:
        ext = Path(fname).suffix.lower()
        if data.startswith(b"\x89PNG\r\n\x1a\n") or ext == ".png":
            return _sanitize_png_without_pillow(data)
        if data.startswith(b"\xff\xd8") or ext in {".jpg", ".jpeg"}:
            return _sanitize_jpeg_without_pillow(data)
        if (len(data) >= 12 and data[:4] == b"RIFF" and data[8:12] == b"WEBP") or ext == ".webp":
            return _sanitize_webp_without_pillow(data)
        detail = f" Pillow auto-install error: {_PIL_INSTALL_ERROR}" if _PIL_INSTALL_ERROR else ""
        raise ValueError(
            "Pillow could not be loaded for this image format. PNG, JPEG, and WebP have a built-in no-Pillow sanitizer; "
            "BMP/TIFF/GIF require Pillow." + detail
        )
    actions: List[str] = []
    with _c8_image_open(BytesIO(data)) as im:  # type: ignore[union-attr]
        fmt = (im.format or Path(fname).suffix.replace(".", "") or "PNG").upper()
        if fmt == "JPG":
            fmt = "JPEG"
        if fmt not in {"JPEG", "PNG", "WEBP", "BMP", "TIFF", "GIF"}:
            raise ValueError(f"Built-in wipe supports common image formats only; detected format {fmt!r}.")
        try:
            if ImageOps is not None:
                im = ImageOps.exif_transpose(im)  # type: ignore[assignment]
                actions.append("applied EXIF orientation to pixels before stripping EXIF")
        except Exception:
            pass
        try:
            im.seek(0)
        except Exception:
            pass
        target_mode = "RGBA" if ("A" in im.getbands() or im.mode in {"RGBA", "LA"}) else ("L" if im.mode == "L" else "RGB")
        im2 = im.convert(target_mode) if im.mode != target_mode else im.copy()
        clean_img = Image.frombytes(im2.mode, im2.size, im2.tobytes())  # type: ignore[union-attr]
        out = BytesIO()
        save_fmt = fmt
        if save_fmt == "JPEG":
            if clean_img.mode not in ("RGB", "L"):
                clean_img = clean_img.convert("RGB")
            clean_img.save(out, format="JPEG", quality=95, optimize=True)
        elif save_fmt == "PNG":
            clean_img.save(out, format="PNG", optimize=True)
        elif save_fmt == "WEBP":
            clean_img.save(out, format="WEBP", quality=95, method=6)
        elif save_fmt == "GIF":
            clean_img = clean_img.convert("P", palette=Image.Palette.ADAPTIVE) if hasattr(Image, "Palette") else clean_img.convert("P")  # type: ignore[union-attr]
            clean_img.save(out, format="GIF")
        else:
            clean_img.save(out, format=save_fmt)
    actions += ["rebuilt image from pixel bytes", "dropped EXIF", "dropped GPS", "dropped XMP", "dropped ICC/profile data", "dropped comments/text chunks/thumbnails"]
    mime = {"JPEG": "image/jpeg", "PNG": "image/png", "WEBP": "image/webp", "BMP": "image/bmp", "TIFF": "image/tiff", "GIF": "image/gif"}.get(save_fmt, "application/octet-stream")
    return out.getvalue(), actions, mime


def _sanitize_pdf_bytes(fname: str, data: bytes) -> Tuple[bytes, List[str], str]:
    if not PYPDF_AVAILABLE:
        _ensure_pypdf_available()
    if not PYPDF_AVAILABLE:
        raise ValueError("pypdf is not installed, so built-in PDF metadata wiping is unavailable.")
    actions = ["rebuilt PDF page tree with pypdf"]
    reader = PdfReader(BytesIO(data), strict=False)  # type: ignore[misc]
    if getattr(reader, "is_encrypted", False):
        try:
            reader.decrypt("")
            actions.append("opened PDF with empty password")
        except Exception:
            raise ValueError("Encrypted PDF could not be opened with an empty password; cannot sanitize it.")
    writer = PdfWriter()  # type: ignore[misc]
    for page in reader.pages:
        try:
            if NameObject is not None:
                page.pop(NameObject("/Metadata"), None)  # type: ignore[misc]
                page.pop(NameObject("/PieceInfo"), None)  # type: ignore[misc]
        except Exception:
            pass
        writer.add_page(page)
    try:
        if NameObject is not None:
            writer._root_object.pop(NameObject("/Metadata"), None)  # type: ignore[attr-defined,misc]
            writer._root_object.pop(NameObject("/PieceInfo"), None)  # type: ignore[attr-defined,misc]
    except Exception:
        pass
    try:
        writer._info = None  # type: ignore[attr-defined]
        actions.append("removed PDF document-info dictionary")
    except Exception:
        pass
    out = BytesIO()
    writer.write(out)
    actions += ["removed root XMP metadata reference where present", "removed page metadata references where present", "created new PDF trailer"]
    return out.getvalue(), actions, "application/pdf"


def _zipinfo_clean(name: str, is_dir: bool = False) -> zipfile.ZipInfo:
    zi = zipfile.ZipInfo(name, (1980, 1, 1, 0, 0, 0))
    zi.compress_type = zipfile.ZIP_DEFLATED
    zi.create_system = 0
    zi.comment = b""
    zi.external_attr = (0o755 if is_dir else 0o600) << 16
    return zi


def _clean_content_types_xml(raw: bytes) -> bytes:
    text = raw.decode("utf-8", errors="replace")
    text = re.sub(r"<Override[^>]+PartName=\"/docProps/[^\"]+\"[^>]*/>", "", text, flags=re.I)
    text = re.sub(r"<Override[^>]+PartName=\"/customXml/[^\"]+\"[^>]*/>", "", text, flags=re.I)
    return text.encode("utf-8")


def _clean_rels_xml(raw: bytes) -> bytes:
    text = raw.decode("utf-8", errors="replace")
    text = re.sub(r"<Relationship[^>]+Target=\"(?:docProps|customXml)/[^\"]+\"[^>]*/>", "", text, flags=re.I)
    text = re.sub(r"<Relationship[^>]+Type=\"[^\"]*(?:metadata|core-properties|extended-properties|custom-properties)[^\"]*\"[^>]*/>", "", text, flags=re.I)
    return text.encode("utf-8")


def _sanitize_inner_member(name: str, raw: bytes, actions: List[str]) -> bytes:
    lower = name.lower()
    if _is_image_filename(name) and PIL_AVAILABLE:
        try:
            clean, img_actions, _mime = _sanitize_image_bytes(name, raw)
            actions.append(f"stripped metadata from embedded image: {name}")
            return clean
        except Exception as e:
            actions.append(f"embedded image unchanged ({name}): {e}")
            return raw
    if lower == "[content_types].xml":
        actions.append("removed docProps/customXml overrides from [Content_Types].xml")
        return _clean_content_types_xml(raw)
    if lower.endswith(".rels"):
        cleaned = _clean_rels_xml(raw)
        if cleaned != raw:
            actions.append(f"removed metadata relationships from {name}")
        return cleaned
    return raw


def _sanitize_zip_bytes(fname: str, data: bytes) -> Tuple[bytes, List[str], str]:
    actions: List[str] = []
    inbuf = BytesIO(data)
    outbuf = BytesIO()
    dropped: List[str] = []
    with zipfile.ZipFile(inbuf, "r") as zin, zipfile.ZipFile(outbuf, "w", compression=zipfile.ZIP_DEFLATED, allowZip64=True) as zout:
        _c8_check_zip(zin)
        zout.comment = b""
        names = zin.namelist()
        lower_names = {n.lower() for n in names}
        is_ooxml = bool({"[content_types].xml", "word/document.xml", "xl/workbook.xml", "ppt/presentation.xml"} & lower_names)
        seen = set()
        for info in zin.infolist():
            name = info.filename
            if not name or name in seen:
                continue
            seen.add(name)
            lower = name.lower()
            is_dir = name.endswith("/")
            if lower.startswith("__macosx/") or lower.endswith(".ds_store") or lower.endswith("thumbs.db"):
                dropped.append(name); continue
            if is_ooxml and (lower.startswith("docprops/") or lower.startswith("customxml/")):
                dropped.append(name); continue
            if is_dir:
                zout.writestr(_zipinfo_clean(name, True), b"")
                continue
            raw = _c8_zip_read(zin, info)
            raw = _sanitize_inner_member(name, raw, actions)
            zout.writestr(_zipinfo_clean(name, False), raw)
    if dropped:
        actions.append("dropped metadata/container members: " + ", ".join(dropped[:30]) + (" ..." if len(dropped) > 30 else ""))
    actions += ["normalized ZIP member timestamps to 1980-01-01", "cleared ZIP comments", "normalized ZIP file attributes/creator system"]
    ext = Path(fname).suffix.lower()
    mime = mimetypes.guess_type(fname)[0] or ("application/vnd.openxmlformats-officedocument.wordprocessingml.document" if ext == ".docx" else "application/zip")
    return outbuf.getvalue(), actions, mime


def _sanitize_gzip_bytes(fname: str, data: bytes) -> Tuple[bytes, List[str], str]:
    with gzip.GzipFile(fileobj=BytesIO(data), mode="rb") as gz:
        raw = gz.read(MAX_UPLOAD_BYTES + 1)
    if len(raw) > MAX_UPLOAD_BYTES:
        raise ValueError("Expanded GZIP data exceeds upload size limit.")
    out = BytesIO()
    with gzip.GzipFile(filename="", mode="wb", fileobj=out, mtime=0) as gzout:
        gzout.write(raw)
    return out.getvalue(), ["recompressed GZIP with mtime=0", "removed original-name field from GZIP header"], "application/gzip"


def _sanitize_tar_bytes(fname: str, data: bytes) -> Tuple[bytes, List[str], str]:
    if data.startswith(b"\x1f\x8b"):
        data = _c8_bounded_inflate(data, _c8_archive_budget(), 16 + zlib.MAX_WBITS)
    if data.startswith((b"BZh", b"\xfd7zXZ")):
        raise C8SecurityInputError("Use an uncompressed TAR or TAR.GZ for metadata cleaning.")
    out = BytesIO()
    actions = []
    total = 0
    seen = set()
    with tarfile.open(fileobj=BytesIO(data), mode="r:") as tin, tarfile.open(fileobj=out, mode="w") as tout:
        for index, member in enumerate(tin):
            if index >= 2000:
                raise C8SecurityInputError("Too many archive entries.")
            name = _c8_archive_name(member.name)
            key = name.rstrip("/").casefold()
            if key in seen:
                raise C8SecurityInputError("Duplicate archive member path.")
            seen.add(key)
            if not (member.isfile() or member.isdir()) or member.issparse():
                raise C8SecurityInputError("TAR links, sparse files and special files are not supported.")
            total += member.size
            if member.size < 0 or total > _c8_archive_budget():
                raise C8SecurityInputError("Expanded archive exceeds the memory budget.")
            item = tarfile.TarInfo(name)
            item.type = tarfile.DIRTYPE if member.isdir() else tarfile.REGTYPE
            item.mode = 0o755 if member.isdir() else 0o600
            if member.isfile():
                with tin.extractfile(member) as stream:
                    raw = stream.read(member.size + 1)
                if len(raw) != member.size:
                    raise C8SecurityInputError("Truncated archive member.")
                raw = _sanitize_inner_member(name, raw, actions)
                item.size = len(raw)
                tout.addfile(item, BytesIO(raw))
            else:
                tout.addfile(item)
    actions.append("normalized TAR ownership, permissions and timestamps; rejected unsafe member types/paths")
    return out.getvalue(), actions, "application/x-tar"


def _detect_metadata_wipe_kind(fname: str, data: bytes) -> str:
    ext = Path(fname).suffix.lower()
    if ext == ".pdf" or data[:5] == b"%PDF-":
        return "pdf"
    if _is_image_filename(fname):
        return "image"
    if data[:2] == b"\x1f\x8b" or ext == ".gz":
        return "gzip"
    try:
        if zipfile.is_zipfile(BytesIO(data)):
            return "zip_or_office"
    except Exception:
        pass
    try:
        with tarfile.open(fileobj=BytesIO(data), mode="r:"):
            return "tar"
    except Exception:
        pass
    return "generic"


def metadata_wipe_image(filename: str, data_b64: str) -> Dict[str, Any]:
    data = decode_upload_b64(data_b64)
    data_b64 = ""  # release the large base64 input before rebuilding the file
    fname = safe_filename(filename)
    before_b64 = base64.b64encode(data).decode("ascii")
    before = metadata_view(fname, before_b64)
    kind = _detect_metadata_wipe_kind(fname, data)
    actions: List[str] = []
    caveats: List[str] = []
    mime = mimetypes.guess_type(fname)[0] or "application/octet-stream"
    clean = data
    if kind == "image":
        clean, actions, mime = _sanitize_image_bytes(fname, data)
    elif kind == "pdf":
        clean, actions, mime = _sanitize_pdf_bytes(fname, data)
    elif kind == "zip_or_office":
        clean, actions, mime = _sanitize_zip_bytes(fname, data)
    elif kind == "gzip":
        clean, actions, mime = _sanitize_gzip_bytes(fname, data)
    elif kind == "tar":
        clean, actions, mime = _sanitize_tar_bytes(fname, data)
    else:
        # No known metadata container was detected. Preserve bytes and report honestly rather than pretending.
        caveats.append("No supported metadata container was detected; bytes were not rewritten. Use image/PDF/Office/ZIP/TAR/GZIP for active wiping.")
        actions.append("unsupported generic file: no metadata-specific rewrite performed")

    ext = Path(fname).suffix.lower() or ".bin"
    clean_filename = f"meta_wiped_{uuid.uuid4().hex[:12]}{ext}"
    after_b64 = base64.b64encode(clean).decode("ascii")
    after = metadata_view(clean_filename, after_b64)
    before_sha = (before.get("hashes") or {}).get("sha256")
    after_sha = hashlib.sha256(clean).hexdigest()
    if before_sha == after_sha and kind != "generic":
        caveats.append("Output hash is unchanged; file may not have contained removable metadata or sanitizer could not alter it.")
    caveats.append("This removes known metadata containers, not visible document content. Text inside pages/cells/slides/images remains if it is part of the content.")
    caveats.append("Backups, cloud sync history, filesystem journal entries, and previous copies are outside this web app's control.")
    audit("metadata", "wipe_strong", {"filename": fname, "kind": kind, "before": len(data), "after": len(clean), "actions": len(actions)})
    return {
        "ok": True,
        "filename": fname,
        "clean_filename": clean_filename,
        "detected_kind": kind,
        "clean_size_bytes": len(clean),
        "original_size_bytes": len(data),
        "mime": mime,
        "download_b64": after_b64,
        "before": before,
        "after": after,
        "wipe_report": {
            "detected_kind": kind,
            "actions": actions,
            "caveats": caveats,
            "before_sha256": before_sha,
            "after_sha256": after_sha,
            "bytes_delta": len(clean) - len(data),
            "supported_sanitizers": ["image pixel rebuild", "PDF page-tree rebuild", "Office/ZIP docProps/customXml strip", "embedded image strip", "ZIP timestamp/comment normalization", "TAR owner/time normalization", "GZIP mtime/name normalization"],
        },
    }


