def _dome_float(value: Any, fallback: Optional[float] = None) -> Optional[float]:
    try:
        n = float(value)
        if math.isfinite(n):
            return n
    except Exception:
        pass
    return fallback


def _dome_state_codes(raw: Any) -> List[str]:
    text = re.sub(r"\s+", " ", str(raw or "").strip().upper())
    if not text:
        return []
    parts = [p.strip() for p in re.split(r"[,;]+", text) if p.strip()]
    if len(parts) == 1:
        mapped = DOME_STATE_NAMES.get(parts[0])
        if mapped:
            return [mapped]
    codes: List[str] = []
    for part in parts:
        code = DOME_STATE_NAMES.get(part) or part
        if code in DOME_STATE_BBOXES and code not in codes:
            codes.append(code)
    return codes


def _dome_bbox_from_payload(payload: Dict[str, Any]) -> Tuple[Tuple[float, float, float, float], str]:
    mode = str(payload.get("mode") or "manual").strip().lower()
    if mode == "usa":
        return DOME_USA_BBOX, "USA"
    if mode == "state":
        codes = _dome_state_codes(payload.get("states") or payload.get("state") or "NJ")
        if not codes:
            raise ValueError("Enter valid state code(s), for example NJ or NY, NJ, PA.")
        boxes = [DOME_STATE_BBOXES[c] for c in codes]
        return (
            min(b[0] for b in boxes), min(b[1] for b in boxes),
            max(b[2] for b in boxes), max(b[3] for b in boxes),
        ), ", ".join(codes)
    bbox = (
        _dome_float(payload.get("minlat")), _dome_float(payload.get("minlon")),
        _dome_float(payload.get("maxlat")), _dome_float(payload.get("maxlon")),
    )
    if any(v is None for v in bbox):
        raise ValueError("Manual bounding box requires minLat, minLon, maxLat, and maxLon.")
    minlat, minlon, maxlat, maxlon = [float(v) for v in bbox if v is not None]
    if not (-90 <= minlat <= 90 and -90 <= maxlat <= 90 and -180 <= minlon <= 180 and -180 <= maxlon <= 180):
        raise ValueError("Bounding box values are outside valid latitude/longitude ranges.")
    if minlat >= maxlat or minlon >= maxlon:
        raise ValueError("Bounding box minimums must be lower than maximums.")
    return (minlat, minlon, maxlat, maxlon), "manual bbox"


_N_NUMBER_LETTERS = "ABCDEFGHJKLMNPQRSTUVWXYZ"
_N_NUMBER_LAST_CHARS = _N_NUMBER_LETTERS + "0123456789"
_N_SUFFIX_BUCKET = 1 + len(_N_NUMBER_LETTERS) * (1 + len(_N_NUMBER_LETTERS))
_N_BUCKET_4 = 1 + len(_N_NUMBER_LETTERS) + 10
_N_BUCKET_3 = 10 * _N_BUCKET_4 + _N_SUFFIX_BUCKET
_N_BUCKET_2 = 10 * _N_BUCKET_3 + _N_SUFFIX_BUCKET
_N_BUCKET_1 = 10 * _N_BUCKET_2 + _N_SUFFIX_BUCKET


def _n_suffix_offset(suffix: str) -> Optional[int]:
    if not suffix:
        return 0
    if len(suffix) > 2 or any(ch not in _N_NUMBER_LETTERS for ch in suffix):
        return None
    offset = (len(_N_NUMBER_LETTERS) + 1) * _N_NUMBER_LETTERS.index(suffix[0]) + 1
    if len(suffix) == 2:
        offset += _N_NUMBER_LETTERS.index(suffix[1]) + 1
    return offset


def _n_suffix_from_offset(offset: int) -> Optional[str]:
    if offset == 0:
        return ""
    if offset < 0 or offset >= _N_SUFFIX_BUCKET:
        return None
    first = _N_NUMBER_LETTERS[(offset - 1) // (len(_N_NUMBER_LETTERS) + 1)]
    remainder = (offset - 1) % (len(_N_NUMBER_LETTERS) + 1)
    if remainder == 0:
        return first
    return first + _N_NUMBER_LETTERS[remainder - 1]


def _dome_normalize_registration(value: Any) -> str:
    raw = re.sub(r"\s+", "", str(value or "").strip().upper())
    compact = re.sub(r"[^A-Z0-9]", "", raw)
    if not compact:
        return ""
    if compact.startswith("N"):
        return compact
    if re.fullmatch(r"[1-9][0-9]{0,4}", compact) or re.fullmatch(r"[1-9][0-9]{0,3}[A-HJ-NP-Z]", compact) or re.fullmatch(r"[1-9][0-9]{0,2}[A-HJ-NP-Z]{2}", compact):
        return "N" + compact
    if "-" in raw and re.fullmatch(r"[A-Z0-9]{1,3}-[A-Z0-9]{2,8}", raw):
        return raw
    return compact


def _dome_n_number_to_icao24(registration: Any) -> str:
    reg = _dome_normalize_registration(registration)
    if not reg.startswith("N"):
        return ""
    if not (re.fullmatch(r"N[1-9][0-9]{0,4}", reg) or re.fullmatch(r"N[1-9][0-9]{0,3}[A-HJ-NP-Z]", reg) or re.fullmatch(r"N[1-9][0-9]{0,2}[A-HJ-NP-Z]{2}", reg)):
        return ""
    body = reg[1:]
    count = 1
    for idx, ch in enumerate(body):
        if idx == 4:
            if ch not in _N_NUMBER_LAST_CHARS:
                return ""
            count += _N_NUMBER_LAST_CHARS.index(ch) + 1
            break
        if ch in _N_NUMBER_LETTERS:
            suffix = _n_suffix_offset(body[idx:])
            if suffix is None:
                return ""
            count += suffix
            break
        digit = int(ch)
        if idx == 0:
            count += (digit - 1) * _N_BUCKET_1
        elif idx == 1:
            count += digit * _N_BUCKET_2 + _N_SUFFIX_BUCKET
        elif idx == 2:
            count += digit * _N_BUCKET_3 + _N_SUFFIX_BUCKET
        elif idx == 3:
            count += digit * _N_BUCKET_4 + _N_SUFFIX_BUCKET
    if count < 1 or count > 0xDF7C7:
        return ""
    return "a" + format(count, "05x")


def _icao24_to_n_number(icao24: Any) -> str:
    key = str(icao24 or "").strip().upper()
    if not re.match(r"^A[0-9A-F]{5}$", key):
        return ""
    value = int(key[1:], 16) - 1
    if value < 0 or value >= 0xDF7C7:
        return ""
    out = "N" + str(value // _N_BUCKET_1 + 1)
    rem1 = value % _N_BUCKET_1
    if rem1 < _N_SUFFIX_BUCKET:
        return out + (_n_suffix_from_offset(rem1) or "")
    rem1 -= _N_SUFFIX_BUCKET
    d2, rem2 = divmod(rem1, _N_BUCKET_2)
    out += str(d2)
    if rem2 < _N_SUFFIX_BUCKET:
        return out + (_n_suffix_from_offset(rem2) or "")
    rem2 -= _N_SUFFIX_BUCKET
    d3, rem3 = divmod(rem2, _N_BUCKET_3)
    out += str(d3)
    if rem3 < _N_SUFFIX_BUCKET:
        return out + (_n_suffix_from_offset(rem3) or "")
    rem3 -= _N_SUFFIX_BUCKET
    d4, rem4 = divmod(rem3, _N_BUCKET_4)
    out += str(d4)
    if rem4 == 0:
        return out
    if 1 <= rem4 <= len(_N_NUMBER_LAST_CHARS):
        return out + _N_NUMBER_LAST_CHARS[rem4 - 1]
    return ""


def _meters_to_feet(value: Any) -> Optional[int]:
    n = _dome_float(value)
    return int(round(n * 3.280839895)) if n is not None else None


def _mps_to_knots(value: Any) -> Optional[int]:
    n = _dome_float(value)
    return int(round(n * 1.9438444924)) if n is not None else None


def _mps_to_mph(value: Any) -> Optional[int]:
    n = _dome_float(value)
    return int(round(n * 2.2369362921)) if n is not None else None


def _mps_to_fpm(value: Any) -> Optional[int]:
    n = _dome_float(value)
    return int(round(n * 196.8503937)) if n is not None else None


def _heading_cardinal(track: Any) -> str:
    n = _dome_float(track)
    if n is None:
        return ""
    labels = ("N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE", "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW")
    return labels[int((n % 360) / 22.5 + 0.5) % 16]


def _dome_ts_iso(timestamp: Any) -> str:
    n = _dome_float(timestamp)
    if n is None:
        return ""
    try:
        return datetime.fromtimestamp(n, timezone.utc).replace(microsecond=0).isoformat()
    except Exception:
        return ""


def _dome_movement_status(record: Dict[str, Any]) -> str:
    """Best-effort flight phase from public position fields; never presented as a filed flight-plan state."""
    if not isinstance(record, dict):
        return "Unknown"
    if bool(record.get("on_ground")):
        return "On ground"
    vertical_fpm = _dome_float(record.get("vertical_rate_fpm"))
    if vertical_fpm is None:
        vertical_mps = _dome_float(record.get("vertical_rate"))
        vertical_fpm = vertical_mps * 196.8503937 if vertical_mps is not None else None
    if vertical_fpm is not None:
        if vertical_fpm >= 500:
            return "Climbing"
        if vertical_fpm <= -500:
            return "Descending"
        if abs(vertical_fpm) <= 250:
            return "Level / near-level"
    speed_kt = _dome_float(record.get("spd_kt"))
    if speed_kt is None:
        speed_mps = _dome_float(record.get("velocity"), _dome_float(record.get("spd_mps")))
        speed_kt = speed_mps * 1.9438444924 if speed_mps is not None else None
    if speed_kt is not None and speed_kt < 35:
        return "Low-speed airborne / uncertain"
    return "Airborne"


def _dome_classification_confidence(record: Dict[str, Any], category: str, reason: str) -> str:
    if category in {"Unknown", "Operator unconfirmed"} or not isinstance(record, dict):
        return "Unconfirmed"
    reason_l = str(reason or "").lower()
    if "aircraft database category" in reason_l:
        return "High"
    owner_operator = any(str(record.get(k) or "").strip() for k in (
        "owner", "registered_owner", "operator", "airline", "airline_name", "operating_as", "operator_code"
    ))
    if owner_operator and ("matched" in reason_l or "published operator code" in reason_l):
        return "High"
    if "callsign" in reason_l or "likely" in str(category).lower():
        return "Medium"
    if owner_operator:
        return "Medium"
    return "Low"


def _dome_data_completeness(record: Dict[str, Any]) -> Dict[str, Any]:
    fields = (
        "icao24", "registration", "callsign", "owner", "operator", "manufacturer", "model", "typecode",
        "serial_number", "year_mfr", "country", "lat", "lon", "alt_ft", "spd_kt", "track", "squawk",
        "position_source", "last_seen"
    )
    present = [key for key in fields if record.get(key) not in (None, "", [], {})]
    score = int(round((len(present) / len(fields)) * 100)) if fields else 0
    return {"score": score, "present": len(present), "possible": len(fields)}


def _dome_first_keyword(blob: str, keywords: Tuple[str, ...]) -> str:
    for keyword in keywords:
        key = str(keyword).upper().replace(".", " ").replace("-", " ").strip()
        if not key:
            continue
        if len(key) <= 4 and re.fullmatch(r"[A-Z0-9]+", key):
            if re.search(rf"(?<![A-Z0-9]){re.escape(key)}(?![A-Z0-9])", blob):
                return keyword
        elif key in blob:
            return keyword
    return ""


def _dome_classify_ownership(record: Dict[str, Any]) -> Tuple[str, str]:
    """Classify aircraft ownership/use from the strongest current public evidence.

    Important: ``ownership_category`` can be a category we derived earlier from a
    sparse live track.  Do not let an inherited Private/GA guess outrank owner,
    operator, unit, or callsign evidence added by later enrichment.
    """
    if not isinstance(record, dict):
        return "Unknown", "No aircraft fields available."

    # Only treat source/database category fields as explicit evidence.  The
    # ownership_category field is usually our own prior classification and is
    # therefore only a fallback after fresh owner/operator evidence is checked.
    explicit = str(
        record.get("classification")
        or record.get("use_category")
        or record.get("category_detail")
        or record.get("source_ownership_category")
        or ""
    ).strip()
    explicit_upper = explicit.upper()
    inherited = str(record.get("ownership_category") or "").strip()
    inherited_upper = inherited.upper()

    fields = (
        "operator", "owner", "registered_owner", "unit", "label", "role", "callsign", "model", "typecode",
        "manufacturer", "notes", "sources", "origin_country", "country", "airline", "airline_name",
        "operating_as", "painted_as", "operator_code", "flight",
    )
    blob = " ".join(str(record.get(k) or "") for k in fields).upper().replace(".", " ").replace("-", " ")
    callsign = re.sub(r"[^A-Z0-9]", "", str(record.get("callsign") or "").upper())

    # Strong explicit military/government source categories remain authoritative.
    if explicit:
        if any(x in explicit_upper for x in ("MIL", "ARMY", "NAVY", "AIR FORCE", "USAF", "USMC", "DOD")):
            return "Government / military", f"Aircraft database category: {explicit}."
        if any(x in explicit_upper for x in ("GOV", "PUBLIC", "SHERIFF", "POLICE", "FIRE", "RESCUE", "LAW ENFORCEMENT")):
            return "Government / public safety", f"Aircraft database category: {explicit}."

    # Fresh owner/operator/unit/callsign evidence outranks an old Private/GA
    # classification produced from a bare civil registration.
    hit = _dome_first_keyword(blob, _DOME_MILITARY_KEYWORDS)
    if hit:
        return "Government / military", f"Matched military keyword in current aircraft metadata: {hit}."
    if callsign.startswith(_DOME_MILITARY_CALLSIGN_PREFIXES):
        return "Government / military", f"Public callsign pattern {callsign[:6]} is consistent with military/government operations."
    hit = _dome_first_keyword(blob, _DOME_GOVERNMENT_KEYWORDS)
    if hit:
        return "Government / public safety", f"Matched government/public-safety keyword in current aircraft metadata: {hit}."
    if callsign.startswith(_DOME_GOVERNMENT_CALLSIGN_PREFIXES):
        return "Government / public safety", f"Public callsign pattern {callsign[:6]} is consistent with a government operator."

    # Commercial source/category evidence comes next.
    if explicit and any(x in explicit_upper for x in ("COMM", "AIRLINE", "CARGO")):
        return "Commercial", f"Aircraft database category: {explicit}."
    hit = _dome_first_keyword(blob, _DOME_COMMERCIAL_KEYWORDS)
    if hit:
        return "Commercial", f"Matched commercial/operator keyword: {hit}."
    for prefix in sorted(_DOME_COMMERCIAL_CALLSIGN_PREFIXES, key=len, reverse=True):
        if callsign.startswith(prefix) and len(callsign) > len(prefix):
            return "Commercial", f"Callsign prefix {prefix} commonly belongs to an airline, cargo, or charter operator."
    operator_code = re.sub(
        r"[^A-Z0-9]",
        "",
        str(
            record.get("operator_code")
            or record.get("operating_as")
            or record.get("registered_owner_operator_flag_code")
            or ""
        ).upper(),
    )
    if operator_code in _DOME_COMMERCIAL_CALLSIGN_PREFIXES:
        return "Commercial", f"Published operator code {operator_code} matches a known airline, cargo, or charter operator."

    # Private/GA is deliberately lower priority than identified public-service
    # ownership. This prevents records such as Anaheim Police Department from
    # being mislabeled merely because the aircraft has an ordinary N-number.
    if explicit and any(x in explicit_upper for x in ("PRIV", "GENERAL AVIATION", "PRIVATE / GA")):
        return "Private / GA", f"Aircraft database category: {explicit}."
    hit = _dome_first_keyword(blob, _DOME_PRIVATE_KEYWORDS)
    if hit:
        return "Private / GA", f"Matched private/general-aviation keyword: {hit}."

    # Preserve a previous non-private category only as a last-resort hint. Never
    # preserve inherited Private/GA ahead of newly enriched ownership evidence.
    if inherited and not any(x in inherited_upper for x in ("PRIV", "GENERAL AVIATION", "PRIVATE / GA", "LIKELY")):
        if "MILITARY" in inherited_upper:
            return "Government / military", "Preserved prior government/military classification after re-evaluation."
        if "GOVERNMENT" in inherited_upper or "PUBLIC" in inherited_upper:
            return "Government / public safety", "Preserved prior government/public-safety classification after re-evaluation."
        if "COMMERCIAL" in inherited_upper:
            return "Commercial", "Preserved prior commercial classification after re-evaluation."

    if record.get("registration") or record.get("tail"):
        return "Private / GA (likely)", "Civil registration is available and no government, military, public-safety, or commercial marker was found."
    known_details: List[str] = []
    model = " ".join(
        str(value or "").strip()
        for value in (record.get("manufacturer"), record.get("model"), record.get("typecode"))
        if str(value or "").strip()
    )
    if model:
        known_details.append(f"aircraft type {model}")
    country = str(record.get("country") or record.get("origin_country") or "").strip()
    if country:
        known_details.append(f"reported country {country}")
    adsb_category = str(record.get("adsb_category") or "").strip()
    if adsb_category and adsb_category.lower() not in {"no info", "no ads-b category", "0", "1"}:
        known_details.append(f"ADS-B category {adsb_category}")
    if known_details:
        return (
            "Operator unconfirmed",
            "Public metadata provides "
            + ", ".join(known_details[:3])
            + ", but does not publish enough reliable owner or operator evidence for a stronger classification.",
        )
    return "Unknown", "No owner, operator, registration, aircraft type, callsign, or country metadata is available for this live ICAO address."


def _dome_flight_class(record: Dict[str, Any]) -> str:
    if bool(record.get("on_ground")):
        return "Ground"
    speed = _dome_float(record.get("velocity"), 0.0) or 0.0
    altitude = _dome_float(record.get("geo_altitude"), _dome_float(record.get("baro_altitude"), 0.0)) or 0.0
    adsb_category = str(record.get("adsb_category") or "").lower()
    if "rotorcraft" in adsb_category or (speed < 40 and altitude < 3000):
        return "Helicopter / rotorcraft"
    if speed >= 140:
        return "Jet"
    if speed >= 40:
        return "Prop / turboprop"
    return "Unknown"


def _dome_json_dicts(value: Any, max_depth: int = 5) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    def walk(item: Any, depth: int) -> None:
        if depth < 0:
            return
        if isinstance(item, dict):
            out.append(item)
            for child in item.values():
                if isinstance(child, (dict, list)):
                    walk(child, depth - 1)
        elif isinstance(item, list):
            for child in item[:30]:
                if isinstance(child, (dict, list)):
                    walk(child, depth - 1)
    walk(value, max_depth)
    return out


def _dome_external_value(dicts: List[Dict[str, Any]], *keys: str) -> str:
    wanted = {k.lower() for k in keys}
    for mapping in dicts:
        for key, value in mapping.items():
            if str(key).strip().lower() in wanted:
                if isinstance(value, (dict, list, tuple, set)):
                    continue
                text = str(value or "").strip()
                if text and text.lower() not in {"nan", "none", "null"}:
                    return text
    return ""


def _dome_extract_external_info(data: Any) -> Dict[str, Any]:
    """Normalize useful public aircraft metadata without importing contact/address fields."""
    dicts = _dome_json_dicts(data)
    aliases = {
        "icao24": ("mode_s", "modes", "mode-s", "hex", "icao24", "icao_address"),
        "registration": ("registration", "reg", "n_number", "n-number", "tail", "tail_number"),
        "manufacturer": ("manufacturer", "manufacturername", "manufacturer_name", "make"),
        "model": ("model", "type", "aircraft_type", "type_description", "aircraft", "desc", "model_name"),
        "typecode": ("typecode", "type_code", "icao_type", "icaotypecode", "icao_type_code"),
        "aircraft_type": ("aircraft_type", "aircraft_class", "type_description", "aircraft_description"),
        "operator": ("operator", "operator_name", "registered_owner_operator", "airline", "airline_name", "operatorname"),
        "operator_code": (
            "operator_code", "operator_flag_code", "registered_owner_operator_flag_code",
            "operating_as", "painted_as", "operator_icao", "icao_airline_code",
        ),
        "operator_icao": ("operator_icao", "icao_airline_code", "airline_icao", "icao_operator"),
        "operator_iata": ("operator_iata", "iata_airline_code", "airline_iata", "iata_operator"),
        "owner": ("owner", "registered_owner", "registeredowners", "registered_owner_operator"),
        "serial_number": ("serial_number", "serial", "serialnumber", "msn", "construction_number", "cn"),
        "year_mfr": ("built", "year", "year_mfr", "manufacture_year", "year_built", "built_year"),
        "country": (
            "country", "country_name", "country_iso", "country_iso_name",
            "registered_owner_country_name", "registered_owner_country_iso_name",
        ),
        "owner_country": ("registered_owner_country_name", "owner_country", "owner_country_name"),
        "registration_status": ("registration_status", "reg_status", "status"),
        "aircraft_status": ("aircraft_status", "status_description", "airworthiness_status"),
        "engine_type": ("engine_type", "engines_type", "engine_description", "engine_model"),
        "engine_count": ("engine_count", "engines_count", "number_of_engines", "num_engines"),
        "seat_count": ("seat_count", "seats", "number_of_seats", "num_seats"),
        "category_detail": ("category", "aircraft_category", "wake_turbulence", "wtc"),
        "photo_url": ("url_photo", "photo", "image", "image_url", "photo_url"),
        "photo_thumbnail_url": ("url_photo_thumbnail", "photo_thumbnail", "photo_thumbnail_url", "thumbnail", "thumbnail_url"),
    }
    info: Dict[str, Any] = {}
    for out_key, keys in aliases.items():
        value = _dome_external_value(dicts, *keys)
        if value:
            if out_key == "registration":
                value = _dome_normalize_registration(value)
            elif out_key == "icao24":
                value = re.sub(r"[^0-9a-f]", "", value.lower())[:6]
            info[out_key] = value
    if info.get("registration"):
        info.setdefault("tail", info["registration"])
    if info.get("owner"):
        info.setdefault("registered_owner", info["owner"])
    if info.get("operator_icao"):
        info.setdefault("operator_code", info["operator_icao"])
    return info


def _dome_fetch_json(url: str, timeout: float = 7.0, max_bytes: int = 2 * 1024 * 1024) -> Any:
    cache_key = url
    now = time.time()
    cached = _DOME_LOOKUP_CACHE.get(cache_key)
    if cached and now - float(cached.get("fetched_at") or 0) < 12 * 3600:
        return cached.get("data")
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "C8-Dome-Web/3.0", "Accept": "application/json"})
        with _c8_urlopen(req, timeout=timeout) as response:
            raw = response.read(max_bytes + 1)
            if len(raw) > max_bytes:
                return {}
        data = json.loads(raw.decode("utf-8", errors="replace"))
        _DOME_LOOKUP_CACHE[cache_key] = {"fetched_at": now, "data": data}
        return data
    except Exception:
        return {}


def _dome_fr24_token() -> str:
    return str(os.environ.get("LL_WEB_FR24_API_TOKEN") or os.environ.get("FR24_API_TOKEN") or "").strip()


def _dome_fr24_live_lookup(registration: str = "", callsign: str = "") -> Tuple[Dict[str, Any], str]:
    """Use the licensed FR24 API only; never scrape the consumer website."""
    token = _dome_fr24_token()
    if not token:
        return {}, "API token not configured"
    params: Dict[str, str] = {"limit": "5"}
    registration = _dome_normalize_registration(registration)
    callsign = re.sub(r"[^A-Za-z0-9]", "", str(callsign or "").upper())[:15]
    if registration:
        params["registrations"] = registration
    elif callsign:
        params["callsigns"] = callsign
    else:
        return {}, "No FR24 registration or callsign filter available"
    url = DOME_FR24_API_URL + "?" + urllib.parse.urlencode(params)
    cache_key = "fr24:" + hashlib.sha256(url.encode("utf-8", errors="ignore")).hexdigest()
    now = time.time()
    cached = _DOME_LOOKUP_CACHE.get(cache_key)
    if cached and now - float(cached.get("fetched_at") or 0) < 30:
        cached_data = cached.get("data")
        return (dict(cached_data), "official API cache") if isinstance(cached_data, dict) else ({}, "official API cache empty")
    try:
        request = urllib.request.Request(url, headers={
            "User-Agent": "C8-Dome-FR24/1.0",
            "Accept": "application/json",
            "Accept-Version": "v1",
            "Authorization": "Bearer " + token,
        })
        with _c8_urlopen(request, timeout=8.0) as response:
            raw = response.read(2 * 1024 * 1024 + 1)
            if len(raw) > 2 * 1024 * 1024:
                return {}, "FR24 response exceeded the size limit"
        payload = json.loads(raw.decode("utf-8", errors="replace"))
        rows = payload.get("data") if isinstance(payload, dict) else []
        if not isinstance(rows, list) or not rows:
            return {}, "official API returned no matching live flight"
        row = next((item for item in rows if isinstance(item, dict)), None)
        if not isinstance(row, dict):
            return {}, "official API returned no usable live flight"
        reg = _dome_normalize_registration(row.get("reg") or registration)
        info: Dict[str, Any] = {
            "fr24_id": str(row.get("fr24_id") or "")[:80],
            "flight": str(row.get("flight") or "")[:80],
            "callsign": str(row.get("callsign") or callsign)[:80],
            "icao24": re.sub(r"[^0-9a-f]", "", str(row.get("hex") or "").lower())[:6],
            "registration": reg,
            "tail": reg,
            "lat": row.get("lat"),
            "lon": row.get("lon"),
            "alt_ft": row.get("alt"),
            "spd_kt": row.get("gspeed"),
            "vertical_rate_fpm": row.get("vspeed"),
            "track": row.get("track"),
            "heading": row.get("track"),
            "last_seen": str(row.get("timestamp") or "")[:80],
            "typecode": str(row.get("type") or "")[:80],
            "painted_as": str(row.get("painted_as") or "")[:80],
            "operating_as": str(row.get("operating_as") or "")[:80],
            "origin_iata": str(row.get("orig_iata") or "")[:16],
            "origin_icao": str(row.get("orig_icao") or "")[:16],
            "destination_iata": str(row.get("dest_iata") or "")[:16],
            "destination_icao": str(row.get("dest_icao") or "")[:16],
            "eta": str(row.get("eta") or "")[:80],
            "position_source": str(row.get("source") or "FR24")[:80],
            "squawk": str(row.get("squawk") or "")[:16],
            "aircraft_type": str(row.get("type") or "")[:80],
            "operator_icao": str(row.get("operating_as") or "")[:16],
        }
        info = {key: value for key, value in info.items() if value not in (None, "")}
        _DOME_LOOKUP_CACHE[cache_key] = {"fetched_at": now, "data": info}
        return info, "official API live positions"
    except urllib.error.HTTPError as exc:
        return {}, f"official API HTTP {int(getattr(exc, 'code', 0) or 0)}"
    except Exception:
        return {}, "official API request failed"


def _dome_route_summary(data: Any) -> str:
    dicts = _dome_json_dicts(data)
    def airport(names: Tuple[str, ...]) -> str:
        for mapping in dicts:
            lower = {str(k).lower(): v for k, v in mapping.items()}
            for name in names:
                value = lower.get(name)
                if isinstance(value, dict):
                    code = value.get("icao_code") or value.get("iata_code") or value.get("icao") or value.get("iata") or value.get("airport")
                    city = value.get("name") or value.get("municipality") or value.get("city")
                    if code or city:
                        return " / ".join(str(x) for x in (code, city) if x)
        return ""
    origin = airport(("origin", "departure", "from"))
    destination = airport(("destination", "arrival", "to"))
    callsign = _dome_external_value(dicts, "callsign", "flight", "flight_number")
    airline = _dome_external_value(dicts, "airline", "airline_name")
    parts: List[str] = []
    if callsign:
        parts.append(f"Flight/callsign: {callsign}")
    if airline:
        parts.append(f"Airline/operator: {airline}")
    if origin or destination:
        parts.append(f"Route: {origin or '?'} -> {destination or '?'}")
    return "\n".join(parts)


def _dome_route_details(data: Any) -> Dict[str, Any]:
    dicts = _dome_json_dicts(data)

    def airport(names: Tuple[str, ...]) -> Dict[str, Any]:
        for mapping in dicts:
            lower = {str(k).lower(): v for k, v in mapping.items()}
            for name in names:
                value = lower.get(name)
                if not isinstance(value, dict):
                    continue
                result: Dict[str, Any] = {
                    "icao": str(value.get("icao_code") or value.get("icao") or "").strip(),
                    "iata": str(value.get("iata_code") or value.get("iata") or "").strip(),
                    "name": str(value.get("name") or value.get("airport_name") or "").strip(),
                    "city": str(value.get("municipality") or value.get("city") or "").strip(),
                    "country": str(value.get("country_name") or value.get("country") or "").strip(),
                }
                lat = _dome_float(value.get("latitude"), _dome_float(value.get("lat")))
                lon = _dome_float(value.get("longitude"), _dome_float(value.get("lon"), _dome_float(value.get("lng"))))
                if lat is not None and lon is not None and -90 <= lat <= 90 and -180 <= lon <= 180:
                    result["latitude"] = round(lat, 6)
                    result["longitude"] = round(lon, 6)
                return {k: v for k, v in result.items() if v not in (None, "")}
        return {}

    details: Dict[str, Any] = {
        "origin": airport(("origin", "departure", "from")),
        "destination": airport(("destination", "arrival", "to")),
        "callsign": _dome_external_value(dicts, "callsign", "flight", "flight_number"),
        "airline": _dome_external_value(dicts, "airline", "airline_name", "operator", "operator_name"),
        "flight_number": _dome_external_value(dicts, "flight_number", "flight", "number"),
    }
    return {k: v for k, v in details.items() if v not in (None, "", {}, [])}


def _dome_state_row(state: List[Any]) -> Dict[str, Any]:
    def at(idx: int, default: Any = None) -> Any:
        return state[idx] if idx < len(state) else default
    now_ts = time.time()
    icao = re.sub(r"[^0-9a-f]", "", str(at(0) or "").strip().lower())
    last_contact = _dome_float(at(4))
    time_position = _dome_float(at(3))
    try:
        category_i = int(at(17)) if at(17) is not None else None
    except Exception:
        category_i = None
    row: Dict[str, Any] = {
        "icao24": icao,
        "registration": _icao24_to_n_number(icao),
        "tail": _icao24_to_n_number(icao),
        "unit": "",
        "callsign": str(at(1) or "").strip(),
        "origin_country": str(at(2) or "").strip(),
        "country": str(at(2) or "").strip(),
        "time_position": time_position,
        "last_contact": last_contact,
        "latitude": _dome_float(at(6)),
        "longitude": _dome_float(at(5)),
        "lat": _dome_float(at(6)),
        "lon": _dome_float(at(5)),
        "baro_altitude": _dome_float(at(7)),
        "geo_altitude": _dome_float(at(13)),
        "alt_m": _dome_float(at(7), _dome_float(at(13))),
        "alt_ft": _meters_to_feet(at(7) if at(7) is not None else at(13)),
        "on_ground": bool(at(8)),
        "velocity": _dome_float(at(9)),
        "spd_mps": _dome_float(at(9)),
        "spd_kt": _mps_to_knots(at(9)),
        "spd_mph": _mps_to_mph(at(9)),
        "track": _dome_float(at(10)),
        "heading": _heading_cardinal(at(10)),
        "vertical_rate": _dome_float(at(11)),
        "vertical_rate_fpm": _mps_to_fpm(at(11)),
        "age_s": int(max(0, now_ts - last_contact)) if last_contact is not None else None,
        "adsb_category": _DOME_CATEGORY_LABELS.get(category_i, str(category_i) if category_i is not None else ""),
        "category_code": category_i,
        "model": "",
        "manufacturer": "",
        "operator": "",
        "owner": "",
        "last_seen": _dome_ts_iso(last_contact) if last_contact is not None else "",
        "squawk": str(at(14) or "").strip(),
        "spi": bool(at(15)),
        "position_source": at(16),
        "_received_at": now_ts,
    }
    ownership, reason = _dome_classify_ownership(row)
    row["ownership_category"] = ownership
    row["ownership_category_reason"] = reason
    row["ownership_confidence"] = _dome_classification_confidence(row, ownership, reason)
    row["flight_class"] = _dome_flight_class(row)
    row["movement_status"] = _dome_movement_status(row)
    row["data_completeness"] = _dome_data_completeness(row)
    return row


def _dome_cache_key(region: str, bbox: Tuple[float, float, float, float]) -> str:
    return region.upper() + ":" + ":".join(f"{v:.4f}" for v in bbox)


def _dome_cached_snapshot(cache_key: str, warning: str = "") -> Optional[Dict[str, Any]]:
    cached = _DOME_SNAPSHOT_CACHE.get(cache_key)
    if not cached:
        return None
    response = dict(cached.get("response") or {})
    response["rows"] = [dict(r) for r in response.get("rows") or []]
    response["cached"] = True
    response["cache_age_seconds"] = int(max(0, time.time() - float(cached.get("fetched_at") or time.time())))
    if warning:
        response["warning"] = warning
    return response


def dome_airtrack_snapshot(payload: Dict[str, Any], client: str = "unknown") -> Dict[str, Any]:
    now = time.time()
    bbox, region = _dome_bbox_from_payload(payload)
    mode = str(payload.get("mode") or "manual").strip().lower()
    max_aircraft = int(max(50, min(5000, int(payload.get("max_aircraft") or DOME_MAX_AIRCRAFT_DEFAULT))))
    cache_key = _dome_cache_key(region, bbox)
    min_poll = DOME_MIN_POLL_SECONDS if mode == "state" else DOME_BBOX_MIN_POLL_SECONDS
    force = bool(payload.get("force"))

    with _DOME_FETCH_LOCK:
        global_backoff_until = float(_DOME_BACKOFF_UNTIL.get("__global__") or 0.0)
        if global_backoff_until > now:
            wait = int(math.ceil(global_backoff_until - now))
            cached = _dome_cached_snapshot(cache_key, f"OpenSky global 429 guard is active for {wait}s; showing cached tracks.")
            if cached:
                cached["backoff_seconds_remaining"] = wait
                return cached
            raise ValueError(f"OpenSky global 429 guard: wait {wait} second(s) before polling.")
        if global_backoff_until and global_backoff_until <= now:
            _DOME_BACKOFF_UNTIL.pop("__global__", None)
            _DOME_BACKOFF_SECONDS.pop("__global__", None)
        backoff_until = float(_DOME_BACKOFF_UNTIL.get(cache_key) or 0.0)
        if backoff_until > now:
            wait = int(math.ceil(backoff_until - now))
            cached = _dome_cached_snapshot(cache_key, f"OpenSky 429 guard is active for {wait}s; showing cached tracks.")
            if cached:
                cached["backoff_seconds_remaining"] = wait
                return cached
            raise ValueError(f"OpenSky 429 guard: wait {wait} second(s) before polling this region.")

        cached = _DOME_SNAPSHOT_CACHE.get(cache_key)
        cache_age = now - float((cached or {}).get("fetched_at") or 0.0)
        if cached and not force and cache_age < min_poll:
            result = _dome_cached_snapshot(cache_key, f"429-safe cache reused; next real OpenSky refresh in {int(math.ceil(min_poll - cache_age))}s.")
            if result:
                result["next_real_poll_seconds"] = int(math.ceil(min_poll - cache_age))
                return result

        # No per-user C-8 snapshot throttle. The shared region cache/min-poll above
        # still prevents needless upstream requests, and OpenSky's own 429 backoff
        # remains enforced globally.
        _DOME_LAST_FETCH_BY_CLIENT[client] = now

    params = {
        "lamin": f"{bbox[0]:.6f}", "lomin": f"{bbox[1]:.6f}",
        "lamax": f"{bbox[2]:.6f}", "lomax": f"{bbox[3]:.6f}",
    }
    url = DOME_OPENSKY_URL + "?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers={"User-Agent": "C8-Dome-Web/3.0", "Accept": "application/json"})
    try:
        with _c8_urlopen(req, timeout=20.0) as resp:
            raw = resp.read(6 * 1024 * 1024 + 1)
            if len(raw) > 6 * 1024 * 1024:
                raise ValueError("OpenSky response exceeded the Dome snapshot size limit.")
    except urllib.error.HTTPError as e:
        if int(getattr(e, "code", 0) or 0) == 429:
            with _DOME_FETCH_LOCK:
                previous = max(int(_DOME_BACKOFF_SECONDS.get(cache_key) or 0), int(_DOME_BACKOFF_SECONDS.get("__global__") or 0))
                delay = DOME_INITIAL_429_BACKOFF_SECONDS if previous <= 0 else min(previous * 2, DOME_MAX_429_BACKOFF_SECONDS)
                for key in (cache_key, "__global__"):
                    _DOME_BACKOFF_SECONDS[key] = delay
                    _DOME_BACKOFF_UNTIL[key] = time.time() + delay
            cached = _dome_cached_snapshot(cache_key, f"OpenSky returned HTTP 429; backing off {delay}s and keeping cached live tracks.")
            if cached:
                cached["backoff_seconds_remaining"] = delay
                return cached
            raise ValueError(f"OpenSky returned HTTP 429. Backing off for {delay} seconds.")
        cached = _dome_cached_snapshot(cache_key, f"OpenSky returned HTTP {getattr(e, 'code', 'error')}; showing cached tracks.")
        if cached:
            return cached
        raise ValueError(f"OpenSky returned HTTP {getattr(e, 'code', 'error')}.")
    except Exception as e:
        cached = _dome_cached_snapshot(cache_key, f"OpenSky request failed; showing cached tracks. {e}")
        if cached:
            return cached
        raise ValueError(f"OpenSky snapshot failed: {e}")

    try:
        data = json.loads(raw.decode("utf-8", errors="replace"))
    except Exception as e:
        raise ValueError(f"OpenSky returned invalid JSON: {e}")
    states = data.get("states") if isinstance(data, dict) else []
    if not isinstance(states, list):
        states = []
    rows = [_dome_state_row(s) for s in states if isinstance(s, list)]
    rows = [r for r in rows if r.get("latitude") is not None and r.get("longitude") is not None]
    def _dome_snapshot_priority(row: Dict[str, Any]) -> int:
        category = str(row.get("ownership_category") or "").lower()
        if "government" in category and "military" in category:
            return 0
        if "government" in category:
            return 1
        if "commercial" in category:
            return 2
        return 3
    rows.sort(key=lambda r: (_dome_snapshot_priority(r), r.get("age_s") if r.get("age_s") is not None else 999999, r.get("icao24") or ""))
    rows = rows[:max_aircraft]
    response = {
        "ok": True,
        "region": region,
        "mode": mode,
        "bbox": {"minlat": bbox[0], "minlon": bbox[1], "maxlat": bbox[2], "maxlon": bbox[3]},
        "source": DOME_OPENSKY_URL,
        "time": data.get("time") if isinstance(data, dict) else None,
        "fetched_at": now_iso(),
        "fetched_epoch": time.time(),
        "min_poll_seconds": min_poll,
        "max_aircraft": max_aircraft,
        "aircraft_count": len(rows),
        "rows": rows,
        "cached": False,
        "cache_age_seconds": 0,
    }
    with _DOME_FETCH_LOCK:
        _DOME_SNAPSHOT_CACHE[cache_key] = {"fetched_at": time.time(), "response": response}
        _DOME_BACKOFF_UNTIL.pop(cache_key, None)
        _DOME_BACKOFF_SECONDS.pop(cache_key, None)
    audit("Dome", "airtrack_snapshot", {"region": region, "bbox": bbox, "rows": len(rows), "cached": False})
    return response


def _dome_live_matches(query: str) -> List[Dict[str, Any]]:
    q = str(query or "").strip().lower()
    if not q:
        return []
    matches: Dict[str, Dict[str, Any]] = {}
    with _DOME_FETCH_LOCK:
        snapshots = [dict(v.get("response") or {}) for v in _DOME_SNAPSHOT_CACHE.values()]
    for snapshot in snapshots:
        for row in snapshot.get("rows") or []:
            fields = (row.get("icao24"), row.get("tail"), row.get("registration"), row.get("callsign"), row.get("unit"), row.get("operator"), row.get("owner"))
            if any(q in str(value or "").lower() for value in fields):
                key = str(row.get("icao24") or row.get("tail") or uuid.uuid4().hex)
                matches[key] = dict(row)
    return list(matches.values())[:100]


def dome_aircraft_lookup(payload: Dict[str, Any]) -> Dict[str, Any]:
    query = str(payload.get("query") or payload.get("tail") or payload.get("icao24") or "").strip()
    if not query or len(query) > 120:
        raise ValueError("Enter one tail number, ICAO24 hex, or callsign.")
    compact = re.sub(r"[^A-Za-z0-9]", "", query).upper()
    direct_key = re.sub(r"[^A-Za-z0-9-]", "", query).upper()
    is_hex = bool(re.fullmatch(r"[0-9A-F]{6}", compact))
    normalized_registration = _dome_normalize_registration(direct_key)
    registration = normalized_registration if normalized_registration.startswith("N") else ""
    icao_candidates: List[str] = []
    if is_hex:
        icao_candidates.append(compact.lower())
    if registration.startswith("N"):
        mapped = _dome_n_number_to_icao24(registration)
        if mapped:
            icao_candidates.append(mapped)
    live_matches = _dome_live_matches(query)
    for row in live_matches:
        icao = re.sub(r"[^0-9a-f]", "", str(row.get("icao24") or "").lower())
        if icao and icao not in icao_candidates:
            icao_candidates.append(icao)
        if not registration or not registration.startswith("N"):
            possible = _dome_normalize_registration(row.get("registration") or row.get("tail"))
            if possible:
                registration = possible

    aircraft: Dict[str, Any] = {}
    sources: List[str] = []
    sources_checked: List[str] = ["current Dome/OpenSky cache"]
    queried_adsb_keys: set = set()
    if live_matches:
        aircraft.update({k: v for k, v in live_matches[0].items() if v not in (None, "", [], {})})
        sources.append("current Dome/OpenSky cache")

    if not is_hex and direct_key:
        direct_candidates = [direct_key]
        if normalized_registration.startswith("N") and normalized_registration not in direct_candidates:
            direct_candidates.append(normalized_registration)
        for aircraft_key in direct_candidates[:2]:
            key_lower = aircraft_key.lower()
            if key_lower in queried_adsb_keys:
                continue
            queried_adsb_keys.add(key_lower)
            sources_checked.append(f"ADSBDB aircraft lookup ({aircraft_key})")
            adsb = _dome_fetch_json(DOME_ADSBDB_LOOKUP.format(urllib.parse.quote(aircraft_key)))
            info = _dome_extract_external_info(adsb)
            if not info:
                continue
            aircraft.update(info)
            sources.append("ADSBDB aircraft lookup")
            discovered_registration = _dome_normalize_registration(info.get("registration"))
            if discovered_registration:
                registration = discovered_registration
            discovered_icao = re.sub(r"[^0-9a-f]", "", str(info.get("icao24") or "").lower())[:6]
            if len(discovered_icao) == 6 and discovered_icao not in icao_candidates:
                icao_candidates.insert(0, discovered_icao)
            break

    for icao in icao_candidates[:2]:
        if icao not in queried_adsb_keys:
            queried_adsb_keys.add(icao)
            sources_checked.append(f"ADSBDB aircraft lookup ({icao})")
            adsb = _dome_fetch_json(DOME_ADSBDB_LOOKUP.format(urllib.parse.quote(icao)))
            info = _dome_extract_external_info(adsb)
            if info:
                aircraft.update(info)
                sources.append("ADSBDB aircraft lookup")
        sources_checked.append(f"HexDB aircraft lookup ({icao})")
        hexdb = _dome_fetch_json(DOME_HEXDB_AIRCRAFT_LOOKUP.format(urllib.parse.quote(icao)))
        info2 = _dome_extract_external_info(hexdb)
        if isinstance(hexdb, dict):
            if hexdb.get("Registration"):
                info2.setdefault("registration", _dome_normalize_registration(hexdb.get("Registration")))
                info2.setdefault("tail", info2.get("registration"))
            if hexdb.get("RegisteredOwners"):
                info2.setdefault("owner", str(hexdb.get("RegisteredOwners")))
                info2.setdefault("registered_owner", str(hexdb.get("RegisteredOwners")))
            if hexdb.get("Type"):
                info2.setdefault("model", str(hexdb.get("Type")))
            if hexdb.get("ICAOTypeCode"):
                info2.setdefault("typecode", str(hexdb.get("ICAOTypeCode")))
            if hexdb.get("Manufacturer"):
                info2.setdefault("manufacturer", str(hexdb.get("Manufacturer")))
        if info2:
            aircraft.update(info2)
            sources.append("HexDB aircraft lookup")
        discovered_registration = _dome_normalize_registration(aircraft.get("registration"))
        if discovered_registration:
            registration = discovered_registration

    if icao_candidates:
        aircraft.setdefault("icao24", icao_candidates[0])
        aircraft.setdefault("registration", _icao24_to_n_number(icao_candidates[0]))
        aircraft.setdefault("tail", aircraft.get("registration") or _icao24_to_n_number(icao_candidates[0]))
    if registration:
        aircraft.setdefault("registration", registration)
        aircraft.setdefault("tail", registration)

    callsign = str((live_matches[0].get("callsign") if live_matches else "") or "").strip()
    if not callsign and not is_hex and not registration.startswith("N"):
        callsign = compact
    fr24_info, fr24_status = _dome_fr24_live_lookup(
        str(aircraft.get("registration") or registration or ""),
        callsign,
    )
    sources_checked.append(
        "Flightradar24 official API"
        if _dome_fr24_token()
        else "Flightradar24 official API (token not configured)"
    )
    if fr24_info:
        fr24_icao = re.sub(r"[^0-9a-f]", "", str(fr24_info.get("icao24") or "").lower())
        if fr24_icao and fr24_icao not in icao_candidates:
            icao_candidates.insert(0, fr24_icao)
        if live_matches:
            live_matches[0].update(fr24_info)
        else:
            live_matches.append(dict(fr24_info))
        aircraft.update(fr24_info)
        callsign = str(fr24_info.get("callsign") or callsign).strip()
        sources.append("Flightradar24 official API")
    route: Dict[str, Any] = {}
    if callsign:
        route_data = _dome_fetch_json(DOME_ADSBDB_CALLSIGN_LOOKUP.format(urllib.parse.quote_plus(callsign)))
        summary = _dome_route_summary(route_data)
        source = "ADSBDB callsign"
        if not summary:
            route_data = _dome_fetch_json(DOME_HEXDB_ROUTE_LOOKUP.format(urllib.parse.quote_plus(callsign)))
            summary = _dome_route_summary(route_data)
            source = "HexDB route"
        if summary:
            route = {"summary": summary, "source": source, "details": _dome_route_details(route_data)}
            sources.append(source)
    if not route and fr24_info:
        origin = str(fr24_info.get("origin_icao") or fr24_info.get("origin_iata") or "").strip()
        destination = str(fr24_info.get("destination_icao") or fr24_info.get("destination_iata") or "").strip()
        if origin or destination:
            route = {
                "summary": f"{origin or 'Unknown origin'} -> {destination or 'Unknown destination'}",
                "source": "Flightradar24 official API",
                "details": {
                    "origin": {"icao": str(fr24_info.get("origin_icao") or ""), "iata": str(fr24_info.get("origin_iata") or "")},
                    "destination": {"icao": str(fr24_info.get("destination_icao") or ""), "iata": str(fr24_info.get("destination_iata") or "")},
                    "callsign": str(fr24_info.get("callsign") or callsign or ""),
                    "flight_number": str(fr24_info.get("flight") or ""),
                },
            }

    merged_for_category: Dict[str, Any] = {}
    if live_matches:
        merged_for_category.update(live_matches[0])
    merged_for_category.update(aircraft)
    category, reason = _dome_classify_ownership(merged_for_category)
    if category in {"Unknown", "Operator unconfirmed"}:
        checked_public = [name for name in sources_checked if name != "current Dome/OpenSky cache"]
        if checked_public:
            reason += " Checked: " + ", ".join(checked_public) + "."
    aircraft["ownership_category"] = category
    aircraft["ownership_category_reason"] = reason
    aircraft["ownership_confidence"] = _dome_classification_confidence(merged_for_category, category, reason)
    aircraft["flight_class"] = _dome_flight_class(merged_for_category)
    aircraft["movement_status"] = _dome_movement_status(merged_for_category)
    aircraft["data_completeness"] = _dome_data_completeness({**merged_for_category, **aircraft})

    links: Dict[str, str] = {}
    fr24_registration = _dome_normalize_registration(aircraft.get("registration") or registration)
    if fr24_registration:
        links["Flightradar24 aircraft page"] = DOME_FR24_AIRCRAFT_URL.format(urllib.parse.quote(fr24_registration.lower()))
    links["Flightradar24 live map"] = DOME_FR24_WEB_URL
    if aircraft.get("registration") and str(aircraft.get("registration")).upper().startswith("N"):
        reg = str(aircraft.get("registration")).upper()
        links["FAA N-Number inquiry"] = DOME_FAA_NNUMBER_URL.format(urllib.parse.quote_plus(reg[1:]))
        links["Airport-Data tail search"] = DOME_AIRPORT_DATA_URL.format(urllib.parse.quote_plus(reg))
        links["Similar aircraft images"] = DOME_GOOGLE_IMAGE_URL.format(urllib.parse.quote_plus(reg + " aircraft"))
    if icao_candidates:
        links["OpenSky aircraft profile"] = DOME_OPENSKY_PROFILE_URL.format(urllib.parse.quote_plus(icao_candidates[0]))
    model = aircraft.get("model") or aircraft.get("typecode")
    if model:
        links["Similar model images"] = DOME_GOOGLE_IMAGE_URL.format(urllib.parse.quote_plus(str(model) + " aircraft"))

    result = {
        "ok": True,
        "query": query,
        "normalized": compact,
        "candidate_hexes": icao_candidates,
        "tail": registration,
        "matches": live_matches,
        "live": live_matches[0] if live_matches else None,
        "aircraft": aircraft,
        "route": route,
        "category": category,
        "category_reason": reason,
        "sources": sorted(set(sources)),
        "sources_checked": list(dict.fromkeys(sources_checked)),
        "links": links,
        "flightradar24": {
            "configured": bool(_dome_fr24_token()),
            "used": bool(fr24_info),
            "status": fr24_status,
            "source": "official API",
        },
        "warnings": ([] if aircraft or live_matches or route else ["No live or public lookup details were found for this query."]),
    }
    audit("Dome", "aircraft_lookup", {"query": query[:80], "matches": len(live_matches), "sources": result["sources"]})
    return result


def _external_tool_path(env_name: str, filename: str) -> Path:
    configured = str(os.environ.get(env_name, "") or "").strip()
    candidates = []
    if configured:
        candidates.append(Path(configured).expanduser())
    script_dir = Path(__file__).resolve().parent
    working_dir = Path.cwd().resolve()
    candidates.extend([script_dir / filename, working_dir / filename])
    for base_dir in (script_dir, working_dir):
        for parent_dir in list(base_dir.parents)[:16]:
            candidates.append(parent_dir / filename)
    for candidate in candidates:
        try:
            resolved = candidate.resolve()
        except Exception:
            continue
        if resolved.is_file():
            return resolved
    raise RuntimeError(f"Required tool is unavailable: {filename}")


def _subprocess_json_report(
    command: List[str],
    timeout_seconds: int,
    max_output_bytes: int = 8 * 1024 * 1024,
) -> Dict[str, Any]:
    try:
        completed = subprocess.run(
            command,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=max(10, min(300, int(timeout_seconds))),
            check=False,
            env={**os.environ, "PYTHONIOENCODING": "utf-8"},
        )
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError(f"Tool runtime exceeded {int(timeout_seconds)} seconds.") from exc
    output = str(completed.stdout or "").strip()
    output_limit = max(1024 * 1024, min(32 * 1024 * 1024, int(max_output_bytes)))
    if len(output.encode("utf-8", errors="replace")) > output_limit:
        raise RuntimeError(
            f"Tool output exceeded the {output_limit // (1024 * 1024)} MiB report limit."
        )
    try:
        report = json.loads(output) if output else {}
    except Exception as exc:
        error_text = str(completed.stderr or "").strip()[:1200]
        raise RuntimeError(error_text or "Tool returned an unreadable report.") from exc
    if not isinstance(report, dict):
        raise RuntimeError("Tool returned an invalid report structure.")
    if completed.returncode != 0 or report.get("ok") is False:
        error_text = str(report.get("error") or completed.stderr or "Tool execution failed.").strip()
        raise RuntimeError(error_text[:1600])
    return report


def email_forensics_analyze(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Self-contained bounded defensive email forensics analyzer."""
    from email import policy as _email_policy
    from email.parser import BytesParser as _BytesParser
    from email.utils import getaddresses as _getaddresses, parsedate_to_datetime as _parsedate_to_datetime
    import html as _html
    import unicodedata as _unicodedata

    manual_text = str(payload.get("raw_text") or "")
    if manual_text.strip():
        filename = "manual-email.txt"
        data = manual_text.encode("utf-8", errors="replace")
        source_mode = "manual"
    else:
        filename = safe_filename(str(payload.get("filename") or "message.eml"))
        suffix = Path(filename).suffix.lower()
        if suffix not in {".eml", ".txt", ".email", ".mbox"}:
            raise ValueError("Email Forensics accepts .eml, .txt, .email, or .mbox files.")
        data = decode_upload_b64(str(payload.get("data_b64") or ""))
        source_mode = "upload"
    if not data:
        raise ValueError("Upload an email file or enter email source text.")
    if len(data) > 8 * 1024 * 1024:
        raise ValueError("Email Forensics input is limited to 8 MiB.")

    dns_enabled = bool(payload.get("dns"))
    deep_dns = bool(payload.get("deep_dns")) and dns_enabled
    probe_urls = bool(payload.get("probe_urls"))
    tls_enabled = bool(payload.get("tls"))
    rdap_enabled = bool(payload.get("rdap"))
    max_online_urls = 10
    max_domains = 20

    try:
        message = _BytesParser(policy=_email_policy.default).parsebytes(data)
    except Exception as exc:
        raise ValueError(f"Email message could not be parsed: {exc}") from exc

    def _header(name: str) -> str:
        try:
            return str(message.get(name) or "").strip()[:12000]
        except Exception:
            return ""

    def _unique(values, limit=200):
        out_values = []
        seen = set()
        for value in values:
            s = str(value or "").strip()
            key = s.lower()
            if s and key not in seen:
                seen.add(key)
                out_values.append(s)
            if len(out_values) >= limit:
                break
        return out_values

    def _domain_from_address(value: str) -> str:
        try:
            parsed = _getaddresses([str(value or "")])
            addr = parsed[0][1] if parsed else ""
            return addr.rsplit("@", 1)[1].lower().rstrip(".") if "@" in addr else ""
        except Exception:
            return ""

    def _base_domain(domain: str) -> str:
        parts = [p for p in str(domain or "").lower().strip(".").split(".") if p]
        return ".".join(parts[-2:]) if len(parts) >= 2 else (parts[0] if parts else "")

    def _domains_align(a: str, b: str) -> Dict[str, Any]:
        a = str(a or "").lower().strip(".")
        b = str(b or "").lower().strip(".")
        if not a or not b:
            return {"available": False, "exact": None, "relaxed": None}
        return {"available": True, "exact": a == b, "relaxed": _base_domain(a) == _base_domain(b)}

    def _unicode_security_flags(value: str) -> List[str]:
        flags: List[str] = []
        text = str(value or "")
        scripts = set()
        bidi_controls = {"RLO", "LRO", "RLE", "LRE", "PDF", "RLI", "LRI", "FSI", "PDI"}
        for ch in text:
            if ord(ch) > 127:
                name = _unicodedata.name(ch, "")
                if "LATIN" in name: scripts.add("latin")
                elif "CYRILLIC" in name: scripts.add("cyrillic")
                elif "GREEK" in name: scripts.add("greek")
                elif name: scripts.add("other")
            if _unicodedata.bidirectional(ch) in bidi_controls:
                flags.append("bidi_control_character")
            cat = _unicodedata.category(ch)
            if cat in {"Cf", "Cc"} and ch not in "\r\n\t":
                flags.append("invisible_or_control_character")
        if len({x for x in scripts if x in {"latin", "cyrillic", "greek"}}) >= 2:
            flags.append("mixed_latin_cyrillic_greek_scripts")
        return sorted(set(flags))

    def _decode_idna_domain(domain: str) -> str:
        try:
            return str(domain or "").encode("ascii").decode("idna")
        except Exception:
            return str(domain or "")

    received = [str(v).strip()[:12000] for v in (message.get_all("Received", []) or [])]
    auth_results = [str(v).strip()[:12000] for v in (message.get_all("Authentication-Results", []) or [])]
    received_spf = [str(v).strip()[:12000] for v in (message.get_all("Received-SPF", []) or [])]
    dkim = [str(v).strip()[:12000] for v in (message.get_all("DKIM-Signature", []) or [])]
    arc = [str(v).strip()[:12000] for v in ((message.get_all("ARC-Authentication-Results", []) or []) + (message.get_all("ARC-Seal", []) or []))]

    # Parse authentication verdicts without pretending to cryptographically re-verify signatures.
    auth_statuses: Dict[str, List[str]] = {"spf": [], "dkim": [], "dmarc": [], "arc": []}
    for line in auth_results + received_spf + arc:
        for match in re.finditer(r"\b(spf|dkim|dmarc|arc)\s*=\s*([A-Za-z0-9_-]+)", line, re.I):
            key = match.group(1).lower()
            value = match.group(2).lower()
            if value not in auth_statuses[key]:
                auth_statuses[key].append(value)
    if not auth_statuses["spf"]:
        for line in received_spf:
            match = re.match(r"\s*([A-Za-z0-9_-]+)", line)
            if match:
                auth_statuses["spf"].append(match.group(1).lower())

    auth_identities: Dict[str, List[str]] = {"header_from": [], "smtp_mailfrom": [], "smtp_helo": [], "dkim_header_d": []}
    for line in auth_results + received_spf:
        identity_patterns = {
            "header_from": r"\bheader\.from=([^;\s]+)",
            "smtp_mailfrom": r"\bsmtp\.mailfrom=([^;\s]+)",
            "smtp_helo": r"\bsmtp\.helo=([^;\s]+)",
            "dkim_header_d": r"\bheader\.d=([^;\s]+)",
        }
        for key, pattern in identity_patterns.items():
            for match in re.finditer(pattern, line, re.I):
                value = match.group(1).strip().strip("<>").lower().rstrip(".")
                if "@" in value:
                    value = value.rsplit("@", 1)[-1]
                if value and value not in auth_identities[key]:
                    auth_identities[key].append(value)

    duplicate_security_headers = {}
    for hname in ("From", "Sender", "Reply-To", "Return-Path", "Message-ID", "Subject", "Date"):
        values = message.get_all(hname, []) or []
        if len(values) > 1:
            duplicate_security_headers[hname.lower().replace("-", "_")] = [str(v)[:1000] for v in values[:10]]

    dkim_identities: List[Dict[str, str]] = []
    for sig in dkim:
        d_match = re.search(r"(?:^|;)\s*d\s*=\s*([^;\s]+)", sig, re.I)
        s_match = re.search(r"(?:^|;)\s*s\s*=\s*([^;\s]+)", sig, re.I)
        i_match = re.search(r"(?:^|;)\s*i\s*=\s*([^;\s]+)", sig, re.I)
        item = {
            "domain": (d_match.group(1).strip().lower() if d_match else ""),
            "selector": (s_match.group(1).strip() if s_match else ""),
            "identity": (i_match.group(1).strip() if i_match else ""),
        }
        if any(item.values()):
            dkim_identities.append(item)

    bodies: List[str] = []
    html_parts: List[str] = []
    attachments: List[Dict[str, Any]] = []
    part_count = 0
    high_risk_ext = {".exe", ".dll", ".scr", ".com", ".bat", ".cmd", ".ps1", ".vbs", ".vbe", ".js", ".jse", ".wsf", ".wsh", ".hta", ".msi", ".jar", ".lnk", ".iso", ".img"}
    macro_ext = {".docm", ".xlsm", ".pptm", ".xlam", ".dotm", ".xltm", ".potm", ".ppam", ".sldm"}
    archive_ext = {".zip", ".rar", ".7z", ".gz", ".tgz", ".bz2", ".xz", ".tar"}
    office_ext = {".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx", ".rtf"}

    def _magic_name(blob: bytes) -> str:
        if blob.startswith(b"MZ"): return "PE/Windows executable"
        if blob.startswith(b"\x7fELF"): return "ELF executable"
        if blob.startswith(b"PK\x03\x04"): return "ZIP/OOXML container"
        if blob.startswith(b"%PDF-"): return "PDF"
        if blob.startswith(b"\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1"): return "OLE compound document"
        if blob.startswith(b"Rar!\x1a\x07"): return "RAR archive"
        if blob.startswith(b"7z\xbc\xaf\x27\x1c"): return "7-Zip archive"
        return "Unknown/other"

    for part in message.walk():
        part_count += 1
        ctype = str(part.get_content_type() or "application/octet-stream")
        filename_part = str(part.get_filename() or "").strip()
        disposition = str(part.get_content_disposition() or "")
        try:
            raw_part = part.get_payload(decode=True)
        except Exception:
            raw_part = None
        if filename_part or disposition == "attachment":
            blob = bytes(raw_part or b"")
            safe_name = safe_filename(filename_part or "attachment.bin")
            suffixes = [x.lower() for x in Path(safe_name).suffixes]
            ext = suffixes[-1] if suffixes else ""
            risk_flags = []
            if ext in high_risk_ext:
                risk_flags.append("executable_or_script_extension")
            if ext in macro_ext:
                risk_flags.append("macro_enabled_office_document")
            if ext in archive_ext:
                risk_flags.append("archive_attachment")
            if len(suffixes) >= 2 and suffixes[-2] in {".pdf", ".doc", ".docx", ".jpg", ".jpeg", ".png", ".txt"} and ext in high_risk_ext:
                risk_flags.append("double_extension_disguise")
            magic = _magic_name(blob)
            if magic in {"PE/Windows executable", "ELF executable"} and ext not in {".exe", ".dll", ".elf", ".bin"}:
                risk_flags.append("content_signature_extension_mismatch")
            if ctype.startswith("image/") and magic in {"PE/Windows executable", "ELF executable", "ZIP/OOXML container"}:
                risk_flags.append("mime_type_content_mismatch")
            sample_lower = blob[:2_000_000].lower()
            if magic == "PDF" and any(sig in sample_lower for sig in (b"/javascript", b"/js ", b"/openaction", b"/launch")):
                risk_flags.append("pdf_active_content_indicator")
            if magic == "OLE compound document" and any(sig in sample_lower for sig in (b"vba", b"macros", b"autoopen", b"document_open")):
                risk_flags.append("office_macro_indicator")
            if magic == "ZIP/OOXML container":
                if b"vbaproject.bin" in sample_lower or b"word/vba" in sample_lower or b"xl/vba" in sample_lower:
                    risk_flags.append("ooxml_macro_indicator")
                if b"externalLink".lower() in sample_lower or b"attachedtemplate" in sample_lower:
                    risk_flags.append("ooxml_external_reference_indicator")
            attachments.append({
                "filename": safe_name,
                "extension": ext or "N/A",
                "content_type": ctype,
                "size_bytes": len(blob),
                "md5": hashlib.md5(blob).hexdigest(),
                "sha1": hashlib.sha1(blob).hexdigest(),
                "sha256": hashlib.sha256(blob).hexdigest(),
                "magic_signature": magic,
                "content_disposition": disposition or "attachment",
                "risk_flags": risk_flags,
            })
            continue
        if ctype in {"text/plain", "text/html"}:
            try:
                content = part.get_content()
                if isinstance(content, bytes):
                    content = content.decode(part.get_content_charset() or "utf-8", errors="replace")
                content = str(content)[:500000]
            except Exception:
                content = bytes(raw_part or b"").decode(part.get_content_charset() or "utf-8", errors="replace")[:500000]
            bodies.append(content)
            if ctype == "text/html":
                html_parts.append(content)

    body_text = "\n".join(bodies)
    header_text = "\n".join(f"{k}: {v}" for k, v in message.items())
    searchable = (header_text + "\n" + body_text)[:2_000_000]

    email_re = re.compile(r"\b([A-Z0-9._%+-]{1,64}@[A-Z0-9.-]{1,253}\.[A-Z]{2,63})\b", re.I)
    url_re = re.compile(r"https?://[^\s<>\"'{}|\\^`]+", re.I)
    ipv4_re = re.compile(r"(?<![0-9A-Fa-f:.])(?:\d{1,3}\.){3}\d{1,3}(?![0-9A-Fa-f:.])")

    found_emails = _unique([x.strip(".,;:()[]<>") for x in email_re.findall(searchable)], 250)
    found_urls_raw = _unique([x.rstrip(".,;:!?)]}") for x in url_re.findall(searchable)], 250)

    def _redact_url(url: str) -> str:
        try:
            p = urllib.parse.urlsplit(url)
            query = "REDACTED" if p.query else ""
            fragment = "REDACTED" if p.fragment else ""
            return urllib.parse.urlunsplit((p.scheme, p.netloc, p.path, query, fragment))
        except Exception:
            return "[invalid URL]"

    found_urls = [_redact_url(u) for u in found_urls_raw]
    domains: List[str] = []
    for addr in found_emails:
        domain = addr.rsplit("@", 1)[-1].lower().rstrip(".")
        if domain and domain not in domains:
            domains.append(domain)
    for hname in ("From", "To", "Cc", "Reply-To", "Sender", "Return-Path"):
        for _disp, addr in _getaddresses([str(x) for x in (message.get_all(hname, []) or [])]):
            if "@" in addr:
                d = addr.rsplit("@", 1)[-1].lower().rstrip(".")
                if d and d not in domains:
                    domains.append(d)
    for url in found_urls_raw:
        try:
            host = str(urllib.parse.urlsplit(url).hostname or "").lower().rstrip(".")
        except Exception:
            host = ""
        if host:
            try:
                ipaddress.ip_address(host)
                host_is_ip = True
            except Exception:
                host_is_ip = False
            if not host_is_ip and host not in domains:
                domains.append(host)
    domains = domains[:max_domains]

    ips: List[str] = []
    for raw_ip in ipv4_re.findall(searchable):
        try:
            normalized = str(ipaddress.ip_address(raw_ip))
            if normalized not in ips:
                ips.append(normalized)
        except Exception:
            pass
    # IPv6 literals are intentionally extracted conservatively from bracketed header tokens.
    for token in re.findall(r"\[([0-9A-Fa-f:]{2,})\]", searchable):
        try:
            normalized = str(ipaddress.ip_address(token))
            if normalized not in ips:
                ips.append(normalized)
        except Exception:
            pass
    ips = ips[:150]

    address_headers: Dict[str, List[Dict[str, str]]] = {}
    for hname in ("From", "To", "Cc", "Bcc", "Reply-To", "Sender", "Return-Path"):
        values = message.get_all(hname, []) or []
        parsed = []
        for display, addr in _getaddresses([str(v) for v in values]):
            if display or addr:
                parsed.append({"display_name": str(display)[:500], "address": str(addr)[:500]})
        if parsed:
            address_headers[hname.lower().replace("-", "_")] = parsed[:100]

    from_domain = _domain_from_address(_header("From"))
    reply_domain = _domain_from_address(_header("Reply-To"))
    return_path_domain = _domain_from_address(_header("Return-Path"))
    sender_domain = _domain_from_address(_header("Sender"))
    from_display = ((address_headers.get("from") or [{}])[0].get("display_name") or "")
    subject_text = _header("Subject")
    message_id = _header("Message-ID")
    msgid_match = re.search(r"@([^>\s]+)", message_id)
    message_id_domain = msgid_match.group(1).lower().rstrip(".") if msgid_match else ""
    header_consistency = {
        "from_domain": from_domain or "N/A",
        "reply_to_domain": reply_domain or "N/A",
        "return_path_domain": return_path_domain or "N/A",
        "sender_domain": sender_domain or "N/A",
        "message_id_domain": message_id_domain or "N/A",
        "from_vs_reply_to": _domains_align(from_domain, reply_domain),
        "from_vs_return_path": _domains_align(from_domain, return_path_domain),
        "from_vs_sender": _domains_align(from_domain, sender_domain),
        "from_vs_message_id": _domains_align(from_domain, message_id_domain),
    }

    # Received headers are stored newest-first by convention. Preserve that order and add parsed evidence.
    routing_hops: List[Dict[str, Any]] = []
    parsed_hop_times: List[Any] = []
    for idx, line in enumerate(received):
        from_m = re.search(r"\bfrom\s+(.+?)(?=\s+by\s+)", line, re.I | re.S)
        by_m = re.search(r"\bby\s+(.+?)(?=\s+(?:with|id|for|via)\b|;|$)", line, re.I | re.S)
        with_m = re.search(r"\bwith\s+([^;]+?)(?=\s+(?:id|for|via)\b|;|$)", line, re.I | re.S)
        date_text = line.rsplit(";", 1)[1].strip() if ";" in line else ""
        dt = None
        if date_text:
            try:
                dt = _parsedate_to_datetime(date_text)
                if dt and dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
            except Exception:
                dt = None
        parsed_hop_times.append(dt)
        hop_ips = []
        for candidate in ipv4_re.findall(line) + re.findall(r"\[([0-9A-Fa-f:]{2,})\]", line):
            try:
                normalized = str(ipaddress.ip_address(candidate))
                if normalized not in hop_ips:
                    hop_ips.append(normalized)
            except Exception:
                pass
        ip_details = []
        for value in hop_ips:
            try:
                obj = ipaddress.ip_address(value)
                scope = "global" if obj.is_global else "private/reserved"
            except Exception:
                scope = "unknown"
            ip_details.append({"ip": value, "scope": scope})
        routing_hops.append({
            "header_index_newest_first": idx + 1,
            "from": (from_m.group(1).strip()[:2000] if from_m else "N/A"),
            "by": (by_m.group(1).strip()[:2000] if by_m else "N/A"),
            "with": (with_m.group(1).strip()[:500] if with_m else "N/A"),
            "timestamp": (dt.isoformat() if dt else (date_text or "N/A")),
            "ip_addresses": ip_details,
            "raw": line,
        })
    for idx in range(len(routing_hops) - 1):
        newer = parsed_hop_times[idx]
        older = parsed_hop_times[idx + 1]
        if newer and older:
            try:
                routing_hops[idx]["delay_from_previous_hop_seconds"] = round((newer - older).total_seconds(), 3)
            except Exception:
                pass

    html_blob = "\n".join(html_parts)
    html_stats = {
        "html_parts": len(html_parts),
        "forms": len(re.findall(r"<form\b", html_blob, re.I)),
        "password_fields": len(re.findall(r"<input[^>]+type\s*=\s*[\"']?password\b", html_blob, re.I)),
        "scripts": len(re.findall(r"<script\b", html_blob, re.I)),
        "iframes": len(re.findall(r"<iframe\b", html_blob, re.I)),
        "external_images": len(re.findall(r"<img[^>]+src\s*=\s*[\"']https?://", html_blob, re.I)),
    }
    anchor_mismatches = []
    for match in re.finditer(r"<a\b[^>]*href\s*=\s*[\"'](https?://[^\"']+)[\"'][^>]*>(.*?)</a>", html_blob, re.I | re.S):
        href = match.group(1)
        visible = re.sub(r"<[^>]+>", " ", match.group(2))
        visible = _html.unescape(re.sub(r"\s+", " ", visible)).strip()
        try:
            href_host = str(urllib.parse.urlsplit(href).hostname or "").lower().rstrip(".")
        except Exception:
            href_host = ""
        visible_host_m = re.search(r"(?:https?://)?([A-Z0-9.-]+\.[A-Z]{2,63})", visible, re.I)
        visible_host = visible_host_m.group(1).lower().rstrip(".") if visible_host_m else ""
        if href_host and visible_host and _base_domain(href_host) != _base_domain(visible_host):
            anchor_mismatches.append({"visible_text": visible[:300], "visible_domain": visible_host, "destination_domain": href_host, "url_redacted": _redact_url(href)})
        if len(anchor_mismatches) >= 30:
            break

    shorteners = {"bit.ly", "tinyurl.com", "t.co", "goo.gl", "ow.ly", "buff.ly", "is.gd", "cutt.ly", "rebrand.ly", "shorturl.at", "tiny.one"}
    url_analysis = []
    for original in found_urls_raw:
        try:
            p = urllib.parse.urlsplit(original)
            host = str(p.hostname or "").lower().rstrip(".")
            host_is_ip = False
            try:
                ipaddress.ip_address(host)
                host_is_ip = True
            except Exception:
                pass
            flags = []
            if host_is_ip: flags.append("ip_literal_host")
            if "xn--" in host: flags.append("punycode_domain")
            if p.username or p.password: flags.append("userinfo_in_url")
            if host in shorteners: flags.append("known_url_shortener")
            if p.port and p.port not in {80, 443}: flags.append("non_standard_port")
            if len(host) > 80: flags.append("very_long_hostname")
            if host.count(".") >= 5: flags.append("many_subdomains")
            url_analysis.append({"url_redacted": _redact_url(original), "host": host or "N/A", "scheme": p.scheme, "risk_flags": flags})
        except Exception as exc:
            url_analysis.append({"url_redacted": _redact_url(original), "risk_flags": ["parse_error"], "error": str(exc)[:200]})

    social_terms = {}
    lower_body = body_text.lower()
    for term in ["urgent", "verify your account", "password", "suspended", "invoice", "payment", "gift card", "crypto", "wallet", "wire transfer", "click here", "sign in", "login"]:
        count = lower_body.count(term)
        if count:
            social_terms[term] = count

    findings: List[Dict[str, Any]] = []
    score = 0
    def _finding(severity: str, title: str, evidence: Any, points: int) -> None:
        nonlocal score
        findings.append({"severity": severity, "title": title, "evidence": evidence, "points": points})
        score += int(points)

    auth_fail_values = {"fail", "softfail", "temperror", "permerror"}
    for mech in ("dmarc", "dkim", "spf"):
        bad = [x for x in auth_statuses.get(mech, []) if x in auth_fail_values]
        if bad:
            pts = 25 if mech == "dmarc" else 15
            _finding("high" if mech == "dmarc" else "medium", f"{mech.upper()} reported failure/error", bad, pts)
    if reply_domain and from_domain and not _domains_align(from_domain, reply_domain).get("relaxed"):
        _finding("medium", "Reply-To domain differs from From domain", {"from": from_domain, "reply_to": reply_domain}, 10)
    if return_path_domain and from_domain and not _domains_align(from_domain, return_path_domain).get("relaxed"):
        _finding("low", "Return-Path domain differs from From domain", {"from": from_domain, "return_path": return_path_domain}, 5)
    if "xn--" in from_domain:
        _finding("medium", "From domain contains punycode", {"ascii": from_domain, "unicode": _decode_idna_domain(from_domain)}, 10)
    if duplicate_security_headers:
        _finding("high", "Duplicate security-sensitive email headers", duplicate_security_headers, 20)
    if sender_domain and from_domain and not _domains_align(from_domain, sender_domain).get("relaxed"):
        _finding("medium", "Sender domain differs from visible From domain", {"from": from_domain, "sender": sender_domain}, 10)
    for label, value in (("From display name", from_display), ("Subject", subject_text)):
        unicode_flags = _unicode_security_flags(value)
        if unicode_flags:
            _finding("medium", f"{label} contains Unicode spoofing indicators", {"value": value[:500], "flags": unicode_flags}, 12)
    display_domain_match = re.search(r"([A-Z0-9.-]+\.[A-Z]{2,63})", from_display, re.I)
    if display_domain_match and from_domain:
        claimed = display_domain_match.group(1).lower().rstrip(".")
        if not _domains_align(claimed, from_domain).get("relaxed"):
            _finding("high", "From display name appears to claim a different domain", {"display_name": from_display[:500], "claimed_domain": claimed, "actual_from_domain": from_domain}, 20)
    if from_domain:
        for identity in auth_identities.get("header_from", []):
            if identity and not _domains_align(from_domain, identity).get("relaxed"):
                _finding("medium", "Authentication-Results header.from does not align with visible From", {"from": from_domain, "header_from": identity}, 10)
                break
        dkim_domains = [x.get("domain") for x in dkim_identities if x.get("domain")] + auth_identities.get("dkim_header_d", [])
        if auth_statuses.get("dkim") and any(x == "pass" for x in auth_statuses["dkim"]) and dkim_domains and not any(_domains_align(from_domain, d).get("relaxed") for d in dkim_domains):
            _finding("medium", "DKIM passed but signing domain does not align with visible From", {"from": from_domain, "dkim_domains": _unique(dkim_domains, 20)}, 12)
        mailfrom_domains = auth_identities.get("smtp_mailfrom", [])
        if auth_statuses.get("spf") and any(x == "pass" for x in auth_statuses["spf"]) and mailfrom_domains and not any(_domains_align(from_domain, d).get("relaxed") for d in mailfrom_domains):
            _finding("low", "SPF passed for a domain not aligned with visible From", {"from": from_domain, "smtp_mailfrom": mailfrom_domains[:20]}, 6)
    if message_id and from_domain:
        mid_match = re.search(r"@([^>\s]+)", message_id)
        if mid_match:
            mid_domain = mid_match.group(1).lower().rstrip(".")
            if mid_domain and not _domains_align(from_domain, mid_domain).get("relaxed"):
                _finding("low", "Message-ID domain differs from visible From domain", {"from": from_domain, "message_id_domain": mid_domain}, 4)
    date_header = _header("Date")
    if date_header:
        try:
            msg_date = _parsedate_to_datetime(date_header)
            if msg_date and msg_date.tzinfo is None:
                msg_date = msg_date.replace(tzinfo=timezone.utc)
            if msg_date:
                delta_days = (datetime.now(timezone.utc) - msg_date.astimezone(timezone.utc)).total_seconds() / 86400.0
                if delta_days < -1:
                    _finding("medium", "Message Date is materially in the future", {"date": msg_date.isoformat(), "days_from_now": round(-delta_days, 2)}, 8)
        except Exception:
            _finding("low", "Message Date header could not be parsed", date_header[:500], 2)
    risky_urls = [x for x in url_analysis if x.get("risk_flags")]
    if any("userinfo_in_url" in x.get("risk_flags", []) for x in risky_urls):
        _finding("high", "URL contains embedded userinfo", [x for x in risky_urls if "userinfo_in_url" in x.get("risk_flags", [])][:5], 15)
    if any("ip_literal_host" in x.get("risk_flags", []) for x in risky_urls):
        _finding("medium", "URL points directly to an IP address", [x for x in risky_urls if "ip_literal_host" in x.get("risk_flags", [])][:5], 10)
    if any("punycode_domain" in x.get("risk_flags", []) for x in risky_urls):
        _finding("medium", "URL contains a punycode hostname", [x for x in risky_urls if "punycode_domain" in x.get("risk_flags", [])][:5], 10)
    if anchor_mismatches:
        _finding("medium", "Visible link text domain differs from destination", anchor_mismatches[:10], 15)
    high_attachment_flags = [a for a in attachments if any(f in a.get("risk_flags", []) for f in ("executable_or_script_extension", "macro_enabled_office_document", "content_signature_extension_mismatch", "mime_type_content_mismatch", "double_extension_disguise", "pdf_active_content_indicator", "office_macro_indicator", "ooxml_macro_indicator", "ooxml_external_reference_indicator"))]
    if high_attachment_flags:
        _finding("high", "Attachment requires elevated review", [{"filename": a.get("filename"), "flags": a.get("risk_flags"), "sha256": a.get("sha256")} for a in high_attachment_flags[:10]], min(40, 20 * len(high_attachment_flags)))
    if html_stats["password_fields"] or html_stats["forms"]:
        _finding("medium", "HTML body contains a form/password-input surface", html_stats, 10)
    if not message_id:
        _finding("low", "Message-ID header is absent", "No Message-ID header parsed", 3)
    score = max(0, min(100, score))
    if score >= 60:
        risk_level = "high attention"
    elif score >= 35:
        risk_level = "elevated"
    elif score >= 15:
        risk_level = "moderate"
    else:
        risk_level = "low"

    # Optional DNS enrichment. This does not submit email addresses to reputation services.
    def _dns_records(name: str, qtype: str) -> List[Dict[str, Any]]:
        try:
            fn = globals().get("_ipf_dns_json_records")
            if callable(fn):
                return list(fn(name, qtype) or [])
        except Exception:
            pass
        try:
            q = urllib.parse.urlencode({"name": name, "type": qtype})
            req = urllib.request.Request("https://dns.google/resolve?" + q, headers={"User-Agent": "C8-EmailForensics/3.0", "Accept": "application/json"})
            with _c8_urlopen(req, timeout=5.0) as resp:
                obj = json.loads(resp.read(512_000).decode("utf-8", errors="replace"))
            return [x for x in (obj.get("Answer") or []) if isinstance(x, dict)] if isinstance(obj, dict) else []
        except Exception:
            return []

    def _record_values(rows: List[Dict[str, Any]], limit=40) -> List[str]:
        values = []
        for row in rows or []:
            value = str(row.get("data") or row.get("value") or "").strip()
            if value and value not in values:
                values.append(value)
            if len(values) >= limit:
                break
        return values

    dns_report: Dict[str, Any] = {}
    if dns_enabled:
        for domain in domains:
            item: Dict[str, Any] = {"addresses": [], "aliases": [], "ptr": {}}
            try:
                cname, aliases, addrs = socket.gethostbyname_ex(domain)
                item["canonical_name"] = cname
                item["aliases"] = _unique(aliases, 20)
                item["addresses"] = _unique(addrs, 30)
            except Exception as exc:
                item["resolver_error"] = f"{type(exc).__name__}: {exc}"[:300]
            try:
                infos = socket.getaddrinfo(domain, None, type=socket.SOCK_STREAM)
                for info in infos:
                    addr = str(info[4][0])
                    if addr not in item["addresses"]:
                        item["addresses"].append(addr)
            except Exception:
                pass
            item["addresses"] = item["addresses"][:40]
            if deep_dns:
                item["mx"] = _record_values(_dns_records(domain, "MX"), 30)
                txt_values = _record_values(_dns_records(domain, "TXT"), 50)
                item["txt"] = txt_values
                item["spf"] = [x for x in txt_values if "v=spf1" in x.lower()]
                item["dmarc"] = _record_values(_dns_records("_dmarc." + domain, "TXT"), 20)
                item["mta_sts"] = _record_values(_dns_records("_mta-sts." + domain, "TXT"), 20)
                item["tls_rpt"] = _record_values(_dns_records("_smtp._tls." + domain, "TXT"), 20)
                item["ns"] = _record_values(_dns_records(domain, "NS"), 30)
                for addr in item["addresses"][:10]:
                    try:
                        ip_obj = ipaddress.ip_address(addr)
                        if ip_obj.is_global:
                            item["ptr"][addr] = socket.gethostbyaddr(addr)[0]
                    except Exception:
                        pass
            dns_report[domain] = item
        if deep_dns and dkim_identities:
            dkim_dns = []
            for ident in dkim_identities[:20]:
                d = ident.get("domain") or ""
                s = ident.get("selector") or ""
                if not d or not s:
                    continue
                qname = f"{s}._domainkey.{d}"
                values = _record_values(_dns_records(qname, "TXT"), 10)
                dkim_dns.append({"domain": d, "selector": s, "query": qname, "txt_records": values, "published": bool(values)})
            dns_report["_dkim_selector_checks"] = dkim_dns

    def _public_web_url_allowed(url: str) -> Tuple[bool, str]:
        try:
            parts = urllib.parse.urlsplit(url)
            if parts.scheme.lower() not in {"http", "https"}:
                return False, "non-http-scheme"
            port = parts.port or (443 if parts.scheme.lower() == "https" else 80)
            if port not in {80, 443}:
                return False, "non-standard-port"
        except Exception:
            return False, "invalid-url"
        try:
            ok, reason = _osint_public_profile_host_allowed(url)
            return bool(ok), str(reason)
        except Exception as exc:
            return False, f"validation-error:{exc}"

    class _EmailRedirectHandler(urllib.request.HTTPRedirectHandler):
        def __init__(self):
            super().__init__()
            self.chain: List[Dict[str, Any]] = []
        def redirect_request(self, request, fp, code, msg, headers, newurl):
            resolved = urllib.parse.urljoin(request.full_url, newurl)
            ok, reason = _public_web_url_allowed(resolved)
            self.chain.append({"status_code": int(code or 0), "from": _redact_url(request.full_url), "to": _redact_url(resolved), "allowed": bool(ok), "reason": reason})
            if len(self.chain) > 10:
                raise urllib.error.HTTPError(resolved, 508, "redirect limit", headers, fp)
            if not ok:
                raise urllib.error.HTTPError(resolved, 403, reason, headers, fp)
            return super().redirect_request(request, fp, code, msg, headers, resolved)

    head_report: List[Dict[str, Any]] = []
    if probe_urls:
        for original in found_urls_raw[:max_online_urls]:
            redirect_handler = _EmailRedirectHandler()
            opener = _c8_build_opener(redirect_handler)
            ok, reason = _public_web_url_allowed(original)
            row: Dict[str, Any] = {"url": _redact_url(original), "allowed": ok}
            if not ok:
                row["status"] = "blocked"
                row["reason"] = reason
                head_report.append(row)
                continue
            try:
                req = urllib.request.Request(original, method="HEAD", headers={"User-Agent": "C8-EmailForensics/3.0", "Accept": "*/*"})
                with opener.open(req, timeout=6.0) as resp:
                    final_url_raw = str(getattr(resp, "url", original) or original)
                    row.update({
                        "status": "ok",
                        "status_code": int(getattr(resp, "status", 200) or 200),
                        "final_url": _redact_url(final_url_raw),
                        "content_type": str(resp.headers.get("Content-Type") or "")[:200],
                        "server": str(resp.headers.get("Server") or "")[:200],
                        "redirect_chain": redirect_handler.chain[:10],
                    })
                    try:
                        original_host = str(urllib.parse.urlsplit(original).hostname or "").lower()
                        final_host = str(urllib.parse.urlsplit(final_url_raw).hostname or "").lower()
                        row["cross_domain_redirect"] = bool(original_host and final_host and _base_domain(original_host) != _base_domain(final_host))
                    except Exception:
                        row["cross_domain_redirect"] = False
            except urllib.error.HTTPError as exc:
                row.update({"status": "http-error", "status_code": int(getattr(exc, "code", 0) or 0)})
            except Exception as exc:
                row.update({"status": "error", "error": f"{type(exc).__name__}: {exc}"[:300]})
            head_report.append(row)

    tls_report: Dict[str, Any] = {}
    if tls_enabled:
        for domain in domains[:10]:
            ok, reason = _public_web_url_allowed(f"https://{domain}/")
            if not ok:
                tls_report[domain] = {"status": "blocked", "reason": reason}
                continue
            try:
                ctx = ssl.create_default_context()
                with socket.create_connection((domain, 443), timeout=6.0) as raw_sock:
                    with ctx.wrap_socket(raw_sock, server_hostname=domain) as tls_sock:
                        cert = tls_sock.getpeercert() or {}
                        tls_report[domain] = {
                            "status": "ok",
                            "version": tls_sock.version(),
                            "cipher": tls_sock.cipher(),
                            "subject": cert.get("subject"),
                            "issuer": cert.get("issuer"),
                            "serial_number": cert.get("serialNumber"),
                            "not_before": cert.get("notBefore"),
                            "not_after": cert.get("notAfter"),
                            "subject_alt_names": cert.get("subjectAltName"),
                        }
            except Exception as exc:
                tls_report[domain] = {"status": "error", "error": f"{type(exc).__name__}: {exc}"[:400]}

    rdap_report: Dict[str, Any] = {}
    if rdap_enabled:
        for domain in domains[:10]:
            url = "https://rdap.org/domain/" + urllib.parse.quote(domain, safe="")
            try:
                req = urllib.request.Request(url, headers={"User-Agent": "C8-EmailForensics/3.0", "Accept": "application/rdap+json,application/json"})
                with _c8_urlopen(req, timeout=8.0) as resp:
                    raw = resp.read(1024 * 1024 + 1)
                if len(raw) > 1024 * 1024:
                    raise RuntimeError("RDAP response exceeded 1 MiB")
                obj = json.loads(raw.decode("utf-8", errors="replace"))
                events = (obj.get("events") or [])[:20] if isinstance(obj, dict) else []
                registered_at = None
                age_days = None
                for ev in events:
                    if not isinstance(ev, dict):
                        continue
                    action = str(ev.get("eventAction") or "").lower()
                    if action in {"registration", "registered"}:
                        registered_at = str(ev.get("eventDate") or "")
                        try:
                            dt = datetime.fromisoformat(registered_at.replace("Z", "+00:00"))
                            if dt.tzinfo is None: dt = dt.replace(tzinfo=timezone.utc)
                            age_days = round((datetime.now(timezone.utc) - dt.astimezone(timezone.utc)).total_seconds() / 86400.0, 2)
                        except Exception:
                            pass
                        break
                rdap_report[domain] = {
                    "status": "ok",
                    "handle": obj.get("handle") if isinstance(obj, dict) else None,
                    "ldh_name": obj.get("ldhName") if isinstance(obj, dict) else None,
                    "unicode_name": obj.get("unicodeName") if isinstance(obj, dict) else None,
                    "status_values": obj.get("status") if isinstance(obj, dict) else None,
                    "events": events,
                    "registered_at": registered_at,
                    "domain_age_days": age_days,
                    "nameservers": [x.get("ldhName") for x in (obj.get("nameservers") or [])[:30] if isinstance(x, dict)] if isinstance(obj, dict) else [],
                }
            except Exception as exc:
                rdap_report[domain] = {"status": "error", "error": f"{type(exc).__name__}: {exc}"[:400]}

    # Optional enrichment can strengthen triage, but never becomes a standalone phishing verdict.
    if probe_urls:
        cross_redirects = [x for x in head_report if x.get("cross_domain_redirect")]
        if cross_redirects:
            _finding("medium", "Observed URL redirects to a different registrable domain", cross_redirects[:5], min(15, 5 * len(cross_redirects)))
    if rdap_enabled:
        young_domains = []
        for domain, info in rdap_report.items():
            age = info.get("domain_age_days") if isinstance(info, dict) else None
            if isinstance(age, (int, float)) and 0 <= age < 30:
                young_domains.append({"domain": domain, "age_days": age, "registered_at": info.get("registered_at")})
        if young_domains:
            _finding("medium", "Recently registered domain observed in message", young_domains[:10], min(20, 10 * len(young_domains)))
    score = max(0, min(100, score))
    if score >= 60:
        risk_level = "high attention"
    elif score >= 35:
        risk_level = "elevated"
    elif score >= 15:
        risk_level = "moderate"
    else:
        risk_level = "low"

    authentication_summary = {
        "reported_statuses": auth_statuses,
        "parsed_identities": auth_identities,
        "dkim_signature_identities": dkim_identities,
        "note": "Statuses are parsed from message headers; this analyzer does not claim independent cryptographic verification unless a receiving system recorded it in Authentication-Results.",
    }
    report: Dict[str, Any] = {
        "parser": "C-8 built-in Email / Phishing Forensics v4",
        "summary": {
            "subject": _header("Subject"),
            "date": _header("Date"),
            "message_id": message_id,
            "from": _header("From"),
            "to": _header("To"),
            "reply_to": _header("Reply-To"),
            "return_path": _header("Return-Path"),
            "mime_version": _header("MIME-Version"),
            "content_type": _header("Content-Type"),
            "x_mailer": _header("X-Mailer"),
            "user_agent": _header("User-Agent"),
            "x_originating_ip": _header("X-Originating-IP"),
            "parts": part_count,
            "attachments": len(attachments),
            "received_hops": len(received),
            "domains": len(domains),
            "urls": len(found_urls),
            "risk_score": score,
            "risk_level": risk_level,
        },
        "risk_assessment": {
            "score": score,
            "level": risk_level,
            "findings": findings,
            "method": "Transparent heuristic triage score; it is not a malware/spam verdict and should be reviewed with the underlying evidence.",
        },
        "address_headers": address_headers,
        "duplicate_security_headers": duplicate_security_headers,
        "header_consistency": header_consistency,
        "routing": {
            "received_raw": received,
            "parsed_hops": routing_hops,
            "received_header_order": "newest-first as stored in the message",
        },
        "authentication": {
            "summary": authentication_summary,
            "authentication_results": auth_results,
            "received_spf": received_spf,
            "dkim_signatures": dkim,
            "arc_headers": arc,
        },
        "indicators": {
            "email_addresses": found_emails,
            "domains": domains,
            "ip_addresses": ips,
            "urls_redacted": found_urls,
            "url_analysis": url_analysis,
        },
        "attachments": attachments,
        "body": {
            "text_parts": len(bodies),
            "html_analysis": html_stats,
            "visible_link_destination_mismatches": anchor_mismatches,
            "social_engineering_term_counts": social_terms,
            "combined_text_preview": body_text[:50000],
        },
        "network": {
            "dns": dns_report,
            "url_head_probes": head_report,
            "tls": tls_report,
            "rdap": rdap_report,
        },
        "evidence_quality": {
            "parsed_authentication_headers": bool(auth_results or received_spf or arc),
            "received_hops_parsed": len(routing_hops),
            "attachment_hashes_calculated": len(attachments),
            "network_enrichment_requested": any([dns_enabled, probe_urls, tls_enabled, rdap_enabled]),
            "third_party_reputation_submission": False,
        },
        "notes": [
            "URL query-string and fragment values are redacted in the report.",
            "Attachment hashes and file-signature checks are local and do not execute attachments.",
            "Network enrichment is bounded and only runs for explicitly enabled options.",
            "Private, loopback, link-local, reserved, and non-standard-port URL probe targets are blocked.",
            "Email addresses and message contents are not submitted to third-party reputation APIs by this module.",
        ],
    }

    response = {
        "ok": True,
        "tool": "Email Forensics",
        "filename": filename,
        "source_mode": source_mode,
        "size_bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
        "redaction": "sensitive URL parameter values redacted",
        "network_options": {
            "dns": dns_enabled,
            "deep_dns": deep_dns,
            "url_head_probes": probe_urls,
            "tls": tls_enabled,
            "rdap": rdap_enabled,
            "private_network_access": False,
            "get_fallback": False,
            "third_party_api_enrichment": False,
        },
        "email_report": report,
    }
    audit(
        "Email Forensics",
        "analyze_builtin",
        {
            "filename": filename,
            "source_mode": source_mode,
            "size_bytes": len(data),
            "sha256": response["sha256"],
            "network_options": response["network_options"],
            "attachments": len(attachments),
            "domains": len(domains),
            "urls": len(found_urls),
            "risk_score": score,
            "risk_level": risk_level,
        },
    )
    return response


# Backward-compatible internal alias for older local integrations; the web UI/API use Email Forensics.
def email_deep_analyze(payload: Dict[str, Any]) -> Dict[str, Any]:
    return email_forensics_analyze(payload)


def sub_dominator_scan(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Map likely public sections of one authorized website without helper scripts.

    This is a bounded, robots-aware site mapper. It remains on the selected
    public HTTP(S) host (optionally public subdomains), blocks private/reserved
    destinations and non-standard ports, validates redirects, and enforces
    request/page/byte budgets.
    """
    from html.parser import HTMLParser
    from urllib import robotparser

    if payload.get("authorized") is not True:
        raise ValueError("Confirm that you own or are authorized to assess this site.")

    started = time.time()
    target = str(payload.get("target") or "").strip()
    if not target:
        raise ValueError("Enter the authorized site URL.")
    if len(target) > 2048:
        raise ValueError("The target URL is too long.")
    if "://" not in target:
        target = "https://" + target

    page_cap = 35 if C8_ULTRA_LOW_MEMORY_MODE else (75 if C8_LOW_MEMORY_MODE else 180)
    max_pages = max(1, min(page_cap, int(payload.get("max_pages") or min(30, page_cap))))
    delay = max(0.25, min(5.0, float(payload.get("delay") or 0.75)))
    request_timeout = max(3, min(15, int(payload.get("timeout") or 10)))
    use_sitemaps = payload.get("use_sitemaps") is not False
    use_common_paths = payload.get("use_common_paths") is not False
    include_subdomains = bool(payload.get("include_subdomains"))

    if C8_ULTRA_LOW_MEMORY_MODE:
        max_requests = max_pages + 55
        max_html_bytes = 768 * 1024
        max_xml_bytes = 1024 * 1024
        max_total_bytes = 6 * 1024 * 1024
        max_queue = 500
        max_sitemap_urls = 250
    elif C8_LOW_MEMORY_MODE:
        max_requests = max_pages + 95
        max_html_bytes = 1024 * 1024
        max_xml_bytes = 1536 * 1024
        max_total_bytes = 10 * 1024 * 1024
        max_queue = 900
        max_sitemap_urls = 500
    else:
        max_requests = max_pages + 140
        max_html_bytes = 2 * 1024 * 1024
        max_xml_bytes = 3 * 1024 * 1024
        max_total_bytes = 20 * 1024 * 1024
        max_queue = 2200
        max_sitemap_urls = 900
    user_agent = "C-8-SubDominator/1.1 (+authorized-site-map)"

    parsed_target = urllib.parse.urlsplit(target)
    if parsed_target.scheme.lower() not in {"http", "https"}:
        raise ValueError("Sub-Dominator accepts only http:// or https:// URLs.")
    if parsed_target.username or parsed_target.password:
        raise ValueError("URLs containing embedded credentials are not accepted.")
    base_host = str(parsed_target.hostname or "").strip().lower().rstrip(".")
    if not base_host:
        raise ValueError("The target URL does not contain a valid hostname.")

    def _default_port(scheme: str) -> int:
        return 443 if str(scheme).lower() == "https" else 80

    def _url_port(parts: urllib.parse.SplitResult) -> int:
        try:
            return int(parts.port or _default_port(parts.scheme))
        except Exception:
            return -1

    def _host_in_scope(host: str) -> bool:
        host = str(host or "").strip().lower().rstrip(".")
        if not host:
            return False
        if host == base_host:
            return True
        return include_subdomains and host.endswith("." + base_host)

    def _canonical(url: str) -> str:
        try:
            parts = urllib.parse.urlsplit(str(url or "").strip())
        except Exception:
            return ""
        scheme = parts.scheme.lower()
        host = str(parts.hostname or "").lower().rstrip(".")
        port = _url_port(parts)
        if scheme not in {"http", "https"} or not host or port <= 0:
            return ""
        netloc = f"[{host}]" if ":" in host and not host.startswith("[") else host
        if port != _default_port(scheme):
            netloc += f":{port}"
        path_part = re.sub(r"/{2,}", "/", parts.path or "/")
        return urllib.parse.urlunsplit((scheme, netloc, path_part, parts.query, ""))

    def _validate_url(url: str, *, require_scope: bool = True) -> Tuple[bool, str]:
        try:
            parts = urllib.parse.urlsplit(str(url or "").strip())
        except Exception:
            return False, "invalid-url"
        if parts.scheme.lower() not in {"http", "https"}:
            return False, "non-http-scheme"
        if parts.username or parts.password:
            return False, "embedded-credentials-blocked"
        host = str(parts.hostname or "").strip().lower().rstrip(".")
        if not host:
            return False, "missing-host"
        if _url_port(parts) not in {80, 443}:
            return False, "non-standard-web-port-blocked"
        if require_scope and not _host_in_scope(host):
            return False, "outside-authorized-host-scope"
        ok, reason = _osint_public_profile_host_allowed(url)
        if not ok:
            return False, str(reason)
        return True, host

    first_ok, first_reason = _validate_url(target)
    if not first_ok:
        raise ValueError(f"Target URL is not an allowed public website: {first_reason}.")
    target = _canonical(target)
    target_parts = urllib.parse.urlsplit(target)
    origin = f"{target_parts.scheme}://{target_parts.netloc}"

    class _ScopedRedirectHandler(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, request, fp, code, msg, headers, newurl):
            resolved = urllib.parse.urljoin(request.full_url, newurl)
            ok, reason = _validate_url(resolved)
            if not ok:
                raise urllib.error.HTTPError(resolved, 403, reason, headers, fp)
            redirected = super().redirect_request(request, fp, code, msg, headers, resolved)
            if redirected is not None:
                for key in ("X-C8-Internal-Tool", "X-C8-Internal-Timestamp", "X-C8-Internal-Signature"):
                    try: redirected.remove_header(key)
                    except Exception: pass
                for key, value in _c8_internal_tool_headers("sub-dominator", resolved).items():
                    redirected.add_header(key, value)
            return redirected

    opener = _c8_build_opener(_ScopedRedirectHandler())
    requests_used = 0
    total_bytes = 0
    last_request_at = 0.0
    logs: List[str] = []

    def _log(message: str) -> None:
        logs.append(str(message)[:1000])
        if len(logs) > 700:
            del logs[:100]

    def _throttle() -> None:
        nonlocal last_request_at
        remaining = delay - (time.monotonic() - last_request_at)
        if remaining > 0:
            time.sleep(remaining)
        last_request_at = time.monotonic()

    def _fetch(url: str, *, max_bytes: int, accept: str) -> Tuple[int, str, str, bytes]:
        nonlocal requests_used, total_bytes
        if requests_used >= max_requests:
            raise RuntimeError("Sub-Dominator request budget exhausted.")
        ok, reason = _validate_url(url)
        if not ok:
            raise ValueError(f"Blocked URL: {reason}")
        _throttle()
        request_headers = {
            "User-Agent": user_agent,
            "Accept": accept,
            "Accept-Encoding": "identity",
            "Connection": "close",
        }
        request_headers.update(_c8_internal_tool_headers("sub-dominator", url))
        req = urllib.request.Request(url, headers=request_headers)
        requests_used += 1
        with opener.open(req, timeout=request_timeout) as response:
            final_url = _canonical(response.geturl())
            final_ok, final_reason = _validate_url(final_url)
            if not final_ok:
                raise ValueError(f"Redirected to a blocked URL: {final_reason}")
            status = int(getattr(response, "status", 200) or 200)
            content_type = str(response.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
            data = response.read(int(max_bytes) + 1)
            if len(data) > int(max_bytes):
                raise ValueError("Response exceeded the per-resource size limit.")
            total_bytes += len(data)
            if total_bytes > max_total_bytes:
                raise RuntimeError("Sub-Dominator total download budget exhausted.")
            return status, final_url, content_type, data

    robots = robotparser.RobotFileParser()
    robots_loaded = False
    sitemap_urls: List[str] = []
    robots_url = urllib.parse.urljoin(origin + "/", "robots.txt")
    try:
        status, final_url, content_type, raw = _fetch(
            robots_url,
            max_bytes=512 * 1024,
            accept="text/plain,*/*;q=0.5",
        )
        if status < 400:
            text_robots = raw.decode("utf-8", errors="replace")
            robots.set_url(final_url)
            robots.parse(text_robots.splitlines())
            robots_loaded = True
            _log(f"robots.txt loaded: {final_url}")
            if use_sitemaps:
                for line in text_robots.splitlines():
                    if line.lower().startswith("sitemap:"):
                        candidate = _canonical(line.split(":", 1)[1].strip())
                        ok, _ = _validate_url(candidate)
                        if ok and candidate not in sitemap_urls:
                            sitemap_urls.append(candidate)
    except Exception as exc:
        _log(f"robots.txt unavailable: {type(exc).__name__}: {exc}")

    def _allowed_by_robots(url: str) -> bool:
        if not robots_loaded:
            return True
        try:
            return bool(robots.can_fetch(user_agent, url))
        except Exception:
            return False

    class _PageParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.title_parts: List[str] = []
            self.in_title = False
            self.links: List[Tuple[str, str]] = []
            self._href = ""
            self._anchor_text: List[str] = []
            self._in_anchor = False
            self.meta_description = ""

        def handle_starttag(self, tag, attrs):
            attr = {str(k).lower(): str(v or "") for k, v in attrs}
            tag = str(tag).lower()
            if tag == "title":
                self.in_title = True
            elif tag == "a":
                self._href = attr.get("href", "")
                self._anchor_text = []
                self._in_anchor = True
            elif tag == "meta":
                name = attr.get("name", "").lower()
                prop = attr.get("property", "").lower()
                if (name == "description" or prop == "og:description") and not self.meta_description:
                    self.meta_description = attr.get("content", "")[:500]

        def handle_endtag(self, tag):
            tag = str(tag).lower()
            if tag == "title":
                self.in_title = False
            elif tag == "a" and self._in_anchor:
                anchor = re.sub(r"\s+", " ", " ".join(self._anchor_text)).strip()[:300]
                if self._href:
                    self.links.append((self._href, anchor))
                self._href = ""
                self._anchor_text = []
                self._in_anchor = False

        def handle_data(self, data):
            value = str(data or "")
            if self.in_title:
                self.title_parts.append(value)
            if self._in_anchor:
                self._anchor_text.append(value)

        @property
        def title(self) -> str:
            return re.sub(r"\s+", " ", " ".join(self.title_parts)).strip()[:500]

    section_terms = {
        # Organization / identity
        "about", "about-us", "company", "organization", "organisation", "mission", "vision", "values",
        "history", "story", "leadership", "leaders", "team", "people", "staff", "board", "management",
        "governance", "offices", "locations", "branches", "departments", "divisions", "directory",
        # Contact / help / service
        "contact", "contact-us", "support", "help", "help-center", "faq", "faqs", "questions", "feedback",
        "customer-service", "service-center", "status", "availability", "hours", "appointments", "forms",
        # Products / services / commerce
        "product", "products", "service", "services", "solution", "solutions", "offerings", "features",
        "catalog", "catalogue", "category", "categories", "collection", "collections", "shop", "store",
        "pricing", "plans", "packages", "subscriptions", "marketplace", "inventory", "brands", "vendors",
        # Content / communications
        "blog", "blogs", "news", "press", "media", "newsroom", "announcements", "updates", "stories",
        "article", "articles", "publications", "publication", "reports", "report", "insights", "research",
        "podcast", "podcasts", "videos", "video", "gallery", "galleries", "photos", "multimedia",
        # Documentation / learning
        "docs", "documentation", "guide", "guides", "manual", "manuals", "handbook", "reference",
        "learn", "learning", "education", "training", "tutorial", "tutorials", "courses", "course",
        "knowledge", "knowledge-base", "resources", "resource", "library", "libraries", "downloads", "download",
        "developer", "developers", "api", "apis", "integrations", "integration", "examples", "samples",
        # Events / community / participation
        "events", "event", "calendar", "webinars", "webinar", "meetings", "conference", "conferences",
        "community", "communities", "forum", "forums", "discussion", "discussions", "membership", "members",
        "volunteer", "volunteers", "donate", "donation", "participate", "engage", "outreach",
        # Employment / partners / customers
        "careers", "career", "jobs", "job", "employment", "vacancies", "opportunities", "internships",
        "partners", "partner", "partnerships", "customers", "clients", "case-studies", "case-study",
        "success-stories", "portfolio", "projects", "project", "industries", "industry", "sectors",
        # Government / institutional public sections
        "services-for", "programs", "programmes", "initiatives", "priorities", "policies", "policy",
        "legislation", "regulations", "rules", "notices", "public-notices", "meetings", "minutes", "agendas",
        "records", "public-records", "foia", "open-government", "open-data", "data", "datasets", "statistics",
        "grants", "funding", "contracts", "contracting", "procurement", "tenders", "bids", "suppliers",
        "licenses", "licences", "permits", "applications", "benefits", "eligibility", "complaints",
        # Trust / legal / policy pages
        "privacy", "privacy-policy", "terms", "terms-of-use", "terms-of-service", "legal", "copyright",
        "accessibility", "security", "responsible-disclosure", "disclosure", "compliance", "ethics",
        "cookies", "cookie-policy", "sitemap", "site-map", "archive", "archives",
        # Geography / audiences
        "international", "global", "regional", "regions", "state", "states", "local", "locations",
        "residents", "businesses", "professionals", "students", "parents", "families", "visitors", "media",
    }
    weak_terms = {"home", "index", "page", "view", "details", "item", "post"}

    def _candidate_score(url: str, title: str = "", anchor: str = "", source: str = "crawl") -> Tuple[int, List[str]]:
        parts = urllib.parse.urlsplit(url)
        path_text = urllib.parse.unquote(parts.path or "/").lower()
        tokens = [x for x in re.split(r"[^a-z0-9]+", path_text) if x]
        evidence = " ".join([path_text, str(title or "").lower(), str(anchor or "").lower()])
        score = 0
        reasons: List[str] = []
        hits = sorted({term for term in section_terms if re.search(rf"(?<![a-z0-9]){re.escape(term)}(?![a-z0-9])", evidence)})
        if hits:
            score += min(60, 18 + 10 * len(hits))
            reasons.append("section keywords: " + ", ".join(hits[:5]))
        depth = len([x for x in parts.path.split("/") if x])
        if 1 <= depth <= 3:
            score += 8
            reasons.append(f"navigation depth {depth}")
        if anchor.strip():
            score += 6
            reasons.append("linked from page navigation/content")
        if source == "sitemap":
            score += 12
            reasons.append("published in sitemap")
        elif source == "common-path":
            score += 8
            reasons.append("matched a common public section path")
        if title.strip():
            score += 5
        if any(t in weak_terms for t in tokens) and not hits:
            score -= 4
        if parts.query:
            score -= 5
        return max(0, min(100, score)), reasons

    candidates: Dict[str, Dict[str, Any]] = {}

    def _record_candidate(url: str, *, title: str = "", anchor: str = "", source: str = "crawl", status: int = 200) -> None:
        canonical = _canonical(url)
        if not canonical:
            return
        score, reasons = _candidate_score(canonical, title, anchor, source)
        if score < 12:
            return
        row = candidates.get(canonical)
        if row is None:
            row = {
                "url": canonical,
                "score": score,
                "title": str(title or "")[:500],
                "anchors": str(anchor or "")[:500],
                "sources": source,
                "reasons": "; ".join(reasons),
                "seen": 1,
                "status_code": int(status or 0),
            }
            candidates[canonical] = row
        else:
            row["score"] = max(int(row.get("score") or 0), score)
            if title and not row.get("title"):
                row["title"] = str(title)[:500]
            if anchor:
                existing = str(row.get("anchors") or "")
                if anchor not in existing:
                    row["anchors"] = (existing + (" | " if existing else "") + str(anchor))[:700]
            source_set = [x.strip() for x in str(row.get("sources") or "").split(",") if x.strip()]
            if source not in source_set:
                source_set.append(source)
            row["sources"] = ", ".join(source_set)
            reason_set = [x.strip() for x in str(row.get("reasons") or "").split(";") if x.strip()]
            for reason in reasons:
                if reason not in reason_set:
                    reason_set.append(reason)
            row["reasons"] = "; ".join(reason_set[:8])
            row["seen"] = int(row.get("seen") or 0) + 1

    queue: List[Tuple[str, int, str, str]] = []
    queued: set = set()
    visited: set = set()

    def _enqueue(url: str, depth: int, source: str, anchor: str = "") -> None:
        if len(queue) >= max_queue:
            return
        canonical = _canonical(url)
        if not canonical or canonical in queued or canonical in visited:
            return
        ok, _ = _validate_url(canonical)
        if not ok or not _allowed_by_robots(canonical):
            return
        queued.add(canonical)
        queue.append((canonical, max(0, int(depth)), source, str(anchor or "")[:300]))

    _enqueue(target, 0, "seed")

    if use_common_paths:
        common_paths = [
            # Core organization and contact
            "/about", "/about-us", "/company", "/organization", "/mission", "/vision", "/values",
            "/history", "/leadership", "/leaders", "/team", "/staff", "/people", "/board", "/governance",
            "/departments", "/divisions", "/offices", "/locations", "/directory",
            "/contact", "/contact-us", "/support", "/help", "/help-center", "/faq", "/faqs", "/feedback",
            # Products/services and customer-facing sections
            "/products", "/product", "/services", "/service", "/solutions", "/features", "/pricing", "/plans",
            "/catalog", "/catalogue", "/shop", "/store", "/collections", "/categories", "/marketplace",
            "/customers", "/clients", "/case-studies", "/success-stories", "/industries", "/sectors",
            # Content/news/media
            "/blog", "/news", "/newsroom", "/press", "/media", "/announcements", "/updates", "/articles",
            "/publications", "/reports", "/research", "/insights", "/stories", "/videos", "/gallery", "/podcasts",
            # Documentation/resources/learning
            "/docs", "/documentation", "/guides", "/guide", "/manuals", "/reference", "/resources", "/library",
            "/downloads", "/learn", "/learning", "/education", "/training", "/tutorials", "/courses",
            "/knowledge-base", "/developers", "/developer", "/api", "/integrations", "/examples",
            # Community/events/employment
            "/events", "/calendar", "/meetings", "/webinars", "/conferences", "/community", "/forum", "/forums",
            "/membership", "/members", "/volunteer", "/outreach", "/careers", "/career", "/jobs", "/employment",
            "/opportunities", "/internships", "/partners", "/partnerships", "/portfolio", "/projects",
            # Government/institutional sections
            "/programs", "/programmes", "/initiatives", "/priorities", "/policies", "/policy", "/legislation",
            "/regulations", "/rules", "/notices", "/public-notices", "/agendas", "/minutes", "/records",
            "/public-records", "/foia", "/open-government", "/open-data", "/data", "/datasets", "/statistics",
            "/grants", "/funding", "/contracts", "/contracting", "/procurement", "/tenders", "/bids",
            "/licenses", "/licences", "/permits", "/applications", "/benefits", "/forms", "/complaints",
            # Legal/trust/navigation
            "/privacy", "/privacy-policy", "/terms", "/terms-of-use", "/terms-of-service", "/legal",
            "/accessibility", "/security", "/responsible-disclosure", "/compliance", "/cookies", "/cookie-policy",
            "/sitemap", "/site-map", "/archive", "/archives",
            # Common audience/geographic landing pages
            "/residents", "/businesses", "/professionals", "/students", "/parents", "/families", "/visitors",
            "/international", "/global", "/regional", "/regions", "/states", "/local",
            # Common nested variants
            "/about/leadership", "/about/team", "/about/contact", "/about/history", "/about/mission",
            "/resources/publications", "/resources/reports", "/resources/forms", "/resources/downloads",
            "/news/press-releases", "/news/events", "/media/press", "/media/resources",
            "/services/online", "/services/business", "/services/residents", "/services/visitors",
            "/government/departments", "/government/services", "/government/records", "/government/open-data",
        ]
        for common_path in common_paths:
            _enqueue(urllib.parse.urljoin(origin + "/", common_path.lstrip("/")), 1, "common-path", common_path.strip("/"))

    if use_sitemaps:
        for sitemap_name in (
            "sitemap.xml", "sitemap_index.xml", "sitemap-index.xml", "wp-sitemap.xml",
            "sitemap1.xml", "sitemap-pages.xml", "page-sitemap.xml", "pages-sitemap.xml",
            "sitemap-news.xml", "news-sitemap.xml",
        ):
            default_sitemap = urllib.parse.urljoin(origin + "/", sitemap_name)
            if default_sitemap not in sitemap_urls:
                sitemap_urls.append(default_sitemap)
        seen_sitemaps: set = set()
        sitemap_index = 0
        while sitemap_index < len(sitemap_urls) and sitemap_index < 12 and requests_used < max_requests:
            sitemap_url = sitemap_urls[sitemap_index]
            sitemap_index += 1
            if sitemap_url in seen_sitemaps:
                continue
            seen_sitemaps.add(sitemap_url)
            if not _allowed_by_robots(sitemap_url):
                _log(f"robots.txt disallowed sitemap: {sitemap_url}")
                continue
            try:
                status, final_url, content_type, raw = _fetch(
                    sitemap_url,
                    max_bytes=max_xml_bytes,
                    accept="application/xml,text/xml,text/plain,*/*;q=0.3",
                )
                if status >= 400:
                    continue
                xml = raw.decode("utf-8", errors="replace")
                locs = re.findall(r"<loc\b[^>]*>(.*?)</loc>", xml, flags=re.I | re.S)
                count_added = 0
                for loc in locs:
                    loc = unescape(re.sub(r"\s+", "", loc)).strip()
                    canonical = _canonical(loc)
                    ok, _ = _validate_url(canonical)
                    if not ok:
                        continue
                    if canonical.lower().endswith((".xml", ".xml.gz")) and len(sitemap_urls) < 24:
                        if canonical not in sitemap_urls:
                            sitemap_urls.append(canonical)
                        continue
                    _record_candidate(canonical, source="sitemap")
                    _enqueue(canonical, 1, "sitemap")
                    count_added += 1
                    if count_added >= max_sitemap_urls:
                        break
                _log(f"sitemap parsed: {final_url} ({count_added} in-scope URL(s))")
            except Exception as exc:
                _log(f"sitemap unavailable: {sitemap_url} ({type(exc).__name__}: {exc})")

    visited_pages = 0
    while queue and visited_pages < max_pages and requests_used < max_requests:
        url, depth, source, source_anchor = queue.pop(0)
        queued.discard(url)
        if url in visited:
            continue
        visited.add(url)
        if not _allowed_by_robots(url):
            _log(f"robots.txt disallowed: {url}")
            continue
        try:
            status, final_url, content_type, raw = _fetch(
                url,
                max_bytes=max_html_bytes,
                accept="text/html,application/xhtml+xml,text/plain;q=0.8,*/*;q=0.2",
            )
        except urllib.error.HTTPError as exc:
            _log(f"HTTP {getattr(exc, 'code', 'error')}: {url}")
            continue
        except Exception as exc:
            _log(f"fetch failed: {url} ({type(exc).__name__}: {exc})")
            continue

        if status >= 400:
            _log(f"HTTP {status}: {final_url}")
            continue
        if content_type not in {"text/html", "application/xhtml+xml", "text/plain", ""}:
            _log(f"skipped non-HTML content: {final_url} ({content_type or 'unknown'})")
            continue

        visited_pages += 1
        text_body = raw.decode("utf-8", errors="replace")
        parser = _PageParser()
        try:
            parser.feed(text_body)
        except Exception:
            pass
        title = parser.title
        _record_candidate(final_url, title=title, anchor=source_anchor, source=source, status=status)
        _log(f"visited {visited_pages}/{max_pages}: {final_url} [{status}] {title[:100]}")

        if depth >= 4:
            continue
        for href, anchor_text in parser.links[:1000]:
            href = str(href or "").strip()
            if not href or href.startswith(("#", "mailto:", "tel:", "javascript:", "data:")):
                continue
            absolute = _canonical(urllib.parse.urljoin(final_url, href))
            if not absolute:
                continue
            ok, _ = _validate_url(absolute)
            if not ok:
                continue
            _record_candidate(absolute, anchor=anchor_text, source="crawl")
            if _allowed_by_robots(absolute):
                _enqueue(absolute, depth + 1, "crawl", anchor_text)

    result_rows = sorted(
        candidates.values(),
        key=lambda row: (-int(row.get("score") or 0), -int(row.get("seen") or 0), str(row.get("url") or "")),
    )[:600]
    duration = round(time.time() - started, 3)
    report = {
        "ok": True,
        "tool": "Sub-Dominator",
        "target": target,
        "authorized": True,
        "scope_host": base_host,
        "include_subdomains": include_subdomains,
        "visited_pages": visited_pages,
        "candidate_count": len(result_rows),
        "candidates": result_rows,
        "robots_policy_loaded": robots_loaded,
        "robots_url": robots_url,
        "sitemaps_checked": len(set(sitemap_urls)) if use_sitemaps else 0,
        "requests_used": requests_used,
        "downloaded_bytes": total_bytes,
        "duration_seconds": duration,
        "limits": {
            "max_pages": max_pages,
            "max_requests": max_requests,
            "max_total_bytes": max_total_bytes,
            "request_timeout_seconds": request_timeout,
            "delay_seconds": delay,
            "standard_web_ports_only": True,
            "private_reserved_targets_blocked": True,
        },
        "log": logs,
    }
    audit(
        "Sub-Dominator",
        "authorized_site_scan",
        {
            "target": target[:300],
            "visited_pages": visited_pages,
            "candidate_count": len(result_rows),
            "include_subdomains": include_subdomains,
            "max_pages": max_pages,
            "requests_used": requests_used,
        },
    )
    return {"ok": True, "crawl_results": report}

WEBSITE_COPIER_DOWNLOAD_TTL_SECONDS = max(120, int(os.environ.get("LL_WEB_WEBSITE_COPIER_DOWNLOAD_TTL", "600" if C8_LOW_MEMORY_MODE else "900") or ("600" if C8_LOW_MEMORY_MODE else "900")))
WEBSITE_COPIER_DOWNLOAD_MAX_ITEMS = max(1, min(32, int(os.environ.get("LL_WEB_WEBSITE_COPIER_DOWNLOAD_MAX_ITEMS", "2" if C8_LOW_MEMORY_MODE else "12") or ("2" if C8_LOW_MEMORY_MODE else "12"))))
_WEBSITE_COPIER_DOWNLOAD_LOCK = threading.RLock()
_WEBSITE_COPIER_DOWNLOADS: Dict[str, Dict[str, Any]] = {}
WEBSITE_COPIER_JOB_TTL_SECONDS = 900
WEBSITE_COPIER_MAX_JOBS = 4 if C8_LOW_MEMORY_MODE else 12
WEBSITE_COPIER_ACTIVE_JOB_LIMIT = 1 if C8_LOW_MEMORY_MODE else 2
_WEBSITE_COPIER_JOB_LOCK = threading.RLock()
_WEBSITE_COPIER_JOBS: Dict[str, Dict[str, Any]] = {}


def _website_copier_session_key(session: Dict[str, Any]) -> str:
    token = str((session or {}).get("token") or "")
    if not token:
        raise PermissionError("Authenticated session token is unavailable.")
    return hashlib.sha256(("website-copier|" + token).encode("utf-8", errors="ignore")).hexdigest()


def _website_copier_cleanup_downloads(now: Optional[float] = None) -> None:
    current = float(now if now is not None else time.time())
    expired = [key for key, rec in _WEBSITE_COPIER_DOWNLOADS.items() if current >= float(rec.get("expires_at") or 0)]
    for key in expired:
        _WEBSITE_COPIER_DOWNLOADS.pop(key, None)
    if len(_WEBSITE_COPIER_DOWNLOADS) > WEBSITE_COPIER_DOWNLOAD_MAX_ITEMS:
        ordered = sorted(_WEBSITE_COPIER_DOWNLOADS.items(), key=lambda item: float(item[1].get("created_at") or 0))
        for key, _rec in ordered[:max(0, len(ordered) - WEBSITE_COPIER_DOWNLOAD_MAX_ITEMS)]:
            _WEBSITE_COPIER_DOWNLOADS.pop(key, None)


def _website_copier_store_download(session: Dict[str, Any], archive_payload: Any, filename: str) -> str:
    # r44 keeps the generated ZIP as bytes all the way to the download cache.
    # Older builds base64-encoded the archive only to decode it again here,
    # temporarily using ~33% more memory on small VPS hosts. Base64 remains
    # accepted for compatibility with any older internal caller.
    if isinstance(archive_payload, (bytes, bytearray, memoryview)):
        archive = bytes(archive_payload)
    else:
        try:
            archive = base64.b64decode(str(archive_payload or ""), validate=True)
        except Exception as exc:
            raise RuntimeError("Website Copier produced an invalid ZIP payload.") from exc
    stored_archive_limit = (6 if C8_ULTRA_LOW_MEMORY_MODE else (10 if C8_LOW_MEMORY_MODE else 20)) * 1024 * 1024
    if not archive or len(archive) > stored_archive_limit:
        raise RuntimeError(f"Website Copier ZIP is empty or exceeds the {stored_archive_limit // (1024 * 1024)} MiB server download limit.")
    if not zipfile.is_zipfile(BytesIO(archive)):
        raise RuntimeError("Website Copier output is not a valid ZIP archive.")
    download_token = secrets.token_urlsafe(32)
    now = time.time()
    record = {
        "archive": archive,
        "filename": safe_filename(filename or "website_copy.zip"),
        "session_key": _website_copier_session_key(session),
        "created_at": now,
        "expires_at": now + WEBSITE_COPIER_DOWNLOAD_TTL_SECONDS,
        "sha256": hashlib.sha256(archive).hexdigest(),
    }
    with _WEBSITE_COPIER_DOWNLOAD_LOCK:
        _website_copier_cleanup_downloads(now)
        _WEBSITE_COPIER_DOWNLOADS[download_token] = record
        _website_copier_cleanup_downloads(now)
    return download_token


def _website_copier_get_download(session: Dict[str, Any], download_token: str) -> Tuple[bytes, str, str]:
    token = str(download_token or "").strip()
    if not token or len(token) > 200:
        raise FileNotFoundError("Website Copier download token is invalid.")
    now = time.time()
    with _WEBSITE_COPIER_DOWNLOAD_LOCK:
        _website_copier_cleanup_downloads(now)
        record = _WEBSITE_COPIER_DOWNLOADS.get(token)
        if not record:
            raise FileNotFoundError("Website Copier ZIP expired or was not found. Create the archive again.")
        if not hmac.compare_digest(str(record.get("session_key") or ""), _website_copier_session_key(session)):
            raise PermissionError("This Website Copier ZIP belongs to another authenticated session.")
        archive = bytes(record.get("archive") or b"")
        filename = safe_filename(str(record.get("filename") or "website_copy.zip"))
        sha256_value = str(record.get("sha256") or hashlib.sha256(archive).hexdigest())
    return archive, filename, sha256_value


def _website_copier_cleanup_jobs(now: Optional[float] = None) -> None:
    current = float(now if now is not None else time.time())
    for job_id, job in list(_WEBSITE_COPIER_JOBS.items()):
        if job.get("state") in {"done", "failed"} and current >= float(job.get("expires_at") or 0):
            _WEBSITE_COPIER_JOBS.pop(job_id, None)
    if len(_WEBSITE_COPIER_JOBS) > WEBSITE_COPIER_MAX_JOBS:
        finished = sorted(
            ((job_id, job) for job_id, job in _WEBSITE_COPIER_JOBS.items() if job.get("state") in {"done", "failed"}),
            key=lambda item: float(item[1].get("finished_at") or 0),
        )
        for job_id, _job in finished[:len(_WEBSITE_COPIER_JOBS) - WEBSITE_COPIER_MAX_JOBS]:
            _WEBSITE_COPIER_JOBS.pop(job_id, None)


def _website_copier_job_status(session: Dict[str, Any], job_id: Any) -> Dict[str, Any]:
    clean_id = str(job_id or "").strip()
    if not clean_id or len(clean_id) > 120:
        raise FileNotFoundError("Website Copier job ID is invalid.")
    owner = _website_copier_session_key(session)
    with _WEBSITE_COPIER_JOB_LOCK:
        _website_copier_cleanup_jobs()
        job = _WEBSITE_COPIER_JOBS.get(clean_id)
        if not job:
            raise FileNotFoundError("Website Copier job expired or was lost when the server restarted. Start a new copy.")
        if not hmac.compare_digest(str(job.get("session_key") or ""), owner):
            raise PermissionError("This Website Copier job belongs to another authenticated session.")
        response = {
            "ok": True,
            "job_id": clean_id,
            "state": job["state"],
            "progress": dict(job.get("progress") or {}),
        }
        if job["state"] == "done":
            response["result"] = dict(job.get("result") or {})
        elif job["state"] == "failed":
            response["error"] = str(job.get("error") or "Website Copier could not complete this archive.")
        return response


def _website_copier_job_worker(job_id: str, session_token: str, payload: Dict[str, Any]) -> None:
    def progress(stage: str, pages: int, assets: int, requests: int, message: str) -> None:
        with _WEBSITE_COPIER_JOB_LOCK:
            job = _WEBSITE_COPIER_JOBS.get(job_id)
            if job:
                job["progress"] = {
                    "stage": str(stage)[:40], "pages_saved": int(pages),
                    "assets_saved": int(assets), "requests_used": int(requests),
                    "message": str(message)[:400],
                }

    try:
        with _WEBSITE_COPIER_JOB_LOCK:
            _WEBSITE_COPIER_JOBS[job_id]["state"] = "running"
        with _c8_bounded_network_operation("Website Copier"):
            report = website_copier_copy(payload, progress=progress)
            archive = report.pop("archive_bytes", b"")
            if not isinstance(archive, (bytes, bytearray, memoryview)) or not archive:
                raise RuntimeError("Website Copier did not produce a ZIP payload.")
            download_token = _website_copier_store_download({"token": session_token}, archive, str(report.get("archive_name") or "website_copy.zip"))
            report["download_url"] = "/api/website-copier/download?token=" + urllib.parse.quote(download_token, safe="")
            report["download_expires_seconds"] = WEBSITE_COPIER_DOWNLOAD_TTL_SECONDS
            report["download_ready"] = True
        with _WEBSITE_COPIER_JOB_LOCK:
            job = _WEBSITE_COPIER_JOBS.get(job_id)
            if job:
                job.update(state="done", result=report, finished_at=time.time(), expires_at=time.time() + WEBSITE_COPIER_DOWNLOAD_TTL_SECONDS)
    except Exception as exc:
        if isinstance(exc, (ValueError, RuntimeError, C8SecurityInputError)):
            message = _c8_security_log_text(exc)[:900]
        else:
            message = "Website Copier failed. Check the server log for the error type."
        print(f"Website Copier job {job_id[:12]} failed: {type(exc).__name__}", file=sys.stderr, flush=True)
        with _WEBSITE_COPIER_JOB_LOCK:
            job = _WEBSITE_COPIER_JOBS.get(job_id)
            if job:
                job.update(state="failed", error=message, finished_at=time.time(), expires_at=time.time() + WEBSITE_COPIER_JOB_TTL_SECONDS)
    finally:
        _c8_trim_memory()


def _website_copier_start_job(session: Dict[str, Any], payload: Dict[str, Any]) -> Dict[str, Any]:
    if payload.get("authorized") is not True:
        raise ValueError("Confirm that you own or are authorized to copy this site.")
    target = str(payload.get("target") or "").strip()
    if not target or len(target) > 2048:
        raise ValueError("Enter an authorized public site URL of at most 2048 characters.")
    parts = urllib.parse.urlsplit(target if "://" in target else "https://" + target)
    if parts.scheme.lower() not in {"http", "https"} or not parts.hostname or parts.username or parts.password:
        raise ValueError("Enter an http:// or https:// URL without embedded credentials.")
    owner = _website_copier_session_key(session)
    now = time.time()
    with _WEBSITE_COPIER_JOB_LOCK:
        _website_copier_cleanup_jobs(now)
        active = [job for job in _WEBSITE_COPIER_JOBS.values() if job["state"] in {"queued", "running"}]
        for job in active:
            if hmac.compare_digest(str(job["session_key"]), owner):
                if str(job.get("target") or "") != target:
                    raise RuntimeError("Your previous Website Copier job is still running for another site. Wait for it to finish before starting a new target.")
                return {"ok": True, "job_id": job["id"], "state": job["state"], "poll_seconds": 2.5, "resumed": True}
        if len(active) >= WEBSITE_COPIER_ACTIVE_JOB_LIMIT:
            raise RuntimeError("Another Website Copier job is running. Try again after it completes.")
        job_id = secrets.token_urlsafe(24)
        _WEBSITE_COPIER_JOBS[job_id] = {
            "id": job_id, "session_key": owner, "target": target, "state": "queued", "created_at": now,
            "expires_at": 0, "progress": {"stage": "queued", "pages_saved": 0, "assets_saved": 0, "requests_used": 0},
        }
    try:
        thread = threading.Thread(
            target=_website_copier_job_worker,
            args=(job_id, str(session.get("token") or ""), dict(payload)),
            daemon=True, name="c8-website-copier",
        )
        thread.start()
    except Exception:
        with _WEBSITE_COPIER_JOB_LOCK:
            _WEBSITE_COPIER_JOBS.pop(job_id, None)
        raise
    return {"ok": True, "job_id": job_id, "state": "queued", "poll_seconds": 2.5}


def website_copier_copy(payload: Dict[str, Any], progress: Optional[Any] = None) -> Dict[str, Any]:
    """Create a bounded same-site ZIP archive without external helper scripts.

    The copier is intentionally conservative: authorization must be confirmed,
    only public HTTP(S) destinations on standard web ports are accepted, every
    redirect is revalidated, robots.txt is honored when it can be loaded, and
    page/asset/request/byte budgets are enforced server-side.
    """
    from html.parser import HTMLParser
    from urllib import robotparser

    if payload.get("authorized") is not True:
        raise ValueError("Confirm that you own or are authorized to copy this site.")

    started = time.time()
    target = str(payload.get("target") or "").strip()
    if not target:
        raise ValueError("Enter the authorized public site URL.")
    if len(target) > 2048:
        raise ValueError("The target URL is too long.")
    target_had_explicit_scheme = "://" in target
    if not target_had_explicit_scheme:
        target = "https://" + target

    max_depth = max(0, min(3, int(payload.get("max_depth", 2))))
    copier_page_cap = 8 if C8_ULTRA_LOW_MEMORY_MODE else (14 if C8_LOW_MEMORY_MODE else 40)
    max_pages = max(1, min(copier_page_cap, int(payload.get("max_pages") or min(20, copier_page_cap))))
    delay = max(0.5, min(5.0, float(payload.get("delay") or 1.0)))
    request_timeout = max(3, min(15, int(payload.get("timeout") or 10)))
    include_subdomains = bool(payload.get("include_subdomains"))
    max_runtime_seconds = 360 if C8_ULTRA_LOW_MEMORY_MODE else (600 if C8_LOW_MEMORY_MODE else 900)

    if C8_ULTRA_LOW_MEMORY_MODE:
        max_assets = 48
        max_page_bytes = 768 * 1024
        max_asset_bytes = 1024 * 1024
        max_total_download_bytes = 8 * 1024 * 1024
        max_archive_bytes = 6 * 1024 * 1024
    elif C8_LOW_MEMORY_MODE:
        max_assets = 80
        max_page_bytes = 1024 * 1024
        max_asset_bytes = 2 * 1024 * 1024
        max_total_download_bytes = 12 * 1024 * 1024
        max_archive_bytes = 10 * 1024 * 1024
    else:
        max_assets = 200
        max_page_bytes = 2 * 1024 * 1024
        max_asset_bytes = 4 * 1024 * 1024
        max_total_download_bytes = 24 * 1024 * 1024
        max_archive_bytes = 20 * 1024 * 1024
    max_requests = max_pages + max_assets + 32
    # A browser-compatible UA avoids false negatives on ordinary sites that reject
    # unknown library/default agents. This does not bypass authentication, access
    # controls, robots.txt, or any of the host/network restrictions below.
    user_agent = (
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
        "AppleWebKit/537.36 (KHTML, like Gecko) "
        "Chrome/151.0.0.0 Safari/537.36 C-8-WebsiteCopier/1.2"
    )

    parsed_target = urllib.parse.urlsplit(target)
    if parsed_target.scheme.lower() not in {"http", "https"}:
        raise ValueError("Website Copier accepts only http:// or https:// URLs.")
    if parsed_target.username or parsed_target.password:
        raise ValueError("URLs containing embedded credentials are not accepted.")
    base_host = str(parsed_target.hostname or "").strip().lower().rstrip(".")
    if not base_host:
        raise ValueError("The target URL does not contain a valid hostname.")

    def _default_port(scheme: str) -> int:
        return 443 if scheme.lower() == "https" else 80

    def _url_port(parts: urllib.parse.SplitResult) -> int:
        try:
            return int(parts.port or _default_port(parts.scheme))
        except Exception:
            return -1

    def _host_in_scope(host: str) -> bool:
        h = str(host or "").strip().lower().rstrip(".")
        if not h:
            return False
        if h == base_host:
            return True
        return include_subdomains and h.endswith("." + base_host)

    def _canonical(url: str) -> str:
        parts = urllib.parse.urlsplit(str(url or "").strip())
        scheme = parts.scheme.lower()
        host = str(parts.hostname or "").lower().rstrip(".")
        port = _url_port(parts)
        if not scheme or not host:
            return ""
        netloc = host
        if ":" in host and not host.startswith("["):
            netloc = f"[{host}]"
        if port > 0 and port != _default_port(scheme):
            netloc += f":{port}"
        path = parts.path or "/"
        return urllib.parse.urlunsplit((scheme, netloc, path, parts.query, ""))

    def _validate_url(url: str, *, require_scope: bool = True) -> Tuple[bool, str]:
        try:
            parts = urllib.parse.urlsplit(str(url or "").strip())
        except Exception:
            return False, "invalid-url"
        if parts.scheme.lower() not in {"http", "https"}:
            return False, "non-http-scheme"
        if parts.username or parts.password:
            return False, "embedded-credentials-blocked"
        host = str(parts.hostname or "").strip().lower().rstrip(".")
        if not host:
            return False, "missing-host"
        port = _url_port(parts)
        if port not in {80, 443}:
            return False, "non-standard-web-port-blocked"
        if require_scope and not _host_in_scope(host):
            return False, "outside-authorized-host-scope"
        ok, reason = _osint_public_profile_host_allowed(url)
        if not ok:
            return False, str(reason)
        return True, host

    first_ok, first_reason = _validate_url(target)
    if not first_ok:
        raise ValueError(f"Target URL is not an allowed public website: {first_reason}.")
    target = _canonical(target)

    class _ScopedRedirectHandler(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, request, fp, code, msg, headers, newurl):
            resolved = urllib.parse.urljoin(request.full_url, newurl)
            ok, reason = _validate_url(resolved)
            if not ok:
                raise urllib.error.HTTPError(resolved, 403, reason, headers, fp)
            redirected = super().redirect_request(request, fp, code, msg, headers, resolved)
            if redirected is not None:
                for key in ("X-C8-Internal-Tool", "X-C8-Internal-Timestamp", "X-C8-Internal-Signature"):
                    try: redirected.remove_header(key)
                    except Exception: pass
                for key, value in _c8_internal_tool_headers("website-copier", resolved).items():
                    redirected.add_header(key, value)
            return redirected

    opener = _c8_build_opener(_ScopedRedirectHandler())
    requests_used = 0
    total_downloaded = 0
    logs: List[str] = []
    robots_by_origin: Dict[str, Optional[Any]] = {}
    robots_loaded_any = False

    def _log(message: str) -> None:
        logs.append(str(message)[:1000])
        if len(logs) > 600:
            del logs[:100]

    def _fetch_raw(url: str, max_bytes: int, accept: str) -> Tuple[str, str, bytes, Dict[str, str]]:
        nonlocal requests_used, total_downloaded
        if requests_used >= max_requests:
            raise RuntimeError("Website Copier request budget was exhausted.")
        ok, reason = _validate_url(url)
        if not ok:
            raise ValueError(f"Blocked URL: {reason}")
        requests_used += 1
        request_headers = {
            "User-Agent": user_agent,
            "Accept": accept,
            "Accept-Encoding": "identity",
            "Accept-Language": "en-US,en;q=0.9",
            "Cache-Control": "no-cache",
            "Connection": "close",
        }
        request_headers.update(_c8_internal_tool_headers("website-copier", url))
        req = urllib.request.Request(url, headers=request_headers, method="GET")
        with opener.open(req, timeout=request_timeout) as response:
            status = int(getattr(response, "status", 200) or 200)
            if status >= 400:
                raise RuntimeError(f"HTTP {status}")
            final_url = _canonical(str(getattr(response, "url", url) or url))
            final_ok, final_reason = _validate_url(final_url)
            if not final_ok:
                raise ValueError(f"Blocked redirect destination: {final_reason}")
            data = response.read(int(max_bytes) + 1)
            if len(data) > int(max_bytes):
                raise RuntimeError(f"Response exceeded the {int(max_bytes) // 1024} KiB per-file limit.")
            if total_downloaded + len(data) > max_total_download_bytes:
                raise RuntimeError("Website Copier total download budget was exhausted.")
            total_downloaded += len(data)
            headers = {str(k).lower(): str(v) for k, v in response.headers.items()}
            content_type = str(headers.get("content-type") or "application/octet-stream").split(";", 1)[0].strip().lower()
            return final_url, content_type, data, headers

    def _origin(url: str) -> str:
        parts = urllib.parse.urlsplit(url)
        port = _url_port(parts)
        netloc = str(parts.hostname or "").lower().rstrip(".")
        if ":" in netloc and not netloc.startswith("["):
            netloc = f"[{netloc}]"
        if port != _default_port(parts.scheme):
            netloc += f":{port}"
        return urllib.parse.urlunsplit((parts.scheme.lower(), netloc, "", "", ""))

    def _robots_for(url: str):
        nonlocal robots_loaded_any
        origin = _origin(url)
        if origin in robots_by_origin:
            return robots_by_origin[origin]
        robots_url = origin + "/robots.txt"
        try:
            final_url, _ctype, data, _headers = _fetch_raw(
                robots_url,
                min(512 * 1024, max_page_bytes),
                "text/plain,*/*;q=0.2",
            )
            text = data.decode("utf-8", errors="replace")
            rp = robotparser.RobotFileParser()
            rp.set_url(final_url)
            rp.parse(text.splitlines())
            robots_by_origin[origin] = rp
            robots_loaded_any = True
            _log(f"robots.txt loaded: {final_url}")
            return rp
        except urllib.error.HTTPError as exc:
            if int(getattr(exc, "code", 0) or 0) in {404, 410}:
                robots_by_origin[origin] = None
                _log(f"robots.txt unavailable (HTTP {getattr(exc, 'code', 'error')}): {robots_url}")
                return None
            robots_by_origin[origin] = None
            _log(f"robots.txt could not be loaded: {robots_url} ({exc})")
            return None
        except Exception as exc:
            robots_by_origin[origin] = None
            _log(f"robots.txt could not be loaded: {robots_url} ({exc})")
            return None

    def _robots_allowed(url: str) -> bool:
        rp = _robots_for(url)
        if rp is None:
            return True
        try:
            return bool(rp.can_fetch(user_agent, url))
        except Exception:
            return True

    class _HtmlRefs(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.pages: List[str] = []
            self.assets: List[str] = []
            self.css_chunks: List[str] = []
            self._style_depth = 0

        def handle_starttag(self, tag, attrs):
            attr_map = {str(k).lower(): str(v or "") for k, v in attrs if k}
            tag_l = str(tag or "").lower()
            if tag_l == "a" and attr_map.get("href"):
                self.pages.append(attr_map["href"])
            for key in ("src", "poster"):
                if attr_map.get(key):
                    self.assets.append(attr_map[key])
            if tag_l == "link" and attr_map.get("href"):
                rel = attr_map.get("rel", "").lower()
                if any(word in rel for word in ("stylesheet", "icon", "preload", "manifest")):
                    self.assets.append(attr_map["href"])
            srcset = attr_map.get("srcset", "")
            if srcset:
                for item in srcset.split(","):
                    candidate = item.strip().split()[0] if item.strip() else ""
                    if candidate:
                        self.assets.append(candidate)
            if attr_map.get("style"):
                self.css_chunks.append(attr_map["style"][:200000])
            if tag_l == "style":
                self._style_depth += 1

        def handle_endtag(self, tag):
            if str(tag or "").lower() == "style" and self._style_depth:
                self._style_depth -= 1

        def handle_data(self, data):
            if self._style_depth and data:
                self.css_chunks.append(str(data)[:500000])

    def _resolve_ref(base_url: str, value: str) -> str:
        raw = unescape(str(value or "").strip())
        lower_raw = raw.lower()
        if not raw or lower_raw.startswith(("#", "data:", "javascript:", "mailto:", "tel:", "blob:")):
            return ""
        # Reject JavaScript expressions accidentally captured by CSS-like syntax
        # (for example new URL(document.referrer)).  Real relative/absolute asset
        # references remain accepted.
        if lower_raw.startswith(("document.", "window.", "location.", "navigator.", "event.", "this.")):
            return ""
        if re.fullmatch(r"[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)+", raw):
            return ""
        if any(ch in raw for ch in ("\r", "\n", "{", "}")):
            return ""
        absolute = urllib.parse.urljoin(base_url, raw)
        return _canonical(absolute)

    def _looks_like_page(url: str) -> bool:
        path = urllib.parse.urlsplit(url).path.lower()
        suffix = Path(path).suffix.lower()
        if not suffix:
            return True
        return suffix in {".html", ".htm", ".xhtml", ".php", ".asp", ".aspx", ".jsp", ".cfm"}

    def _looks_like_html_payload(content_type: str, data: bytes) -> Tuple[bool, str]:
        """Accept real HTML even when a server supplies a generic MIME type.

        Some otherwise normal web servers, reverse proxies, object stores, and
        hand-written applications return HTML as text/plain or
        application/octet-stream. We only sniff generic/text MIME responses and
        require recognizable HTML structure before treating them as pages.
        """
        ctype = str(content_type or "").strip().lower()
        if ctype in {"text/html", "application/xhtml+xml"}:
            return True, "declared-html"
        if not data:
            return False, "empty-response"
        sniffable = (
            not ctype
            or ctype.startswith("text/")
            or ctype in {
                "application/octet-stream",
                "binary/octet-stream",
                "application/binary",
                "application/x-httpd-php",
            }
        )
        if not sniffable:
            return False, f"mime:{ctype or 'missing'}"
        sample = bytes(data[:65536]).lstrip(b"\xef\xbb\xbf\x00\t\r\n ").lower()
        markers = (b"<!doctype html", b"<html", b"<head", b"<body", b"<title")
        if any(marker in sample for marker in markers):
            return True, f"sniffed-html:{ctype or 'missing'}"
        return False, f"not-html:{ctype or 'missing'}"

    def _alternate_standard_scheme(url: str) -> str:
        try:
            parts = urllib.parse.urlsplit(url)
            if parts.scheme.lower() == "https":
                return _canonical(urllib.parse.urlunsplit(("http", parts.netloc, parts.path, parts.query, "")))
            if parts.scheme.lower() == "http":
                return _canonical(urllib.parse.urlunsplit(("https", parts.netloc, parts.path, parts.query, "")))
        except Exception:
            pass
        return ""

    def _safe_segment(value: str) -> str:
        value = urllib.parse.unquote(str(value or ""))
        value = re.sub(r"[^A-Za-z0-9._-]+", "_", value).strip("._")
        return value[:96] or "item"

    def _archive_path(url: str, is_page: bool, content_type: str = "") -> str:
        parts = urllib.parse.urlsplit(url)
        host = _safe_segment(str(parts.hostname or base_host))
        raw_parts = [seg for seg in parts.path.split("/") if seg]
        safe_parts = [_safe_segment(seg) for seg in raw_parts]
        if is_page:
            if not safe_parts or parts.path.endswith("/"):
                safe_parts.append("index.html")
            elif not Path(safe_parts[-1]).suffix:
                safe_parts[-1] += ".html"
            elif Path(safe_parts[-1]).suffix.lower() not in {".html", ".htm", ".xhtml"}:
                safe_parts[-1] += ".html"
        else:
            if not safe_parts or parts.path.endswith("/"):
                ext_by_type = {
                    "text/css": ".css", "application/javascript": ".js", "text/javascript": ".js",
                    "image/png": ".png", "image/jpeg": ".jpg", "image/gif": ".gif", "image/webp": ".webp",
                    "image/svg+xml": ".svg", "application/json": ".json", "application/pdf": ".pdf",
                }
                safe_parts.append("asset" + ext_by_type.get(content_type, ".bin"))
        path = "/".join([host] + safe_parts)
        if parts.query:
            stem = Path(path).stem
            suffix = Path(path).suffix
            qhash = hashlib.sha256(parts.query.encode("utf-8", errors="ignore")).hexdigest()[:10]
            path = str(Path(path).with_name(f"{stem}__q_{qhash}{suffix}")).replace("\\", "/")
        return path.replace("\\", "/")[:480]

    page_queue: List[Tuple[str, int]] = [(target, 0)]
    page_seen: set = set()
    asset_candidates: List[str] = []
    asset_seen: set = set()
    page_records: List[Dict[str, Any]] = []
    asset_records: List[Dict[str, Any]] = []
    page_final_seen: set = set()
    implicit_scheme_fallback_queued = False

    def _emit_progress(stage: str, message: str) -> None:
        if callable(progress):
            try:
                progress(stage, len(page_records), len(asset_records), requests_used, message)
            except Exception:
                pass

    _emit_progress("starting", "Checking site permissions and robots.txt.")

    def _should_stop() -> bool:
        if time.time() - started >= max_runtime_seconds:
            _log(f"Stopped at the {max_runtime_seconds}-second server time budget; saving pages and assets collected so far.")
            return True
        if _c8_memory_pressure(0.82 if C8_ULTRA_LOW_MEMORY_MODE else 0.88):
            _log("Stopped early due to server memory pressure; saving pages and assets collected so far.")
            return True
        return False

    def _queue_implicit_scheme_fallback(failed_url: str, reason: str) -> None:
        nonlocal implicit_scheme_fallback_queued
        if target_had_explicit_scheme or implicit_scheme_fallback_queued or page_records:
            return
        alternate = _alternate_standard_scheme(failed_url)
        if not alternate or alternate in page_seen or any(item[0] == alternate for item in page_queue):
            return
        ok, why = _validate_url(alternate)
        if not ok:
            _log(f"Alternate-scheme target was blocked: {alternate} ({why})")
            return
        implicit_scheme_fallback_queued = True
        page_queue.insert(0, (alternate, 0))
        _log(f"Initial HTTPS attempt was unusable ({reason}); trying HTTP on the same authorized host.")

    while page_queue and len(page_records) < max_pages:
        if _should_stop():
            break
        page_url, depth = page_queue.pop(0)
        page_url = _canonical(page_url)
        if not page_url or page_url in page_seen:
            continue
        page_seen.add(page_url)
        ok, reason = _validate_url(page_url)
        if not ok:
            _log(f"Skipped page {page_url}: {reason}")
            continue
        if not _robots_allowed(page_url):
            _log(f"robots.txt disallowed page: {page_url}")
            continue
        if page_records:
            time.sleep(delay)
        try:
            final_url, content_type, data, _headers = _fetch_raw(
                page_url,
                max_page_bytes,
                "text/html,application/xhtml+xml;q=0.9,*/*;q=0.2",
            )
        except Exception as exc:
            detail = f"{type(exc).__name__}: {exc}"
            _log(f"Page fetch failed: {page_url} ({detail})")
            if depth == 0:
                _queue_implicit_scheme_fallback(page_url, detail)
            continue
        is_html, html_reason = _looks_like_html_payload(content_type, data)
        if not is_html:
            _log(f"Skipped non-HTML page response: {final_url} ({content_type or 'missing'}; {html_reason})")
            if depth == 0:
                _queue_implicit_scheme_fallback(page_url, html_reason)
            continue
        final_url = _canonical(final_url)
        if final_url in page_final_seen:
            _log(f"Skipped duplicate final page: {final_url}")
            continue
        page_final_seen.add(final_url)
        if html_reason != "declared-html":
            _log(f"Accepted HTML by content sniffing: {final_url} ({content_type or 'missing'})")
        text = data.decode("utf-8", errors="replace")
        collector = _HtmlRefs()
        try:
            collector.feed(text)
        except Exception:
            pass
        page_records.append({
            "url": final_url,
            "depth": depth,
            "text": text,
            "content_type": content_type,
            "path": _archive_path(final_url, True, content_type),
            "css_chunks": list(collector.css_chunks[:256]),
        })
        _log(f"Saved page {len(page_records)}/{max_pages}: {final_url}")
        _emit_progress("pages", f"Saved page {len(page_records)}/{max_pages}.")

        if depth < max_depth:
            for ref in collector.pages:
                candidate = _resolve_ref(final_url, ref)
                if not candidate or candidate in page_seen or not _looks_like_page(candidate):
                    continue
                allowed, _reason = _validate_url(candidate)
                if allowed and len(page_queue) + len(page_records) < max_pages * 5:
                    page_queue.append((candidate, depth + 1))
        for ref in collector.assets:
            candidate = _resolve_ref(final_url, ref)
            if not candidate or candidate in asset_seen:
                continue
            allowed, _reason = _validate_url(candidate)
            if allowed:
                asset_seen.add(candidate)
                asset_candidates.append(candidate)
                if len(asset_candidates) >= max_assets:
                    break

    if not page_records:
        recent = " | ".join(logs[-8:]) or "No request details were recorded."
        raise RuntimeError(
            "No HTML pages could be archived from the authorized target. "
            "The first page may be unreachable, blocked by robots.txt/access controls, "
            "returning a non-HTML response, or using an invalid TLS certificate. "
            "If the target is this C-8 deployment, r52 uses a signed internal self-site request so its own anti-scrape guard does not block the copier. "
            "For any other site, HTTP 401/403 and robots/access restrictions are intentionally respected. "
            "Try entering the full http:// or https:// URL explicitly. "
            f"Details: {recent}"
        )

    def _css_references(css_text: str) -> List[str]:
        refs: List[str] = []
        # url(...) covers fonts/images and @import url(...). A second expression
        # covers quoted @import "...". Data/blob/javascript references are later
        # rejected by _resolve_ref.
        for match in re.finditer(r"url\(\s*([\"']?)(.*?)\1\s*\)", str(css_text or ""), flags=re.I | re.S):
            value = str(match.group(2) or "").strip()
            if value:
                refs.append(value)
        for match in re.finditer(r"@import\s+(?:url\(\s*)?[\"']([^\"']+)[\"']", str(css_text or ""), flags=re.I):
            value = str(match.group(1) or "").strip()
            if value:
                refs.append(value)
        return refs[:256]

    # Inline style blocks/attributes can reference additional same-site assets.
    # Scan only CSS contexts collected by the HTML parser.  Older builds ran the
    # CSS url(...) regex over the entire HTML/JavaScript body, which could turn
    # JavaScript such as URL(document.referrer) into a bogus asset request.
    for rec in page_records:
        for css_chunk in rec.get("css_chunks") or []:
            for ref in _css_references(css_chunk):
                candidate = _resolve_ref(rec.get("url") or target, ref)
                if not candidate or candidate in asset_seen:
                    continue
                allowed, _reason = _validate_url(candidate)
                if allowed and len(asset_candidates) < max_assets:
                    asset_seen.add(candidate)
                    asset_candidates.append(candidate)

    asset_index = 0
    while asset_index < len(asset_candidates) and len(asset_records) < max_assets and requests_used < max_requests:
        if _should_stop():
            break
        asset_url = asset_candidates[asset_index]
        asset_index += 1
        if not _robots_allowed(asset_url):
            _log(f"robots.txt disallowed asset: {asset_url}")
            continue
        try:
            final_url, content_type, data, _headers = _fetch_raw(
                asset_url,
                max_asset_bytes,
                "text/css,application/javascript,image/*,font/*,application/json,application/pdf,*/*;q=0.4",
            )
        except Exception as exc:
            _log(f"Asset fetch failed: {asset_url} ({exc})")
            continue
        if content_type in {"text/html", "application/xhtml+xml"}:
            _log(f"Skipped asset URL that returned HTML: {final_url}")
            continue
        path = _archive_path(final_url, False, content_type)
        asset_records.append({"url": final_url, "content_type": content_type, "data": data, "path": path})
        _emit_progress("assets", f"Saved asset {len(asset_records)}/{max_assets}.")
        if content_type == "text/css" or str(final_url).lower().split("?", 1)[0].endswith(".css"):
            try:
                css_text = data.decode("utf-8", errors="replace")
                for ref in _css_references(css_text):
                    candidate = _resolve_ref(final_url, ref)
                    if not candidate or candidate in asset_seen:
                        continue
                    allowed, _reason = _validate_url(candidate)
                    if allowed and len(asset_candidates) < max_assets:
                        asset_seen.add(candidate)
                        asset_candidates.append(candidate)
            except Exception as exc:
                _log(f"CSS dependency discovery failed: {final_url} ({exc})")

    # Allocate final unique ZIP paths before creating the URL map. This fixes a
    # stale-link bug from older builds where collision-renamed files were written
    # under a different path than the one HTML rewrites pointed at.
    used_paths: set = set()

    def _unique_path(path: str) -> str:
        candidate = path
        counter = 2
        while candidate.lower() in used_paths:
            pth = Path(path)
            candidate = str(pth.with_name(f"{pth.stem}_{counter}{pth.suffix}")).replace("\\", "/")
            counter += 1
        used_paths.add(candidate.lower())
        return candidate

    for rec in page_records:
        rec["path"] = _unique_path(rec["path"])
    for rec in asset_records:
        rec["path"] = _unique_path(rec["path"])

    url_to_path: Dict[str, str] = {}
    for rec in page_records:
        url_to_path[_canonical(rec["url"])] = rec["path"]
    for rec in asset_records:
        url_to_path[_canonical(rec["url"])] = rec["path"]

    def _relative_archived_url(source_url: str, source_path: str, raw_value: str) -> str:
        resolved = _resolve_ref(source_url, raw_value)
        local = url_to_path.get(resolved)
        if not local:
            return ""
        try:
            return os.path.relpath(local, start=str(Path(source_path).parent)).replace("\\", "/")
        except Exception:
            return local

    attr_pattern = re.compile(
        r"(?P<prefix>\b(?:href|src|poster)\s*=\s*)(?P<quote>[\"'])(?P<value>.*?)(?P=quote)",
        flags=re.I | re.S,
    )
    srcset_pattern = re.compile(
        r"(?P<prefix>\bsrcset\s*=\s*)(?P<quote>[\"'])(?P<value>.*?)(?P=quote)",
        flags=re.I | re.S,
    )

    def _rewrite_css(css_text: str, source_url: str, source_path: str) -> str:
        def repl_url(match):
            quote = match.group(1) or ""
            raw = str(match.group(2) or "").strip()
            relative = _relative_archived_url(source_url, source_path, raw)
            if not relative:
                return match.group(0)
            return f"url({quote}{relative}{quote})"
        return re.sub(r"url\(\s*([\"']?)(.*?)\1\s*\)", repl_url, str(css_text or ""), flags=re.I | re.S)

    def _rewrite_html(text: str, page_url: str, page_path: str) -> str:
        def replace_attr(match):
            raw = match.group("value")
            relative = _relative_archived_url(page_url, page_path, raw)
            if not relative:
                return match.group(0)
            return f"{match.group('prefix')}{match.group('quote')}{relative}{match.group('quote')}"

        def replace_srcset(match):
            rewritten = []
            changed = False
            for entry in str(match.group("value") or "").split(","):
                bits = entry.strip().split()
                if not bits:
                    continue
                relative = _relative_archived_url(page_url, page_path, bits[0])
                if relative:
                    bits[0] = relative
                    changed = True
                rewritten.append(" ".join(bits))
            if not changed:
                return match.group(0)
            return f"{match.group('prefix')}{match.group('quote')}{', '.join(rewritten)}{match.group('quote')}"

        rewritten = attr_pattern.sub(replace_attr, str(text or ""))
        rewritten = srcset_pattern.sub(replace_srcset, rewritten)
        # Covers style attributes and <style> blocks with the same bounded URL map.
        rewritten = _rewrite_css(rewritten, page_url, page_path)
        return rewritten

    _emit_progress("archive", "Packaging collected pages and assets into a ZIP.")
    buffer = BytesIO()
    manifest: List[Dict[str, Any]] = []

    with zipfile.ZipFile(buffer, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=6) as zf:
        for rec in page_records:
            path = rec["path"]
            content = _rewrite_html(rec["text"], rec["url"], path).encode("utf-8", errors="replace")
            zf.writestr(path, content)
            manifest.append({"path": path, "size_bytes": len(content), "type": "page", "url": rec["url"]})
        for rec in asset_records:
            path = rec["path"]
            content = rec["data"]
            if rec.get("content_type") == "text/css" or str(rec.get("url") or "").lower().split("?", 1)[0].endswith(".css"):
                try:
                    content = _rewrite_css(content.decode("utf-8", errors="replace"), rec["url"], path).encode("utf-8")
                except Exception:
                    content = rec["data"]
            zf.writestr(path, content)
            manifest.append({"path": path, "size_bytes": len(content), "type": rec["content_type"] or "asset", "url": rec["url"]})
        start_path = page_records[0]["path"] if page_records else ""
        if start_path:
            start_doc = (
                "<!doctype html><html><head><meta charset=\"utf-8\"><title>C-8 Website Archive</title></head>"
                "<body><h1>C-8 Website Archive</h1><p>This archive contains an authorized static copy.</p>"
                f"<p><a href=\"{escape(start_path, quote=True)}\">Open archived start page</a></p></body></html>"
            ).encode("utf-8")
            zf.writestr("C8_START_HERE.html", start_doc)
            manifest.append({"path": "C8_START_HERE.html", "size_bytes": len(start_doc), "type": "archive-entry", "url": target})
        metadata = {
            "created_at": now_iso(),
            "target": target,
            "host": base_host,
            "authorized": True,
            "include_subdomains": include_subdomains,
            "max_depth": max_depth,
            "max_pages": max_pages,
            "pages_saved": len(page_records),
            "assets_saved": len(asset_records),
            "robots_loaded": robots_loaded_any,
            "requests_used": requests_used,
            "downloaded_bytes": total_downloaded,
        }
        zf.writestr("c8_archive_manifest.json", json.dumps(metadata, indent=2, sort_keys=True).encode("utf-8"))

    archive = buffer.getvalue()
    if len(archive) > max_archive_bytes:
        raise RuntimeError(
            f"Website archive exceeded the {max_archive_bytes // (1024 * 1024)} MiB ZIP response limit. "
            "Lower the page count or link depth."
        )
    archive_sha256 = hashlib.sha256(archive).hexdigest()
    archive_name = _safe_segment(base_host) + "_website_copy.zip"
    duration = round(max(0.0, time.time() - started), 3)
    report = {
        "ok": True,
        "host": base_host,
        "target": target,
        "pages_saved": len(page_records),
        "assets_saved": len(asset_records),
        "files_saved": len(manifest) + 1,
        "archive_name": archive_name,
        "archive_size_bytes": len(archive),
        "archive_sha256": archive_sha256,
        # Private route-only field. The request handler removes this before JSON
        # serialization and stores it behind a short-lived session-bound token.
        "archive_bytes": archive,
        "manifest": manifest,
        "robots_loaded": robots_loaded_any,
        "requests_used": requests_used,
        "downloaded_bytes": total_downloaded,
        "duration_seconds": duration,
        "log": "\n".join(logs[-500:]) or "Archive completed.",
        "limits": {
            "max_depth": max_depth,
            "max_pages": max_pages,
            "max_assets": max_assets,
            "max_requests": max_requests,
            "max_page_bytes": max_page_bytes,
            "max_asset_bytes": max_asset_bytes,
            "max_total_download_bytes": max_total_download_bytes,
            "max_archive_bytes": max_archive_bytes,
            "max_runtime_seconds": max_runtime_seconds,
            "standard_web_ports_only": True,
            "public_networks_only": True,
        },
    }
    audit(
        "Website Copier",
        "authorized_site_copy",
        {
            "host": base_host[:255],
            "pages_saved": len(page_records),
            "files_saved": int(report["files_saved"]),
            "archive_size_bytes": len(archive),
            "archive_sha256": archive_sha256,
            "include_subdomains": include_subdomains,
            "max_depth": max_depth,
            "max_pages": max_pages,
        },
    )
    return report



# ============================================================================
# STEGANO WEB — STEGv4-compatible browser module
# ============================================================================
# This is a self-contained web adaptation of the user's Stegano v4.5 format.
# Uploaded carrier/payload bytes are processed in memory. Generated artifacts are
# exposed only through short-lived, authenticated, session-bound download tokens.
STEG_MAGIC = b"STEGv4"
STEG_VERSION = 4
STEG_FLAG_COMPRESSED = 0x01
STEG_FLAG_ENCRYPTED = 0x02
STEG_FLAG_FEC = 0x04
STEG_FLAG_SHUFFLED = 0x08
STEG_FLAG_AAD = 0x10
STEG_FLAG_SCRYPT = 0x20
STEG_SALT_LEN = 16
STEG_NONCE_LEN = 12
STEG_DIGEST_LEN = 32
STEG_PBKDF2_ITERATIONS = 600_000
STEG_SCRYPT_N = 1 << 15
STEG_SCRYPT_R = 8
STEG_SCRYPT_P = 1
STEG_RS_NSYM = 32
STEG_RS_DATA_CHUNK = 255 - STEG_RS_NSYM
STEG_MAX_FILENAME_BYTES = 1024
STEG_HEADER_STRUCT = struct.Struct(">6sBBBBHQQQI16s12s32s")
STEG_FIXED_HEADER_SIZE = STEG_HEADER_STRUCT.size
STEG_MAX_IMAGE_BYTES = (6 if C8_ULTRA_LOW_MEMORY_MODE else 8) * 1024 * 1024
STEG_MAX_PAYLOAD_BYTES = (2 if C8_ULTRA_LOW_MEMORY_MODE else (3 if C8_LOW_MEMORY_MODE else 4)) * 1024 * 1024
STEG_MAX_OUTPUT_BYTES = (10 if C8_ULTRA_LOW_MEMORY_MODE else (14 if C8_LOW_MEMORY_MODE else 24)) * 1024 * 1024
STEG_DOWNLOAD_TTL_SECONDS = max(120, int(os.environ.get("LL_WEB_STEGANO_DOWNLOAD_TTL", "300" if C8_LOW_MEMORY_MODE else "900") or ("300" if C8_LOW_MEMORY_MODE else "900")))
STEG_DOWNLOAD_MAX_ITEMS = max(2, min(24, int(os.environ.get("LL_WEB_STEGANO_DOWNLOAD_MAX_ITEMS", "4" if C8_LOW_MEMORY_MODE else "12") or ("4" if C8_LOW_MEMORY_MODE else "12"))))
_STEG_DOWNLOAD_LOCK = threading.RLock()
_STEG_DOWNLOADS: Dict[str, Dict[str, Any]] = {}

try:
    from cryptography.hazmat.primitives import hashes as _steg_hashes
    from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC as _StegPBKDF2HMAC
    from cryptography.hazmat.primitives.kdf.scrypt import Scrypt as _StegScrypt
    _STEG_CRYPTO_KDF_AVAILABLE = True
except Exception:
    _steg_hashes = None
    _StegPBKDF2HMAC = None
    _StegScrypt = None
    _STEG_CRYPTO_KDF_AVAILABLE = False

try:
    import reedsolo as _steg_reedsolo
    _STEG_REEDSOLO_AVAILABLE = True
except Exception:
    _steg_reedsolo = None
    _STEG_REEDSOLO_AVAILABLE = False


def _steg_safe_filename(name: Any, fallback: str = "extracted.bin") -> str:
    value = os.path.basename(str(name or "").replace("\x00", "")).strip()
    if not value or value in {".", ".."}:
        value = fallback
    for ch in '<>:"/\\|?*':
        value = value.replace(ch, "_")
    return value[:240] or fallback


def _steg_decode_upload(value: Any, label: str, limit: int) -> bytes:
    text = str(value or "").strip()
    if not text:
        raise ValueError(f"{label} is required.")
    if text.startswith("data:") and "," in text:
        text = text.split(",", 1)[1]
    if len(text) > ((int(limit) + 2) // 3) * 4 + 256:
        raise C8SecurityInputError(f"{label} is too large.")
    try:
        data = base64.b64decode(text, validate=True)
    except Exception as exc:
        raise ValueError(f"{label} is not valid base64 upload data.") from exc
    if not data:
        raise ValueError(f"{label} is empty.")
    if len(data) > int(limit):
        raise ValueError(f"{label} exceeds the {int(limit)//(1024*1024)} MiB web limit.")
    return data


class _StegRGBAImage:
    __slots__ = ("width", "height", "size", "_rgba")

    def __init__(self, width: int, height: int, rgba: bytes):
        self.width = int(width)
        self.height = int(height)
        self.size = (self.width, self.height)
        expected = self.width * self.height * 4
        if self.width <= 0 or self.height <= 0 or len(rgba) != expected:
            raise ValueError("Invalid RGBA image buffer.")
        self._rgba = bytes(rgba)

    def tobytes(self) -> bytes:
        return self._rgba


def _steg_png_paeth(a: int, b: int, c: int) -> int:
    p = a + b - c
    pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
    if pa <= pb and pa <= pc:
        return a
    return b if pb <= pc else c


def _steg_png_unpack_samples(row: bytes, width: int, bit_depth: int) -> List[int]:
    if bit_depth == 8:
        return list(row[:width])
    if bit_depth == 16:
        return [row[i * 2] << 8 | row[i * 2 + 1] for i in range(width)]
    if bit_depth not in (1, 2, 4):
        raise ValueError(f"Unsupported PNG bit depth: {bit_depth}.")
    mask = (1 << bit_depth) - 1
    out: List[int] = []
    for byte in row:
        shift = 8 - bit_depth
        while shift >= 0 and len(out) < width:
            out.append((byte >> shift) & mask)
            shift -= bit_depth
        if len(out) >= width:
            break
    return out


def _steg_png_decode_rgba(data: bytes) -> _StegRGBAImage:
    if not data.startswith(b"\x89PNG\r\n\x1a\n"):
        raise ValueError("Built-in image fallback accepts PNG files only.")
    pos = 8
    width = height = bit_depth = color_type = interlace = None
    palette = b""
    transparency = b""
    idat = bytearray()
    while pos + 12 <= len(data):
        length = struct.unpack(">I", data[pos:pos + 4])[0]
        ctype = data[pos + 4:pos + 8]
        start = pos + 8
        end = start + length
        if end + 4 > len(data):
            raise ValueError("PNG chunk is truncated.")
        chunk = data[start:end]
        if ctype == b"IHDR":
            if length != 13:
                raise ValueError("Invalid PNG IHDR.")
            width, height, bit_depth, color_type, compression, filter_method, interlace = struct.unpack(">IIBBBBB", chunk)
            if compression != 0 or filter_method != 0:
                raise ValueError("Unsupported PNG compression/filter method.")
        elif ctype == b"PLTE":
            palette = bytes(chunk)
        elif ctype == b"tRNS":
            transparency = bytes(chunk)
        elif ctype == b"IDAT":
            idat.extend(chunk)
        elif ctype == b"IEND":
            break
        pos = end + 4
    if not width or not height or bit_depth is None or color_type is None:
        raise ValueError("PNG is missing a valid IHDR.")
    if interlace != 0:
        raise ValueError("Interlaced PNG requires Pillow; save or upload a non-interlaced PNG.")
    if color_type not in (0, 2, 3, 4, 6):
        raise ValueError(f"Unsupported PNG color type: {color_type}.")
    if color_type == 3:
        if bit_depth not in (1, 2, 4, 8):
            raise ValueError("Unsupported indexed PNG bit depth.")
        channels = 1
    else:
        channels = {0: 1, 2: 3, 4: 2, 6: 4}[color_type]
        if bit_depth not in (8, 16):
            raise ValueError("Built-in PNG fallback supports 8/16-bit grayscale/RGB/RGBA images.")
    if int(width) * int(height) > 8_000_000:
        raise C8SecurityInputError("PNG pixel count exceeds the decoder budget.")
    row_bytes = (int(width) * channels * int(bit_depth) + 7) // 8
    bpp = max(1, (channels * int(bit_depth) + 7) // 8)
    try:
        raw = _c8_bounded_inflate(bytes(idat), int(height) * (row_bytes + 1))
    except Exception as exc:
        raise ValueError(f"PNG IDAT decompression failed: {exc}") from exc
    expected = int(height) * (row_bytes + 1)
    if len(raw) != expected:
        raise ValueError("PNG pixel stream is truncated.")
    rows: List[bytes] = []
    previous = bytearray(row_bytes)
    offset = 0
    for _y in range(int(height)):
        ftype = raw[offset]
        offset += 1
        scan = bytearray(raw[offset:offset + row_bytes])
        offset += row_bytes
        recon = bytearray(row_bytes)
        for x in range(row_bytes):
            a = recon[x - bpp] if x >= bpp else 0
            b = previous[x]
            c = previous[x - bpp] if x >= bpp else 0
            val = scan[x]
            if ftype == 0:
                out = val
            elif ftype == 1:
                out = (val + a) & 0xFF
            elif ftype == 2:
                out = (val + b) & 0xFF
            elif ftype == 3:
                out = (val + ((a + b) // 2)) & 0xFF
            elif ftype == 4:
                out = (val + _steg_png_paeth(a, b, c)) & 0xFF
            else:
                raise ValueError(f"Unsupported PNG row filter: {ftype}.")
            recon[x] = out
        rows.append(bytes(recon))
        previous = recon

    rgba = bytearray(int(width) * int(height) * 4)
    out_pos = 0
    for row in rows:
        if color_type == 6:
            step = 4 if bit_depth == 8 else 8
            for x in range(int(width)):
                i = x * step
                if bit_depth == 8:
                    r, g, b, a = row[i:i + 4]
                else:
                    r, g, b, a = row[i], row[i + 2], row[i + 4], row[i + 6]
                rgba[out_pos:out_pos + 4] = bytes((r, g, b, a)); out_pos += 4
        elif color_type == 2:
            step = 3 if bit_depth == 8 else 6
            transparent_rgb = None
            if len(transparency) >= 6:
                transparent_rgb = struct.unpack(">HHH", transparency[:6])
            for x in range(int(width)):
                i = x * step
                if bit_depth == 8:
                    r, g, b = row[i], row[i + 1], row[i + 2]
                    raw_rgb = (r, g, b)
                else:
                    raw_rgb = (row[i] << 8 | row[i + 1], row[i + 2] << 8 | row[i + 3], row[i + 4] << 8 | row[i + 5])
                    r, g, b = row[i], row[i + 2], row[i + 4]
                a = 0 if transparent_rgb is not None and raw_rgb == transparent_rgb else 255
                rgba[out_pos:out_pos + 4] = bytes((r, g, b, a)); out_pos += 4
        elif color_type == 4:
            step = 2 if bit_depth == 8 else 4
            for x in range(int(width)):
                i = x * step
                if bit_depth == 8:
                    g, a = row[i], row[i + 1]
                else:
                    g, a = row[i], row[i + 2]
                rgba[out_pos:out_pos + 4] = bytes((g, g, g, a)); out_pos += 4
        elif color_type == 0:
            samples = _steg_png_unpack_samples(row, int(width), int(bit_depth))
            max_sample = (1 << int(bit_depth)) - 1
            transparent_gray = struct.unpack(">H", transparency[:2])[0] if len(transparency) >= 2 else None
            for sample in samples:
                g = sample >> 8 if bit_depth == 16 else int(round(sample * 255 / max_sample))
                a = 0 if transparent_gray is not None and sample == transparent_gray else 255
                rgba[out_pos:out_pos + 4] = bytes((g, g, g, a)); out_pos += 4
        else:  # indexed
            if len(palette) < 3:
                raise ValueError("Indexed PNG is missing its palette.")
            indices = _steg_png_unpack_samples(row, int(width), int(bit_depth))
            for index in indices:
                pi = index * 3
                if pi + 2 >= len(palette):
                    raise ValueError("PNG palette index is out of range.")
                a = transparency[index] if index < len(transparency) else 255
                rgba[out_pos:out_pos + 4] = bytes((palette[pi], palette[pi + 1], palette[pi + 2], a)); out_pos += 4
    return _StegRGBAImage(int(width), int(height), bytes(rgba))


def _steg_png_chunk(kind: bytes, payload: bytes) -> bytes:
    crc = binascii.crc32(kind)
    crc = binascii.crc32(payload, crc) & 0xFFFFFFFF
    return struct.pack(">I", len(payload)) + kind + payload + struct.pack(">I", crc)


def _steg_png_encode_rgba(width: int, height: int, rgba: bytes) -> bytes:
    width, height = int(width), int(height)
    expected = width * height * 4
    if width <= 0 or height <= 0 or len(rgba) != expected:
        raise ValueError("Invalid RGBA data for PNG output.")
    raw = bytearray()
    stride = width * 4
    for y in range(height):
        raw.append(0)
        raw.extend(rgba[y * stride:(y + 1) * stride])
    ihdr = struct.pack(">IIBBBBB", width, height, 8, 6, 0, 0, 0)
    return b"\x89PNG\r\n\x1a\n" + _steg_png_chunk(b"IHDR", ihdr) + _steg_png_chunk(b"IDAT", zlib.compress(bytes(raw), 6)) + _steg_png_chunk(b"IEND", b"")


def _steg_open_rgba(data: bytes):
    # Prefer Pillow when it is already present because it supports JPEG/WebP/etc.
    # The STEGv4 web path does not *require* Pillow: a built-in PNG decoder is
    # always available, which is enough for generated stego files and browser-
    # normalized carriers.
    if _ensure_pillow_available() and Image is not None:
        try:
            img = _c8_image_open(BytesIO(data))
            img.load()
            rgba = img.convert("RGBA")
            return _StegRGBAImage(rgba.width, rgba.height, rgba.tobytes())
        except Exception as pil_exc:
            if not data.startswith(b"\x89PNG\r\n\x1a\n"):
                raise ValueError(f"Could not open the uploaded image: {pil_exc}") from pil_exc
    try:
        return _steg_png_decode_rgba(data)
    except Exception as exc:
        detail = f" Pillow load error: {_PIL_INSTALL_ERROR}" if _PIL_INSTALL_ERROR else ""
        raise ValueError(f"Could not open the uploaded image with the built-in PNG decoder.{detail} {exc}".strip()) from exc


def _steg_validate_lsb(value: Any) -> int:
    n = int(value)
    if n not in (1, 2, 3, 4):
        raise ValueError("LSB bits must be 1, 2, 3, or 4.")
    return n


def _steg_validate_redundancy(value: Any) -> int:
    n = int(value)
    if n not in (1, 3, 5):
        raise ValueError("Redundancy must be 1, 3, or 5.")
    return n


def _steg_normalize_kdf(value: Any) -> str:
    name = str(value or "scrypt").strip().lower().replace("_", "-")
    if name in {"scrypt", "scrypt-recommended"}:
        return "scrypt"
    if name in {"pbkdf2", "pbkdf2-sha256", "compat", "compatibility"}:
        return "pbkdf2"
    raise ValueError("KDF must be scrypt or pbkdf2.")


def _steg_derive_key(password: str, salt: bytes, kdf_name: str) -> bytes:
    if AESGCM is None or not _STEG_CRYPTO_KDF_AVAILABLE:
        raise RuntimeError("Encrypted Stegano payloads require the Python 'cryptography' package.")
    if not password or len(password) > 1024:
        raise ValueError("Password cannot be empty for encryption.")
    name = _steg_normalize_kdf(kdf_name)
    if name == "scrypt":
        kdf = _StegScrypt(salt=salt, length=32, n=STEG_SCRYPT_N, r=STEG_SCRYPT_R, p=STEG_SCRYPT_P)
    else:
        kdf = _StegPBKDF2HMAC(algorithm=_steg_hashes.SHA256(), length=32, salt=salt, iterations=STEG_PBKDF2_ITERATIONS)
    return kdf.derive(password.encode("utf-8"))


def _steg_build_aad(filename: str, plaintext_size: int, lsb_bits: int, redundancy: int, flags: int) -> bytes:
    fn = _steg_safe_filename(filename, "message.txt").encode("utf-8", errors="replace")[:STEG_MAX_FILENAME_BYTES]
    stable = flags & (STEG_FLAG_COMPRESSED | STEG_FLAG_ENCRYPTED | STEG_FLAG_FEC | STEG_FLAG_SHUFFLED | STEG_FLAG_AAD | STEG_FLAG_SCRYPT)
    return b"STEGv4/AAD\0" + struct.pack(">QBBB", int(plaintext_size), int(lsb_bits), int(redundancy), stable) + fn


def _steg_seed(password: str, salt: bytes) -> int:
    return int.from_bytes(hashlib.sha256(password.encode("utf-8") + salt + b"/stegv4/shuffle").digest()[:16], "big")


def _steg_total_carriers(img: Any) -> int:
    return int(img.width) * int(img.height) * 3


def _steg_carrier_offset(carrier_no: int) -> int:
    pixel = carrier_no // 3
    return pixel * 4 + (carrier_no % 3)


def _steg_slots_needed(byte_count: int, lsb_bits: int) -> int:
    return 0 if byte_count <= 0 else (int(byte_count) * 8 + int(lsb_bits) - 1) // int(lsb_bits)


def _steg_raw_capacity(img: Any, lsb_bits: int) -> int:
    return (_steg_total_carriers(img) * _steg_validate_lsb(lsb_bits)) // 8


def _steg_affine_params(n: int, seed: int) -> Tuple[int, int]:
    if n <= 1:
        return 1, 0
    rng = __import__("random").Random(seed)
    a = rng.randrange(1, n)
    if a % 2 == 0:
        a += 1
    a %= n
    if a == 0:
        a = 1
    attempts = 0
    while math.gcd(a, n) != 1:
        a = (a + 2) % n
        if a == 0:
            a = 1
        attempts += 1
        if attempts > 100000:
            a = 1
            break
    return a, rng.randrange(0, n)


def _steg_body_carriers(total: int, header_slots: int, shuffled: bool, seed: Optional[int]):
    n = int(total) - int(header_slots)
    if n < 0:
        return
    if not shuffled:
        for k in range(n):
            yield header_slots + k
        return
    if seed is None:
        raise ValueError("A shuffle seed is required for shuffled payloads.")
    a, b = _steg_affine_params(n, seed)
    for k in range(n):
        yield header_slots + ((a * k + b) % n)


def _steg_embed(px: bytearray, carriers: Any, data: bytes, lsb_bits: int) -> None:
    lsb = _steg_validate_lsb(lsb_bits)
    total_bits = len(data) * 8
    mask = (1 << lsb) - 1
    bit_pos = 0
    for carrier_no in carriers:
        if bit_pos >= total_bits:
            break
        group = 0
        for _ in range(lsb):
            group <<= 1
            if bit_pos < total_bits:
                group |= (data[bit_pos >> 3] >> (7 - (bit_pos & 7))) & 1
                bit_pos += 1
        idx = _steg_carrier_offset(carrier_no)
        px[idx] = (px[idx] & (~mask & 0xFF)) | group
    if bit_pos < total_bits:
        raise ValueError("Image capacity exhausted while embedding data.")


def _steg_extract(px: bytes, carriers: Any, byte_count: int, lsb_bits: int) -> bytes:
    lsb = _steg_validate_lsb(lsb_bits)
    total_bits = int(byte_count) * 8
    mask = (1 << lsb) - 1
    out = bytearray(max(0, int(byte_count)))
    bit_pos = 0
    for carrier_no in carriers:
        if bit_pos >= total_bits:
            break
        group = px[_steg_carrier_offset(carrier_no)] & mask
        for shift in range(lsb - 1, -1, -1):
            if bit_pos >= total_bits:
                break
            out[bit_pos >> 3] |= ((group >> shift) & 1) << (7 - (bit_pos & 7))
            bit_pos += 1
    if bit_pos < total_bits:
        raise ValueError("Image ended before the requested hidden data could be extracted.")
    return bytes(out)


def _steg_build_header(header: Dict[str, Any]) -> bytes:
    filename_bytes = _steg_safe_filename(header.get("filename"), "message.txt").encode("utf-8", errors="replace")[:STEG_MAX_FILENAME_BYTES]
    fixed = STEG_HEADER_STRUCT.pack(
        STEG_MAGIC, STEG_VERSION, int(header["flags"]), int(header["lsb_bits"]), int(header["redundancy"]),
        len(filename_bytes), int(header["plaintext_size"]), int(header["coded_body_size"]), int(header["pre_fec_size"]),
        int(header["crc32"]), bytes(header["salt"]).ljust(STEG_SALT_LEN, b"\0")[:STEG_SALT_LEN],
        bytes(header["nonce"]).ljust(STEG_NONCE_LEN, b"\0")[:STEG_NONCE_LEN], bytes(header["digest"]).ljust(STEG_DIGEST_LEN, b"\0")[:STEG_DIGEST_LEN],
    )
    return fixed + filename_bytes


def _steg_parse_header(data: bytes) -> Dict[str, Any]:
    if len(data) < STEG_FIXED_HEADER_SIZE:
        raise ValueError("Header is incomplete.")
    magic, version, flags, lsb, redundancy, filename_len, plain_size, coded_size, pre_fec_size, crc32_value, salt, nonce, digest = STEG_HEADER_STRUCT.unpack(data[:STEG_FIXED_HEADER_SIZE])
    if magic != STEG_MAGIC:
        raise ValueError("STEGv4 magic mismatch.")
    if version != STEG_VERSION:
        raise ValueError(f"Unsupported STEG version: {version}")
    _steg_validate_lsb(lsb); _steg_validate_redundancy(redundancy)
    if filename_len > STEG_MAX_FILENAME_BYTES:
        raise ValueError("Header filename length is unreasonable.")
    if any(int(x) > STEG_MAX_OUTPUT_BYTES * 16 for x in (plain_size, coded_size, pre_fec_size)):
        raise ValueError("Header contains an unreasonable payload size for the web module.")
    if plain_size > STEG_MAX_OUTPUT_BYTES:
        raise C8SecurityInputError("Declared plaintext exceeds the download limit.")
    need = STEG_FIXED_HEADER_SIZE + int(filename_len)
    if len(data) < need:
        raise ValueError("Header filename bytes are incomplete.")
    filename = data[STEG_FIXED_HEADER_SIZE:need].decode("utf-8", errors="replace")
    return {
        "flags": int(flags), "lsb_bits": int(lsb), "redundancy": int(redundancy), "filename": _steg_safe_filename(filename),
        "plaintext_size": int(plain_size), "coded_body_size": int(coded_size), "pre_fec_size": int(pre_fec_size), "crc32": int(crc32_value),
        "salt": bytes(salt), "nonce": bytes(nonce), "digest": bytes(digest),
    }


def _steg_header_public(h: Dict[str, Any]) -> Dict[str, Any]:
    flags = int(h.get("flags") or 0)
    return {
        "format": "STEGv4", "version": STEG_VERSION, "flags": flags, "lsb_bits": int(h.get("lsb_bits") or 0),
        "redundancy": int(h.get("redundancy") or 1), "filename": _steg_safe_filename(h.get("filename")),
        "plaintext_size": int(h.get("plaintext_size") or 0), "coded_body_size": int(h.get("coded_body_size") or 0),
        "pre_fec_size": int(h.get("pre_fec_size") or 0), "compressed": bool(flags & STEG_FLAG_COMPRESSED),
        "encrypted": bool(flags & STEG_FLAG_ENCRYPTED), "fec": bool(flags & STEG_FLAG_FEC), "shuffled": bool(flags & STEG_FLAG_SHUFFLED),
        "authenticated_metadata": bool(flags & STEG_FLAG_AAD),
        "kdf": ("scrypt" if flags & STEG_FLAG_SCRYPT else "pbkdf2-sha256") if flags & STEG_FLAG_ENCRYPTED else None,
        "sha256": bytes(h.get("digest") or b"").hex(),
    }


def _steg_read_header(px: bytes, total: int, lsb_bits: int) -> Tuple[Dict[str, Any], int]:
    lsb = _steg_validate_lsb(lsb_bits)
    fixed_slots = _steg_slots_needed(STEG_FIXED_HEADER_SIZE, lsb)
    if fixed_slots > total:
        raise ValueError("Image is too small to contain a STEGv4 header.")
    fixed = _steg_extract(px, range(fixed_slots), STEG_FIXED_HEADER_SIZE, lsb)
    if fixed[:len(STEG_MAGIC)] != STEG_MAGIC:
        raise ValueError("STEGv4 magic mismatch.")
    unpacked = STEG_HEADER_STRUCT.unpack(fixed)
    filename_len = int(unpacked[5])
    if filename_len > STEG_MAX_FILENAME_BYTES:
        raise ValueError("Header filename length is unreasonable.")
    header_len = STEG_FIXED_HEADER_SIZE + filename_len
    header_slots = _steg_slots_needed(header_len, lsb)
    if header_slots > total:
        raise ValueError("Image is too small for the complete STEGv4 header.")
    raw = _steg_extract(px, range(header_slots), header_len, lsb)
    header = _steg_parse_header(raw)
    if int(header["lsb_bits"]) != lsb:
        raise ValueError("Header LSB value does not match detected plane.")
    return header, header_slots


def _steg_prepare_reedsolo() -> None:
    global _steg_reedsolo, _STEG_REEDSOLO_AVAILABLE
    if _STEG_REEDSOLO_AVAILABLE:
        return
    ready, reason = _c8_install_python_dependency("reedsolo")
    if not ready:
        raise RuntimeError(f"Reed-Solomon FEC setup failed: {reason}")
    import reedsolo
    _steg_reedsolo = reedsolo
    _STEG_REEDSOLO_AVAILABLE = True


def _steg_fec_encode(data: bytes) -> bytes:
    if not _STEG_REEDSOLO_AVAILABLE:
        _steg_prepare_reedsolo()
    rs = _steg_reedsolo.RSCodec(STEG_RS_NSYM)
    out = bytearray()
    for offset in range(0, len(data), STEG_RS_DATA_CHUNK):
        out.extend(bytes(rs.encode(data[offset:offset+STEG_RS_DATA_CHUNK])))
    return bytes(out)


def _steg_fec_decode(data: bytes, original_len: int) -> bytes:
    if not _STEG_REEDSOLO_AVAILABLE:
        _steg_prepare_reedsolo()
    rs = _steg_reedsolo.RSCodec(STEG_RS_NSYM)
    out = bytearray(); pos = 0; remain = int(original_len)
    while remain > 0:
        raw_len = min(STEG_RS_DATA_CHUNK, remain); enc_len = raw_len + STEG_RS_NSYM
        chunk = data[pos:pos+enc_len]
        if len(chunk) != enc_len:
            raise ValueError("FEC body is truncated.")
        decoded = rs.decode(chunk)
        if isinstance(decoded, tuple): decoded = decoded[0]
        out.extend(bytes(decoded)[:raw_len]); pos += enc_len; remain -= raw_len
    return bytes(out)


def _steg_majority(transport: bytes, copy_len: int, redundancy: int) -> bytes:
    redundancy = _steg_validate_redundancy(redundancy)
    if redundancy == 1:
        if len(transport) < copy_len: raise ValueError("Transport body is truncated.")
        return transport[:copy_len]
    expected = int(copy_len) * redundancy
    if len(transport) != expected: raise ValueError("Transport length mismatch.")
    copies = [transport[i*copy_len:(i+1)*copy_len] for i in range(redundancy)]
    out = bytearray(copy_len)
    for i in range(copy_len):
        counts: Dict[int,int] = {}; best = copies[0][i]; count = 0
        for c in copies:
            b = c[i]; counts[b] = counts.get(b,0)+1
            if counts[b] > count: best, count = b, counts[b]
        out[i] = best
    return bytes(out)


def _steg_prepare(plaintext: bytes, filename: str, lsb: int, compress: bool, password: str, redundancy: int, use_fec: bool, shuffle: bool, kdf_name: str) -> Tuple[Dict[str, Any], bytes, bytes]:
    lsb = _steg_validate_lsb(lsb); redundancy = _steg_validate_redundancy(redundancy)
    filename = _steg_safe_filename(filename, "message.txt")
    flags = 0; digest = hashlib.sha256(plaintext).digest(); processed = plaintext
    if compress:
        compressed = __import__("zlib").compress(plaintext, level=9)
        if len(compressed) < len(plaintext): processed = compressed; flags |= STEG_FLAG_COMPRESSED
    if use_fec: flags |= STEG_FLAG_FEC
    salt = b"\0" * STEG_SALT_LEN; nonce = b"\0" * STEG_NONCE_LEN
    if password:
        salt = secrets.token_bytes(STEG_SALT_LEN); nonce = secrets.token_bytes(STEG_NONCE_LEN)
        kdf_name = _steg_normalize_kdf(kdf_name); flags |= STEG_FLAG_ENCRYPTED | STEG_FLAG_AAD
        if kdf_name == "scrypt": flags |= STEG_FLAG_SCRYPT
        if shuffle: flags |= STEG_FLAG_SHUFFLED
        aad = _steg_build_aad(filename, len(plaintext), lsb, redundancy, flags)
        processed = AESGCM(_steg_derive_key(password, salt, kdf_name)).encrypt(nonce, processed, aad)
    else:
        shuffle = False
    pre_fec_size = len(processed); crc = binascii.crc32(processed) & 0xffffffff
    coded = _steg_fec_encode(processed) if use_fec else processed
    header = {"flags":flags,"lsb_bits":lsb,"redundancy":redundancy,"filename":filename,"plaintext_size":len(plaintext),"coded_body_size":len(coded),"pre_fec_size":pre_fec_size,"crc32":crc,"salt":salt,"nonce":nonce,"digest":digest}
    raw_header = _steg_build_header(header)
    return header, raw_header, coded * redundancy


def _steg_choose_lsb(img: Any, plaintext: bytes, filename: str, compress: bool, password: str, redundancy: int, use_fec: bool, shuffle: bool, kdf_name: str) -> int:
    for lsb in (1,2,3,4):
        _h, raw, body = _steg_prepare(plaintext, filename, lsb, compress, password, redundancy, use_fec, shuffle, kdf_name)
        if _steg_slots_needed(len(raw),lsb)+_steg_slots_needed(len(body),lsb) <= _steg_total_carriers(img): return lsb
    raise ValueError("Payload does not fit this image even at 4 LSBs with the selected options.")


def _steg_hide_bytes(cover: bytes, plaintext: bytes, filename: str, lsb_value: Any, compress: bool, password: str, redundancy: int, use_fec: bool, shuffle: bool, kdf_name: str) -> Tuple[bytes, Dict[str, Any]]:
    if len(plaintext) > STEG_MAX_PAYLOAD_BYTES:
        raise ValueError(f"Payload exceeds the {STEG_MAX_PAYLOAD_BYTES//(1024*1024)} MiB web limit.")
    img = _steg_open_rgba(cover)
    lsb = _steg_choose_lsb(img, plaintext, filename, compress, password, redundancy, use_fec, shuffle, kdf_name) if str(lsb_value).lower()=="auto" else _steg_validate_lsb(lsb_value)
    header, raw_header, transport = _steg_prepare(plaintext, filename, lsb, compress, password, redundancy, use_fec, shuffle, kdf_name)
    total = _steg_total_carriers(img); hs = _steg_slots_needed(len(raw_header),lsb); bs = _steg_slots_needed(len(transport),lsb)
    if hs + bs > total:
        raise ValueError("Payload is too large for this image with the selected LSB/redundancy options.")
    px = bytearray(img.tobytes()); _steg_embed(px, range(hs), raw_header, lsb)
    seed = _steg_seed(password, header["salt"]) if header["flags"] & STEG_FLAG_SHUFFLED else None
    _steg_embed(px, _steg_body_carriers(total,hs,bool(header["flags"] & STEG_FLAG_SHUFFLED),seed), transport, lsb)
    output = _steg_png_encode_rgba(img.width, img.height, bytes(px))
    if len(output) > STEG_MAX_OUTPUT_BYTES:
        raise RuntimeError(f"Generated PNG exceeds the {STEG_MAX_OUTPUT_BYTES//(1024*1024)} MiB web download limit.")
    report = _steg_header_public(header); report.update({"width":img.width,"height":img.height,"output_bytes":len(output),"payload_sha256":hashlib.sha256(plaintext).hexdigest()})
    return output, report


def _steg_extract_bytes(stego: bytes, password: str) -> Tuple[bytes, Dict[str, Any]]:
    img = _steg_open_rgba(stego); px = img.tobytes(); total = _steg_total_carriers(img); header=None; hs=None
    for lsb in (1,2,3,4):
        try: header,hs=_steg_read_header(px,total,lsb); break
        except Exception: pass
    if header is None or hs is None: raise ValueError("No STEGv4 payload header was found in this image.")
    flags=int(header["flags"])
    if flags & STEG_FLAG_ENCRYPTED and not password: raise ValueError("This payload is encrypted. Enter the password to extract it.")
    if flags & STEG_FLAG_SHUFFLED and not password: raise ValueError("This payload uses keyed placement. Enter the password to locate it.")
    total_transport=int(header["coded_body_size"])*int(header["redundancy"]); required=_steg_slots_needed(total_transport,int(header["lsb_bits"]))
    if hs+required>total: raise ValueError("Header claims a payload larger than the image can contain; image may be corrupted.")
    seed=_steg_seed(password,header["salt"]) if flags & STEG_FLAG_SHUFFLED else None
    transport=_steg_extract(px,_steg_body_carriers(total,hs,bool(flags & STEG_FLAG_SHUFFLED),seed),total_transport,int(header["lsb_bits"]))
    coded=_steg_majority(transport,int(header["coded_body_size"]),int(header["redundancy"]))
    processed=_steg_fec_decode(coded,int(header["pre_fec_size"])) if flags & STEG_FLAG_FEC else coded
    if len(processed)!=int(header["pre_fec_size"]): raise ValueError("Recovered body size does not match the header.")
    if (binascii.crc32(processed)&0xffffffff)!=int(header["crc32"]): raise ValueError("CRC mismatch after redundancy/FEC recovery. If this payload is encrypted/key-shuffled, the password may be wrong; otherwise the image may be corrupted or modified.")
    data=processed
    if flags & STEG_FLAG_ENCRYPTED:
        try:
            kdf_name="scrypt" if flags & STEG_FLAG_SCRYPT else "pbkdf2"; key=_steg_derive_key(password,header["salt"],kdf_name)
            aad=_steg_build_aad(header["filename"],header["plaintext_size"],header["lsb_bits"],header["redundancy"],flags) if flags & STEG_FLAG_AAD else None
            data=AESGCM(key).decrypt(header["nonce"],data,aad)
        except Exception as exc: raise ValueError("Decryption failed. The password is wrong, metadata was altered, or the payload was modified.") from exc
    if flags & STEG_FLAG_COMPRESSED:
        try: data=_c8_bounded_inflate(data, min(STEG_MAX_OUTPUT_BYTES, int(header["plaintext_size"])))
        except Exception as exc: raise ValueError("Payload decompression failed.") from exc
    if len(data)!=int(header["plaintext_size"]): raise ValueError("Recovered payload size does not match the header.")
    digest=hashlib.sha256(data).digest()
    if digest!=header["digest"]: raise ValueError("SHA-256 integrity check failed after extraction.")
    if len(data)>STEG_MAX_OUTPUT_BYTES: raise RuntimeError("Extracted payload exceeds the web download limit.")
    return data,_steg_header_public(header)


def _steg_entropy(data: bytes) -> float:
    if not data: return 0.0
    counts=[0]*256
    for b in data: counts[b]+=1
    total=float(len(data)); value=0.0
    for c in counts:
        if c:
            p=c/total; value-=p*math.log2(p)
    return float(value)


def _steg_scan_signatures(data: bytes) -> List[str]:
    sigs=((b"PK\x03\x04","ZIP/Office"),(b"%PDF-","PDF"),(b"\x7fELF","ELF"),(b"MZ","Windows PE"),(b"\x89PNG\r\n\x1a\n","PNG"),(b"\xff\xd8\xff","JPEG"),(b"GIF87a","GIF"),(b"GIF89a","GIF"),(b"RIFF","RIFF/WAV/WEBP"),(b"7z\xbc\xaf\x27\x1c","7-Zip"),(b"Rar!\x1a\x07","RAR"))
    return [name for sig,name in sigs if sig in data]


def _steg_analyze(stego: bytes, max_lsb: int = 4) -> Dict[str, Any]:
    img=_steg_open_rgba(stego); px=img.tobytes(); total=_steg_total_carriers(img); max_lsb=max(1,min(4,int(max_lsb or 4)))
    planes={}; exact_header=None
    carrier_sample=min(total,2_000_000)
    for lsb in range(1,max_lsb+1):
        header=None
        try:
            h,_hs=_steg_read_header(px,total,lsb); header=_steg_header_public(h); exact_header=header
        except Exception: pass
        probe_len=min(32768,_steg_raw_capacity(img,lsb)); probe=_steg_extract(px,range(_steg_slots_needed(probe_len,lsb)),probe_len,lsb) if probe_len else b""
        printable=sum(1 for b in probe if 32<=b<=126 or b in (9,10,13)); readable=(printable/len(probe)) if probe else 0.0
        ones=0; transitions=0; prev=None
        for c in range(carrier_sample):
            bit=(px[_steg_carrier_offset(c)]>>(lsb-1))&1; ones+=bit
            if prev is not None and bit!=prev: transitions+=1
            prev=bit
        ratio=(ones/carrier_sample) if carrier_sample else 0.0; transition=(transitions/max(1,carrier_sample-1)) if carrier_sample>1 else 0.0
        expected=carrier_sample/2 if carrier_sample else 1; chi=(((ones-expected)**2)/expected+(((carrier_sample-ones)-expected)**2)/expected) if carrier_sample else 0.0
        signatures=_steg_scan_signatures(probe); score=1.0 if header else min(0.95,(0.35 if signatures else 0)+(0.15 if readable>0.45 else 0.08 if readable>0.30 else 0)+(0.08 if _steg_entropy(probe)>7.7 and 0.48<=ratio<=0.52 else 0))
        planes[str(lsb)]={"lsb_bits":lsb,"exact_v4":bool(header),"confidence":round(score,3),"readable_fraction":round(readable,4),"entropy":round(_steg_entropy(probe),4),"ones_ratio":round(ratio,6),"transition_ratio":round(transition,6),"chi_square":round(chi,4),"signatures":signatures,"header":header}
    capacities={str(lsb):{"raw_bytes":_steg_raw_capacity(img,lsb),"approx_body_bytes":max(0,((_steg_total_carriers(img)-_steg_slots_needed(STEG_FIXED_HEADER_SIZE+255,lsb))*lsb)//8)} for lsb in (1,2,3,4)}
    return {"width":img.width,"height":img.height,"mode":"RGBA image; RGB carriers only (alpha preserved)","exact_v4":bool(exact_header),"header":exact_header,"planes":planes,"capacity":capacities,"image_sha256":hashlib.sha256(stego).hexdigest()}


def _steg_diff(original: bytes, stego: bytes) -> Tuple[Dict[str, Any], bytes]:
    a = _steg_open_rgba(original)
    b = _steg_open_rgba(stego)
    if a.size != b.size:
        raise ValueError("Images must have the same dimensions for exact diff metrics.")
    ap = a.tobytes(); bp = b.tobytes()
    total_pixels = a.width * a.height
    changed = 0
    max_delta = 0
    sum_abs = 0
    sum_sq = 0
    deltas = bytearray(total_pixels * 4)
    for pixel in range(total_pixels):
        base = pixel * 4
        dr = abs(ap[base] - bp[base])
        dg = abs(ap[base + 1] - bp[base + 1])
        db = abs(ap[base + 2] - bp[base + 2])
        if dr or dg or db:
            changed += 1
        max_delta = max(max_delta, dr, dg, db)
        sum_abs += dr + dg + db
        sum_sq += dr * dr + dg * dg + db * db
        deltas[base:base + 4] = bytes((dr, dg, db, 255))
    channel_count = max(1, total_pixels * 3)
    mse = sum_sq / channel_count
    psnr = float("inf") if mse <= 0 else 20.0 * math.log10(255.0 / math.sqrt(mse))
    factor = 1.0 if max_delta <= 0 else 255.0 / max_delta
    if factor != 1.0:
        for pixel in range(total_pixels):
            base = pixel * 4
            deltas[base] = min(255, int(deltas[base] * factor))
            deltas[base + 1] = min(255, int(deltas[base + 1] * factor))
            deltas[base + 2] = min(255, int(deltas[base + 2] * factor))
    heatmap = _steg_png_encode_rgba(a.width, a.height, bytes(deltas))
    metrics = {
        "width": a.width, "height": a.height, "changed_pixels": changed,
        "total_pixels": total_pixels,
        "changed_percent": round((changed / max(1, total_pixels)) * 100.0, 6),
        "mean_abs_channel_delta": round(sum_abs / channel_count, 6),
        "max_channel_delta": int(max_delta), "mse": round(float(mse), 6),
        "psnr_db": None if math.isinf(psnr) else round(psnr, 4),
    }
    return metrics, heatmap


def _steg_download_session_key(session: Dict[str,Any]) -> str:
    token=str((session or {}).get("token") or "")
    if not token: raise PermissionError("Authenticated session token is unavailable.")
    return hashlib.sha256(("stegano|"+token).encode("utf-8",errors="ignore")).hexdigest()


def _steg_cleanup_downloads(now: Optional[float]=None) -> None:
    current=float(now if now is not None else time.time())
    for key in [k for k,r in _STEG_DOWNLOADS.items() if current>=float(r.get("expires_at") or 0)]: _STEG_DOWNLOADS.pop(key,None)
    if len(_STEG_DOWNLOADS)>STEG_DOWNLOAD_MAX_ITEMS:
        ordered=sorted(_STEG_DOWNLOADS.items(),key=lambda item:float(item[1].get("created_at") or 0))
        for key,_rec in ordered[:len(ordered)-STEG_DOWNLOAD_MAX_ITEMS]: _STEG_DOWNLOADS.pop(key,None)


def _steg_store_download(session: Dict[str,Any], data: bytes, filename: str, mime: str) -> str:
    if not data or len(data)>STEG_MAX_OUTPUT_BYTES: raise RuntimeError("Generated Stegano download is empty or exceeds the server download limit.")
    token=secrets.token_urlsafe(32); now=time.time()
    rec={"data":bytes(data),"filename":_steg_safe_filename(filename),"mime":str(mime or "application/octet-stream")[:120],"session_key":_steg_download_session_key(session),"created_at":now,"expires_at":now+STEG_DOWNLOAD_TTL_SECONDS,"sha256":hashlib.sha256(data).hexdigest()}
    with _STEG_DOWNLOAD_LOCK:
        _steg_cleanup_downloads(now); _STEG_DOWNLOADS[token]=rec; _steg_cleanup_downloads(now)
    return token


def _steg_get_download(session: Dict[str,Any], token: str) -> Tuple[bytes,str,str,str]:
    key=str(token or "").strip()
    if not key or len(key)>200: raise FileNotFoundError("Stegano download token is invalid.")
    with _STEG_DOWNLOAD_LOCK:
        _steg_cleanup_downloads(); rec=_STEG_DOWNLOADS.get(key)
        if not rec: raise FileNotFoundError("Stegano download expired or was not found. Run the operation again.")
        if not hmac.compare_digest(str(rec.get("session_key") or ""),_steg_download_session_key(session)): raise PermissionError("This Stegano download belongs to another authenticated session.")
        return bytes(rec.get("data") or b""),_steg_safe_filename(rec.get("filename")),str(rec.get("mime") or "application/octet-stream"),str(rec.get("sha256") or "")


def stegano_web_action(session: Dict[str,Any], payload: Dict[str,Any]) -> Dict[str,Any]:
    action=str(payload.get("action") or "status").strip().lower()
    if action=="status":
        return {"ok":True,"tool":"Stegano v4.5 Web","format":"STEGv4","crypto_available":bool(AESGCM is not None and _STEG_CRYPTO_KDF_AVAILABLE),"fec_available":bool(_STEG_REEDSOLO_AVAILABLE),"max_image_bytes":STEG_MAX_IMAGE_BYTES,"max_payload_bytes":STEG_MAX_PAYLOAD_BYTES,"download_ttl_seconds":STEG_DOWNLOAD_TTL_SECONDS,"png_fallback":True,"pillow_available":bool(PIL_AVAILABLE)}
    if action=="hide":
        cover=_steg_decode_upload(payload.get("cover_b64"),"Cover image",STEG_MAX_IMAGE_BYTES)
        payload_b64=str(payload.get("payload_b64") or "").strip(); text_value=payload.get("text")
        if payload_b64:
            plaintext=_steg_decode_upload(payload_b64,"Payload file",STEG_MAX_PAYLOAD_BYTES); filename=_steg_safe_filename(payload.get("payload_filename"),"payload.bin")
        else:
            text=str(text_value or "")
            if not text: raise ValueError("Select a payload file or enter text to hide.")
            plaintext=text.encode("utf-8"); filename=_steg_safe_filename(payload.get("payload_filename"),"message.txt")
            if len(plaintext)>STEG_MAX_PAYLOAD_BYTES: raise ValueError("Text payload exceeds the web limit.")
        password=str(payload.get("password") or ""); use_fec=bool(payload.get("fec")); redundancy=_steg_validate_redundancy(payload.get("redundancy") or 1)
        output,report=_steg_hide_bytes(cover,plaintext,filename,payload.get("lsb") or "auto",bool(payload.get("compress",True)),password,redundancy,use_fec,bool(payload.get("shuffle",True)),str(payload.get("kdf") or "scrypt"))
        base=Path(_steg_safe_filename(payload.get("cover_filename"),"carrier.png")).stem or "carrier"; outname=_steg_safe_filename(payload.get("output_filename"),base+"_steg.png")
        if not outname.lower().endswith(".png"): outname=Path(outname).stem+".png"
        token=_steg_store_download(session,output,outname,"image/png")
        audit("Stegano","hide",{"carrier":_steg_safe_filename(payload.get("cover_filename"),"carrier"),"payload_bytes":len(plaintext),"output_bytes":len(output),"encrypted":bool(password),"lsb":report.get("lsb_bits")})
        return {"ok":True,"action":"hide","download_url":"/api/stegano/download?token="+urllib.parse.quote(token,safe=""),"download_filename":outname,"download_expires_seconds":STEG_DOWNLOAD_TTL_SECONDS,"output_sha256":hashlib.sha256(output).hexdigest(),"report":report}
    if action=="extract":
        image=_steg_decode_upload(payload.get("image_b64"),"Stego image",STEG_MAX_IMAGE_BYTES); data,header=_steg_extract_bytes(image,str(payload.get("password") or "")); filename=_steg_safe_filename(header.get("filename"),"extracted.bin")
        token=_steg_store_download(session,data,filename,mimetypes.guess_type(filename)[0] or "application/octet-stream")
        preview=""; is_text=False
        try:
            decoded=data.decode("utf-8"); printable=sum(1 for ch in decoded[:8000] if ch.isprintable() or ch in "\r\n\t")/max(1,len(decoded[:8000])); is_text=printable>=0.92
            if is_text: preview=decoded[:12000]
        except Exception: pass
        audit("Stegano","extract",{"filename":filename,"bytes":len(data),"encrypted":bool(header.get("encrypted"))})
        return {"ok":True,"action":"extract","filename":filename,"size_bytes":len(data),"sha256":hashlib.sha256(data).hexdigest(),"header":header,"text_preview":preview,"text_preview_available":is_text,"download_url":"/api/stegano/download?token="+urllib.parse.quote(token,safe=""),"download_expires_seconds":STEG_DOWNLOAD_TTL_SECONDS}
    if action in {"inspect","detect","capacity"}:
        image=_steg_decode_upload(payload.get("image_b64"),"Image",STEG_MAX_IMAGE_BYTES); analysis=_steg_analyze(image,int(payload.get("max_lsb") or 4)); audit("Stegano",action,{"image_bytes":len(image),"exact_v4":bool(analysis.get("exact_v4"))}); return {"ok":True,"action":action,"analysis":analysis}
    if action=="diff":
        original=_steg_decode_upload(payload.get("original_b64"),"Original image",STEG_MAX_IMAGE_BYTES); stego=_steg_decode_upload(payload.get("stego_b64"),"Stego image",STEG_MAX_IMAGE_BYTES); metrics,heat=_steg_diff(original,stego); token=_steg_store_download(session,heat,"stegano_diff_heatmap.png","image/png"); audit("Stegano","diff",{"changed_pixels":metrics.get("changed_pixels"),"total_pixels":metrics.get("total_pixels")}); return {"ok":True,"action":"diff","metrics":metrics,"heatmap_url":"/api/stegano/download?token="+urllib.parse.quote(token,safe=""),"heatmap_filename":"stegano_diff_heatmap.png","download_expires_seconds":STEG_DOWNLOAD_TTL_SECONDS}
    raise ValueError("Unsupported Stegano action.")

