BLACK_CLOUD_PUBLIC_KEY_RE = re.compile(r"^[A-Za-z0-9_-]{40,200}$")


def _black_cloud_audit_worker() -> None:
    while True:
        entry = BLACK_CLOUD_AUDIT_QUEUE.get()
        try:
            session, path, payload, client, forwarded_for, user_agent, status, action = entry
            record_user_activity(
                session, path, payload, client,
                forwarded_for=forwarded_for,
                user_agent=user_agent,
                status=status,
                hinted_module="Black Cloud",
                action=action,
            )
        except Exception as exc:
            print(f"Black Cloud audit warning: {str(exc)[:500]}", file=sys.stderr, flush=True)
        finally:
            BLACK_CLOUD_AUDIT_QUEUE.task_done()


def _black_cloud_start_audit_worker() -> None:
    global BLACK_CLOUD_AUDIT_THREAD
    with BLACK_CLOUD_AUDIT_THREAD_LOCK:
        if BLACK_CLOUD_AUDIT_THREAD and BLACK_CLOUD_AUDIT_THREAD.is_alive():
            return
        BLACK_CLOUD_AUDIT_THREAD = threading.Thread(
            target=_black_cloud_audit_worker,
            daemon=True,
            name="black-cloud-audit",
        )
        BLACK_CLOUD_AUDIT_THREAD.start()


def _black_cloud_record_activity_async(
    session: Dict[str, Any],
    path: str,
    payload: Dict[str, Any],
    client: str,
    forwarded_for: str = "",
    user_agent: str = "",
    status: str = "success",
    action: str = "",
) -> bool:
    """Queue audit persistence so messenger responses never wait on database I/O."""
    try:
        _black_cloud_start_audit_worker()
        entry = (
            dict(session or {}), str(path or "")[:255], dict(payload or {}), str(client or "")[:255],
            str(forwarded_for or "")[:1000], str(user_agent or "")[:1000], str(status or "success")[:40],
            str(action or "")[:160],
        )
        BLACK_CLOUD_AUDIT_QUEUE.put_nowait(entry)
        return True
    except Exception:
        # Availability of the encrypted messenger takes priority over a saturated
        # auxiliary audit queue. The queue is bounded to prevent memory growth.
        return False


def _black_cloud_always_on_enabled() -> bool:
    # Black Cloud is embedded in this web server process and is therefore
    # available whenever the site itself is running.
    return True


def _black_cloud_configuration() -> Dict[str, Any]:
    return {
        "host": HOST,
        "port": PORT,
        "proxy_enabled": False,
        "transport": "integrated-https",
    }


def _black_cloud_web_token(value: Any, default: str = "general", max_len: int = 48) -> str:
    cleaned = "".join(
        ch for ch in str(value or "").strip() if ch in BLACK_CLOUD_TOKEN_ALLOWED
    )
    return cleaned[:max_len] or default


def _black_cloud_web_bridge_key(session: Dict[str, Any]) -> str:
    token = str((session or {}).get("token") or "")
    if not token:
        raise RuntimeError("Authenticated session token is unavailable.")
    return hmac.new(
        _local_state_aes_key(),
        b"black-cloud-web|" + token.encode("utf-8", errors="ignore"),
        hashlib.sha256,
    ).hexdigest()


def _black_cloud_session_client_id(session: Dict[str, Any]) -> str:
    """Return a canonical opaque client id bound to the authenticated web session.

    The browser no longer gets to choose the relay identity. This eliminates
    malformed/client-id mismatch failures while keeping the browser's private
    ECDH key entirely client-side.
    """
    token = str((session or {}).get("token") or "")
    if not token:
        raise RuntimeError("Authenticated session token is unavailable.")
    digest = hmac.new(
        _local_state_aes_key(),
        b"black-cloud-client-id|" + token.encode("utf-8", errors="ignore"),
        hashlib.sha256,
    ).digest()[:18]
    client_id = base64.urlsafe_b64encode(digest).decode("ascii").rstrip("=")
    if not BLACK_CLOUD_CLIENT_ID_RE.fullmatch(client_id):
        raise RuntimeError("Black Cloud could not create a valid session identity.")
    return client_id


def _black_cloud_decode_b64url(value: Any) -> bytes:
    text = str(value or "").strip()
    if not text:
        return b""
    # Accept both base64url and conventional base64, with or without padding.
    text = text.replace("-", "+").replace("_", "/")
    if not re.fullmatch(r"[A-Za-z0-9+/]*={0,2}", text):
        return b""
    text = text.rstrip("=")
    text += "=" * ((4 - len(text) % 4) % 4)
    try:
        return base64.b64decode(text.encode("ascii"), validate=True)
    except Exception:
        return b""


def _black_cloud_public_key_from_jwk(value: Any) -> bytes:
    if not isinstance(value, dict):
        return b""
    if str(value.get("kty") or "") != "EC" or str(value.get("crv") or "") != "P-256":
        return b""
    x = _black_cloud_decode_b64url(value.get("x"))
    y = _black_cloud_decode_b64url(value.get("y"))
    if len(x) != 32 or len(y) != 32:
        return b""
    return b"\x04" + x + y


def _black_cloud_validate_public_key(
    public_key: Any = None,
    public_key_bytes: Any = None,
    public_key_jwk: Any = None,
) -> str:
    """Validate a browser P-256 public key and return canonical raw base64url.

    New browsers send the 65-byte uncompressed point as a JSON integer array.
    JWK and base64/base64url remain accepted for compatibility. The private key
    is never sent to or reconstructed by the server.
    """
    raw = b""

    if isinstance(public_key_bytes, (list, tuple)) and len(public_key_bytes) == 65:
        try:
            if all(isinstance(item, int) and not isinstance(item, bool) and 0 <= item <= 255 for item in public_key_bytes):
                raw = bytes(public_key_bytes)
        except Exception:
            raw = b""

    if not raw:
        raw = _black_cloud_public_key_from_jwk(public_key_jwk)

    if not raw:
        if isinstance(public_key, dict):
            raw = _black_cloud_public_key_from_jwk(public_key)
        else:
            raw = _black_cloud_decode_b64url(public_key)

    # WebCrypto exports an uncompressed P-256 point: 0x04 || X(32) || Y(32).
    if len(raw) != 65 or raw[0] != 0x04:
        raise ValueError(
            "Invalid Black Cloud P-256 public key. Reload the page with Ctrl+F5 and reopen Black Cloud."
        )

    try:
        from cryptography.hazmat.primitives.asymmetric import ec
        ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), raw)
    except Exception as exc:
        raise C8SecurityInputError("The supplied public key is not a valid P-256 curve point.") from exc
    canonical = base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")
    if not BLACK_CLOUD_PUBLIC_KEY_RE.fullmatch(canonical):
        raise ValueError("Black Cloud could not normalize the P-256 public key.")
    return canonical


def _black_cloud_connected_bridges() -> List[Any]:
    with BLACK_CLOUD_WEB_LOCK:
        return [
            bridge for bridge in BLACK_CLOUD_WEB_BRIDGES.values()
            if isinstance(bridge, BlackCloudWebBridge) and bridge.connected
        ]


def _black_cloud_connected_users() -> List[str]:
    return sorted(
        {bridge.nickname for bridge in _black_cloud_connected_bridges()},
        key=str.lower,
    )


def _black_cloud_find_client(client_id: str) -> Optional[Any]:
    client_id = str(client_id or "")
    if not client_id:
        return None
    for bridge in _black_cloud_connected_bridges():
        if secrets.compare_digest(str(getattr(bridge, "client_id", "") or ""), client_id):
            return bridge
    return None


def _black_cloud_validate_identity(client_id: Any, public_key: Any) -> Tuple[str, str]:
    client_id = str(client_id or "").strip()
    if not BLACK_CLOUD_CLIENT_ID_RE.fullmatch(client_id):
        raise ValueError("Invalid Black Cloud client identity.")
    return client_id, _black_cloud_validate_public_key(public_key)


def _black_cloud_peer_directory(for_bridge: Optional[Any] = None) -> List[Dict[str, str]]:
    peers: List[Dict[str, str]] = []
    for bridge in _black_cloud_connected_bridges():
        if bridge is for_bridge:
            continue
        client_id = str(getattr(bridge, "client_id", "") or "")
        public_key = str(getattr(bridge, "public_key", "") or "")
        if not client_id or not public_key:
            continue
        peers.append({
            "client_id": client_id,
            "nickname": str(getattr(bridge, "nickname", "") or "user")[:80],
            "public_key": public_key,
        })
    peers.sort(key=lambda row: (row.get("nickname", "").lower(), row.get("client_id", "")))
    return peers


class BlackCloudWebBridge:
    """In-process ciphertext relay for one authenticated website session.

    The relay never receives readable message text. Browsers perform the P-256
    ECDH/HKDF and per-text AES-256-GCM encryption before calling the send API.
    The server only keeps encrypted protocol packets in memory long enough for
    connected recipients to poll them.
    """

    def __init__(self, bridge_key: str, username: str):
        self.bridge_key = str(bridge_key)
        session_tag = self.bridge_key[:6]
        safe_user = _black_cloud_web_token(username, default="operator", max_len=24)
        self.nickname = _black_cloud_web_token(
            f"{safe_user}_{session_tag}",
            default=f"user_{session_tag}",
            max_len=48,
        )
        self.channel = "direct"
        self.client_id = ""
        self.public_key = ""
        self.connected = False
        self.connected_at = ""
        self.last_activity = time.time()
        self._message_id = 0
        self._messages: List[Dict[str, Any]] = []
        self._lock = threading.RLock()
        self._recent_packet_hashes = {}

    def _append(self, kind: str, sender: str, text: str) -> None:
        safe_text = str(text or "").replace("\x00", "?").replace("\r", " ")
        if len(safe_text) > BLACK_CLOUD_WEB_MAX_MESSAGE:
            safe_text = safe_text[:BLACK_CLOUD_WEB_MAX_MESSAGE]
        with self._lock:
            self._message_id += 1
            self._messages.append(
                {
                    "id": self._message_id,
                    "kind": str(kind or "message")[:24],
                    "sender": _black_cloud_web_token(sender, default="system", max_len=48),
                    "text": safe_text,
                    "timestamp": now_iso(),
                }
            )
            if len(self._messages) > BLACK_CLOUD_WEB_HISTORY_LIMIT:
                del self._messages[:-BLACK_CLOUD_WEB_HISTORY_LIMIT]

    def connect(self, client_id: Any, public_key: Any) -> None:
        client_id, public_key = _black_cloud_validate_identity(client_id, public_key)
        existing = _black_cloud_find_client(client_id)
        if existing is not None and existing is not self:
            raise RuntimeError("That Black Cloud browser identity is already connected.")
        self.client_id = client_id
        self.public_key = public_key
        self.connected = True
        self.connected_at = now_iso()
        self.last_activity = time.time()
        self._append(
            "system",
            "system",
            "Integrated Black Cloud relay ready. Select a secure contact and type a message.",
        )

    def _validate_hello(self, parts: List[str]) -> Tuple[str, str]:
        if len(parts) != 4 or parts[0] != BLACK_CLOUD_BROWSER_PROTOCOL or parts[1] != "HELLO":
            raise ValueError("Invalid Black Cloud identity packet.")
        return _black_cloud_validate_identity(parts[2], parts[3])

    def _validate_dm(self, parts: List[str]) -> Tuple[str, str]:
        if len(parts) != 9 or parts[0] != BLACK_CLOUD_BROWSER_PROTOCOL or parts[1] != "DM":
            raise ValueError("Invalid Black Cloud encrypted-text packet.")
        target_id = str(parts[2] or "")
        sender_id = str(parts[3] or "")
        if not BLACK_CLOUD_CLIENT_ID_RE.fullmatch(target_id):
            raise ValueError("Invalid Black Cloud recipient identity.")
        if not BLACK_CLOUD_CLIENT_ID_RE.fullmatch(sender_id):
            raise ValueError("Invalid Black Cloud sender identity.")
        if not self.client_id or not secrets.compare_digest(sender_id, self.client_id):
            raise PermissionError("Black Cloud sender identity does not match this session.")
        # The remaining fields are opaque authenticated ciphertext/key material.
        for value in parts[4:]:
            if not value or len(value) > 20_000 or not re.fullmatch(r"[A-Za-z0-9_-]+", value):
                raise ValueError("Invalid Black Cloud encrypted packet encoding.")
        return target_id, sender_id

    def send_message(self, message: Any) -> None:
        text = str(message or "").replace("\x00", "").replace("\r", "").replace("\n", "").strip()
        if not text:
            raise ValueError("Encrypted Black Cloud packet is empty.")
        if len(text) > BLACK_CLOUD_WEB_MAX_MESSAGE:
            raise ValueError(
                f"Encrypted Black Cloud packets are limited to {BLACK_CLOUD_WEB_MAX_MESSAGE} characters."
            )
        if not self.connected:
            raise RuntimeError("Open the Black Cloud secure messenger first.")

        parts = text.split("|")
        packet_type = parts[1] if len(parts) > 1 else ""
        recipients: List[BlackCloudWebBridge]

        if packet_type == "HELLO":
            client_id, public_key = self._validate_hello(parts)
            # HELLO remains accepted for backward compatibility, but current
            # browsers register their public identity during /chat/connect.
            if not secrets.compare_digest(client_id, self.client_id):
                raise PermissionError("Black Cloud HELLO identity does not match this session.")
            if not secrets.compare_digest(public_key, self.public_key):
                raise PermissionError("Black Cloud HELLO public key does not match this session.")
            recipients = _black_cloud_connected_bridges()
        elif packet_type == "DM":
            target_id, _sender_id = self._validate_dm(parts)
            target = _black_cloud_find_client(target_id)
            if target is None or not target.connected:
                raise RuntimeError("The selected secure contact is no longer connected.")
            # Direct ciphertext is relayed only to the sender and intended recipient,
            # rather than broadcasting it to every authenticated Black Cloud user.
            recipients = [self] if target is self else [self, target]
        else:
            raise ValueError("Black Cloud accepts only end-to-end encrypted protocol packets.")

        if packet_type == "DM":
            fingerprint = hashlib.sha256(text.encode("utf-8")).digest()
            with self._lock:
                now = time.monotonic()
                self._recent_packet_hashes = {k: ts for k, ts in self._recent_packet_hashes.items() if now - ts < 600}
                if fingerprint in self._recent_packet_hashes:
                    raise C8SecurityInputError("Duplicate encrypted packet rejected.")
                if len(self._recent_packet_hashes) >= 2048:
                    raise C8SecurityInputError("Message rate exceeded; wait before sending again.")
                self._recent_packet_hashes[fingerprint] = now
        delivered = set()
        for bridge in recipients:
            marker = id(bridge)
            if marker in delivered or not bridge.connected:
                continue
            delivered.add(marker)
            bridge._append("message", self.nickname, text)
        self.last_activity = time.time()

    def snapshot(self, after_id: int = 0) -> Dict[str, Any]:
        self.last_activity = time.time()
        cursor = max(0, int(after_id or 0))
        with self._lock:
            messages = [
                dict(item) for item in self._messages
                if int(item.get("id") or 0) > cursor
            ][-200:]
            last_id = self._message_id
        return {
            "ok": True,
            "connected": bool(self.connected),
            "state": "online" if self.connected else "disconnected",
            "channel": self.channel,
            "nickname": self.nickname,
            "client_id": self.client_id,
            "users": _black_cloud_connected_users(),
            "peers": _black_cloud_peer_directory(self),
            "typing": [],
            "messages": messages,
            "last_message_id": last_id,
            "connected_at": self.connected_at,
            "transport": "integrated-https",
            "relay_mode": "in-process-encrypted-signaling-and-text",
            "history_storage": "memory-only",
            "photo_max_bytes": BLACK_CLOUD_PHOTO_MAX_BYTES,
            "photo_ttl_seconds": BLACK_CLOUD_PHOTO_TTL_SECONDS,
        }

    def close(self) -> None:
        self.connected = False
        self.client_id = ""
        self.public_key = ""
        self.last_activity = time.time()
        with self._lock:
            self._messages.clear()


def _black_cloud_web_get(session: Dict[str, Any]) -> Optional[BlackCloudWebBridge]:
    key = _black_cloud_web_bridge_key(session)
    with BLACK_CLOUD_WEB_LOCK:
        bridge = BLACK_CLOUD_WEB_BRIDGES.get(key)
    return bridge if isinstance(bridge, BlackCloudWebBridge) else None


def black_cloud_web_connect(
    session: Dict[str, Any],
    client_id: Any = None,
    public_key: Any = None,
    public_key_bytes: Any = None,
    public_key_jwk: Any = None,
) -> Dict[str, Any]:
    # The relay identity is generated by the authenticated server session.
    # `client_id` remains accepted in the request for compatibility but is not
    # trusted or used, so malformed browser IDs cannot break messenger startup.
    key = _black_cloud_web_bridge_key(session)
    validated_id = _black_cloud_session_client_id(session)
    validated_key = _black_cloud_validate_public_key(
        public_key=public_key,
        public_key_bytes=public_key_bytes,
        public_key_jwk=public_key_jwk,
    )
    with BLACK_CLOUD_WEB_LOCK:
        current = BLACK_CLOUD_WEB_BRIDGES.get(key)
        if (
            isinstance(current, BlackCloudWebBridge)
            and current.connected
            and secrets.compare_digest(str(current.client_id or ""), validated_id)
            and secrets.compare_digest(str(current.public_key or ""), validated_key)
        ):
            # Background pre-connect and a user click can arrive together. Treat
            # the second request as a cheap refresh instead of destroying keys,
            # history, and the relay bridge that was just created.
            current.last_activity = time.time()
            response = current.snapshot()
            response["client_id"] = validated_id
            response["reused_connection"] = True
            return response
        old = BLACK_CLOUD_WEB_BRIDGES.pop(key, None)
        if isinstance(old, BlackCloudWebBridge):
            old.close()
        bridge = BlackCloudWebBridge(key, str(session.get("username") or "operator"))
        bridge.connect(validated_id, validated_key)
        BLACK_CLOUD_WEB_BRIDGES[key] = bridge
        response = bridge.snapshot()
        response["client_id"] = validated_id
    return response


def black_cloud_web_poll(session: Dict[str, Any], after_id: Any = 0) -> Dict[str, Any]:
    try:
        cursor = max(0, int(after_id or 0))
    except (TypeError, ValueError):
        cursor = 0
    bridge = _black_cloud_web_get(session)
    if not bridge:
        return {
            "ok": True,
            "connected": False,
            "state": "ready",
            "channel": "direct",
            "users": _black_cloud_connected_users(),
            "peers": _black_cloud_peer_directory(None),
            "typing": [],
            "messages": [],
            "last_message_id": cursor,
            "transport": "integrated-https",
            "relay_mode": "in-process-encrypted-signaling-and-text",
            "history_storage": "memory-only",
            "photo_max_bytes": BLACK_CLOUD_PHOTO_MAX_BYTES,
            "photo_ttl_seconds": BLACK_CLOUD_PHOTO_TTL_SECONDS,
        }
    return bridge.snapshot(cursor)


def black_cloud_web_send(session: Dict[str, Any], message: Any) -> Dict[str, Any]:
    """Accept one encrypted packet without replaying queued history in the POST response.

    Delivery history is consumed only through /chat/poll. Returning bridge.snapshot()
    here used to resend already-processed ciphertext after every send, which could
    correctly trigger the browser replay/sequence protections on valid messages.
    """
    bridge = _black_cloud_web_get(session)
    if not bridge:
        raise RuntimeError("Open the Black Cloud secure messenger first.")
    bridge.send_message(message)
    return {
        "ok": True,
        "accepted": True,
        "connected": bool(bridge.connected),
        "state": "online" if bridge.connected else "disconnected",
        "channel": bridge.channel,
        "nickname": bridge.nickname,
        "client_id": bridge.client_id,
        "users": _black_cloud_connected_users(),
        "peers": _black_cloud_peer_directory(bridge),
        "typing": [],
        "messages": [],
        "transport": "integrated-https",
        "relay_mode": "in-process-encrypted-signaling-and-text",
        "history_storage": "memory-only",
        "photo_max_bytes": BLACK_CLOUD_PHOTO_MAX_BYTES,
        "photo_ttl_seconds": BLACK_CLOUD_PHOTO_TTL_SECONDS,
    }


def black_cloud_web_disconnect(session: Dict[str, Any]) -> Dict[str, Any]:
    key = _black_cloud_web_bridge_key(session)
    with BLACK_CLOUD_WEB_LOCK:
        bridge = BLACK_CLOUD_WEB_BRIDGES.pop(key, None)
    if isinstance(bridge, BlackCloudWebBridge):
        bridge.close()
    return {
        "ok": True,
        "connected": False,
        "state": "ready",
        "channel": "direct",
        "users": _black_cloud_connected_users(),
        "peers": _black_cloud_peer_directory(None),
        "typing": [],
        "messages": [],
        "last_message_id": 0,
        "transport": "integrated-https",
        "relay_mode": "in-process-encrypted-messaging-with-photo-quarantine",
        "history_storage": "memory-only",
        "photo_max_bytes": BLACK_CLOUD_PHOTO_MAX_BYTES,
        "photo_ttl_seconds": BLACK_CLOUD_PHOTO_TTL_SECONDS,
    }


def _black_cloud_photo_cleanup(now: Optional[float] = None) -> None:
    current = float(now if now is not None else time.time())
    with BLACK_CLOUD_PHOTO_LOCK:
        for token, record in list(BLACK_CLOUD_PHOTOS.items()):
            if current >= float(record.get("expires_at") or 0):
                BLACK_CLOUD_PHOTOS.pop(token, None)
        while len(BLACK_CLOUD_PHOTOS) > BLACK_CLOUD_PHOTO_MAX_ITEMS:
            oldest = min(BLACK_CLOUD_PHOTOS, key=lambda item: float(BLACK_CLOUD_PHOTOS[item].get("created_epoch") or 0))
            BLACK_CLOUD_PHOTOS.pop(oldest, None)
        while sum(len(bytes(item.get("ciphertext") or b"")) for item in BLACK_CLOUD_PHOTOS.values()) > BLACK_CLOUD_PHOTO_MAX_STORE_BYTES:
            if not BLACK_CLOUD_PHOTOS:
                break
            oldest = min(BLACK_CLOUD_PHOTOS, key=lambda item: float(BLACK_CLOUD_PHOTOS[item].get("created_epoch") or 0))
            BLACK_CLOUD_PHOTOS.pop(oldest, None)


def _black_cloud_photo_rate_check(session: Dict[str, Any]) -> None:
    """Bound expensive decoder/scanner work per authenticated browser session."""
    key = _black_cloud_web_bridge_key(session)
    now = time.monotonic()
    cutoff = now - BLACK_CLOUD_PHOTO_SCAN_WINDOW_SECONDS
    with BLACK_CLOUD_PHOTO_RATE_LOCK:
        recent = [stamp for stamp in BLACK_CLOUD_PHOTO_SCAN_TIMES.get(key, []) if stamp > cutoff]
        if len(recent) >= BLACK_CLOUD_PHOTO_SCAN_MAX_PER_WINDOW:
            raise C8SecurityInputError(
                "Too many photo scans. Wait one minute before trying another photo."
            )
        recent.append(now)
        BLACK_CLOUD_PHOTO_SCAN_TIMES[key] = recent
        if len(BLACK_CLOUD_PHOTO_SCAN_TIMES) > 2048:
            for old_key, stamps in list(BLACK_CLOUD_PHOTO_SCAN_TIMES.items()):
                kept = [stamp for stamp in stamps if stamp > cutoff]
                if kept:
                    BLACK_CLOUD_PHOTO_SCAN_TIMES[old_key] = kept
                else:
                    BLACK_CLOUD_PHOTO_SCAN_TIMES.pop(old_key, None)


def _black_cloud_photo_container_check(data: bytes, filename: str) -> Dict[str, Any]:
    """Strictly validate a static image container before any pixel decoder sees it.

    The gate rejects format/extension mismatches, animation, corrupt chunk tables,
    oversized metadata, and bytes appended after the declared image container.
    """
    if not isinstance(data, (bytes, bytearray)) or not data:
        raise C8SecurityInputError("Photo rejected: empty image container.")
    raw = bytes(data)
    suffix = Path(str(filename or "")).suffix.lower()
    extension_formats = {
        ".jpg": "JPEG", ".jpeg": "JPEG", ".png": "PNG", ".webp": "WEBP",
    }
    if suffix and suffix not in extension_formats:
        raise C8SecurityInputError("Photo rejected: only JPEG, PNG, and WebP filenames are accepted.")

    detected = ""
    metadata_bytes = 0
    chunk_count = 0
    if raw.startswith(b"\xff\xd8\xff"):
        detected = "JPEG"
        if len(raw) < 16:
            raise C8SecurityInputError("Photo rejected: JPEG image structure is incomplete.")
        offset = 2
        saw_frame = False
        saw_scan = False
        saw_end = False
        in_entropy = False
        while offset < len(raw):
            if in_entropy:
                marker_start = raw.find(b"\xff", offset)
                if marker_start < 0:
                    raise C8SecurityInputError("Photo rejected: JPEG scan data is truncated.")
                offset = marker_start + 1
                while offset < len(raw) and raw[offset] == 0xFF:
                    offset += 1
                if offset >= len(raw):
                    raise C8SecurityInputError("Photo rejected: JPEG scan marker is truncated.")
                marker = raw[offset]
                offset += 1
                if marker == 0x00 or 0xD0 <= marker <= 0xD7:
                    continue
                in_entropy = False
            else:
                if raw[offset] != 0xFF:
                    raise C8SecurityInputError("Photo rejected: JPEG marker table is malformed.")
                while offset < len(raw) and raw[offset] == 0xFF:
                    offset += 1
                if offset >= len(raw):
                    raise C8SecurityInputError("Photo rejected: JPEG marker table is truncated.")
                marker = raw[offset]
                offset += 1
            if marker == 0xD9:
                if offset != len(raw):
                    raise C8SecurityInputError("Photo rejected: JPEG has appended data after its final image marker.")
                saw_end = True
                break
            if marker == 0xD8:
                raise C8SecurityInputError("Photo rejected: JPEG contains an unexpected nested image marker.")
            if marker in {0x01, *range(0xD0, 0xD8)}:
                continue
            if offset + 2 > len(raw):
                raise C8SecurityInputError("Photo rejected: JPEG segment is truncated.")
            segment_length = int.from_bytes(raw[offset:offset + 2], "big")
            if segment_length < 2 or offset + segment_length > len(raw):
                raise C8SecurityInputError("Photo rejected: JPEG segment length is invalid.")
            payload_length = segment_length - 2
            if 0xE0 <= marker <= 0xEF or marker == 0xFE:
                metadata_bytes += payload_length
                if payload_length > 256 * 1024:
                    raise C8SecurityInputError("Photo rejected: an oversized JPEG metadata segment was detected.")
            if marker in {0xC0, 0xC1, 0xC2, 0xC3, 0xC5, 0xC6, 0xC7, 0xC9, 0xCA, 0xCB, 0xCD, 0xCE, 0xCF}:
                saw_frame = True
            if marker == 0xDA:
                saw_scan = True
            offset += segment_length
            chunk_count += 1
            if chunk_count > 1024:
                raise C8SecurityInputError("Photo rejected: JPEG contains too many segments.")
            if marker == 0xDA:
                in_entropy = True
        if not saw_frame or not saw_scan or not saw_end or offset != len(raw):
            raise C8SecurityInputError("Photo rejected: JPEG image structure is incomplete.")
    elif raw.startswith(b"\x89PNG\r\n\x1a\n"):
        detected = "PNG"
        offset = 8
        saw_header = False
        saw_pixels = False
        saw_end = False
        allowed_critical = {b"IHDR", b"PLTE", b"IDAT", b"IEND"}
        while offset < len(raw):
            if offset + 12 > len(raw):
                raise C8SecurityInputError("Photo rejected: PNG chunk table is truncated.")
            length = int.from_bytes(raw[offset:offset + 4], "big")
            chunk_type = raw[offset + 4:offset + 8]
            chunk_end = offset + 12 + length
            if length > BLACK_CLOUD_PHOTO_MAX_BYTES or chunk_end > len(raw):
                raise C8SecurityInputError("Photo rejected: PNG chunk length is invalid.")
            payload = raw[offset + 8:offset + 8 + length]
            expected_crc = int.from_bytes(raw[offset + 8 + length:chunk_end], "big")
            actual_crc = zlib.crc32(chunk_type + payload) & 0xFFFFFFFF
            if actual_crc != expected_crc:
                raise C8SecurityInputError("Photo rejected: PNG chunk integrity check failed.")
            if not re.fullmatch(rb"[A-Za-z]{4}", chunk_type):
                raise C8SecurityInputError("Photo rejected: PNG contains an invalid chunk type.")
            if chunk_type == b"IHDR":
                if saw_header or offset != 8 or length != 13:
                    raise C8SecurityInputError("Photo rejected: PNG header is invalid.")
                saw_header = True
            elif chunk_type == b"IDAT":
                saw_pixels = True
            elif chunk_type == b"IEND":
                if length != 0 or chunk_end != len(raw):
                    raise C8SecurityInputError("Photo rejected: PNG has appended data after its final chunk.")
                saw_end = True
            elif chunk_type in {b"acTL", b"fcTL", b"fdAT"}:
                raise C8SecurityInputError("Photo rejected: animated PNG files are not accepted.")
            elif not (chunk_type[0] & 0x20) and chunk_type not in allowed_critical:
                raise C8SecurityInputError("Photo rejected: PNG contains an unknown critical chunk.")
            if chunk_type in {b"tEXt", b"zTXt", b"iTXt", b"eXIf", b"iCCP"}:
                metadata_bytes += length
                if length > 256 * 1024:
                    raise C8SecurityInputError("Photo rejected: an oversized PNG metadata chunk was detected.")
            offset = chunk_end
            chunk_count += 1
            if chunk_count > 4096:
                raise C8SecurityInputError("Photo rejected: PNG contains too many chunks.")
            if saw_end:
                break
        if not (saw_header and saw_pixels and saw_end) or offset != len(raw):
            raise C8SecurityInputError("Photo rejected: PNG image structure is incomplete.")
    elif len(raw) >= 20 and raw[:4] == b"RIFF" and raw[8:12] == b"WEBP":
        detected = "WEBP"
        if int.from_bytes(raw[4:8], "little") + 8 != len(raw):
            raise C8SecurityInputError("Photo rejected: WebP has appended or truncated container data.")
        offset = 12
        saw_pixels = False
        while offset < len(raw):
            if offset + 8 > len(raw):
                raise C8SecurityInputError("Photo rejected: WebP chunk table is truncated.")
            chunk_type = raw[offset:offset + 4]
            length = int.from_bytes(raw[offset + 4:offset + 8], "little")
            chunk_end = offset + 8 + length + (length & 1)
            if length > BLACK_CLOUD_PHOTO_MAX_BYTES or chunk_end > len(raw):
                raise C8SecurityInputError("Photo rejected: WebP chunk length is invalid.")
            if chunk_type in {b"VP8 ", b"VP8L"}:
                saw_pixels = True
            if chunk_type in {b"ANIM", b"ANMF"}:
                raise C8SecurityInputError("Photo rejected: animated WebP files are not accepted.")
            if chunk_type in {b"EXIF", b"XMP ", b"ICCP"}:
                metadata_bytes += length
                if length > 256 * 1024:
                    raise C8SecurityInputError("Photo rejected: an oversized WebP metadata chunk was detected.")
            offset = chunk_end
            chunk_count += 1
            if chunk_count > 1024:
                raise C8SecurityInputError("Photo rejected: WebP contains too many chunks.")
        if not saw_pixels or offset != len(raw):
            raise C8SecurityInputError("Photo rejected: WebP image structure is incomplete.")
    else:
        raise C8SecurityInputError("Photo rejected: only genuine JPEG, PNG, and WebP images are accepted.")

    expected = extension_formats.get(suffix)
    if expected and expected != detected:
        raise C8SecurityInputError("Photo rejected: the filename extension does not match the image container.")
    if metadata_bytes > 512 * 1024:
        raise C8SecurityInputError("Photo rejected: excessive embedded metadata was detected.")
    return {
        "format": detected,
        "strict_eof": True,
        "metadata_bytes": metadata_bytes,
        "chunks_or_segments": chunk_count,
        "sha256": hashlib.sha256(raw).hexdigest(),
    }


def _black_cloud_photo_decode_upload(value: Any) -> bytes:
    encoded = str(value or "").strip()
    if not encoded:
        raise ValueError("Select a photo to scan and send.")
    max_encoded = ((BLACK_CLOUD_PHOTO_MAX_BYTES + 2) // 3) * 4 + 8
    if len(encoded) > max_encoded:
        raise ValueError(f"Black Cloud photos are limited to {BLACK_CLOUD_PHOTO_MAX_BYTES // (1024 * 1024)} MiB.")
    try:
        data = base64.b64decode(encoded, validate=True)
    except Exception as exc:
        raise ValueError("The uploaded photo encoding is invalid.") from exc
    if not data:
        raise ValueError("The uploaded photo is empty.")
    if len(data) > BLACK_CLOUD_PHOTO_MAX_BYTES:
        raise ValueError(f"Black Cloud photos are limited to {BLACK_CLOUD_PHOTO_MAX_BYTES // (1024 * 1024)} MiB.")
    return data


def _black_cloud_photo_sanitize(data: bytes, filename: str) -> Tuple[bytes, str, int, int, str]:
    """Decode pixels and rebuild a static JPEG with metadata and trailing data removed."""
    if not _ensure_pillow_available(force_install=True):
        raise RuntimeError(
            "Photo delivery is blocked because the secure image decoder is unavailable. "
            f"Pillow setup error: {_PIL_INSTALL_ERROR or 'unknown error'}"
        )
    allowed = {"JPEG", "PNG", "WEBP"}
    try:
        with BLACK_CLOUD_PHOTO_DECODE_LOCK:
            with Image.open(BytesIO(data)) as probe:
                image_format = str(probe.format or "").upper()
                width, height = int(probe.width), int(probe.height)
                frames = int(getattr(probe, "n_frames", 1) or 1)
                if image_format not in allowed:
                    raise ValueError("Only JPEG, PNG, and WebP photos are accepted.")
                if frames != 1:
                    raise ValueError("Animated or multi-frame images are not accepted. Send one static photo.")
                if width < 1 or height < 1 or width * height > BLACK_CLOUD_PHOTO_MAX_PIXELS:
                    raise ValueError("The photo dimensions exceed the 8-megapixel safety limit.")
                probe.verify()
            with Image.open(BytesIO(data)) as source:
                rebuilt = ImageOps.exif_transpose(source)
                rebuilt.load()
                if "A" in rebuilt.getbands():
                    rgba = rebuilt.convert("RGBA")
                    flattened = Image.new("RGB", rgba.size, (255, 255, 255))
                    flattened.paste(rgba, mask=rgba.getchannel("A"))
                    rebuilt = flattened
                else:
                    rebuilt = rebuilt.convert("RGB")
                resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS")
                rebuilt.thumbnail((BLACK_CLOUD_PHOTO_MAX_DIMENSION, BLACK_CLOUD_PHOTO_MAX_DIMENSION), resampling)
                output = b""
                for _shrink in range(5):
                    for quality in (88, 82, 74, 66):
                        buffer = BytesIO()
                        rebuilt.save(buffer, format="JPEG", quality=quality, optimize=True, progressive=True)
                        output = buffer.getvalue()
                        if len(output) <= BLACK_CLOUD_PHOTO_MAX_OUTPUT_BYTES:
                            break
                    if len(output) <= BLACK_CLOUD_PHOTO_MAX_OUTPUT_BYTES:
                        break
                    next_size = (max(1, int(rebuilt.width * 0.82)), max(1, int(rebuilt.height * 0.82)))
                    rebuilt = rebuilt.resize(next_size, resampling)
                if not output or len(output) > BLACK_CLOUD_PHOTO_MAX_OUTPUT_BYTES:
                    raise ValueError("The sanitized photo is still too large to deliver safely.")
                out_width, out_height = int(rebuilt.width), int(rebuilt.height)
    except (ValueError, RuntimeError):
        raise
    except Exception as exc:
        raise ValueError(f"The selected file could not be safely decoded as a photo: {exc}") from exc
    safe_stem = Path(_ff_safe_name(filename or "photo")).stem[:100] or "photo"
    safe_name = f"{safe_stem}.jpg"
    return output, safe_name, out_width, out_height, image_format


def _black_cloud_clam_scan(data: bytes) -> Dict[str, Any]:
    executable = shutil.which("clamdscan") or shutil.which("clamscan")
    if not executable:
        return {"available": False, "engine": "ClamAV", "status": "not_installed", "clean": None}
    try:
        # Both clamscan and clamdscan accept '-' as an input stream. This keeps
        # quarantined plaintext out of temporary files and persistent storage.
        completed = subprocess.run(
            [executable, "--no-summary", "-"], input=data,
            capture_output=True, timeout=45,
        )
        output = (completed.stdout or completed.stderr or b"").decode("utf-8", "replace").strip()[-1600:]
        if completed.returncode == 0:
            return {"available": True, "engine": Path(executable).name, "status": "complete", "clean": True}
        if completed.returncode == 1:
            return {"available": True, "engine": Path(executable).name, "status": "infected", "clean": False, "detail": output}
        return {"available": True, "engine": Path(executable).name, "status": "error", "clean": False, "detail": output or f"exit {completed.returncode}"}
    except subprocess.TimeoutExpired:
        return {"available": True, "engine": Path(executable).name, "status": "error", "clean": False, "detail": "ClamAV scan timed out."}
    except Exception as exc:
        return {"available": True, "engine": Path(executable).name, "status": "error", "clean": False, "detail": f"{type(exc).__name__}: {exc}"[:1600]}


def _black_cloud_photo_static_scan(data: bytes, filename: str) -> Dict[str, Any]:
    # Keep the standard antivirus test marker split in source so the application
    # file itself is not mistaken for an EICAR sample by host scanners.
    eicar = b"X5O!P%@AP[4\\PZX54(P^)7CC)7}$" + b"EICAR-STANDARD-ANTIVIRUS-TEST-FILE!$H+H*"
    if eicar in data:
        raise C8SecurityInputError("Photo rejected: the EICAR antivirus test signature was detected.")
    report = file_forensics_scan({
        "filename": filename,
        "data_b64": base64.b64encode(data).decode("ascii"),
        "custom_yara": "",
    })
    yara_report = report.get("yara") if isinstance(report.get("yara"), dict) else {}
    if not bool(yara_report.get("available")) or not bool(yara_report.get("scan_complete")):
        reason = str(yara_report.get("reason") or yara_report.get("install_error") or "YARA did not complete.")
        raise RuntimeError(f"Photo delivery is blocked until the YARA malware scanner is ready. {reason}")
    blocked = [
        item for item in (report.get("findings") or [])
        if str((item or {}).get("severity") or "").upper() in {"CRITICAL", "HIGH", "MEDIUM"}
    ]
    if blocked:
        labels = ", ".join(str(item.get("title") or "malware indicator") for item in blocked[:4])
        raise C8SecurityInputError(f"Photo rejected by malware screening: {labels}.")
    clam = _black_cloud_clam_scan(data)
    if clam.get("available") and not clam.get("clean"):
        detail = str(clam.get("detail") or clam.get("status") or "scan failed")[:500]
        raise C8SecurityInputError(f"Photo rejected because ClamAV did not return a clean result: {detail}")
    return {
        "sha256": str((report.get("hashes") or {}).get("sha256") or hashlib.sha256(data).hexdigest()),
        "risk_score": int((report.get("summary") or {}).get("risk_score") or 0),
        "finding_count": int((report.get("summary") or {}).get("findings") or 0),
        "yara_engine": str(yara_report.get("engine") or "yara-python"),
        "yara_version": str(yara_report.get("version") or ""),
        "yara_matches": int((report.get("summary") or {}).get("yara_matches") or 0),
        "clamav": clam,
    }


def _black_cloud_photo_encrypt_for_viewers(
    sanitized: bytes,
    token: str,
    sha256_hex: str,
    mime: str,
    viewers: List[BlackCloudWebBridge],
) -> Dict[str, Any]:
    if AESGCM is None:
        raise RuntimeError("Photo delivery is blocked because AES-256-GCM support is unavailable.")
    try:
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import ec
        from cryptography.hazmat.primitives.kdf.hkdf import HKDF
    except Exception as exc:
        raise RuntimeError("Photo delivery is blocked because the cryptography package is unavailable.") from exc
    content_key = bytearray(secrets.token_bytes(32))
    content_nonce = secrets.token_bytes(12)
    body_aad = f"{BLACK_CLOUD_PHOTO_PROTOCOL}|{token}|{sha256_hex}|{mime}|BODY".encode("utf-8")
    ciphertext = AESGCM(bytes(content_key)).encrypt(content_nonce, sanitized, body_aad)
    ephemeral_private = ec.generate_private_key(ec.SECP256R1())
    ephemeral_public = ephemeral_private.public_key().public_bytes(
        serialization.Encoding.X962,
        serialization.PublicFormat.UncompressedPoint,
    )
    salt = secrets.token_bytes(32)
    wraps: Dict[str, Dict[str, str]] = {}
    try:
        for viewer in viewers:
            client_id = str(viewer.client_id or "")
            raw_public = _black_cloud_decode_b64url(viewer.public_key)
            if not BLACK_CLOUD_CLIENT_ID_RE.fullmatch(client_id) or len(raw_public) != 65:
                raise RuntimeError("A Black Cloud viewer key is invalid; reconnect both browsers and try again.")
            browser_public = ec.EllipticCurvePublicKey.from_encoded_point(ec.SECP256R1(), raw_public)
            shared = bytearray(ephemeral_private.exchange(ec.ECDH(), browser_public))
            wrap_key = HKDF(
                algorithm=hashes.SHA256(), length=32, salt=salt,
                info=f"{BLACK_CLOUD_PHOTO_PROTOCOL}|WRAP|{token}|{client_id}".encode("utf-8"),
            ).derive(bytes(shared))
            for index in range(len(shared)):
                shared[index] = 0
            wrap_nonce = secrets.token_bytes(12)
            wrap_aad = f"{BLACK_CLOUD_PHOTO_PROTOCOL}|WRAP|{token}|{client_id}|{sha256_hex}".encode("utf-8")
            wrapped_key = AESGCM(wrap_key).encrypt(wrap_nonce, bytes(content_key), wrap_aad)
            wraps[client_id] = {
                "nonce": base64.urlsafe_b64encode(wrap_nonce).decode("ascii").rstrip("="),
                "key": base64.urlsafe_b64encode(wrapped_key).decode("ascii").rstrip("="),
            }
    finally:
        for index in range(len(content_key)):
            content_key[index] = 0
    return {
        "ciphertext": ciphertext,
        "content_nonce": base64.urlsafe_b64encode(content_nonce).decode("ascii").rstrip("="),
        "ephemeral_public": base64.urlsafe_b64encode(ephemeral_public).decode("ascii").rstrip("="),
        "salt": base64.urlsafe_b64encode(salt).decode("ascii").rstrip("="),
        "wraps": wraps,
    }


def black_cloud_photo_scan(session: Dict[str, Any], payload: Dict[str, Any]) -> Dict[str, Any]:
    sender = _black_cloud_web_get(session)
    if not sender or not sender.connected:
        raise RuntimeError("Open the Black Cloud secure messenger before sending a photo.")
    target_id = str(payload.get("target_id") or "").strip()
    if not BLACK_CLOUD_CLIENT_ID_RE.fullmatch(target_id):
        raise ValueError("Select a valid secure contact before sending a photo.")
    target = _black_cloud_find_client(target_id)
    if target is None or not target.connected or target is sender:
        raise RuntimeError("The selected secure contact is no longer connected.")
    _black_cloud_photo_rate_check(session)
    filename = _ff_safe_name(payload.get("filename") or "photo")
    original = _black_cloud_photo_decode_upload(payload.get("data_b64"))
    original_container = _black_cloud_photo_container_check(original, filename)
    original_scan = _black_cloud_photo_static_scan(original, filename)
    sanitized, safe_name, width, height, original_format = _black_cloud_photo_sanitize(original, filename)
    if original_format != str(original_container.get("format") or ""):
        raise C8SecurityInputError("Photo rejected: independent image decoders disagreed about its format.")
    sanitized_container = _black_cloud_photo_container_check(sanitized, safe_name)
    sanitized_scan = _black_cloud_photo_static_scan(sanitized, safe_name)
    sha256_hex = hashlib.sha256(sanitized).hexdigest()
    sanitized_size = len(sanitized)
    token = secrets.token_urlsafe(32)
    encrypted = _black_cloud_photo_encrypt_for_viewers(
        sanitized, token, sha256_hex, "image/jpeg", [sender, target]
    )
    del original, sanitized
    created = time.time()
    expires = created + BLACK_CLOUD_PHOTO_TTL_SECONDS
    scan_summary = {
        "status": "clean",
        "sanitized": True,
        "policy": BLACK_CLOUD_PHOTO_POLICY,
        "container_validated": True,
        "strict_end_of_file": bool(original_container.get("strict_eof") and sanitized_container.get("strict_eof")),
        "original_format": original_format,
        "engines": ["strict container validation", "built-in static signatures", sanitized_scan.get("yara_engine") or "yara-python", "Pillow pixel rebuild"],
        "clamav": "complete" if (original_scan.get("clamav") or {}).get("available") else "not installed (YARA + static checks completed)",
        "yara_version": sanitized_scan.get("yara_version") or original_scan.get("yara_version") or "",
    }
    record = {
        **encrypted,
        "token": token,
        "filename": safe_name,
        "mime": "image/jpeg",
        "size_bytes": sanitized_size,
        "sha256": sha256_hex,
        "width": width,
        "height": height,
        "sender_id": sender.client_id,
        "target_id": target.client_id,
        "created_epoch": created,
        "expires_at": expires,
        "scan": scan_summary,
    }
    if len(bytes(record.get("ciphertext") or b"")) > BLACK_CLOUD_PHOTO_MAX_STORE_BYTES:
        raise ValueError("The sanitized photo is too large for the encrypted memory store.")
    with BLACK_CLOUD_PHOTO_LOCK:
        BLACK_CLOUD_PHOTOS[token] = record
        _black_cloud_photo_cleanup(created)
    descriptor = {
        "protocol": BLACK_CLOUD_PHOTO_PROTOCOL,
        "token": token,
        "filename": safe_name,
        "mime": "image/jpeg",
        "size_bytes": sanitized_size,
        "sha256": sha256_hex,
        "width": width,
        "height": height,
        "expires_at": int(expires),
        "scan": scan_summary,
    }
    return {"ok": True, "approved": True, "attachment": descriptor}


def black_cloud_photo_fetch(session: Dict[str, Any], payload: Dict[str, Any]) -> Dict[str, Any]:
    bridge = _black_cloud_web_get(session)
    if not bridge or not bridge.connected:
        raise RuntimeError("Open the Black Cloud secure messenger before loading this photo.")
    token = str(payload.get("token") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_-]{32,96}", token):
        raise ValueError("Invalid Black Cloud photo token.")
    _black_cloud_photo_cleanup()
    with BLACK_CLOUD_PHOTO_LOCK:
        record = BLACK_CLOUD_PHOTOS.get(token)
        if not isinstance(record, dict):
            raise FileNotFoundError("This scanned photo expired or is no longer available.")
        client_id = str(bridge.client_id or "")
        wrap = (record.get("wraps") or {}).get(client_id)
        if not isinstance(wrap, dict):
            raise PermissionError("This scanned photo was not addressed to this secure session.")
        response = {
            "ok": True,
            "protocol": BLACK_CLOUD_PHOTO_PROTOCOL,
            "token": token,
            "filename": record.get("filename"),
            "mime": record.get("mime"),
            "size_bytes": record.get("size_bytes"),
            "sha256": record.get("sha256"),
            "width": record.get("width"),
            "height": record.get("height"),
            "expires_at": int(float(record.get("expires_at") or 0)),
            "scan": dict(record.get("scan") or {}),
            "ephemeral_public": record.get("ephemeral_public"),
            "salt": record.get("salt"),
            "content_nonce": record.get("content_nonce"),
            "wrap_nonce": wrap.get("nonce"),
            "wrapped_key": wrap.get("key"),
            "ciphertext_b64": base64.urlsafe_b64encode(bytes(record.get("ciphertext") or b"")).decode("ascii").rstrip("="),
        }
    return response


def _black_cloud_scanner_prewarm() -> None:
    try:
        _ensure_pillow_available(force_install=True)
    except Exception as exc:
        print(f"Black Cloud image decoder prewarm warning: {str(exc)[:500]}", file=sys.stderr, flush=True)
    try:
        _ff_ensure_yara()
    except Exception as exc:
        print(f"Black Cloud YARA prewarm warning: {str(exc)[:500]}", file=sys.stderr, flush=True)


def _black_cloud_start_scanner_prewarm() -> None:
    global BLACK_CLOUD_SCANNER_PREWARM_STARTED
    with BLACK_CLOUD_SCANNER_PREWARM_LOCK:
        if BLACK_CLOUD_SCANNER_PREWARM_STARTED:
            return
        BLACK_CLOUD_SCANNER_PREWARM_STARTED = True
        threading.Thread(
            target=_black_cloud_scanner_prewarm,
            daemon=True,
            name="black-cloud-scanner-prewarm",
        ).start()


def _black_cloud_web_cleanup() -> None:
    now = time.time()
    with _SESSION_LOCK:
        valid_keys = {
            hmac.new(
                _local_state_aes_key(),
                b"black-cloud-web|" + token.encode("utf-8", errors="ignore"),
                hashlib.sha256,
            ).hexdigest()
            for token in _SESSIONS
        }
    expired: List[BlackCloudWebBridge] = []
    with BLACK_CLOUD_WEB_LOCK:
        for key, bridge in list(BLACK_CLOUD_WEB_BRIDGES.items()):
            if (
                key not in valid_keys
                or not isinstance(bridge, BlackCloudWebBridge)
                or now - float(getattr(bridge, "last_activity", 0.0) or 0.0)
                > BLACK_CLOUD_WEB_IDLE_SECONDS
            ):
                BLACK_CLOUD_WEB_BRIDGES.pop(key, None)
                if isinstance(bridge, BlackCloudWebBridge):
                    expired.append(bridge)
    for bridge in expired:
        bridge.close()
    _black_cloud_photo_cleanup(now)


def black_cloud_status() -> Dict[str, Any]:
    users = _black_cloud_connected_users()
    _black_cloud_photo_cleanup()
    with BLACK_CLOUD_PHOTO_LOCK:
        photo_items = len(BLACK_CLOUD_PHOTOS)
        photo_bytes = sum(len(bytes(item.get("ciphertext") or b"")) for item in BLACK_CLOUD_PHOTOS.values())
    return {
        "ok": True,
        "available": True,
        "source_error": "",
        "source": {
            "filename": Path(__file__).name,
            "size_bytes": 0,
            "sha256": "",
        },
        "process_running": True,
        "listener_ready": True,
        "state": "online",
        "pid": os.getpid(),
        "started_at": BLACK_CLOUD_RELAY_STARTED_AT,
        "bind_host": HOST,
        "port": PORT,
        "always_on": True,
        "proxy_enabled": False,
        "transport": "integrated-https",
        "relay_mode": "in-process-encrypted-messaging-with-photo-quarantine",
        "connected_clients": len(users),
        "users": users,
        "scanned_photo_items": photo_items,
        "encrypted_photo_bytes": photo_bytes,
        "photo_ttl_seconds": BLACK_CLOUD_PHOTO_TTL_SECONDS,
        "history_storage": "memory-only",
        "log": (
            "Black Cloud is embedded in the main site process. "
            "Authenticated users can use encrypted text plus browser WebRTC voice. Photos are decoded, rebuilt without metadata, malware-scanned, then retained only as recipient-wrapped AES-256-GCM ciphertext. "
            "No external Black Cloud Python file, subprocess, TCP 5000 listener, or separate watchdog service is required."
        ),
    }


def black_cloud_start() -> Dict[str, Any]:
    result = black_cloud_status()
    result["message"] = "Black Cloud is integrated into the site and already online."
    return result


def black_cloud_restart() -> Dict[str, Any]:
    global BLACK_CLOUD_RELAY_GENERATION
    with BLACK_CLOUD_LOCK:
        with BLACK_CLOUD_WEB_LOCK:
            bridges = list(BLACK_CLOUD_WEB_BRIDGES.values())
            BLACK_CLOUD_WEB_BRIDGES.clear()
            BLACK_CLOUD_RELAY_GENERATION += 1
        with BLACK_CLOUD_PHOTO_LOCK:
            BLACK_CLOUD_PHOTOS.clear()
        for bridge in bridges:
            if isinstance(bridge, BlackCloudWebBridge):
                bridge.close()
    result = black_cloud_status()
    result["message"] = "Integrated Black Cloud relay connections were reset. Browsers will reconnect automatically."
    return result


def black_cloud_stop(force: bool = False) -> Dict[str, Any]:
    # The relay shares the website process, so it cannot be stopped independently.
    result = black_cloud_restart()
    result["message"] = "Black Cloud is part of the site process; active messenger connections were cleared instead."
    return result


def _black_cloud_watchdog_loop() -> None:
    # Standalone mode only needs periodic in-memory cleanup. It never attempts
    # to locate or launch an external Black Cloud script.
    while True:
        try:
            _black_cloud_web_cleanup()
        except Exception as exc:
            print(f"Black Cloud cleanup warning: {str(exc)[:800]}", file=sys.stderr, flush=True)
        time.sleep(BLACK_CLOUD_WATCHDOG_INTERVAL_SECONDS)


def _black_cloud_start_watchdog() -> None:
    global BLACK_CLOUD_WATCHDOG_THREAD
    with BLACK_CLOUD_WATCHDOG_LOCK:
        if not (BLACK_CLOUD_WATCHDOG_THREAD and BLACK_CLOUD_WATCHDOG_THREAD.is_alive()):
            BLACK_CLOUD_WATCHDOG_THREAD = threading.Thread(
                target=_black_cloud_watchdog_loop,
                daemon=True,
                name="black-cloud-integrated-cleanup",
            )
            BLACK_CLOUD_WATCHDOG_THREAD.start()
    _black_cloud_start_audit_worker()
    _black_cloud_start_scanner_prewarm()


