def render_login_page(csp_nonce: str = "", client_ip: str = "unknown", user_agent: str = "") -> bytes:
    nonce = _clean_csp_nonce(csp_nonce)
    nonce_attr = f' nonce="{escape(nonce, quote=True)}"' if nonce else ""
    login_csrf = _login_csrf_token(client_ip, user_agent)
    html = (
        LOGIN_PAGE_HTML
        .replace("__SYSTEM__", escape(SYSTEM_NAME))
        .replace("__AGENCY__", escape(AGENCY_NAME))
        .replace("__WARNING__", escape(GOV_WARNING).replace("\n", "<br>"))
        .replace("__BIND_LABEL__", escape(_bind_label()))
        .replace("__FAVICON_VERSION__", escape(C8_FAVICON_VERSION))
        .replace("__TERMS_VERSION__", escape(TERMS_VERSION))
        .replace("__LOGIN_CSRF__", escape(login_csrf, quote=True))
        .replace("__NONCE_ATTR__", nonce_attr)
    )
    return html.encode("utf-8")


